--
-- Name: _actuarial_age_bands(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._actuarial_age_bands(p_org_id uuid, p_start timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN (
    WITH band_members AS (
      SELECT
        CASE
          WHEN EXTRACT(YEAR FROM AGE(CURRENT_DATE, mem.date_of_birth::date)) < 18 THEN '0-17'
          WHEN EXTRACT(YEAR FROM AGE(CURRENT_DATE, mem.date_of_birth::date)) < 26 THEN '18-25'
          WHEN EXTRACT(YEAR FROM AGE(CURRENT_DATE, mem.date_of_birth::date)) < 36 THEN '26-35'
          WHEN EXTRACT(YEAR FROM AGE(CURRENT_DATE, mem.date_of_birth::date)) < 46 THEN '36-45'
          WHEN EXTRACT(YEAR FROM AGE(CURRENT_DATE, mem.date_of_birth::date)) < 56 THEN '46-55'
          WHEN EXTRACT(YEAR FROM AGE(CURRENT_DATE, mem.date_of_birth::date)) < 65 THEN '56-64'
          ELSE '65+'
        END AS age_band,
        mem.id AS member_id,
        mem.has_existing_condition
      FROM members mem
      WHERE mem.organization_id = p_org_id
        AND mem.date_of_birth IS NOT NULL
    ),

    band_needs AS (
      SELECT
        bm.age_band,
        COUNT(n.id) AS needs_count,
        COALESCE(SUM(n.total_amount), 0) AS submitted,
        COALESCE(SUM(n.approved_amount), 0) AS approved,
        COALESCE(SUM(n.reimbursed_amount), 0) AS paid,
        ROUND(COALESCE(AVG(n.total_amount), 0)::numeric, 2) AS avg_need
      FROM band_members bm
      LEFT JOIN needs n ON n.member_id = bm.member_id
        AND n.organization_id = p_org_id
        AND n.created_at >= p_start
      GROUP BY bm.age_band
    ),

    band_summary AS (
      SELECT
        bm.age_band,
        COUNT(DISTINCT bm.member_id) AS member_count,
        ROUND(
          COUNT(DISTINCT bm.member_id) FILTER (WHERE bm.has_existing_condition = true)::numeric
          / NULLIF(COUNT(DISTINCT bm.member_id), 0) * 100, 1
        ) AS pct_preexisting
      FROM band_members bm
      GROUP BY bm.age_band
    )

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'ageBand',           bs.age_band,
      'eligibleMembers',   CASE WHEN bs.member_count < 5 THEN 0 ELSE bs.member_count::int END,
      'needsCount',        CASE WHEN bs.member_count < 5 THEN 0 ELSE COALESCE(bn.needs_count, 0)::int END,
      'totalSubmitted',    CASE WHEN bs.member_count < 5 THEN 0 ELSE COALESCE(bn.submitted, 0) END,
      'totalApproved',     CASE WHEN bs.member_count < 5 THEN 0 ELSE COALESCE(bn.approved, 0) END,
      'totalPaid',         CASE WHEN bs.member_count < 5 THEN 0 ELSE COALESCE(bn.paid, 0) END,
      'avgNeedSize',       CASE WHEN bs.member_count < 5 THEN 0 ELSE COALESCE(bn.avg_need, 0) END,
      'needsPer100',       CASE WHEN bs.member_count < 5 THEN 0
        WHEN bs.member_count > 0
        THEN ROUND((COALESCE(bn.needs_count, 0)::numeric / bs.member_count) * 100, 1)
        ELSE 0 END,
      'pctPreexisting',    CASE WHEN bs.member_count < 5 THEN 0 ELSE COALESCE(bs.pct_preexisting, 0) END
    ) ORDER BY
      CASE bs.age_band
        WHEN '0-17'  THEN 1
        WHEN '18-25' THEN 2
        WHEN '26-35' THEN 3
        WHEN '36-45' THEN 4
        WHEN '46-55' THEN 5
        WHEN '56-64' THEN 6
        WHEN '65+'   THEN 7
      END
    ), '[]'::jsonb)
    FROM band_summary bs
    LEFT JOIN band_needs bn ON bn.age_band = bs.age_band
  );
END;
$$;


--
-- Name: _actuarial_contributions(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._actuarial_contributions(p_org_id uuid, p_start timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN (
    WITH months AS (
      SELECT gs::date AS month
      FROM generate_series(p_start, DATE_TRUNC('month', CURRENT_DATE), '1 month') gs
    ),

    monthly_expected AS (
      SELECT
        m.month,
        COALESCE(SUM(bs.amount), 0) AS expected,
        COUNT(bs.id) AS active_schedules,
        ROUND(COALESCE(AVG(bs.amount), 0)::numeric, 2) AS avg_contribution,
        ROUND(COALESCE(
          PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY bs.amount), 0
        )::numeric, 2) AS median_contribution
      FROM months m
      LEFT JOIN billing_schedules bs ON bs.organization_id = p_org_id
        AND bs.status = 'active'
        AND bs.start_date <= m.month + INTERVAL '1 month'
        AND (bs.end_date IS NULL OR bs.end_date >= m.month)
      GROUP BY m.month
    ),

    monthly_actual AS (
      SELECT
        DATE_TRUNC('month', bt.processed_at)::date AS month,
        COALESCE(SUM(bt.amount) FILTER (
          WHERE bt.status = 'success' AND bt.transaction_type = 'charge'
        ), 0) AS collected,
        COALESCE(SUM(bt.processing_fee) FILTER (WHERE bt.status = 'success'), 0) AS fees,
        COUNT(*) FILTER (WHERE bt.status = 'failed') AS failed_count,
        COALESCE(SUM(bt.amount) FILTER (WHERE bt.status = 'failed'), 0) AS failed_amount
      FROM billing_transactions bt
      WHERE bt.organization_id = p_org_id
        AND bt.processed_at >= p_start
      GROUP BY 1
    )

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'period',              TO_CHAR(me.month, 'YYYY-MM'),
      'activeSchedules',     me.active_schedules,
      'avgContribution',     me.avg_contribution,
      'medianContribution',  me.median_contribution,
      'totalExpected',       me.expected,
      'totalCollected',      COALESCE(ma.collected, 0),
      'totalFailed',         COALESCE(ma.failed_amount, 0),
      'failedCount',         COALESCE(ma.failed_count, 0),
      'processingFees',      COALESCE(ma.fees, 0),
      'netRevenue',          COALESCE(ma.collected, 0) - COALESCE(ma.fees, 0),
      'collectionRate',      CASE WHEN me.expected > 0
        THEN ROUND((COALESCE(ma.collected, 0)::numeric / me.expected) * 100, 1)
        ELSE 0 END
    ) ORDER BY me.month), '[]'::jsonb)
    FROM monthly_expected me
    LEFT JOIN monthly_actual ma ON ma.month = me.month
  );
END;
$$;


--
-- Name: _actuarial_exposure_dev(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._actuarial_exposure_dev(p_org_id uuid, p_start timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN (
    WITH months AS (
      SELECT gs::date AS month
      FROM generate_series(p_start, DATE_TRUNC('month', CURRENT_DATE), '1 month') gs
    ),

    daily_exposure AS (
      SELECT
        DATE_TRUNC('month', d.day)::date AS month,
        ROUND(SUM(daily_count)::numeric / MAX(days_in_month)) AS member_months,
        MAX(daily_count) FILTER (WHERE d.day = DATE_TRUNC('month', d.day)) AS beginning_members,
        MAX(daily_count) FILTER (WHERE d.day = (DATE_TRUNC('month', d.day) + INTERVAL '1 month' - INTERVAL '1 day')::date) AS ending_members
      FROM (
        SELECT
          d.day::date AS day,
          EXTRACT(DAY FROM (DATE_TRUNC('month', d.day) + INTERVAL '1 month' - INTERVAL '1 day'))::int AS days_in_month,
          COUNT(DISTINCT mem.id) AS daily_count
        FROM generate_series(p_start, DATE_TRUNC('month', CURRENT_DATE) + INTERVAL '1 month' - INTERVAL '1 day', '1 day') d(day)
        LEFT JOIN members mem ON mem.organization_id = p_org_id
          AND mem.created_at::date <= d.day::date
          AND (mem.status = 'active'
               OR (mem.status IN ('inactive', 'terminated') AND mem.updated_at::date > d.day::date))
        GROUP BY d.day
      ) d
      GROUP BY DATE_TRUNC('month', d.day)
    ),

    monthly_movement AS (
      SELECT
        m.month,
        COUNT(DISTINCT mem.id) FILTER (
          WHERE DATE_TRUNC('month', mem.created_at) = m.month
        ) AS new_enrollments,
        COUNT(DISTINCT mem.id) FILTER (
          WHERE mem.status IN ('inactive', 'terminated')
            AND DATE_TRUNC('month', mem.updated_at) = m.month
            AND mem.created_at < m.month
        ) AS terminations
      FROM months m
      LEFT JOIN members mem ON mem.organization_id = p_org_id
      GROUP BY m.month
    ),

    service_month_claims AS (
      SELECT
        DATE_TRUNC('month', COALESCE(n.incident_date::timestamptz, n.created_at))::date AS service_month,
        COALESCE(SUM(n.approved_amount) FILTER (
          WHERE n.status IN ('approved', 'paid', 'closed')
        ), 0) AS incurred_amount,
        COALESCE(SUM(n.reimbursed_amount) FILTER (
          WHERE n.reimbursed_amount > 0
        ), 0) AS paid_amount,
        COALESCE(SUM(
          COALESCE(n.approved_amount, 0) - COALESCE(n.reimbursed_amount, 0)
        ) FILTER (
          WHERE n.status IN ('approved')
            AND COALESCE(n.reimbursed_amount, 0) < COALESCE(n.approved_amount, 0)
        ), 0) AS pending_amount,
        ROUND(COALESCE(AVG(
          EXTRACT(DAY FROM (n.created_at - n.incident_date::timestamptz))
        ) FILTER (WHERE n.incident_date IS NOT NULL), 0)::numeric) AS avg_report_lag,
        ROUND(COALESCE(AVG(
          EXTRACT(DAY FROM (
            COALESCE(n.payment_date::timestamptz, n.last_status_change_at) - n.created_at
          ))
        ) FILTER (WHERE n.reimbursed_amount > 0), 0)::numeric) AS avg_payment_lag
      FROM needs n
      WHERE n.organization_id = p_org_id
        AND COALESCE(n.incident_date::timestamptz, n.created_at) >= p_start
      GROUP BY 1
    )

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'period',            TO_CHAR(m.month, 'YYYY-MM'),
      'serviceMonth',      TO_CHAR(m.month, 'YYYY-MM'),
      'memberMonths',      COALESCE(de.member_months, 0),
      'beginningMembers',  COALESCE(de.beginning_members, 0),
      'endingMembers',     COALESCE(de.ending_members, 0),
      'newEnrollments',    COALESCE(mv.new_enrollments, 0),
      'terminations',      COALESCE(mv.terminations, 0),
      'incurredAmount',    COALESCE(sc.incurred_amount, 0),
      'paidAmount',        COALESCE(sc.paid_amount, 0),
      'pendingAmount',     COALESCE(sc.pending_amount, 0),
      'reportLagDays',     COALESCE(sc.avg_report_lag, 0),
      'paymentLagDays',    COALESCE(sc.avg_payment_lag, 0),
      'pmpm',              CASE
        WHEN COALESCE(de.member_months, 0) > 0
        THEN ROUND((COALESCE(sc.incurred_amount, 0) / de.member_months)::numeric, 2)
        ELSE 0 END
    ) ORDER BY m.month), '[]'::jsonb)
    FROM months m
    LEFT JOIN daily_exposure de ON de.month = m.month
    LEFT JOIN monthly_movement mv ON mv.month = m.month
    LEFT JOIN service_month_claims sc ON sc.service_month = m.month
  );
END;
$$;


--
-- Name: _actuarial_monthly(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._actuarial_monthly(p_org_id uuid, p_start timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN (
    WITH months AS (
      SELECT gs::date AS month
      FROM generate_series(p_start, DATE_TRUNC('month', CURRENT_DATE), '1 month') gs
    ),

    monthly_members AS (
      SELECT
        m.month,
        COUNT(DISTINCT mem.id) AS eligible,
        COUNT(DISTINCT mem.id) FILTER (
          WHERE DATE_TRUNC('month', mem.created_at) = m.month
        ) AS new_members
      FROM months m
      LEFT JOIN members mem ON mem.organization_id = p_org_id
        AND mem.created_at < m.month + INTERVAL '1 month'
        AND (mem.status = 'active'
             OR mem.updated_at >= m.month)
      GROUP BY m.month
    ),

    monthly_needs AS (
      SELECT
        DATE_TRUNC('month', n.created_at)::date AS month,
        COUNT(*)                                         AS submitted_count,
        COALESCE(SUM(n.total_amount), 0)                 AS submitted_amount,
        COUNT(*) FILTER (WHERE n.status IN ('approved','paid','closed'))
                                                         AS approved_count,
        COALESCE(SUM(n.approved_amount), 0)              AS approved_amount,
        COALESCE(SUM(n.reimbursed_amount), 0)            AS paid_amount,
        ROUND(COALESCE(AVG(n.total_amount), 0)::numeric, 2)       AS avg_need,
        ROUND(COALESCE(
          PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY n.total_amount), 0
        )::numeric, 2)                                            AS median_need,
        COALESCE(MAX(n.total_amount), 0)                 AS max_need,
        COUNT(*) FILTER (WHERE n.total_amount > 25000)   AS over_25k,
        COUNT(*) FILTER (WHERE n.total_amount > 50000)   AS over_50k,
        COALESCE(SUM(n.iua_amount), 0)                   AS iua_total,
        COALESCE(SUM(n.member_responsibility_amount), 0) AS member_resp
      FROM needs n
      WHERE n.organization_id = p_org_id
        AND n.created_at >= p_start
      GROUP BY 1
    ),

    monthly_revenue AS (
      SELECT
        DATE_TRUNC('month', bt.processed_at)::date AS month,
        COALESCE(SUM(bt.amount) FILTER (
          WHERE bt.status = 'success' AND bt.transaction_type = 'charge'
        ), 0) AS collected,
        COALESCE(SUM(bt.processing_fee) FILTER (
          WHERE bt.status = 'success'
        ), 0) AS fees,
        COALESCE(SUM(bt.net_amount) FILTER (
          WHERE bt.status = 'success' AND bt.transaction_type = 'charge'
        ), 0) AS net_collected,
        COUNT(*) FILTER (
          WHERE bt.status = 'failed'
        ) AS failed_count,
        COALESCE(SUM(bt.amount) FILTER (
          WHERE bt.status = 'failed'
        ), 0) AS failed_amount
      FROM billing_transactions bt
      WHERE bt.organization_id = p_org_id
        AND bt.processed_at >= p_start
      GROUP BY 1
    )

    SELECT COALESCE(jsonb_agg(row_data ORDER BY m.month), '[]'::jsonb)
    FROM months m
    LEFT JOIN monthly_members mm ON mm.month = m.month
    LEFT JOIN monthly_needs mn   ON mn.month = m.month
    LEFT JOIN monthly_revenue mr ON mr.month = m.month
    CROSS JOIN LATERAL (
      SELECT jsonb_build_object(
        'period',                    TO_CHAR(m.month, 'YYYY-MM'),
        'eligibleMembers',           COALESCE(mm.eligible, 0),
        'newMembers',                COALESCE(mm.new_members, 0),
        'contributionsCollected',    COALESCE(mr.collected, 0),
        'processingFees',            COALESCE(mr.fees, 0),
        'netRevenue',                COALESCE(mr.net_collected, 0),
        'failedPayments',            COALESCE(mr.failed_count, 0),
        'failedAmount',              COALESCE(mr.failed_amount, 0),
        'needsSubmittedCount',       COALESCE(mn.submitted_count, 0),
        'needsSubmittedAmount',      COALESCE(mn.submitted_amount, 0),
        'needsApprovedCount',        COALESCE(mn.approved_count, 0),
        'needsApprovedAmount',       COALESCE(mn.approved_amount, 0),
        'needsPaidAmount',           COALESCE(mn.paid_amount, 0),
        'avgNeedSize',               COALESCE(mn.avg_need, 0),
        'medianNeedSize',            COALESCE(mn.median_need, 0),
        'maxSingleNeed',             COALESCE(mn.max_need, 0),
        'needsOver25k',              COALESCE(mn.over_25k, 0),
        'needsOver50k',              COALESCE(mn.over_50k, 0),
        'needsPer100Members',        CASE WHEN COALESCE(mm.eligible, 0) > 0
          THEN ROUND((COALESCE(mn.submitted_count, 0)::numeric / mm.eligible) * 100, 1)
          ELSE 0 END,
        'lossRatio',                 CASE WHEN COALESCE(mr.collected, 0) > 0
          THEN ROUND((COALESCE(mn.paid_amount, 0)::numeric / mr.collected) * 100, 1)
          ELSE 0 END,
        'avgMemberContribution',     CASE WHEN COALESCE(mm.eligible, 0) > 0
          THEN ROUND((COALESCE(mr.collected, 0)::numeric / mm.eligible), 2)
          ELSE 0 END,
        'iuaApplied',                COALESCE(mn.iua_total, 0),
        'memberResponsibility',      COALESCE(mn.member_resp, 0)
      ) AS row_data
    ) lat
  );
END;
$$;


--
-- Name: _actuarial_needs_by_type(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._actuarial_needs_by_type(p_org_id uuid, p_start timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN (
    WITH type_agg AS (
      SELECT
        COALESCE(n.need_type, 'Other') AS need_type,
        COUNT(*)                                         AS cnt,
        COALESCE(SUM(n.total_amount), 0)                 AS submitted,
        COALESCE(SUM(n.approved_amount), 0)              AS approved,
        COALESCE(SUM(n.reimbursed_amount), 0)            AS paid,
        ROUND(COALESCE(AVG(n.total_amount), 0)::numeric, 2)       AS avg_amount
      FROM needs n
      WHERE n.organization_id = p_org_id
        AND n.created_at >= p_start
      GROUP BY 1
    ),
    total AS (
      SELECT SUM(cnt) AS grand_total FROM type_agg
    )
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'needType',         ta.need_type,
      'count',            CASE WHEN ta.cnt < 5 THEN 0 ELSE ta.cnt::int END,
      'totalSubmitted',   CASE WHEN ta.cnt < 5 THEN 0 ELSE ta.submitted END,
      'totalApproved',    CASE WHEN ta.cnt < 5 THEN 0 ELSE ta.approved END,
      'totalPaid',        CASE WHEN ta.cnt < 5 THEN 0 ELSE ta.paid END,
      'avgAmount',        CASE WHEN ta.cnt < 5 THEN 0 ELSE ta.avg_amount END,
      'pctOfTotal',       CASE WHEN t.grand_total > 0
        THEN ROUND((ta.cnt::numeric / t.grand_total) * 100, 1)
        ELSE 0 END
    ) ORDER BY ta.cnt DESC), '[]'::jsonb)
    FROM type_agg ta
    CROSS JOIN total t
  );
END;
$$;


--
-- Name: _actuarial_summary(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._actuarial_summary(p_org_id uuid, p_start timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total_members       bigint;
  v_active_members      bigint;
  v_total_needs         bigint;
  v_total_submitted     numeric;
  v_total_approved      numeric;
  v_total_paid          numeric;
  v_total_collected     numeric;
  v_total_expected      numeric;
  v_avg_monthly_share   numeric;
  v_loss_ratio          numeric;
  v_collection_rate     numeric;
  v_cat_count           bigint;
  v_utilization_rate    numeric;
BEGIN
  SELECT COUNT(*), COUNT(*) FILTER (WHERE status = 'active')
    INTO v_total_members, v_active_members
    FROM members WHERE organization_id = p_org_id;

  SELECT
    COUNT(*),
    COALESCE(SUM(total_amount), 0),
    COALESCE(SUM(approved_amount), 0),
    COALESCE(SUM(reimbursed_amount), 0),
    COUNT(*) FILTER (WHERE total_amount > 25000)
    INTO v_total_needs, v_total_submitted, v_total_approved, v_total_paid, v_cat_count
    FROM needs
    WHERE organization_id = p_org_id AND created_at >= p_start;

  SELECT COALESCE(SUM(amount) FILTER (
    WHERE status = 'success' AND transaction_type = 'charge'
  ), 0) INTO v_total_collected
  FROM billing_transactions
  WHERE organization_id = p_org_id AND processed_at >= p_start;

  SELECT COALESCE(SUM(amount), 0)
    INTO v_total_expected
    FROM billing_schedules
    WHERE organization_id = p_org_id AND status = 'active';

  SELECT ROUND(COALESCE(AVG(amount), 0)::numeric, 2)
    INTO v_avg_monthly_share
    FROM billing_schedules
    WHERE organization_id = p_org_id AND status = 'active';

  v_loss_ratio := CASE WHEN v_total_collected > 0
    THEN ROUND((v_total_paid / v_total_collected * 100)::numeric, 1)
    ELSE 0 END;

  v_collection_rate := CASE WHEN v_total_expected > 0
    THEN ROUND((v_total_collected / v_total_expected * 100)::numeric, 1)
    ELSE 0 END;

  v_utilization_rate := CASE WHEN v_active_members > 0
    THEN ROUND((v_total_needs::numeric / v_active_members * 100)::numeric, 1)
    ELSE 0 END;

  RETURN jsonb_build_object(
    'totalMembers', v_total_members,
    'activeMembers', v_active_members,
    'totalNeedsSubmitted', v_total_needs,
    'totalAmountSubmitted', v_total_submitted,
    'totalAmountApproved', v_total_approved,
    'totalAmountPaid', v_total_paid,
    'totalContributionsCollected', v_total_collected,
    'currentMRR', v_total_expected,
    'avgMonthlyShare', v_avg_monthly_share,
    'overallLossRatio', v_loss_ratio,
    'collectionRate', v_collection_rate,
    'utilizationPer100', v_utilization_rate,
    'catastrophicNeedsCount', v_cat_count
  );
END;
$$;


--
-- Name: _crm_jsonb_value_is_blank(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._crm_jsonb_value_is_blank(v jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT v IS NULL
    OR v = 'null'::jsonb
    OR v = '""'::jsonb
    OR (jsonb_typeof(v) = 'string' AND btrim(v #>> '{}') = '');
$$;


--
-- Name: _demographics_agents(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._demographics_agents(p_org_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total         bigint;
  v_active        bigint;
  v_mpb_certified bigint;
  v_eo_current    bigint;
  v_with_downline bigint;
  v_state_dist    jsonb;
  v_type_dist     jsonb;
  v_status_dist   jsonb;
  v_cert_rate     numeric;
  v_eo_rate       numeric;
BEGIN
  SELECT COUNT(*),
         COUNT(*) FILTER (WHERE status = 'active'),
         COUNT(*) FILTER (WHERE mpb_certified = true),
         COUNT(*) FILTER (WHERE mpb_eo_current = true),
         COUNT(*) FILTER (WHERE id IN (
           SELECT DISTINCT parent_advisor_id FROM advisors
           WHERE organization_id = p_org_id AND parent_advisor_id IS NOT NULL
         ))
    INTO v_total, v_active, v_mpb_certified, v_eo_current, v_with_downline
    FROM advisors
   WHERE organization_id = p_org_id;

  v_cert_rate := CASE WHEN v_total > 0 THEN ROUND((v_mpb_certified::numeric / v_total) * 100, 1) ELSE 0 END;
  v_eo_rate   := CASE WHEN v_total > 0 THEN ROUND((v_eo_current::numeric / v_total) * 100, 1) ELSE 0 END;

  -- State distribution
  SELECT COALESCE(jsonb_agg(jsonb_build_object('label', COALESCE(state, 'Unknown'), 'count',
           CASE WHEN cnt < 5 THEN 0 ELSE cnt END)), '[]'::jsonb)
    INTO v_state_dist
    FROM (
      SELECT state, COUNT(*)::int AS cnt
      FROM advisors WHERE organization_id = p_org_id
      GROUP BY state ORDER BY COUNT(*) DESC LIMIT 15
    ) sub;

  -- Producer type distribution
  SELECT COALESCE(jsonb_agg(jsonb_build_object('label', COALESCE(producer_type, 'Not specified'), 'count',
           CASE WHEN cnt < 5 THEN 0 ELSE cnt END)), '[]'::jsonb)
    INTO v_type_dist
    FROM (
      SELECT producer_type, COUNT(*)::int AS cnt
      FROM advisors WHERE organization_id = p_org_id
      GROUP BY producer_type ORDER BY COUNT(*) DESC
    ) sub;

  -- Status distribution (with small-group suppression)
  SELECT COALESCE(jsonb_agg(jsonb_build_object('label', COALESCE(status, 'unknown'), 'count',
           CASE WHEN cnt < 5 THEN 0 ELSE cnt END)), '[]'::jsonb)
    INTO v_status_dist
    FROM (
      SELECT status, COUNT(*)::int AS cnt
      FROM advisors WHERE organization_id = p_org_id
      GROUP BY status ORDER BY COUNT(*) DESC
    ) sub;

  RETURN jsonb_build_object(
    'total', v_total,
    'active', v_active,
    'mpbCertifiedRate', v_cert_rate,
    'eoCurrentRate', v_eo_rate,
    'withDownline', v_with_downline,
    'independent', v_total - v_with_downline,
    'stateDistribution', v_state_dist,
    'producerTypeDistribution', v_type_dist,
    'statusDistribution', v_status_dist
  );
END;
$$;


--
-- Name: _demographics_enrollments(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._demographics_enrollments(p_org_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total         bigint;
  v_approved      bigint;
  v_approval_rate numeric;
  v_status_dist   jsonb;
  v_channel_dist  jsonb;
  v_hh_dist       jsonb;
  v_monthly_trend jsonb;
  v_age65_count   bigint;
  v_mandate_count bigint;
BEGIN
  SELECT COUNT(*),
         COUNT(*) FILTER (WHERE status = 'approved')
    INTO v_total, v_approved
    FROM enrollments
   WHERE organization_id = p_org_id;

  v_approval_rate := CASE WHEN v_total > 0
    THEN ROUND((v_approved::numeric / v_total) * 100, 1)
    ELSE 0 END;

  -- Status distribution (with small-group suppression)
  SELECT COALESCE(jsonb_agg(jsonb_build_object('label', COALESCE(status, 'unknown'), 'count',
           CASE WHEN cnt < 5 THEN 0 ELSE cnt END)), '[]'::jsonb)
    INTO v_status_dist
    FROM (
      SELECT status, COUNT(*)::int AS cnt
      FROM enrollments WHERE organization_id = p_org_id
      GROUP BY status ORDER BY COUNT(*) DESC
    ) sub;

  -- Channel distribution
  SELECT COALESCE(jsonb_agg(jsonb_build_object('label', COALESCE(channel, 'Direct'), 'count',
           CASE WHEN cnt < 5 THEN 0 ELSE cnt END)), '[]'::jsonb)
    INTO v_channel_dist
    FROM (
      SELECT channel, COUNT(*)::int AS cnt
      FROM enrollments WHERE organization_id = p_org_id
      GROUP BY channel ORDER BY COUNT(*) DESC
    ) sub;

  -- Household size distribution
  SELECT COALESCE(jsonb_agg(jsonb_build_object('bucket', bucket, 'count',
           CASE WHEN cnt < 5 THEN 0 ELSE cnt END)), '[]'::jsonb)
    INTO v_hh_dist
    FROM (
      SELECT
        CASE
          WHEN household_size IS NULL THEN 'Unknown'
          WHEN household_size >= 5 THEN '5+'
          ELSE household_size::text
        END AS bucket,
        COUNT(*)::int AS cnt
      FROM enrollments WHERE organization_id = p_org_id
      GROUP BY 1 ORDER BY 1
    ) sub;

  -- Monthly trend (last 12 months)
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'month', TO_CHAR(month, 'YYYY-MM'),
    'count', cnt::int
  ) ORDER BY month), '[]'::jsonb)
    INTO v_monthly_trend
    FROM (
      SELECT DATE_TRUNC('month', created_at) AS month, COUNT(*) AS cnt
      FROM enrollments
      WHERE organization_id = p_org_id
        AND created_at >= DATE_TRUNC('month', CURRENT_DATE) - INTERVAL '11 months'
      GROUP BY 1
    ) sub;

  -- Warning counts
  SELECT COUNT(*) FILTER (WHERE has_age65_warning = true),
         COUNT(*) FILTER (WHERE has_mandate_warning = true)
    INTO v_age65_count, v_mandate_count
    FROM enrollments
   WHERE organization_id = p_org_id;

  RETURN jsonb_build_object(
    'total', v_total,
    'approved', v_approved,
    'approvalRate', v_approval_rate,
    'statusDistribution', v_status_dist,
    'channelDistribution', v_channel_dist,
    'householdSizeDistribution', v_hh_dist,
    'monthlyTrend', v_monthly_trend,
    'age65WarningCount', v_age65_count,
    'mandateWarningCount', v_mandate_count
  );
END;
$$;


--
-- Name: _demographics_health(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._demographics_health(p_org_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total_needs     bigint;
  v_approved_needs  bigint;
  v_approval_rate   numeric;
  v_status_dist     jsonb;
  v_type_dist       jsonb;
  v_preexist_rate   numeric;
  v_total_members   bigint;
  v_preexist_count  bigint;
BEGIN
  -- Needs counts
  SELECT COUNT(*),
         COUNT(*) FILTER (WHERE status = 'approved')
    INTO v_total_needs, v_approved_needs
    FROM needs
   WHERE organization_id = p_org_id;

  v_approval_rate := CASE WHEN v_total_needs > 0
    THEN ROUND((v_approved_needs::numeric / v_total_needs) * 100, 1)
    ELSE 0 END;

  -- Needs by status (with small-group suppression)
  SELECT COALESCE(jsonb_agg(jsonb_build_object('label', COALESCE(status, 'unknown'), 'count',
           CASE WHEN cnt < 5 THEN 0 ELSE cnt END)), '[]'::jsonb)
    INTO v_status_dist
    FROM (
      SELECT status, COUNT(*)::int AS cnt
      FROM needs WHERE organization_id = p_org_id
      GROUP BY status ORDER BY COUNT(*) DESC
    ) sub;

  -- Needs by type/category
  SELECT COALESCE(jsonb_agg(jsonb_build_object('label', COALESCE(need_type, 'Other'), 'count',
           CASE WHEN cnt < 5 THEN 0 ELSE cnt END)), '[]'::jsonb)
    INTO v_type_dist
    FROM (
      SELECT need_type, COUNT(*)::int AS cnt
      FROM needs WHERE organization_id = p_org_id
      GROUP BY need_type ORDER BY COUNT(*) DESC LIMIT 10
    ) sub;

  -- Pre-existing conditions rate from members
  SELECT COUNT(*),
         COUNT(*) FILTER (WHERE has_existing_condition = true)
    INTO v_total_members, v_preexist_count
    FROM members
   WHERE organization_id = p_org_id;

  v_preexist_rate := CASE WHEN v_total_members > 0
    THEN ROUND((v_preexist_count::numeric / v_total_members) * 100, 1)
    ELSE 0 END;

  RETURN jsonb_build_object(
    'totalNeeds', v_total_needs,
    'approvedNeeds', v_approved_needs,
    'approvalRate', v_approval_rate,
    'statusDistribution', v_status_dist,
    'typeDistribution', v_type_dist,
    'preExistingConditionRate', v_preexist_rate
  );
END;
$$;


--
-- Name: _demographics_members(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._demographics_members(p_org_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total          bigint;
  v_active         bigint;
  v_avg_age        numeric;
  v_age_dist       jsonb;
  v_gender_dist    jsonb;
  v_state_dist     jsonb;
  v_plan_dist      jsonb;
  v_status_dist    jsonb;
  v_smoker_dist    jsonb;
  v_coverage_dist  jsonb;
BEGIN
  -- Totals
  SELECT COUNT(*),
         COUNT(*) FILTER (WHERE status = 'active')
    INTO v_total, v_active
    FROM members
   WHERE organization_id = p_org_id;

  -- Average age (rounded, no individual DOBs exposed)
  SELECT ROUND(AVG(EXTRACT(YEAR FROM AGE(CURRENT_DATE, date_of_birth::date))))
    INTO v_avg_age
    FROM members
   WHERE organization_id = p_org_id
     AND date_of_birth IS NOT NULL;

  -- Age distribution (bucketed)
  SELECT COALESCE(jsonb_agg(jsonb_build_object('bucket', bucket, 'count',
           CASE WHEN cnt < 5 THEN 0 ELSE cnt END)), '[]'::jsonb)
    INTO v_age_dist
    FROM (
      SELECT
        CASE
          WHEN EXTRACT(YEAR FROM AGE(CURRENT_DATE, date_of_birth::date)) < 18 THEN '0-17'
          WHEN EXTRACT(YEAR FROM AGE(CURRENT_DATE, date_of_birth::date)) < 26 THEN '18-25'
          WHEN EXTRACT(YEAR FROM AGE(CURRENT_DATE, date_of_birth::date)) < 36 THEN '26-35'
          WHEN EXTRACT(YEAR FROM AGE(CURRENT_DATE, date_of_birth::date)) < 46 THEN '36-45'
          WHEN EXTRACT(YEAR FROM AGE(CURRENT_DATE, date_of_birth::date)) < 56 THEN '46-55'
          WHEN EXTRACT(YEAR FROM AGE(CURRENT_DATE, date_of_birth::date)) < 65 THEN '56-64'
          ELSE '65+'
        END AS bucket,
        COUNT(*)::int AS cnt
      FROM members
      WHERE organization_id = p_org_id AND date_of_birth IS NOT NULL
      GROUP BY 1
      ORDER BY MIN(EXTRACT(YEAR FROM AGE(CURRENT_DATE, date_of_birth::date)))
    ) sub;

  -- Gender distribution
  SELECT COALESCE(jsonb_agg(jsonb_build_object('label', COALESCE(gender, 'Not specified'), 'count',
           CASE WHEN cnt < 5 THEN 0 ELSE cnt END)), '[]'::jsonb)
    INTO v_gender_dist
    FROM (
      SELECT gender, COUNT(*)::int AS cnt
      FROM members WHERE organization_id = p_org_id
      GROUP BY gender ORDER BY COUNT(*) DESC
    ) sub;

  -- State distribution (top 15 + Other)
  SELECT COALESCE(jsonb_agg(jsonb_build_object('label', label, 'count',
           CASE WHEN cnt < 5 THEN 0 ELSE cnt END)), '[]'::jsonb)
    INTO v_state_dist
    FROM (
      SELECT label, SUM(cnt)::int AS cnt FROM (
        SELECT
          CASE WHEN rn <= 15 THEN COALESCE(state, 'Unknown') ELSE 'Other' END AS label,
          cnt,
          rn
        FROM (
          SELECT state, COUNT(*)::int AS cnt,
                 ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC) AS rn
          FROM members WHERE organization_id = p_org_id
          GROUP BY state
        ) ranked
      ) grouped
      GROUP BY label ORDER BY SUM(cnt) DESC
    ) sub;

  -- Plan distribution
  SELECT COALESCE(jsonb_agg(jsonb_build_object('label', COALESCE(plan_name, 'No plan'), 'count',
           CASE WHEN cnt < 5 THEN 0 ELSE cnt END)), '[]'::jsonb)
    INTO v_plan_dist
    FROM (
      SELECT plan_name, COUNT(*)::int AS cnt
      FROM members WHERE organization_id = p_org_id
      GROUP BY plan_name ORDER BY COUNT(*) DESC LIMIT 10
    ) sub;

  -- Status distribution (with small-group suppression)
  SELECT COALESCE(jsonb_agg(jsonb_build_object('label', COALESCE(status, 'unknown'), 'count',
           CASE WHEN cnt < 5 THEN 0 ELSE cnt END)), '[]'::jsonb)
    INTO v_status_dist
    FROM (
      SELECT status, COUNT(*)::int AS cnt
      FROM members WHERE organization_id = p_org_id
      GROUP BY status ORDER BY COUNT(*) DESC
    ) sub;

  -- Smoker distribution (with small-group suppression)
  SELECT jsonb_build_object(
    'smoker',    CASE WHEN COUNT(*) FILTER (WHERE is_smoker = true)  < 5 THEN 0 ELSE COUNT(*) FILTER (WHERE is_smoker = true)::int  END,
    'nonSmoker', CASE WHEN COUNT(*) FILTER (WHERE is_smoker = false) < 5 THEN 0 ELSE COUNT(*) FILTER (WHERE is_smoker = false)::int END,
    'unknown',   CASE WHEN COUNT(*) FILTER (WHERE is_smoker IS NULL) < 5 THEN 0 ELSE COUNT(*) FILTER (WHERE is_smoker IS NULL)::int END
  ) INTO v_smoker_dist
  FROM members WHERE organization_id = p_org_id;

  -- Coverage type distribution
  SELECT COALESCE(jsonb_agg(jsonb_build_object('label', COALESCE(coverage_type, 'Not specified'), 'count',
           CASE WHEN cnt < 5 THEN 0 ELSE cnt END)), '[]'::jsonb)
    INTO v_coverage_dist
    FROM (
      SELECT coverage_type, COUNT(*)::int AS cnt
      FROM members WHERE organization_id = p_org_id
      GROUP BY coverage_type ORDER BY COUNT(*) DESC
    ) sub;

  RETURN jsonb_build_object(
    'total', v_total,
    'active', v_active,
    'avgAge', COALESCE(v_avg_age, 0),
    'ageDistribution', v_age_dist,
    'genderDistribution', v_gender_dist,
    'stateDistribution', v_state_dist,
    'planDistribution', v_plan_dist,
    'statusDistribution', v_status_dist,
    'smokerDistribution', v_smoker_dist,
    'coverageDistribution', v_coverage_dist
  );
END;
$$;


--
-- Name: _guard_org_members_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._guard_org_members_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  is_self  boolean;
  is_admin boolean;
BEGIN
  NEW.updated_at := now();

  -- Only run guards for end-user calls; service role / SECURITY DEFINER
  -- callers (e.g. provisioning RPCs) skip this check via SET LOCAL ROLE
  -- or by setting auth.uid() = NULL.
  IF auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;

  is_self  := (OLD.user_id = auth.uid());
  is_admin := (public.user_role_in(OLD.organization_id) IN ('owner', 'super_admin', 'admin'));

  IF is_self AND NOT is_admin THEN
    IF NEW.role            <> OLD.role            THEN RAISE EXCEPTION 'cannot change role on own membership'           USING ERRCODE='42501'; END IF;
    IF NEW.is_active       <> OLD.is_active       THEN RAISE EXCEPTION 'cannot change is_active on own membership'      USING ERRCODE='42501'; END IF;
    IF NEW.organization_id <> OLD.organization_id THEN RAISE EXCEPTION 'cannot change organization_id'                  USING ERRCODE='42501'; END IF;
    IF NEW.user_id         <> OLD.user_id         THEN RAISE EXCEPTION 'cannot change user_id'                          USING ERRCODE='42501'; END IF;
    IF NEW.invited_by IS DISTINCT FROM OLD.invited_by THEN RAISE EXCEPTION 'cannot change invited_by'                   USING ERRCODE='42501'; END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: _parse_import_boolean(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._parse_import_boolean(bool_str text) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF bool_str IS NULL OR bool_str = '' THEN
    RETURN false;
  END IF;
  RETURN UPPER(bool_str) IN ('TRUE', 'YES', '1', 'T', 'Y');
END;
$$;


--
-- Name: _parse_import_date(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._parse_import_date(date_str text) RETURNS date
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
DECLARE
  v_clean text;
  v_result date;
  v_year int;
BEGIN
  IF date_str IS NULL THEN
    RETURN NULL;
  END IF;

  v_clean := btrim(date_str);
  IF v_clean = '' OR v_clean = '0000-00-00' OR lower(v_clean) IN ('null', 'n/a', '-') THEN
    RETURN NULL;
  END IF;

  -- 1. ISO YYYY-MM-DD (most common, low ambiguity)
  IF v_clean ~ '^\d{4}-\d{2}-\d{2}(\s|T|$)' THEN
    BEGIN
      v_result := to_date(substring(v_clean from 1 for 10), 'YYYY-MM-DD');
      v_year := EXTRACT(YEAR FROM v_result)::int;
      IF v_year BETWEEN 1900 AND 2100 THEN
        RETURN v_result;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;

  -- 2. MM/DD/YYYY (US standard, 4-digit year)
  IF v_clean ~ '^\d{1,2}/\d{1,2}/\d{4}$' THEN
    BEGIN
      v_result := to_date(v_clean, 'FMMM/FMDD/YYYY');
      v_year := EXTRACT(YEAR FROM v_result)::int;
      IF v_year BETWEEN 1900 AND 2100 THEN
        RETURN v_result;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;

  -- 3. MM/DD/YY (2-digit year — apply Y2K pivot, NEVER trust raw)
  IF v_clean ~ '^\d{1,2}/\d{1,2}/\d{2}$' THEN
    BEGIN
      v_result := to_date(v_clean, 'FMMM/FMDD/YY');
      v_year := EXTRACT(YEAR FROM v_result)::int;
      -- to_date with YY may already pivot; normalise regardless.
      IF v_year BETWEEN 0 AND 29 THEN
        RETURN v_result + INTERVAL '2000 years';
      ELSIF v_year BETWEEN 30 AND 99 THEN
        RETURN v_result + INTERVAL '1900 years';
      ELSIF v_year BETWEEN 1900 AND 2100 THEN
        -- to_date already produced a sane 4-digit year (Postgres ≥ 12 pivots).
        RETURN v_result;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;

  -- 4. YYYY/MM/DD (rare but possible)
  IF v_clean ~ '^\d{4}/\d{1,2}/\d{1,2}$' THEN
    BEGIN
      v_result := to_date(v_clean, 'YYYY/FMMM/FMDD');
      v_year := EXTRACT(YEAR FROM v_result)::int;
      IF v_year BETWEEN 1900 AND 2100 THEN
        RETURN v_result;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;

  -- 5. MM-DD-YYYY / DD-MM-YYYY ambiguous — try MDY first
  IF v_clean ~ '^\d{1,2}-\d{1,2}-\d{4}$' THEN
    BEGIN
      v_result := to_date(v_clean, 'FMMM-FMDD-YYYY');
      v_year := EXTRACT(YEAR FROM v_result)::int;
      IF v_year BETWEEN 1900 AND 2100 THEN
        RETURN v_result;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;

  -- 6. Last-resort: explicit cast, but reject if year < 1900 to avoid the
  --    historic bug where '6/1/26'::date returned 0026-06-01.
  BEGIN
    v_result := v_clean::date;
    v_year := EXTRACT(YEAR FROM v_result)::int;
    IF v_year BETWEEN 1900 AND 2100 THEN
      RETURN v_result;
    ELSIF v_year BETWEEN 0 AND 29 THEN
      RETURN v_result + INTERVAL '2000 years';
    ELSIF v_year BETWEEN 30 AND 99 THEN
      RETURN v_result + INTERVAL '1900 years';
    END IF;
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RETURN NULL;
END;
$_$;


--
-- Name: FUNCTION _parse_import_date(date_str text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public._parse_import_date(date_str text) IS 'Parses CSV date strings safely. Tries ISO, MM/DD/YYYY, MM/DD/YY (with Y2K pivot), YYYY/MM/DD, and MM-DD-YYYY in order. Rejects results outside 1900..2100 to prevent 2-digit-year-AD bugs (e.g. ''6/1/26'' becoming 0026-06-01).';


