--
-- Name: _sync_profile_to_org_member(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._sync_profile_to_org_member() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_role text;
BEGIN
  -- No-op if either side of the (user_id, organization_id) pair is missing.
  IF NEW.user_id IS NULL OR NEW.organization_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Coerce legacy / out-of-list roles to 'staff' so the CHECK passes.
  v_role := CASE
    WHEN NEW.role IN ('owner', 'super_admin', 'admin', 'staff', 'read_only')
      THEN NEW.role
    ELSE 'staff'
  END;

  INSERT INTO public.organization_members
    (organization_id, user_id, role, is_default, joined_at)
  VALUES
    (NEW.organization_id, NEW.user_id, v_role, true, COALESCE(NEW.created_at, now()))
  ON CONFLICT (organization_id, user_id) DO NOTHING;

  RETURN NEW;
END;
$$;


--
-- Name: accept_team_invitation(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_team_invitation(p_token text, p_full_name text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_invitation record;
  v_profile_id uuid;
  v_user_email text;
BEGIN
  -- Get current user's email
  SELECT email INTO v_user_email
  FROM auth.users
  WHERE id = auth.uid();

  IF v_user_email IS NULL THEN
    RAISE EXCEPTION 'User not authenticated';
  END IF;

  -- Get and validate invitation with row-level lock to prevent race conditions
  SELECT * INTO v_invitation
  FROM team_invitations
  WHERE token = p_token
    AND status = 'pending'
    AND expires_at > now()
  FOR UPDATE SKIP LOCKED;

  IF v_invitation IS NULL THEN
    RAISE EXCEPTION 'Invalid or expired invitation';
  END IF;

  -- Check email matches
  IF lower(v_invitation.email) != lower(v_user_email) THEN
    RAISE EXCEPTION 'Invitation is for a different email address';
  END IF;

  -- Check user doesn't already have a profile in this org
  IF EXISTS (
    SELECT 1 FROM profiles
    WHERE user_id = auth.uid()
    AND organization_id = v_invitation.organization_id
  ) THEN
    RAISE EXCEPTION 'User already has a profile in this organization';
  END IF;

  -- Mark invitation as accepted FIRST to prevent race condition
  UPDATE team_invitations
  SET
    status = 'accepted',
    accepted_at = now(),
    updated_at = now()
  WHERE id = v_invitation.id
    AND status = 'pending';

  -- Verify the update happened (another transaction didn't beat us)
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invitation was already accepted';
  END IF;

  -- Create profile
  INSERT INTO profiles (
    user_id,
    organization_id,
    email,
    full_name,
    role,
    is_active
  ) VALUES (
    auth.uid(),
    v_invitation.organization_id,
    v_user_email,
    p_full_name,
    v_invitation.role,
    true
  )
  RETURNING id INTO v_profile_id;

  -- Update invitation with profile reference
  UPDATE team_invitations
  SET accepted_by = v_profile_id
  WHERE id = v_invitation.id;

  RETURN v_profile_id;
END;
$$;


--
-- Name: apply_age_65_auto_cancellation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_age_65_auto_cancellation(p_record_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r record;
  v_dob date;
  v_birthday_month date;
  v_count int := 0;
  v_results jsonb := '[]'::jsonb;
BEGIN
  FOR r IN
    SELECT cr.id,
           cr.organization_id,
           cr.title,
           cr.email,
           cr.owner_id,
           cr.advisor_id,
           cr.data->>'date_of_birth' AS dob_text
      FROM public.crm_records cr
      JOIN public.crm_modules m ON m.id = cr.module_id
     WHERE m.key IN ('contacts', 'members')
       AND cr.market_type = 'healthshare'
       AND cr.data ? 'date_of_birth'
       AND cr.data->>'date_of_birth' ~ '^\d{4}-\d{2}-\d{2}'
       AND (cr.status IS NULL OR cr.status NOT IN ('Cancelled', 'Terminated'))
       AND COALESCE((cr.data->>'age_65_cancel_override')::boolean, false) = false
       AND (p_record_id IS NULL OR cr.id = p_record_id)
  LOOP
    BEGIN
      v_dob := substring(r.dob_text from 1 for 10)::date;
    EXCEPTION WHEN OTHERS THEN
      CONTINUE;
    END;

    v_birthday_month := make_date(
      EXTRACT(YEAR FROM v_dob)::int + 65,
      EXTRACT(MONTH FROM v_dob)::int,
      1
    );

    IF v_birthday_month > CURRENT_DATE THEN
      CONTINUE;
    END IF;

    UPDATE public.crm_records
       SET status = 'Cancelled',
           cancellation_date = v_birthday_month,
           data = data || jsonb_build_object(
             'cancellation_date', v_birthday_month::text,
             'cancellation_reason', 'Aged out at 65',
             'auto_cancelled_at', now()::text
           ),
           updated_at = now()
     WHERE id = r.id;

    v_count := v_count + 1;
    v_results := v_results || jsonb_build_object(
      'record_id', r.id,
      'org_id', r.organization_id,
      'member_name', r.title,
      'member_email', r.email,
      'cancellation_date', v_birthday_month,
      'owner_id', r.owner_id
    );
  END LOOP;

  RETURN jsonb_build_object('count', v_count, 'cancelled', v_results);
END;
$$;


--
-- Name: FUNCTION apply_age_65_auto_cancellation(p_record_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.apply_age_65_auto_cancellation(p_record_id uuid) IS 'Auto-cancels HealthShare members at age 65 on the 1st of their birthday month. Pass a record id for live single-record application; pass NULL for the nightly batch. Returns {count, cancelled[]}. Queues rep email notifications via crm_age_65_cancellation_outbox.';


--
-- Name: apply_role_from_groups(uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_role_from_groups(u uuid, groups text[]) RETURNS public.user_role
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  new_role user_role;
BEGIN
  new_role := public.map_role_from_groups(groups);
  UPDATE public.profiles
     SET role = new_role,
         updated_at = now()
   WHERE id = u;
  RETURN new_role;
END;
$$;


--
-- Name: apply_sla_to_ticket(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_sla_to_ticket() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  policy_id uuid;
  policy_record RECORD;
  calculated_due_at timestamptz;
BEGIN
  -- Only apply SLA if not already set
  IF NEW.sla_due_at IS NOT NULL THEN
    RETURN NEW;
  END IF;

  BEGIN
    -- Match SLA policy based on ticket properties
    policy_id := match_sla_policy(to_jsonb(NEW));

    IF policy_id IS NOT NULL THEN
      SELECT * INTO policy_record FROM sla_policies WHERE id = policy_id;

      -- Calculate due date
      calculated_due_at := NEW.created_at + (policy_record.resolution_hours || ' hours')::interval;

      -- Update the ticket with SLA due date
      UPDATE tickets
      SET sla_due_at = calculated_due_at
      WHERE id = NEW.id;

      -- Insert SLA event record (with error handling)
      BEGIN
        INSERT INTO sla_events (ticket_id, event_type, sla_policy_id, due_at)
        VALUES (NEW.id, 'started', policy_id, calculated_due_at);
      EXCEPTION WHEN OTHERS THEN
        -- Log error but don't fail the ticket creation
        RAISE WARNING 'Failed to create SLA event for ticket %: %', NEW.id, SQLERRM;
      END;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    -- If SLA calculation fails completely, log but continue
    RAISE WARNING 'SLA calculation failed for ticket %: %', NEW.id, SQLERRM;
  END;

  RETURN NEW;
END;
$$;


--
-- Name: approve_payout_batch(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_payout_batch(p_batch_id uuid, p_approved_by uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_batch   record;
  v_config  jsonb;
  v_creator uuid;
BEGIN
  -- Lock the row
  SELECT * INTO v_batch
  FROM commission_payment_batches
  WHERE id = p_batch_id
  FOR UPDATE;

  IF v_batch IS NULL THEN
    RETURN jsonb_build_object('error', 'Batch not found');
  END IF;

  -- Idempotent: already processing
  IF v_batch.status = 'processing' THEN
    RETURN jsonb_build_object(
      'batch_id', p_batch_id,
      'status', 'processing',
      'already_approved', true,
      'approved_by', v_batch.approved_by,
      'approved_at', v_batch.approved_at
    );
  END IF;

  -- Only draft batches can be approved
  IF v_batch.status <> 'draft' THEN
    RETURN jsonb_build_object(
      'error', 'Batch cannot be approved from status: ' || v_batch.status
    );
  END IF;

  -- Load compliance config
  v_config := get_payout_compliance_config(v_batch.organization_id);

  -- Hard cap check
  IF v_batch.total_amount > (v_config->>'max_single_payout')::numeric THEN
    -- Log the block
    INSERT INTO payout_audit_log (
      organization_id, event_type, entity_type, entity_id,
      actor_id, actor_type, amount, details
    ) VALUES (
      v_batch.organization_id, 'threshold_exceeded', 'commission_payment_batch', p_batch_id,
      p_approved_by, 'user', v_batch.total_amount,
      jsonb_build_object('max_single_payout', v_config->>'max_single_payout')
    );
    RETURN jsonb_build_object(
      'error', 'Batch total $' || v_batch.total_amount || ' exceeds maximum payout limit of $' || (v_config->>'max_single_payout')
    );
  END IF;

  -- Separation of duties: find who created the batch
  SELECT actor_id INTO v_creator
  FROM payout_batch_logs
  WHERE batch_id = p_batch_id AND action = 'created'
  ORDER BY created_at LIMIT 1;

  -- Self-approve check
  IF v_creator IS NOT NULL
     AND v_creator = p_approved_by
     AND v_batch.total_amount > (v_config->>'self_approve_threshold')::numeric
  THEN
    INSERT INTO payout_audit_log (
      organization_id, event_type, entity_type, entity_id,
      actor_id, actor_type, amount, details
    ) VALUES (
      v_batch.organization_id, 'approval_blocked', 'commission_payment_batch', p_batch_id,
      p_approved_by, 'user', v_batch.total_amount,
      jsonb_build_object(
        'reason', 'creator_cannot_self_approve',
        'threshold', v_config->>'self_approve_threshold'
      )
    );
    RETURN jsonb_build_object(
      'error', 'Separation of duties: batch creator cannot approve batches above $' || (v_config->>'self_approve_threshold'),
      'code', 'SELF_APPROVE_BLOCKED'
    );
  END IF;

  -- Dual-approval check (for future: stub logs the requirement)
  -- When Phase A4+ adds a second approver field, this will enforce it.
  -- For now, log a warning in the audit trail if threshold is exceeded.
  IF v_batch.total_amount > (v_config->>'dual_approve_threshold')::numeric THEN
    INSERT INTO payout_audit_log (
      organization_id, event_type, entity_type, entity_id,
      actor_id, actor_type, amount, details
    ) VALUES (
      v_batch.organization_id, 'threshold_exceeded', 'commission_payment_batch', p_batch_id,
      p_approved_by, 'user', v_batch.total_amount,
      jsonb_build_object(
        'reason', 'dual_approval_recommended',
        'threshold', v_config->>'dual_approve_threshold'
      )
    );
  END IF;

  -- Transition: draft → processing
  UPDATE commission_payment_batches
  SET status = 'processing',
      approved_by = p_approved_by,
      approved_at = now(),
      updated_at = now()
  WHERE id = p_batch_id;

  -- Update payout items
  UPDATE commission_payouts
  SET status = 'processing',
      approved_by = p_approved_by,
      approved_at = now(),
      updated_at = now()
  WHERE id IN (
    SELECT DISTINCT payout_id FROM commission_ledger
    WHERE payout_batch_id = p_batch_id AND payout_id IS NOT NULL
  );

  -- Log to payout_batch_logs
  INSERT INTO payout_batch_logs (
    organization_id, batch_id, action,
    actor_id, actor_type,
    prev_status, new_status, details
  ) VALUES (
    v_batch.organization_id, p_batch_id, 'approved',
    p_approved_by, 'user',
    'draft', 'processing',
    jsonb_build_object(
      'batch_number', v_batch.batch_number,
      'total_amount', v_batch.total_amount,
      'total_advisors', v_batch.total_advisors
    )
  );

  -- Log to immutable audit
  INSERT INTO payout_audit_log (
    organization_id, event_type, entity_type, entity_id,
    actor_id, actor_type, prev_status, new_status,
    amount, details
  ) VALUES (
    v_batch.organization_id, 'batch_approved', 'commission_payment_batch', p_batch_id,
    p_approved_by, 'user', 'draft', 'processing',
    v_batch.total_amount,
    jsonb_build_object(
      'batch_number', v_batch.batch_number,
      'total_advisors', v_batch.total_advisors
    )
  );

  -- financial_audit_log
  INSERT INTO financial_audit_log (
    organization_id, action, entity_type, entity_id,
    performed_by, details
  ) VALUES (
    v_batch.organization_id, 'payout_approved', 'commission_payment_batch', p_batch_id,
    p_approved_by,
    jsonb_build_object(
      'batch_number', v_batch.batch_number,
      'total_amount', v_batch.total_amount,
      'total_advisors', v_batch.total_advisors
    )
  );

  RETURN jsonb_build_object(
    'batch_id', p_batch_id,
    'batch_number', v_batch.batch_number,
    'status', 'processing',
    'approved_by', p_approved_by,
    'approved_at', now(),
    'total_amount', v_batch.total_amount,
    'total_advisors', v_batch.total_advisors
  );
END;
$_$;


--
-- Name: approve_payout_batch(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_payout_batch(p_batch_id uuid, p_approved_by uuid, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_batch            record;
  v_config           jsonb;
  v_creator          uuid;
  v_existing_primary uuid;
  v_needs_dual       boolean;
  v_approval_type    text;
  v_approval_count   int;
BEGIN
  -- Lock the row
  SELECT * INTO v_batch
  FROM commission_payment_batches
  WHERE id = p_batch_id
  FOR UPDATE;

  IF v_batch IS NULL THEN
    RETURN jsonb_build_object('error', 'Batch not found');
  END IF;

  -- Idempotent: already processing
  IF v_batch.status = 'processing' THEN
    RETURN jsonb_build_object(
      'batch_id', p_batch_id,
      'status', 'processing',
      'already_approved', true,
      'approved_by', v_batch.approved_by,
      'approved_at', v_batch.approved_at
    );
  END IF;

  -- Only draft batches can be approved
  IF v_batch.status <> 'draft' THEN
    RETURN jsonb_build_object(
      'error', 'Batch cannot be approved from status: ' || v_batch.status
    );
  END IF;

  -- Load compliance config
  v_config := get_payout_compliance_config(v_batch.organization_id);

  -- Hard cap check
  IF v_batch.total_amount > (v_config->>'max_single_payout')::numeric THEN
    INSERT INTO payout_audit_log (
      organization_id, event_type, entity_type, entity_id,
      actor_id, actor_type, amount, details
    ) VALUES (
      v_batch.organization_id, 'threshold_exceeded', 'commission_payment_batch', p_batch_id,
      p_approved_by, 'user', v_batch.total_amount,
      jsonb_build_object('max_single_payout', v_config->>'max_single_payout')
    );
    RETURN jsonb_build_object(
      'error', 'Batch total $' || v_batch.total_amount || ' exceeds maximum payout limit of $' || (v_config->>'max_single_payout')
    );
  END IF;

  -- Find batch creator from logs
  SELECT actor_id INTO v_creator
  FROM payout_batch_logs
  WHERE batch_id = p_batch_id AND action = 'created'
  ORDER BY created_at LIMIT 1;

  -- Self-approve check (creator cannot approve above threshold)
  IF v_creator IS NOT NULL
     AND v_creator = p_approved_by
     AND v_batch.total_amount > (v_config->>'self_approve_threshold')::numeric
  THEN
    INSERT INTO payout_audit_log (
      organization_id, event_type, entity_type, entity_id,
      actor_id, actor_type, amount, details
    ) VALUES (
      v_batch.organization_id, 'approval_blocked', 'commission_payment_batch', p_batch_id,
      p_approved_by, 'user', v_batch.total_amount,
      jsonb_build_object(
        'reason', 'creator_cannot_self_approve',
        'threshold', v_config->>'self_approve_threshold'
      )
    );
    RETURN jsonb_build_object(
      'error', 'Separation of duties: batch creator cannot approve batches above $' || (v_config->>'self_approve_threshold'),
      'code', 'SELF_APPROVE_BLOCKED'
    );
  END IF;

  -- Determine if dual approval is needed
  v_needs_dual := v_batch.total_amount > (v_config->>'dual_approve_threshold')::numeric;

  -- Check existing approvals
  SELECT count(*) INTO v_approval_count
  FROM payout_approvals
  WHERE batch_id = p_batch_id;

  -- Check if this person already approved
  IF EXISTS (SELECT 1 FROM payout_approvals WHERE batch_id = p_batch_id AND approver_id = p_approved_by) THEN
    RETURN jsonb_build_object(
      'error', 'You have already approved this batch',
      'code', 'DUPLICATE_APPROVAL'
    );
  END IF;

  -- Determine approval type
  IF v_approval_count = 0 THEN
    v_approval_type := 'primary';
  ELSE
    v_approval_type := 'secondary';
  END IF;

  -- Record the approval
  INSERT INTO payout_approvals (
    organization_id, batch_id, approver_id,
    approval_type, notes
  ) VALUES (
    v_batch.organization_id, p_batch_id, p_approved_by,
    v_approval_type, p_notes
  );

  -- If dual approval needed and we only have primary → return pending
  IF v_needs_dual AND v_approval_type = 'primary' THEN
    -- Log the partial approval
    INSERT INTO payout_audit_log (
      organization_id, event_type, entity_type, entity_id,
      actor_id, actor_type, amount, details
    ) VALUES (
      v_batch.organization_id, 'batch_approved', 'commission_payment_batch', p_batch_id,
      p_approved_by, 'user', v_batch.total_amount,
      jsonb_build_object(
        'approval_type', 'primary',
        'dual_required', true,
        'awaiting_secondary', true,
        'threshold', v_config->>'dual_approve_threshold'
      )
    );

    INSERT INTO payout_batch_logs (
      organization_id, batch_id, action,
      actor_id, actor_type,
      prev_status, new_status, details
    ) VALUES (
      v_batch.organization_id, p_batch_id, 'approved',
      p_approved_by, 'user',
      'draft', 'draft',
      jsonb_build_object(
        'approval_type', 'primary',
        'dual_required', true,
        'note', 'Awaiting secondary approval'
      )
    );

    RETURN jsonb_build_object(
      'batch_id', p_batch_id,
      'status', 'draft',
      'approval_type', 'primary',
      'dual_required', true,
      'awaiting_secondary', true,
      'approved_by', p_approved_by,
      'message', 'Primary approval recorded. A second approver is required for batches above $' || (v_config->>'dual_approve_threshold')
    );
  END IF;

  -- All approvals met → transition to processing
  UPDATE commission_payment_batches
  SET status = 'processing',
      approved_by = p_approved_by,
      approved_at = now(),
      updated_at = now()
  WHERE id = p_batch_id;

  -- Update payout items
  UPDATE commission_payouts
  SET status = 'processing',
      approved_by = p_approved_by,
      approved_at = now(),
      updated_at = now()
  WHERE id IN (
    SELECT DISTINCT payout_id FROM commission_ledger
    WHERE payout_batch_id = p_batch_id AND payout_id IS NOT NULL
  );

  -- Log to payout_batch_logs
  INSERT INTO payout_batch_logs (
    organization_id, batch_id, action,
    actor_id, actor_type,
    prev_status, new_status, details
  ) VALUES (
    v_batch.organization_id, p_batch_id, 'approved',
    p_approved_by, 'user',
    'draft', 'processing',
    jsonb_build_object(
      'batch_number', v_batch.batch_number,
      'total_amount', v_batch.total_amount,
      'total_advisors', v_batch.total_advisors,
      'approval_type', v_approval_type,
      'dual_approval', v_needs_dual
    )
  );

  -- Immutable audit log
  INSERT INTO payout_audit_log (
    organization_id, event_type, entity_type, entity_id,
    actor_id, actor_type, prev_status, new_status,
    amount, details
  ) VALUES (
    v_batch.organization_id, 'batch_approved', 'commission_payment_batch', p_batch_id,
    p_approved_by, 'user', 'draft', 'processing',
    v_batch.total_amount,
    jsonb_build_object(
      'batch_number', v_batch.batch_number,
      'total_advisors', v_batch.total_advisors,
      'approval_type', v_approval_type,
      'dual_approval', v_needs_dual
    )
  );

  -- financial_audit_log
  INSERT INTO financial_audit_log (
    organization_id, action, entity_type, entity_id,
    performed_by, details
  ) VALUES (
    v_batch.organization_id, 'payout_approved', 'commission_payment_batch', p_batch_id,
    p_approved_by,
    jsonb_build_object(
      'batch_number', v_batch.batch_number,
      'total_amount', v_batch.total_amount,
      'total_advisors', v_batch.total_advisors,
      'approval_type', v_approval_type,
      'dual_approval', v_needs_dual
    )
  );

  RETURN jsonb_build_object(
    'batch_id', p_batch_id,
    'batch_number', v_batch.batch_number,
    'status', 'processing',
    'approved_by', p_approved_by,
    'approved_at', now(),
    'total_amount', v_batch.total_amount,
    'total_advisors', v_batch.total_advisors,
    'approval_type', v_approval_type,
    'dual_approval', v_needs_dual
  );
END;
$_$;


--
-- Name: archive_old_audit_logs(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_old_audit_logs(p_days_to_keep integer DEFAULT 90) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_deleted integer;
BEGIN
  -- Move to archive table or delete based on retention policy
  DELETE FROM public.system_audit_log
  WHERE timestamp < now() - (p_days_to_keep || ' days')::interval
    AND risk_level NOT IN ('high', 'critical'); -- Keep high-risk logs longer

  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted;
END;
$$;


--
-- Name: audit_log_hash_chain_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_log_hash_chain_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_previous_hash text;
BEGIN
  -- Get the previous hash for this organization
  SELECT entry_hash INTO v_previous_hash
  FROM public.unified_audit_logs
  WHERE organization_id = NEW.organization_id
  ORDER BY sequence_number DESC
  LIMIT 1
  FOR UPDATE SKIP LOCKED;

  -- Set previous hash (NULL for first entry in org)
  NEW.previous_hash := v_previous_hash;

  -- Compute entry hash
  NEW.entry_hash := compute_audit_entry_hash(
    NEW.sequence_number,
    NEW.previous_hash,
    NEW.organization_id,
    NEW.app_source,
    NEW.actor_id,
    NEW.action,
    NEW.target_entity_type,
    NEW.target_entity_id,
    NEW.details,
    NEW.created_at
  );

  RETURN NEW;
END;
$$;


--
-- Name: audit_staff_log_changes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_staff_log_changes() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_changes jsonb DEFAULT '{}'::jsonb;
  v_action text;
BEGIN
  IF (TG_OP = 'INSERT') THEN
    v_action := 'staff_log_create';
    v_changes := jsonb_build_object(
      'log_id', NEW.id,
      'log_number', NEW.log_number,
      'log_type', NEW.log_type,
      'title', NEW.title,
      'status', NEW.status,
      'priority', NEW.priority
    );
    
    PERFORM public.insert_audit_log(
      auth.uid(),
      NEW.created_by,
      v_action,
      v_changes
    );
    
  ELSIF (TG_OP = 'UPDATE') THEN
    v_action := 'staff_log_update';
    
    -- Track specific changes
    IF OLD.status IS DISTINCT FROM NEW.status THEN
      v_changes := v_changes || jsonb_build_object('status_changed', jsonb_build_object('from', OLD.status, 'to', NEW.status));
    END IF;
    
    IF OLD.priority IS DISTINCT FROM NEW.priority THEN
      v_changes := v_changes || jsonb_build_object('priority_changed', jsonb_build_object('from', OLD.priority, 'to', NEW.priority));
    END IF;
    
    IF OLD.assigned_to IS DISTINCT FROM NEW.assigned_to THEN
      v_changes := v_changes || jsonb_build_object('assigned_to_changed', jsonb_build_object('from', OLD.assigned_to, 'to', NEW.assigned_to));
    END IF;
    
    IF v_changes != '{}'::jsonb THEN
      v_changes := v_changes || jsonb_build_object('log_id', NEW.id, 'log_number', NEW.log_number);
      
      PERFORM public.insert_audit_log(
        auth.uid(),
        NULL,
        v_action,
        v_changes
      );
    END IF;
    
  ELSIF (TG_OP = 'DELETE') THEN
    v_action := 'staff_log_delete';
    v_changes := jsonb_build_object(
      'log_id', OLD.id,
      'log_number', OLD.log_number,
      'title', OLD.title
    );
    
    PERFORM public.insert_audit_log(
      auth.uid(),
      NULL,
      v_action,
      v_changes
    );
  END IF;
  
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: auto_cancel_expired_records(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_cancel_expired_records() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count integer;
BEGIN
  WITH expired AS (
    UPDATE crm_records
    SET status = 'Cancelled',
        data = COALESCE(data, '{}'::jsonb) || jsonb_build_object(
          'contact_status', 'Cancelled',
          'auto_cancelled_at', to_char(now(), 'YYYY-MM-DD'),
          'auto_cancelled_reason', 'Cancellation date passed'
        ),
        updated_at = now()
    WHERE cancellation_date IS NOT NULL
      AND cancellation_date < CURRENT_DATE
      AND status NOT IN ('Cancelled', 'Terminated', 'Archived', 'Deceased')
    RETURNING id
  )
  SELECT count(*) INTO v_count FROM expired;

  RETURN jsonb_build_object('cancelled_count', v_count);
END;
$$;


--
-- Name: auto_create_weekly_batches(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_create_weekly_batches() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_org            record;
  v_period_start   date;
  v_period_end     date;
  v_existing       int;
  v_batch_result   jsonb;
  v_created        int := 0;
  v_skipped        int := 0;
  v_failed         int := 0;
  v_org_results    jsonb := '[]'::jsonb;
BEGIN
  -- Period: last completed week (Monday to Sunday)
  -- e.g. if run on Friday 2026-03-06, covers Mon 2026-02-24 → Sun 2026-03-02
  v_period_end   := (date_trunc('week', current_date) - interval '1 day')::date;   -- Previous Sunday
  v_period_start := (v_period_end - interval '6 days')::date;                       -- Previous Monday

  FOR v_org IN
    SELECT id FROM organizations
    WHERE id IN (
      -- Only orgs that have at least one 'available' ledger entry in the period
      SELECT DISTINCT organization_id
      FROM commission_ledger
      WHERE status = 'available'
        AND created_at >= v_period_start::timestamptz
        AND created_at < (v_period_end + interval '1 day')::timestamptz
    )
  LOOP
    BEGIN
      -- Idempotency: skip if a batch already exists for this org + period
      SELECT count(*) INTO v_existing
      FROM commission_payment_batches
      WHERE organization_id = v_org.id
        AND period_start = v_period_start
        AND period_end = v_period_end
        AND status <> 'failed';  -- Allow retry after failure

      IF v_existing > 0 THEN
        v_skipped := v_skipped + 1;
        v_org_results := v_org_results || jsonb_build_object(
          'org_id', v_org.id, 'action', 'skipped', 'reason', 'batch_exists'
        );
        CONTINUE;
      END IF;

      -- Create batch via existing function (handles locking + ledger linking)
      v_batch_result := create_payout_batch(
        v_org.id,
        v_period_start,
        v_period_end,
        'Weekly auto-batch ' || v_period_start::text || ' to ' || v_period_end::text
      );

      -- Log creation
      IF v_batch_result ? 'batch_id' THEN
        INSERT INTO payout_batch_logs (
          organization_id, batch_id, action,
          actor_id, actor_type,
          prev_status, new_status,
          details
        ) VALUES (
          v_org.id,
          (v_batch_result->>'batch_id')::uuid,
          'created',
          NULL, 'cron',
          NULL, 'draft',
          jsonb_build_object(
            'trigger', 'auto_create_weekly_batches',
            'period_start', v_period_start,
            'period_end', v_period_end,
            'result', v_batch_result
          )
        );

        v_created := v_created + 1;
        v_org_results := v_org_results || jsonb_build_object(
          'org_id', v_org.id, 'action', 'created', 'batch', v_batch_result
        );
      ELSE
        v_failed := v_failed + 1;
        v_org_results := v_org_results || jsonb_build_object(
          'org_id', v_org.id, 'action', 'empty', 'result', v_batch_result
        );
      END IF;

    EXCEPTION WHEN OTHERS THEN
      v_failed := v_failed + 1;
      v_org_results := v_org_results || jsonb_build_object(
        'org_id', v_org.id, 'action', 'error', 'error', SQLERRM
      );
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'period_start', v_period_start,
    'period_end', v_period_end,
    'created', v_created,
    'skipped', v_skipped,
    'failed', v_failed,
    'orgs', v_org_results,
    'ran_at', now()
  );
END;
$$;


--
-- Name: auto_link_email_thread(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_link_email_thread() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_participant record;
  v_contact_id uuid;
BEGIN
  FOR v_participant IN SELECT * FROM jsonb_array_elements(NEW.participants)
  LOOP
    SELECT cr.id INTO v_contact_id
    FROM crm_records cr
    JOIN crm_modules cm ON cr.module_id = cm.id
    WHERE cr.organization_id = NEW.organization_id
      AND cm.key = 'Contacts'
      AND cr.data->>'Email' = v_participant.value->>'email'
    LIMIT 1;

    IF v_contact_id IS NOT NULL THEN
      NEW.linked_contact_id := v_contact_id;
      EXIT;
    END IF;
  END LOOP;

  RETURN NEW;
END;
$$;


--
-- Name: bulk_auto_merge_duplicates(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bulk_auto_merge_duplicates(p_org_id uuid, p_max_per_rule integer DEFAULT 1000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor_profile_id uuid;
  v_actor_org_id     uuid;
  v_actor_role       text;
  v_pair             RECORD;
  v_rpc_result       jsonb;

  v_rule1 int := 0;
  v_rule2 int := 0;
  v_rule3 int := 0;
  v_rule4 int := 0;
  v_rule5 int := 0;
  v_errors int := 0;
BEGIN
  IF p_org_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'p_org_id is required');
  END IF;
  IF p_max_per_rule IS NULL OR p_max_per_rule < 1 OR p_max_per_rule > 5000 THEN
    p_max_per_rule := 1000;
  END IF;

  SELECT id, organization_id, crm_role
    INTO v_actor_profile_id, v_actor_org_id, v_actor_role
    FROM public.profiles
   WHERE user_id = auth.uid()
   LIMIT 1;

  IF v_actor_profile_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;
  IF v_actor_role NOT IN ('crm_admin', 'crm_manager') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Only CRM admins and managers can run bulk merge');
  END IF;
  IF v_actor_org_id <> p_org_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'You can only run bulk merge for your own organization');
  END IF;

  -- Give ourselves headroom for large orgs. This is the same statement_timeout
  -- escalation the one-shot PIFH migration uses.
  PERFORM set_config('statement_timeout', '10min', true);

  -- ---- Rule 1: linked_member_id collisions -----------------------------
  FOR v_pair IN
    WITH pairs AS (
      SELECT
        (data->>'linked_member_id') AS member_id,
        id, organization_id, module_id, status, updated_at,
        (SELECT count(*) FROM crm_notes  n WHERE n.record_id = crm_records.id) +
        (SELECT count(*) FROM crm_tasks  t WHERE t.record_id = crm_records.id) +
        (SELECT count(*) FROM crm_attachments a WHERE a.record_id = crm_records.id)
          AS history_count
      FROM crm_records
      WHERE organization_id = p_org_id
        AND data ? 'linked_member_id'
        AND data->>'linked_member_id' <> ''
    ),
    grouped AS (
      SELECT member_id, module_id
        FROM pairs GROUP BY member_id, module_id HAVING COUNT(*) > 1
    ),
    ranked AS (
      SELECT p.*,
             ROW_NUMBER() OVER (
               PARTITION BY p.member_id, p.module_id
               ORDER BY p.history_count DESC,
                        (p.status = 'Active') DESC,
                        p.updated_at DESC NULLS LAST
             ) AS rn
        FROM pairs p
        JOIN grouped g ON g.member_id = p.member_id AND g.module_id = p.module_id
    )
    SELECT k.id AS keeper_id, d.id AS duplicate_id
      FROM ranked k
      JOIN ranked d
        ON d.member_id = k.member_id
       AND d.module_id = k.module_id
       AND k.rn = 1
       AND d.rn > 1
     WHERE NOT EXISTS (
       SELECT 1 FROM crm_duplicate_dismissals dd
        WHERE dd.organization_id = p_org_id
          AND dd.left_record_id  = LEAST(k.id, d.id)
          AND dd.right_record_id = GREATEST(k.id, d.id)
     )
     LIMIT p_max_per_rule
  LOOP
    BEGIN
      SELECT merge_crm_records(
        p_keeper_id    => v_pair.keeper_id,
        p_duplicate_id => v_pair.duplicate_id,
        p_user_id      => v_actor_profile_id
      ) INTO v_rpc_result;
      IF (v_rpc_result->>'success')::boolean THEN
        v_rule1 := v_rule1 + 1;
      ELSE
        v_errors := v_errors + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
    END;
  END LOOP;

  -- ---- Rule 2: enrollment-sync twins (zero history) --------------------
  FOR v_pair IN
    WITH sync_twins AS (
      SELECT id, organization_id, module_id, email, phone,
             data->>'first_name' AS first_name,
             data->>'last_name'  AS last_name
        FROM crm_records
       WHERE organization_id = p_org_id
         AND data->>'source' = 'enrollment_sync'
         AND NOT EXISTS (SELECT 1 FROM crm_notes       n WHERE n.record_id = crm_records.id)
         AND NOT EXISTS (SELECT 1 FROM crm_tasks       t WHERE t.record_id = crm_records.id)
         AND NOT EXISTS (SELECT 1 FROM crm_attachments a WHERE a.record_id = crm_records.id)
    )
    SELECT real_rec.id AS keeper_id, sync.id AS duplicate_id
      FROM sync_twins sync
      JOIN crm_records real_rec
        ON real_rec.id        <> sync.id
       AND real_rec.organization_id    = sync.organization_id
       AND real_rec.module_id = sync.module_id
       AND (
            (real_rec.email IS NOT NULL AND sync.email IS NOT NULL
               AND LOWER(real_rec.email) = LOWER(sync.email))
         OR (
            real_rec.phone IS NOT NULL AND sync.phone IS NOT NULL
               AND real_rec.phone = sync.phone
               AND sync.first_name IS NOT NULL AND sync.last_name IS NOT NULL
               AND LOWER(COALESCE(real_rec.data->>'first_name','')) = LOWER(sync.first_name)
               AND LOWER(COALESCE(real_rec.data->>'last_name', '')) = LOWER(sync.last_name)
            )
       )
     WHERE NOT EXISTS (
       SELECT 1 FROM crm_duplicate_dismissals dd
        WHERE dd.organization_id = p_org_id
          AND dd.left_record_id  = LEAST(real_rec.id, sync.id)
          AND dd.right_record_id = GREATEST(real_rec.id, sync.id)
     )
     LIMIT p_max_per_rule
  LOOP
    BEGIN
      SELECT merge_crm_records(
        p_keeper_id    => v_pair.keeper_id,
        p_duplicate_id => v_pair.duplicate_id,
        p_user_id      => v_actor_profile_id
      ) INTO v_rpc_result;
      IF (v_rpc_result->>'success')::boolean THEN
        v_rule2 := v_rule2 + 1;
      ELSE
        v_errors := v_errors + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
    END;
  END LOOP;

  -- ---- Rule 3: exact email, one side empty -----------------------------
  FOR v_pair IN
    WITH empties AS (
      SELECT id, organization_id, module_id, email
        FROM crm_records
       WHERE organization_id = p_org_id
         AND email IS NOT NULL AND email <> ''
         AND NOT EXISTS (SELECT 1 FROM crm_notes       n WHERE n.record_id = crm_records.id)
         AND NOT EXISTS (SELECT 1 FROM crm_tasks       t WHERE t.record_id = crm_records.id)
         AND NOT EXISTS (SELECT 1 FROM crm_attachments a WHERE a.record_id = crm_records.id)
    )
    SELECT real_rec.id AS keeper_id, empty.id AS duplicate_id
      FROM empties empty
      JOIN crm_records real_rec
        ON real_rec.id        <> empty.id
       AND real_rec.organization_id    = empty.organization_id
       AND real_rec.module_id = empty.module_id
       AND real_rec.email IS NOT NULL
       AND LOWER(real_rec.email) = LOWER(empty.email)
     WHERE NOT EXISTS (
       SELECT 1 FROM crm_duplicate_dismissals dd
        WHERE dd.organization_id = p_org_id
          AND dd.left_record_id  = LEAST(real_rec.id, empty.id)
          AND dd.right_record_id = GREATEST(real_rec.id, empty.id)
     )
     LIMIT p_max_per_rule
  LOOP
    BEGIN
      SELECT merge_crm_records(
        p_keeper_id    => v_pair.keeper_id,
        p_duplicate_id => v_pair.duplicate_id,
        p_user_id      => v_actor_profile_id
      ) INTO v_rpc_result;
      IF (v_rpc_result->>'success')::boolean THEN
        v_rule3 := v_rule3 + 1;
      ELSE
        v_errors := v_errors + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
    END;
  END LOOP;

  -- ---- Rule 4: phone + first + last, one side empty --------------------
  FOR v_pair IN
    WITH empties AS (
      SELECT id, organization_id, module_id, phone,
             data->>'first_name' AS first_name,
             data->>'last_name'  AS last_name
        FROM crm_records
       WHERE organization_id = p_org_id
         AND phone IS NOT NULL AND phone <> ''
         AND data->>'first_name' IS NOT NULL
         AND data->>'last_name'  IS NOT NULL
         AND NOT EXISTS (SELECT 1 FROM crm_notes       n WHERE n.record_id = crm_records.id)
         AND NOT EXISTS (SELECT 1 FROM crm_tasks       t WHERE t.record_id = crm_records.id)
         AND NOT EXISTS (SELECT 1 FROM crm_attachments a WHERE a.record_id = crm_records.id)
    )
    SELECT real_rec.id AS keeper_id, empty.id AS duplicate_id
      FROM empties empty
      JOIN crm_records real_rec
        ON real_rec.id        <> empty.id
       AND real_rec.organization_id    = empty.organization_id
       AND real_rec.module_id = empty.module_id
       AND real_rec.phone = empty.phone
       AND LOWER(COALESCE(real_rec.data->>'first_name','')) = LOWER(empty.first_name)
       AND LOWER(COALESCE(real_rec.data->>'last_name', '')) = LOWER(empty.last_name)
     WHERE NOT EXISTS (
       SELECT 1 FROM crm_duplicate_dismissals dd
        WHERE dd.organization_id = p_org_id
          AND dd.left_record_id  = LEAST(real_rec.id, empty.id)
          AND dd.right_record_id = GREATEST(real_rec.id, empty.id)
     )
     LIMIT p_max_per_rule
  LOOP
    BEGIN
      SELECT merge_crm_records(
        p_keeper_id    => v_pair.keeper_id,
        p_duplicate_id => v_pair.duplicate_id,
        p_user_id      => v_actor_profile_id
      ) INTO v_rpc_result;
      IF (v_rpc_result->>'success')::boolean THEN
        v_rule4 := v_rule4 + 1;
      ELSE
        v_errors := v_errors + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
    END;
  END LOOP;

  -- ---- Rule 5: DOB + first + last, one side empty ----------------------
  FOR v_pair IN
    WITH empties AS (
      SELECT id, organization_id, module_id,
             data->>'date_of_birth' AS dob,
             data->>'first_name'    AS first_name,
             data->>'last_name'     AS last_name
        FROM crm_records
       WHERE organization_id = p_org_id
         AND data->>'date_of_birth' IS NOT NULL
         AND data->>'date_of_birth' <> ''
         AND data->>'first_name' IS NOT NULL
         AND data->>'last_name'  IS NOT NULL
         AND NOT EXISTS (SELECT 1 FROM crm_notes       n WHERE n.record_id = crm_records.id)
         AND NOT EXISTS (SELECT 1 FROM crm_tasks       t WHERE t.record_id = crm_records.id)
         AND NOT EXISTS (SELECT 1 FROM crm_attachments a WHERE a.record_id = crm_records.id)
    )
    SELECT real_rec.id AS keeper_id, empty.id AS duplicate_id
      FROM empties empty
      JOIN crm_records real_rec
        ON real_rec.id        <> empty.id
       AND real_rec.organization_id    = empty.organization_id
       AND real_rec.module_id = empty.module_id
       AND real_rec.data->>'date_of_birth' = empty.dob
       AND LOWER(COALESCE(real_rec.data->>'first_name','')) = LOWER(empty.first_name)
       AND LOWER(COALESCE(real_rec.data->>'last_name', '')) = LOWER(empty.last_name)
     WHERE NOT EXISTS (
       SELECT 1 FROM crm_duplicate_dismissals dd
        WHERE dd.organization_id = p_org_id
          AND dd.left_record_id  = LEAST(real_rec.id, empty.id)
          AND dd.right_record_id = GREATEST(real_rec.id, empty.id)
     )
     LIMIT p_max_per_rule
  LOOP
    BEGIN
      SELECT merge_crm_records(
        p_keeper_id    => v_pair.keeper_id,
        p_duplicate_id => v_pair.duplicate_id,
        p_user_id      => v_actor_profile_id
      ) INTO v_rpc_result;
      IF (v_rpc_result->>'success')::boolean THEN
        v_rule5 := v_rule5 + 1;
      ELSE
        v_errors := v_errors + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'rule1',   v_rule1,
    'rule2',   v_rule2,
    'rule3',   v_rule3,
    'rule4',   v_rule4,
    'rule5',   v_rule5,
    'errors',  v_errors,
    'total',   v_rule1 + v_rule2 + v_rule3 + v_rule4 + v_rule5
  );
END;
$$;


--
-- Name: FUNCTION bulk_auto_merge_duplicates(p_org_id uuid, p_max_per_rule integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.bulk_auto_merge_duplicates(p_org_id uuid, p_max_per_rule integer) IS 'Tenant-generic bulk auto-merge. Runs the same moderate rule set as 202604210005 (linked_member_id, enrollment-sync twins, email/phone/DOB with empty-side) but for any org the caller admins. Respects the crm_duplicate_dismissals table. Returns per-rule counts.';


--
-- Name: bump_knowledge_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bump_knowledge_version() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  latest_version int;
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO knowledge_versions(article_id, version, title, content_md, created_by)
    VALUES(NEW.id, 1, NEW.title, NEW.content_md, NEW.author_id);
  ELSIF TG_OP = 'UPDATE' AND (OLD.title IS DISTINCT FROM NEW.title OR OLD.content_md IS DISTINCT FROM NEW.content_md) THEN
    SELECT COALESCE(MAX(version), 0) INTO latest_version
    FROM knowledge_versions
    WHERE article_id = NEW.id;

    INSERT INTO knowledge_versions(article_id, version, title, content_md, created_by)
    VALUES(NEW.id, latest_version + 1, NEW.title, NEW.content_md, NEW.author_id);
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: calculate_call_duration(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_call_duration() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.ended_at IS NOT NULL AND NEW.started_at IS NOT NULL THEN
    NEW.duration_seconds = EXTRACT(EPOCH FROM (NEW.ended_at - NEW.started_at))::int;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: calculate_enrollment_commission(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_enrollment_commission(p_enrollment_id uuid, p_commission_type text DEFAULT 'signup'::text) RETURNS numeric
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_enrollment enrollments%ROWTYPE;
  v_advisor advisors%ROWTYPE;
  v_rate commission_rates%ROWTYPE;
  v_vendor_cost numeric;
  v_net_amount numeric;
  v_commission numeric;
BEGIN
  -- Get enrollment
  SELECT * INTO v_enrollment FROM enrollments WHERE id = p_enrollment_id;
  IF v_enrollment IS NULL THEN RETURN 0; END IF;

  -- Get advisor
  SELECT * INTO v_advisor FROM advisors WHERE id = v_enrollment.advisor_id;
  IF v_advisor IS NULL OR NOT v_advisor.commission_eligible THEN RETURN 0; END IF;

  -- Get applicable commission rate
  SELECT * INTO v_rate
  FROM commission_rates
  WHERE organization_id = v_enrollment.organization_id
    AND (product_id IS NULL OR product_id = v_enrollment.product_id)
    AND (benefit_type_id IS NULL OR benefit_type_id = v_enrollment.benefit_type_id)
    AND (agent_level_id IS NULL OR agent_level_id = v_advisor.agent_level_id)
    AND is_active = true
    AND effective_date <= CURRENT_DATE
    AND (end_date IS NULL OR end_date > CURRENT_DATE)
  ORDER BY
    CASE WHEN product_id IS NOT NULL THEN 0 ELSE 1 END,
    CASE WHEN benefit_type_id IS NOT NULL THEN 0 ELSE 1 END,
    CASE WHEN agent_level_id IS NOT NULL THEN 0 ELSE 1 END
  LIMIT 1;

  IF v_rate IS NULL THEN RETURN 0; END IF;

  -- Get vendor cost (use function if exists, otherwise default to 0)
  v_vendor_cost := 0;

  -- Calculate net amount
  v_net_amount := COALESCE(v_enrollment.total_monthly_cost, 0) - v_vendor_cost;

  -- Calculate commission based on type
  CASE p_commission_type
    WHEN 'signup' THEN
      IF v_rate.signup_commission_percent > 0 THEN
        v_commission := v_net_amount * (v_rate.signup_commission_percent / 100);
      ELSE
        v_commission := v_rate.signup_commission;
      END IF;
    WHEN 'monthly' THEN
      IF v_rate.monthly_commission_percent > 0 THEN
        v_commission := v_net_amount * (v_rate.monthly_commission_percent / 100);
      ELSE
        v_commission := v_rate.monthly_commission;
      END IF;
    ELSE
      v_commission := 0;
  END CASE;

  RETURN COALESCE(v_commission, 0);
END;
$$;


--
-- Name: calculate_net_premium(numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_net_premium(p_full_premium numeric, p_tax_credit numeric) RETURNS TABLE(gross_premium numeric, tax_credit numeric, net_premium numeric)
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT
    p_full_premium                                  AS gross_premium,
    p_tax_credit                                    AS tax_credit,
    GREATEST(p_full_premium - p_tax_credit, 0)      AS net_premium;
$$;


--
-- Name: FUNCTION calculate_net_premium(p_full_premium numeric, p_tax_credit numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.calculate_net_premium(p_full_premium numeric, p_tax_credit numeric) IS 'Returns gross, credit, and net premium for display';


--
-- Name: calculate_next_billing_date(date, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_next_billing_date(p_current_date date, p_frequency text, p_billing_day integer) RETURNS date
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  next_date date;
  target_day integer;
BEGIN
  target_day := LEAST(p_billing_day, 28);
  
  CASE p_frequency
    WHEN 'monthly' THEN
      next_date := DATE_TRUNC('month', p_current_date) + INTERVAL '1 month' + (target_day - 1) * INTERVAL '1 day';
      IF next_date <= p_current_date THEN
        next_date := DATE_TRUNC('month', p_current_date) + INTERVAL '2 months' + (target_day - 1) * INTERVAL '1 day';
      END IF;
    WHEN 'quarterly' THEN
      next_date := DATE_TRUNC('month', p_current_date) + INTERVAL '3 months' + (target_day - 1) * INTERVAL '1 day';
      IF next_date <= p_current_date THEN
        next_date := DATE_TRUNC('month', p_current_date) + INTERVAL '6 months' + (target_day - 1) * INTERVAL '1 day';
      END IF;
    WHEN 'annual' THEN
      next_date := DATE_TRUNC('year', p_current_date) + INTERVAL '1 year' + (EXTRACT(MONTH FROM p_current_date) - 1) * INTERVAL '1 month' + (target_day - 1) * INTERVAL '1 day';
      IF next_date <= p_current_date THEN
        next_date := next_date + INTERVAL '1 year';
      END IF;
    ELSE
      next_date := p_current_date + INTERVAL '1 month';
  END CASE;
  
  RETURN next_date;
END;
$$;


--
-- Name: calculate_next_retry_time(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_next_retry_time(attempt_number integer) RETURNS timestamp with time zone
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  retry_delays integer[] := ARRAY[1, 3, 5, 7];
  delay_days integer;
BEGIN
  IF attempt_number > array_length(retry_delays, 1) THEN
    RETURN NULL;
  END IF;
  delay_days := retry_delays[attempt_number];
  RETURN now() + (delay_days || ' days')::interval;
END;
$$;


--
-- Name: calculate_premium(text, integer, text, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_premium(p_plan_code text, p_age integer, p_rating_area_code text, p_tobacco boolean DEFAULT false, p_year integer DEFAULT 2025) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_plan_id uuid;
  v_age_band_id uuid;
  v_rating_area_id uuid;
  v_monthly_rate numeric;
  v_tobacco_multiplier numeric;
  v_plan_state text;
BEGIN
  -- 1. Resolve plan_id via indexed plan_code lookup
  SELECT id, rating_area_state
  INTO v_plan_id, v_plan_state
  FROM plans
  WHERE (plan_code = p_plan_code OR code = p_plan_code)
    AND is_active = true
  LIMIT 1;

  IF v_plan_id IS NULL THEN
    RAISE EXCEPTION 'Plan not found: %', p_plan_code;
  END IF;

  -- 2. Resolve age band via indexed range lookup
  SELECT id INTO v_age_band_id
  FROM age_bands
  WHERE p_age >= min_age AND p_age <= max_age
  LIMIT 1;

  IF v_age_band_id IS NULL THEN
    RAISE EXCEPTION 'No age band for age: %', p_age;
  END IF;

  -- 3. Resolve rating area via indexed code lookup
  SELECT id INTO v_rating_area_id
  FROM rating_areas
  WHERE rating_area_code = p_rating_area_code
    AND is_active = true;

  -- Fallback to DEFAULT area if specific area not found
  IF v_rating_area_id IS NULL THEN
    SELECT id INTO v_rating_area_id
    FROM rating_areas
    WHERE rating_area_code = 'DEFAULT-001';
  END IF;

  IF v_rating_area_id IS NULL THEN
    RAISE EXCEPTION 'Rating area not found: %', p_rating_area_code;
  END IF;

  -- 4. Look up rate via composite index (single index scan)
  SELECT monthly_rate INTO v_monthly_rate
  FROM plan_rates
  WHERE plan_id = v_plan_id
    AND rating_area_id = v_rating_area_id
    AND age_band_id = v_age_band_id
    AND tobacco = false  -- Always get non-tobacco base rate
    AND effective_year = p_year;

  IF v_monthly_rate IS NULL THEN
    RAISE EXCEPTION 'No rate found for plan=%, area=%, age=%, year=%',
      p_plan_code, p_rating_area_code, p_age, p_year;
  END IF;

  -- 5. Apply tobacco multiplier from configurable table
  IF p_tobacco THEN
    SELECT multiplier INTO v_tobacco_multiplier
    FROM tobacco_multipliers
    WHERE (state = COALESCE(v_plan_state, 'DEFAULT') OR state = 'DEFAULT')
      AND effective_year = p_year
    ORDER BY CASE WHEN state = 'DEFAULT' THEN 1 ELSE 0 END
    LIMIT 1;

    v_tobacco_multiplier := COALESCE(v_tobacco_multiplier, 1.5);
    v_monthly_rate := ROUND(v_monthly_rate * v_tobacco_multiplier, 2);
  END IF;

  -- 6. Return final monthly premium
  RETURN v_monthly_rate;
END;
$$;


--
-- Name: FUNCTION calculate_premium(p_plan_code text, p_age integer, p_rating_area_code text, p_tobacco boolean, p_year integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.calculate_premium(p_plan_code text, p_age integer, p_rating_area_code text, p_tobacco boolean, p_year integer) IS 'Enterprise premium calculation: plan_code, age, area, tobacco, year → monthly rate';


--
-- Name: calculate_premium(text, integer, text, boolean, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_premium(p_plan_code text, p_age integer, p_rating_area_code text, p_tobacco boolean DEFAULT false, p_year integer DEFAULT 2025, p_benefit_tier text DEFAULT NULL::text) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_plan_id uuid;
  v_age_band_id uuid;
  v_rating_area_id uuid;
  v_monthly_rate numeric;
  v_tobacco_multiplier numeric;
  v_plan_state text;
  v_tier_modifier numeric := 1.0;
  v_tier_adjustment numeric := 0;
BEGIN
  -- 1. Resolve plan_id
  SELECT id, rating_area_state INTO v_plan_id, v_plan_state
  FROM plans
  WHERE (plan_code = p_plan_code OR code = p_plan_code)
    AND is_active = true
  LIMIT 1;

  IF v_plan_id IS NULL THEN
    RAISE EXCEPTION 'Plan not found: %', p_plan_code;
  END IF;

  -- 2. Resolve age band
  SELECT id INTO v_age_band_id
  FROM age_bands
  WHERE p_age >= min_age AND p_age <= max_age
  LIMIT 1;

  IF v_age_band_id IS NULL THEN
    RAISE EXCEPTION 'No age band for age: %', p_age;
  END IF;

  -- 3. Resolve rating area (with DEFAULT fallback)
  SELECT id INTO v_rating_area_id
  FROM rating_areas
  WHERE rating_area_code = p_rating_area_code AND is_active = true;

  IF v_rating_area_id IS NULL THEN
    SELECT id INTO v_rating_area_id
    FROM rating_areas WHERE rating_area_code = 'DEFAULT-001';
  END IF;

  IF v_rating_area_id IS NULL THEN
    RAISE EXCEPTION 'Rating area not found: %', p_rating_area_code;
  END IF;

  -- 4. Look up base rate (single composite index scan)
  SELECT monthly_rate INTO v_monthly_rate
  FROM plan_rates
  WHERE plan_id = v_plan_id
    AND rating_area_id = v_rating_area_id
    AND age_band_id = v_age_band_id
    AND tobacco = false
    AND effective_year = p_year;

  IF v_monthly_rate IS NULL THEN
    RAISE EXCEPTION 'No rate for plan=%, area=%, age=%, year=%',
      p_plan_code, p_rating_area_code, p_age, p_year;
  END IF;

  -- 5. Apply benefit tier modifier (Phase K)
  IF p_benefit_tier IS NOT NULL THEN
    SELECT pbm.premium_modifier, pbm.fixed_adjustment
    INTO v_tier_modifier, v_tier_adjustment
    FROM plan_benefit_matrix pbm
    JOIN benefit_tiers bt ON bt.id = pbm.benefit_tier_id
    WHERE pbm.plan_id = v_plan_id
      AND bt.tier_code = p_benefit_tier
      AND pbm.active = true;

    v_tier_modifier := COALESCE(v_tier_modifier, 1.0);
    v_tier_adjustment := COALESCE(v_tier_adjustment, 0);
  END IF;

  -- Apply tier: final = base × modifier + adjustment
  v_monthly_rate := ROUND(v_monthly_rate * v_tier_modifier + v_tier_adjustment, 2);

  -- 6. Apply tobacco multiplier
  IF p_tobacco THEN
    SELECT multiplier INTO v_tobacco_multiplier
    FROM tobacco_multipliers
    WHERE (state = COALESCE(v_plan_state, 'DEFAULT') OR state = 'DEFAULT')
      AND effective_year = p_year
    ORDER BY CASE WHEN state = 'DEFAULT' THEN 1 ELSE 0 END
    LIMIT 1;

    v_tobacco_multiplier := COALESCE(v_tobacco_multiplier, 1.5);
    v_monthly_rate := ROUND(v_monthly_rate * v_tobacco_multiplier, 2);
  END IF;

  RETURN v_monthly_rate;
END;
$$;


--
-- Name: calculate_system_uptime(text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_system_uptime(p_component_name text, p_start_date timestamp with time zone, p_end_date timestamp with time zone) RETURNS TABLE(uptime_percentage numeric, total_checks bigint, healthy_checks bigint, warning_checks bigint, error_checks bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    ROUND(
      (COUNT(*) FILTER (WHERE status = 'healthy')::numeric / NULLIF(COUNT(*)::numeric, 0)) * 100,
      2
    ) as uptime_percentage,
    COUNT(*) as total_checks,
    COUNT(*) FILTER (WHERE status = 'healthy') as healthy_checks,
    COUNT(*) FILTER (WHERE status = 'warning') as warning_checks,
    COUNT(*) FILTER (WHERE status = 'error') as error_checks
  FROM system_health_logs
  WHERE component_name = p_component_name
    AND checked_at BETWEEN p_start_date AND p_end_date;
END;
$$;


--
-- Name: can_access_organization(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_access_organization(p_org_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_super boolean;
  v_user_org_id uuid;
BEGIN
  SELECT is_super_admin, organization_id 
  INTO v_is_super, v_user_org_id
  FROM public.profiles 
  WHERE user_id = auth.uid() 
  LIMIT 1;
  
  -- Super admins can access any organization
  IF v_is_super = true THEN
    RETURN true;
  END IF;
  
  -- Regular users can only access their own organization
  RETURN v_user_org_id = p_org_id;
END;
$$;


--
-- Name: FUNCTION can_access_organization(p_org_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.can_access_organization(p_org_id uuid) IS 'Returns true if user can access the specified organization';


--
-- Name: can_user_send_email(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_user_send_email(p_profile_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_settings user_email_settings%ROWTYPE;
BEGIN
  SELECT * INTO v_settings FROM user_email_settings WHERE profile_id = p_profile_id;

  -- No settings = no restrictions
  IF v_settings.id IS NULL THEN
    RETURN true;
  END IF;

  -- Reset if new day
  IF v_settings.last_send_reset_at < CURRENT_DATE THEN
    UPDATE user_email_settings
    SET emails_sent_today = 0, last_send_reset_at = CURRENT_DATE
    WHERE profile_id = p_profile_id;
    RETURN true;
  END IF;

  -- Check limit
  RETURN v_settings.emails_sent_today < v_settings.daily_send_limit;
END;
$$;


--
-- Name: cancel_future_billing_on_enrollment_cancelled(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_future_billing_on_enrollment_cancelled() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  IF NEW.status = 'cancelled' AND OLD.status <> 'cancelled' THEN
    UPDATE billing_schedules
    SET status = 'cancelled',
        cancelled_at = now(),
        cancelled_reason = COALESCE(NEW.inactive_reason, 'enrollment_cancelled'),
        end_date = COALESCE(NEW.end_date, CURRENT_DATE),
        updated_at = now()
    WHERE enrollment_id = NEW.id
      AND status IN ('active', 'paused');

    UPDATE commissions
    SET status = 'cancelled',
        status_reason = 'enrollment_cancelled',
        updated_at = now()
    WHERE enrollment_id = NEW.id
      AND status = 'pending';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: cancel_long_running_queries(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_long_running_queries() RETURNS TABLE(pid integer, duration interval, query_text text, cancelled boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    a.pid::int,
    now() - a.query_start AS duration,
    LEFT(a.query, 200) AS query_text,
    pg_cancel_backend(a.pid) AS cancelled
  FROM pg_stat_activity a
  WHERE a.state = 'active'
    AND a.query_start < now() - interval '2 minutes'
    AND a.pid != pg_backend_pid()
    AND a.query NOT LIKE '%pg_stat_activity%';
END;
$$;


--
-- Name: check_approval_required(uuid, text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_approval_required(p_org_id uuid, p_entity_type text, p_entity_id uuid, p_action text, p_data jsonb) RETURNS TABLE(required boolean, rule_id uuid, rule_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_rule record;
BEGIN
  FOR v_rule IN
    SELECT agr.id, agr.name, agr.trigger_conditions
    FROM approval_guard_rules agr
    WHERE agr.organization_id = p_org_id
      AND agr.entity_type = p_entity_type
      AND agr.is_active = true
    ORDER BY agr.priority DESC
  LOOP
    IF p_data ? (v_rule.trigger_conditions->>'field') THEN
      required := true;
      rule_id := v_rule.id;
      rule_name := v_rule.name;
      RETURN NEXT;
      RETURN;
    END IF;
  END LOOP;

  required := false;
  RETURN NEXT;
END;
$$;


--
-- Name: check_approval_required(uuid, uuid, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_approval_required(p_org_id uuid, p_module_id uuid, p_trigger_type text, p_record_data jsonb, p_trigger_context jsonb DEFAULT '{}'::jsonb) RETURNS TABLE(rule_id uuid, process_id uuid, rule_name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rule RECORD;
  v_cond_array jsonb;
  v_condition RECORD;
  v_logic text;
  v_matches boolean;
  v_field_value jsonb;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM profiles WHERE user_id = auth.uid() AND organization_id = p_org_id
  ) THEN
    RETURN;
  END IF;

  FOR v_rule IN
    SELECT * FROM crm_approval_rules
    WHERE crm_approval_rules.organization_id = p_org_id
      AND crm_approval_rules.module_id = p_module_id
      AND crm_approval_rules.trigger_type = p_trigger_type
      AND crm_approval_rules.is_enabled = true
    ORDER BY priority ASC
  LOOP
    -- conditions is jsonb with {logic, conditions[]} structure
    v_cond_array := COALESCE(v_rule.conditions->'conditions', '[]'::jsonb);
    v_logic := COALESCE(v_rule.conditions->>'logic', 'AND');

    IF jsonb_array_length(v_cond_array) = 0 THEN
      rule_id := v_rule.id;
      process_id := v_rule.process_id;
      rule_name := v_rule.name;
      RETURN NEXT;
      CONTINUE;
    END IF;

    v_matches := CASE WHEN upper(v_logic) = 'AND' THEN true ELSE false END;

    FOR v_condition IN
      SELECT * FROM jsonb_to_recordset(v_cond_array)
      AS x(field text, operator text, value jsonb)
    LOOP
      v_field_value := p_record_data->v_condition.field;

      DECLARE
        v_cond_met boolean := false;
      BEGIN
        CASE v_condition.operator
          WHEN 'equals' THEN
            v_cond_met := v_field_value = v_condition.value;
          WHEN 'not_equals' THEN
            v_cond_met := v_field_value != v_condition.value;
          WHEN 'greater_than' THEN
            v_cond_met := (v_field_value::text)::numeric > (v_condition.value::text)::numeric;
          WHEN 'less_than' THEN
            v_cond_met := (v_field_value::text)::numeric < (v_condition.value::text)::numeric;
          WHEN 'contains' THEN
            v_cond_met := v_field_value::text ILIKE '%' || (v_condition.value#>>'{}') || '%';
          WHEN 'in' THEN
            v_cond_met := v_field_value <@ v_condition.value;
          WHEN 'changed' THEN
            v_cond_met := p_trigger_context ? v_condition.field;
          ELSE
            v_cond_met := false;
        END CASE;

        IF upper(v_logic) = 'AND' AND NOT v_cond_met THEN
          v_matches := false;
          EXIT;
        ELSIF upper(v_logic) = 'OR' AND v_cond_met THEN
          v_matches := true;
          EXIT;
        END IF;
      END;
    END LOOP;

    IF v_matches THEN
      rule_id := v_rule.id;
      process_id := v_rule.process_id;
      rule_name := v_rule.name;
      RETURN NEXT;
    END IF;
  END LOOP;
END;
$$;


--
-- Name: check_crm_duplicate(uuid, uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_crm_duplicate(p_org_id uuid, p_module_id uuid, p_email text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_exclude_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, title text, email text, phone text, status text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT r.id, r.title, r.email, r.phone, r.status, r.created_at
  FROM crm_records r
  WHERE r.organization_id = p_org_id
    AND r.module_id = p_module_id
    AND (p_exclude_id IS NULL OR r.id != p_exclude_id)
    AND (
      -- Primary: match by email (case-insensitive)
      (p_email IS NOT NULL AND p_email != '' AND LOWER(r.email) = LOWER(p_email))
      OR
      -- Fallback: match by phone only when no email provided
      (
        (p_email IS NULL OR p_email = '')
        AND p_phone IS NOT NULL AND p_phone != ''
        AND r.phone = p_phone
      )
    )
  LIMIT 5;
END;
$$;


--
-- Name: FUNCTION check_crm_duplicate(p_org_id uuid, p_module_id uuid, p_email text, p_phone text, p_exclude_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.check_crm_duplicate(p_org_id uuid, p_module_id uuid, p_email text, p_phone text, p_exclude_id uuid) IS 'Check for duplicate CRM records by email (primary) or phone (fallback). Used for pre-insert validation.';


--
-- Name: check_org_plan_feature(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_org_plan_feature(p_org_id uuid, p_feature_key text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_plan text;
  v_features_by_plan constant jsonb := '{
    "trial":      ["basic_crm", "basic_reports", "basic_enrollments"],
    "standard":   ["basic_crm", "basic_reports", "basic_enrollments",
                   "custom_fields", "email_templates", "advisor_hierarchy"],
    "pro":        ["basic_crm", "basic_reports", "basic_enrollments",
                   "custom_fields", "email_templates", "advisor_hierarchy",
                   "automations", "advanced_reports", "carrier_database",
                   "premium_compare", "audit_logs"],
    "enterprise": ["basic_crm", "basic_reports", "basic_enrollments",
                   "custom_fields", "email_templates", "advisor_hierarchy",
                   "automations", "advanced_reports", "carrier_database",
                   "premium_compare", "audit_logs",
                   "api_access", "sso", "white_label", "dedicated_support",
                   "data_export", "custom_branding"]
  }'::jsonb;
BEGIN
  SELECT plan INTO v_plan
    FROM public.organizations
   WHERE id = p_org_id;

  IF v_plan IS NULL THEN RETURN false; END IF;

  RETURN (v_features_by_plan->v_plan) ? p_feature_key;
END;
$$;


--
-- Name: FUNCTION check_org_plan_feature(p_org_id uuid, p_feature_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.check_org_plan_feature(p_org_id uuid, p_feature_key text) IS 'Returns true if org_id''s plan tier includes feature key. Plan-feature matrix is hard-coded inside the function body for now; lift into a settings table when the matrix needs to change without a migration.';


--
-- Name: check_org_seat_capacity(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_org_seat_capacity(p_org_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_limit int;
  v_used  int;
BEGIN
  SELECT seats_limit INTO v_limit
    FROM public.organizations
   WHERE id = p_org_id;

  IF v_limit IS NULL THEN
    RETURN true;  -- unlimited
  END IF;

  SELECT public.count_org_active_seats(p_org_id) INTO v_used;
  RETURN v_used < v_limit;
END;
$$;


--
-- Name: check_product_eligibility(uuid, integer, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_product_eligibility(p_plan_id uuid, p_member_age integer, p_member_state text DEFAULT NULL::text, p_household_size integer DEFAULT 1) RETURNS TABLE(is_eligible boolean, failed_rules jsonb)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rule record;
  v_failed_rules jsonb := '[]'::jsonb;
  v_is_eligible boolean := true;
  v_rule_passed boolean;
BEGIN
  FOR v_rule IN
    SELECT * FROM product_eligibility_rules
    WHERE plan_id = p_plan_id AND is_active = true
    ORDER BY sort_order
  LOOP
    v_rule_passed := true;

    CASE v_rule.rule_type
      WHEN 'age' THEN
        IF p_member_age < (v_rule.config->>'min_age')::integer OR
           p_member_age > (v_rule.config->>'max_age')::integer THEN
          v_rule_passed := false;
        END IF;

      WHEN 'state' THEN
        IF p_member_state IS NOT NULL THEN
          IF v_rule.config->>'mode' = 'include' THEN
            IF NOT (v_rule.config->'states') ? p_member_state THEN
              v_rule_passed := false;
            END IF;
          ELSIF v_rule.config->>'mode' = 'exclude' THEN
            IF (v_rule.config->'states') ? p_member_state THEN
              v_rule_passed := false;
            END IF;
          END IF;
        END IF;

      WHEN 'household' THEN
        IF p_household_size > (v_rule.config->>'max_size')::integer THEN
          v_rule_passed := false;
        END IF;

      ELSE
        -- Custom rules would need application logic
        NULL;
    END CASE;

    IF NOT v_rule_passed THEN
      IF v_rule.is_blocking THEN
        v_is_eligible := false;
      END IF;
      v_failed_rules := v_failed_rules || jsonb_build_object(
        'rule_id', v_rule.id,
        'rule_name', v_rule.rule_name,
        'rule_type', v_rule.rule_type,
        'error_message', COALESCE(v_rule.error_message, 'Eligibility requirement not met'),
        'is_blocking', v_rule.is_blocking
      );
    END IF;
  END LOOP;

  RETURN QUERY SELECT v_is_eligible, v_failed_rules;
END;
$$;


--
-- Name: check_rate_limit(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_rate_limit(p_identifier text, p_endpoint text, p_max_requests integer DEFAULT 100, p_window_seconds integer DEFAULT 60) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_window_start timestamptz;
  v_count integer;
BEGIN
  -- Truncate current time to the window boundary using p_window_seconds
  v_window_start := to_timestamp(
    floor(extract(epoch FROM now()) / p_window_seconds) * p_window_seconds
  );

  INSERT INTO public.rate_limits (identifier, endpoint, window_start, request_count)
  VALUES (p_identifier, p_endpoint, v_window_start, 1)
  ON CONFLICT (identifier, endpoint, window_start)
  DO UPDATE SET request_count = rate_limits.request_count + 1
  RETURNING request_count INTO v_count;

  RETURN v_count <= p_max_requests;
END;
$$;


--
-- Name: FUNCTION check_rate_limit(p_identifier text, p_endpoint text, p_max_requests integer, p_window_seconds integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.check_rate_limit(p_identifier text, p_endpoint text, p_max_requests integer, p_window_seconds integer) IS 'Checks and increments rate limit counter, returns true if under limit';


