--
-- Name: claim_pending_emails(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_pending_emails(batch_size integer DEFAULT 50) RETURNS SETOF public.notification_queue
    LANGUAGE sql
    SET search_path TO 'public'
    AS $$
  UPDATE notification_queue
  SET status = 'sending',
      attempts = attempts + 1,
      last_attempt_at = now(),
      updated_at = now()
  WHERE id IN (
    SELECT id
    FROM notification_queue
    WHERE status = 'pending'
      AND channel = 'email'
      AND scheduled_for <= now()
    ORDER BY scheduled_for ASC
    LIMIT batch_size
    FOR UPDATE SKIP LOCKED
  )
  RETURNING *;
$$;


--
-- Name: claim_scheduler_job(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_scheduler_job(p_job_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_claimed boolean;
BEGIN
  UPDATE crm_scheduler_jobs
  SET status = 'processing',
      attempts = attempts + 1,
      last_attempt_at = now()
  WHERE id = p_job_id
    AND status = 'pending'
  RETURNING true INTO v_claimed;
  
  RETURN COALESCE(v_claimed, false);
END;
$$;


--
-- Name: classify_market_type(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.classify_market_type(p_product text, p_carrier text, p_coverage text DEFAULT NULL::text, p_iua text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_product text := LOWER(COALESCE(p_product, ''));
  v_carrier text := LOWER(COALESCE(p_carrier, ''));
  v_coverage text := LOWER(COALESCE(p_coverage, ''));
BEGIN
  IF v_product ~ '(health\s*share|sharing|ministry|impact|knew\s*health|oneshare|sedera|liberty|zion|aliera|medishare|samaritan|mpowering|mpb|mpower|jericho|unite|chr\b)'
    OR v_carrier ~ '(health\s*share|sharing|ministry|impact|knew\s*health|oneshare|sedera|liberty|zion|aliera|medishare|samaritan|mpowering|mpb|mpower|jericho|unite|chr\b)'
    OR v_coverage ~ '(sharing|iua|unshareable)'
  THEN
    RETURN 'healthshare';
  END IF;

  IF NULLIF(TRIM(COALESCE(p_iua, '')), '') IS NOT NULL THEN
    RETURN 'healthshare';
  END IF;

  IF v_carrier ~ '(blue\s*cross|bcbs|aetna|united\s*health|cigna|humana|anthem|kaiser|molina|centene|oscar|ambetter|caresource|coventry|wellcare|bright\s*health|friday|clover)'
    OR v_product ~ '(hmo|ppo|epo|pos|marketplace|aca|exchange|medicaid|medicare|cobra|short.term|gap|supplemental|indemnity)'
  THEN
    RETURN 'traditional_insurance';
  END IF;

  RETURN 'unknown';
END;
$$;


--
-- Name: FUNCTION classify_market_type(p_product text, p_carrier text, p_coverage text, p_iua text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.classify_market_type(p_product text, p_carrier text, p_coverage text, p_iua text) IS 'Classifies a CRM record as healthshare, traditional_insurance, or unknown based on product name, carrier name, coverage option, and IUA amount.';


