--
-- Name: commission_to_crm_sync_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commission_to_crm_sync_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF (TG_OP = 'INSERT') THEN
    PERFORM public.recalc_crm_commission_summary(NEW.member_id, NEW.organization_id);
    RETURN NEW;
  ELSIF (TG_OP = 'UPDATE') THEN
    PERFORM public.recalc_crm_commission_summary(NEW.member_id, NEW.organization_id);
    IF OLD.member_id IS DISTINCT FROM NEW.member_id OR OLD.organization_id IS DISTINCT FROM NEW.organization_id THEN
      PERFORM public.recalc_crm_commission_summary(OLD.member_id, OLD.organization_id);
    END IF;
    RETURN NEW;
  ELSIF (TG_OP = 'DELETE') THEN
    PERFORM public.recalc_crm_commission_summary(OLD.member_id, OLD.organization_id);
    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: compare_network_coverage(uuid[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compare_network_coverage(p_network_ids uuid[], p_zip_code text) RETURNS TABLE(network_id uuid, network_name text, network_type text, carrier_name text, total_providers integer, preferred_providers integer, specialty_coverage jsonb, coverage_score numeric, coverage_grade text, avg_tier_discount numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    pn.id                AS network_id,
    pn.network_name,
    pn.network_type,
    ic.carrier_name,
    COALESCE(ncz.provider_count, 0)  AS total_providers,
    COALESCE(ncz.preferred_count, 0) AS preferred_providers,
    COALESCE(ncz.specialty_coverage, '{}'::jsonb) AS specialty_coverage,
    COALESCE(ncz.coverage_score, 0)  AS coverage_score,
    CASE
      WHEN COALESCE(ncz.coverage_score, 0) >= 90 THEN 'A'
      WHEN COALESCE(ncz.coverage_score, 0) >= 70 THEN 'B'
      WHEN COALESCE(ncz.coverage_score, 0) >= 50 THEN 'C'
      WHEN COALESCE(ncz.coverage_score, 0) >= 30 THEN 'D'
      ELSE 'F'
    END                  AS coverage_grade,
    COALESCE(
      (SELECT ROUND(AVG(np2.tier_discount_pct), 2)
       FROM network_providers np2
       WHERE np2.network_id = pn.id AND np2.is_active = true),
      0
    )                    AS avg_tier_discount
  FROM provider_networks pn
  LEFT JOIN network_coverage_zips ncz
    ON ncz.network_id = pn.id AND ncz.zip_code = p_zip_code
  LEFT JOIN insurance_carriers ic ON ic.id = pn.carrier_id
  WHERE pn.id = ANY(p_network_ids)
    AND pn.is_active = true
  ORDER BY COALESCE(ncz.coverage_score, 0) DESC;
END;
$$;


--
-- Name: compare_premiums(text[], integer, text, boolean, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compare_premiums(p_plan_codes text[], p_age integer, p_rating_area_code text, p_tobacco boolean DEFAULT false, p_year integer DEFAULT 2025, p_benefit_tier text DEFAULT NULL::text) RETURNS TABLE(plan_code text, plan_name text, brand_name text, category text, metal_tier text, benefit_tier text, monthly_premium numeric, annual_premium numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    COALESCE(p.plan_code, p.code) AS plan_code,
    p.name AS plan_name,
    p.brand_name,
    p.category,
    p.metal_tier,
    p_benefit_tier AS benefit_tier,
    calculate_premium(COALESCE(p.plan_code, p.code), p_age, p_rating_area_code, p_tobacco, p_year, p_benefit_tier) AS monthly_premium,
    calculate_premium(COALESCE(p.plan_code, p.code), p_age, p_rating_area_code, p_tobacco, p_year, p_benefit_tier) * 12 AS annual_premium
  FROM plans p
  WHERE (p.plan_code = ANY(p_plan_codes) OR p.code = ANY(p_plan_codes))
    AND p.is_active = true
  ORDER BY monthly_premium ASC;
END;
$$;


--
-- Name: complete_job(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_job(p_job_id uuid, p_status text, p_error text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE integration_jobs
  SET
    completed_at = now(),
    last_error = p_error,
    next_retry_at = CASE
      WHEN p_status = 'failed' AND attempts < max_attempts
      THEN now() + (attempts * interval '5 minutes')
      ELSE NULL
    END,
    status = CASE
      WHEN p_status = 'failed' AND attempts < max_attempts THEN 'pending'
      ELSE p_status
    END
  WHERE id = p_job_id;
END;
$$;


--
-- Name: complete_scheduler_job(uuid, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_scheduler_job(p_job_id uuid, p_status text, p_result jsonb DEFAULT NULL::jsonb, p_error text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE crm_scheduler_jobs
  SET status = p_status,
      result = COALESCE(p_result, result),
      last_error = p_error,
      completed_at = CASE WHEN p_status IN ('completed', 'failed', 'cancelled') THEN now() ELSE NULL END
  WHERE id = p_job_id;
END;
$$;


--
-- Name: compute_audit_entry_hash(bigint, text, uuid, text, uuid, text, text, text, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_audit_entry_hash(p_sequence_number bigint, p_previous_hash text, p_organization_id uuid, p_app_source text, p_actor_id uuid, p_action text, p_target_entity_type text, p_target_entity_id text, p_details jsonb, p_created_at timestamp with time zone) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public'
    AS $$
  SELECT encode(
    sha256(
      convert_to(
        COALESCE(p_sequence_number::text, '') || '|' ||
        COALESCE(p_previous_hash, 'GENESIS') || '|' ||
        COALESCE(p_organization_id::text, '') || '|' ||
        COALESCE(p_app_source, '') || '|' ||
        COALESCE(p_actor_id::text, '') || '|' ||
        COALESCE(p_action, '') || '|' ||
        COALESCE(p_target_entity_type, '') || '|' ||
        COALESCE(p_target_entity_id, '') || '|' ||
        COALESCE(p_details::text, '{}') || '|' ||
        COALESCE(p_created_at::text, ''),
        'UTF8'
      )
    ),
    'hex'
  );
$$;


--
-- Name: compute_first_billing_date(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_first_billing_date(p_effective_date date) RETURNS date
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
  RETURN (p_effective_date - interval '1 month')::date
         - (EXTRACT(day FROM (p_effective_date - interval '1 month')::date)::int - 20);
END;
$$;


--
-- Name: convert_lead_to_contact(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.convert_lead_to_contact(p_lead_record_id uuid, p_user_id uuid, p_merge_into_contact_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_lead_record           crm_records%ROWTYPE;
  v_org_id                uuid;
  v_leads_module_id       uuid;
  v_contacts_module_id    uuid;
  v_lead_data             jsonb;
  v_contact_data          jsonb;
  v_contact_title         text;
  v_new_contact_id        uuid;
  v_existing_contact_id   uuid;
  v_existing_data         jsonb;
  v_start_date            date;
  v_contact_status        text;
  v_sharing_carrier_id    uuid;
  v_market_type           text;
BEGIN
  SELECT * INTO v_lead_record FROM crm_records WHERE id = p_lead_record_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Lead record not found');
  END IF;

  v_org_id    := v_lead_record.organization_id;
  v_lead_data := COALESCE(v_lead_record.data, '{}'::jsonb);

  SELECT m.id INTO v_leads_module_id
  FROM crm_modules m
  WHERE m.id = v_lead_record.module_id AND m.key = 'leads';

  IF v_leads_module_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Record does not belong to a Leads module');
  END IF;

  IF v_lead_record.status = 'Converted'
     OR v_lead_data->>'is_converted' = 'true' THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'This lead has already been converted',
      'converted_contact_id', v_lead_data->>'converted_contact_id'
    );
  END IF;

  SELECT m.id INTO v_contacts_module_id
  FROM crm_modules m
  WHERE m.organization_id = v_org_id AND m.key = 'contacts' AND m.is_enabled = true
  LIMIT 1;

  IF v_contacts_module_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Contacts module not found or is disabled');
  END IF;

  v_start_date := COALESCE(
    public._parse_import_date(v_lead_data->>'current_year_start_date'),
    public._parse_import_date(v_lead_data->>'original_start_date'),
    public._parse_import_date(v_lead_data->>'health_insurance_start_date'),
    public._parse_import_date(v_lead_data->>'start_date'),
    public._parse_import_date(v_lead_data->>'sharing_effective_date'),
    public._parse_import_date(v_lead_data->>'insurance_effective_date'),
    v_lead_record.current_year_start_date,
    v_lead_record.original_start_date
  );

  v_contact_status := CASE
    WHEN v_start_date IS NOT NULL AND v_start_date > CURRENT_DATE THEN 'Pending'
    ELSE 'Active'
  END;

  IF (v_lead_data->>'sharing_entity') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_sharing_carrier_id := (v_lead_data->>'sharing_entity')::uuid;
  END IF;

  v_market_type := COALESCE(
    v_lead_record.market_type,
    CASE
      WHEN NULLIF(btrim(v_lead_data->>'sharing_entity'), '') IS NOT NULL THEN 'healthshare'
      ELSE NULL
    END
  );

  v_contact_data := jsonb_build_object(
    'salutation', v_lead_data->>'salutation',
    'first_name', v_lead_data->>'first_name',
    'last_name', v_lead_data->>'last_name',
    'email', v_lead_data->>'email',
    'phone', v_lead_data->>'phone',
    'mobile', v_lead_data->>'mobile',
    'date_of_birth', v_lead_data->>'date_of_birth',
    'lead_source', v_lead_data->>'lead_source',
    'owner_id', v_lead_data->>'owner_id',
    'coverage_option', v_lead_data->>'coverage_option',
    'product', v_lead_data->>'product_type',
    'start_date', COALESCE(v_lead_data->>'start_date', to_char(v_start_date, 'YYYY-MM-DD')),
    'health_insurance_start_date', v_lead_data->>'health_insurance_start_date',
    'health_insurance_end_date', v_lead_data->>'health_insurance_end_date',
    'health_insurance_plan_name', v_lead_data->>'health_insurance_plan_name',
    'health_insurance_carrier', v_lead_data->>'health_insurance_carrier',
    'health_insurance_premium', v_lead_data->>'health_insurance_premium',
    'health_insurance_status', v_lead_data->>'health_insurance_status',
    'health_insurance_deductible', v_lead_data->>'health_insurance_deductible',
    'sharing_entity', v_lead_data->>'sharing_entity',
    'member_tier', v_lead_data->>'member_tier',
    'monthly_contribution', v_lead_data->>'monthly_contribution',
    'iua_amount', v_lead_data->>'iua_amount',
    'sharing_effective_date', v_lead_data->>'sharing_effective_date',
    'sharing_status', v_lead_data->>'sharing_status',
    'sharing_member_id', v_lead_data->>'sharing_member_id',
    'previous_membership', v_lead_data->>'previous_membership',
    'insurance_effective_date', v_lead_data->>'insurance_effective_date',
    'contact_status', v_contact_status,
    'converted_from_lead_id', p_lead_record_id::text
  );

  SELECT COALESCE(jsonb_object_agg(k, v), '{}'::jsonb)
    INTO v_contact_data
    FROM jsonb_each(v_contact_data) AS x(k, v)
   WHERE NOT public._crm_jsonb_value_is_blank(v);

  v_contact_title := TRIM(
    COALESCE(v_lead_data->>'first_name', '') || ' ' || COALESCE(v_lead_data->>'last_name', '')
  );
  IF v_contact_title = '' THEN
    v_contact_title := 'Converted Lead';
  END IF;

  IF p_merge_into_contact_id IS NOT NULL THEN
    SELECT id, COALESCE(data, '{}'::jsonb) INTO v_new_contact_id, v_existing_data
    FROM crm_records
    WHERE id = p_merge_into_contact_id
      AND organization_id = v_org_id
      AND module_id = v_contacts_module_id;

    IF v_new_contact_id IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'Target contact not found');
    END IF;

    UPDATE crm_records
    SET data = (
      SELECT COALESCE(jsonb_object_agg(
        COALESCE(ek.key, nk.key),
        CASE
          WHEN ek.key IS NULL THEN nk.value
          WHEN public._crm_jsonb_value_is_blank(ek.value) THEN nk.value
          ELSE ek.value
        END
      ), '{}'::jsonb)
      FROM jsonb_each(v_existing_data) ek
      FULL OUTER JOIN jsonb_each(v_contact_data) nk ON ek.key = nk.key
      WHERE NOT public._crm_jsonb_value_is_blank(
        CASE
          WHEN ek.key IS NULL THEN nk.value
          WHEN public._crm_jsonb_value_is_blank(ek.value) THEN nk.value
          ELSE ek.value
        END
      )
    ),
    email = COALESCE(NULLIF(email, ''), v_lead_record.email),
    phone = COALESCE(NULLIF(phone, ''), v_lead_record.phone),
    original_start_date = COALESCE(original_start_date, v_start_date),
    current_year_start_date = COALESCE(current_year_start_date, v_start_date),
    market_type = COALESCE(market_type, v_market_type),
    carrier_id = COALESCE(carrier_id, v_lead_record.carrier_id, v_sharing_carrier_id),
    updated_at = now()
    WHERE id = p_merge_into_contact_id;

  ELSE
    IF v_lead_record.email IS NOT NULL AND v_lead_record.email != '' THEN
      SELECT id INTO v_existing_contact_id
      FROM crm_records
      WHERE organization_id = v_org_id
        AND module_id = v_contacts_module_id
        AND LOWER(email) = LOWER(v_lead_record.email)
      LIMIT 1;

      IF v_existing_contact_id IS NOT NULL THEN
        RETURN jsonb_build_object(
          'success', false,
          'error', 'A contact with email ' || v_lead_record.email || ' already exists',
          'existing_contact_id', v_existing_contact_id
        );
      END IF;
    END IF;

    INSERT INTO crm_records (
      organization_id, module_id, owner_id,
      title, status, email, phone,
      data, created_by, created_at, updated_at,
      original_start_date, current_year_start_date,
      market_type, carrier_id
    ) VALUES (
      v_org_id, v_contacts_module_id, v_lead_record.owner_id,
      v_contact_title, v_contact_status,
      v_lead_record.email, v_lead_record.phone,
      v_contact_data, p_user_id, now(), now(),
      v_start_date, v_start_date,
      v_market_type,
      COALESCE(v_lead_record.carrier_id, v_sharing_carrier_id)
    )
    RETURNING id INTO v_new_contact_id;
  END IF;

  UPDATE crm_notes SET record_id = v_new_contact_id WHERE record_id = p_lead_record_id;

  BEGIN
    UPDATE notes SET record_id = v_new_contact_id WHERE record_id = p_lead_record_id;
  EXCEPTION WHEN undefined_table THEN NULL;
  END;

  INSERT INTO crm_record_links (
    organization_id, source_record_id, target_record_id,
    link_type, is_primary, created_by
  ) VALUES (
    v_org_id, p_lead_record_id, v_new_contact_id,
    'lead_to_contact', true, p_user_id
  );

  UPDATE crm_records
  SET status = 'Converted',
      data = jsonb_set(
        jsonb_set(
          jsonb_set(
            jsonb_set(COALESCE(data, '{}'::jsonb), '{is_converted}', 'true'::jsonb),
            '{converted_date}', to_jsonb(to_char(now(), 'YYYY-MM-DD'))
          ),
          '{converted_contact_id}', to_jsonb(v_new_contact_id::text)
        ),
        '{lead_status}', '"Converted"'::jsonb
      ),
      updated_at = now()
  WHERE id = p_lead_record_id;

  INSERT INTO crm_audit_log (organization_id, actor_id, entity, entity_id, action, diff)
  VALUES (
    v_org_id, p_user_id, 'lead', p_lead_record_id, 'update',
    jsonb_build_object(
      'action', CASE WHEN p_merge_into_contact_id IS NOT NULL THEN 'merge_into_contact' ELSE 'convert_to_contact' END,
      'converted_contact_id', v_new_contact_id,
      'contact_title', v_contact_title,
      'contact_status', v_contact_status,
      'effective_start_date', v_start_date,
      'merged', p_merge_into_contact_id IS NOT NULL,
      'converted_at', now()
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'contact_id', v_new_contact_id,
    'contact_title', v_contact_title,
    'contact_status', v_contact_status,
    'effective_start_date', v_start_date,
    'lead_id', p_lead_record_id,
    'message', CASE
      WHEN p_merge_into_contact_id IS NOT NULL THEN 'Lead merged into existing contact successfully'
      WHEN v_contact_status = 'Pending' THEN
        'Lead converted to a Pending contact — status will auto-activate on ' || to_char(v_start_date, 'Mon FMDD, YYYY')
      ELSE 'Lead converted to contact successfully'
    END
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$_$;


--
-- Name: convert_lead_to_member(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.convert_lead_to_member(p_lead_record_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_lead_record crm_records%ROWTYPE;
  v_org_id uuid;
  v_new_member_id uuid;
BEGIN
  SELECT * INTO v_lead_record
  FROM crm_records
  WHERE id = p_lead_record_id;

  IF v_lead_record.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Lead record not found');
  END IF;

  v_org_id := v_lead_record.organization_id;

  IF v_lead_record.email IS NOT NULL THEN
    SELECT id INTO v_new_member_id
    FROM members
    WHERE email = v_lead_record.email
      AND organization_id = v_org_id
    LIMIT 1;
  END IF;

  IF v_new_member_id IS NULL THEN
    INSERT INTO members (
      organization_id, first_name, last_name, email, phone,
      status, created_at, updated_at
    ) VALUES (
      v_org_id,
      v_lead_record.data->>'first_name',
      v_lead_record.data->>'last_name',
      v_lead_record.email,
      v_lead_record.phone,
      'Active', now(), now()
    )
    RETURNING id INTO v_new_member_id;
  END IF;

  UPDATE crm_records
  SET status = 'Converted',
      data = jsonb_set(
        jsonb_set(
          COALESCE(data, '{}'::jsonb),
          '{lead_status}', '"Converted"'::jsonb
        ),
        '{converted_member_id}', to_jsonb(v_new_member_id::text)
      ),
      updated_at = now()
  WHERE id = p_lead_record_id;

  -- Fixed: use correct crm_audit_log columns (actor_id, entity_id, diff)
  INSERT INTO crm_audit_log (organization_id, actor_id, entity, entity_id, action, diff)
  VALUES (
    v_org_id,
    p_user_id,
    'lead',
    p_lead_record_id,
    'update',
    jsonb_build_object(
      'converted_to_member_id', v_new_member_id,
      'converted_at', now()
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'member_id', v_new_member_id,
    'lead_id', p_lead_record_id,
    'message', 'Lead converted to member successfully'
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


--
-- Name: count_org_active_seats(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.count_org_active_seats(p_org_id uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COUNT(*)::int
    FROM public.organization_members
   WHERE organization_id = p_org_id
     AND is_active = true;
$$;


