--
-- Name: create_default_advisor_link(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_default_advisor_link() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_slug text;
BEGIN
  -- Generate slug from name
  v_slug := lower(regexp_replace(
    NEW.first_name || '-' || NEW.last_name,
    '[^a-zA-Z0-9]', '-', 'g'
  ));

  -- Ensure uniqueness by appending random chars if needed
  WHILE EXISTS (SELECT 1 FROM enrollment_links WHERE organization_id = NEW.organization_id AND slug = v_slug) LOOP
    v_slug := v_slug || '-' || substring(md5(random()::text) from 1 for 4);
  END LOOP;

  -- Create the default link
  INSERT INTO enrollment_links (
    organization_id, advisor_id, name, slug, description
  ) VALUES (
    NEW.organization_id,
    NEW.id,
    NEW.first_name || ' ' || NEW.last_name || ' - Default Link',
    v_slug,
    'Default enrollment link for ' || NEW.first_name || ' ' || NEW.last_name
  );

  RETURN NEW;
END;
$$;


--
-- Name: create_enrollment_tx(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_enrollment_tx(p_org_id uuid, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_enrollment_id uuid;
  v_idem text := NULLIF(p_payload->>'idempotency_key', '');
  v_dep record;
BEGIN
  -- Fast path: a prior submit with this key already created the enrollment.
  IF v_idem IS NOT NULL THEN
    SELECT id INTO v_enrollment_id
      FROM enrollments
     WHERE organization_id = p_org_id AND idempotency_key = v_idem;
    IF FOUND THEN
      RETURN jsonb_build_object('enrollment_id', v_enrollment_id, 'idempotent_replay', true);
    END IF;
  END IF;

  BEGIN
    INSERT INTO enrollments (
      organization_id,
      primary_member_id,
      advisor_id,
      selected_plan_id,
      effective_date,
      household_size,
      base_monthly_cost,
      permanent_bill_day,
      enrollment_source,
      channel,
      custom_fields,
      idempotency_key,
      status
    ) VALUES (
      p_org_id,
      (p_payload->>'primary_member_id')::uuid,
      (p_payload->>'advisor_id')::uuid,
      (p_payload->>'selected_plan_id')::uuid,
      (p_payload->>'effective_date')::date,
      COALESCE((p_payload->>'household_size')::int, 1),
      COALESCE((p_payload->>'base_monthly_cost')::numeric, 0),
      COALESCE((p_payload->>'permanent_bill_day')::int, 20),
      COALESCE(p_payload->>'enrollment_source', 'admin'),
      COALESCE(p_payload->>'channel', 'direct'),
      COALESCE(p_payload->'custom_fields', '{}'::jsonb),
      v_idem,
      'draft'
    )
    RETURNING id INTO v_enrollment_id;
  EXCEPTION WHEN unique_violation THEN
    -- A concurrent submit with the same key won the race; return the surviving row.
    SELECT id INTO v_enrollment_id
      FROM enrollments
     WHERE organization_id = p_org_id AND idempotency_key = v_idem;
    RETURN jsonb_build_object('enrollment_id', v_enrollment_id, 'idempotent_replay', true);
  END;

  FOR v_dep IN SELECT * FROM jsonb_array_elements(COALESCE(p_payload->'dependents', '[]'::jsonb))
  LOOP
    INSERT INTO enrollment_dependents (
      organization_id,
      enrollment_id,
      dependent_id,
      relationship,
      additional_cost,
      status
    ) VALUES (
      p_org_id,
      v_enrollment_id,
      (v_dep.value->>'dependentId')::uuid,
      v_dep.value->>'relationship',
      COALESCE((v_dep.value->>'additionalCost')::numeric, 0),
      'active'
    );
  END LOOP;

  RETURN jsonb_build_object('enrollment_id', v_enrollment_id);
END;
$$;


--
-- Name: create_franchise_relationship(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_franchise_relationship(p_parent_org_id uuid, p_child_org_id uuid, p_relationship_type text DEFAULT 'franchise'::text, p_granted_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rel_id uuid;
  v_del_id uuid;
BEGIN
  -- Verify caller is in parent org
  IF (SELECT get_user_organization_id()) != p_parent_org_id THEN
    RAISE EXCEPTION 'ACCESS_DENIED: must be in parent org';
  END IF;

  -- Prevent circular references
  IF EXISTS (
    SELECT 1 FROM org_relationships
    WHERE parent_org_id = p_child_org_id AND child_org_id = p_parent_org_id
  ) THEN
    RAISE EXCEPTION 'CIRCULAR_REF: child org is already a parent of this org';
  END IF;

  -- Create relationship
  INSERT INTO org_relationships (parent_org_id, child_org_id, relationship_type)
  VALUES (p_parent_org_id, p_child_org_id, p_relationship_type)
  ON CONFLICT (parent_org_id, child_org_id) DO UPDATE
    SET status = 'active',
        relationship_type = p_relationship_type,
        updated_at = now()
  RETURNING id INTO v_rel_id;

  -- Create default analytics_viewer delegation
  INSERT INTO org_delegations (
    parent_org_id, child_org_id, delegated_role,
    permissions, granted_by
  ) VALUES (
    p_parent_org_id, p_child_org_id, 'analytics_viewer',
    '{
      "view_aggregated_analytics": true,
      "view_advisor_roster": false,
      "view_commission_totals": true,
      "view_enrollment_totals": true,
      "view_product_breakdown": true,
      "view_monthly_trends": true,
      "view_individual_advisors": false,
      "view_raw_records": false,
      "manage_child_settings": false
    }'::jsonb,
    p_granted_by
  )
  ON CONFLICT (parent_org_id, child_org_id, delegated_role) DO UPDATE
    SET status = 'active',
        updated_at = now()
  RETURNING id INTO v_del_id;

  RETURN jsonb_build_object(
    'relationship_id', v_rel_id,
    'delegation_id', v_del_id,
    'status', 'active'
  );
END;
$$;


--
-- Name: create_payout_batch(uuid, date, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_payout_batch(p_org_id uuid, p_period_start date, p_period_end date, p_description text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_batch_id       uuid;
  v_batch_number   text;
  v_total_amount   numeric := 0;
  v_total_advisors int := 0;
  v_advisor_row    record;
  v_payout_id      uuid;
  v_link_count     int := 0;
BEGIN
  -- Advisory lock to prevent concurrent batch creation for same org
  PERFORM pg_advisory_xact_lock(hashtext(p_org_id::text || 'payout_batch'));

  -- Generate batch number
  v_batch_number := 'PAY-' || to_char(p_period_start, 'YYYYMM') || '-' ||
                    lpad((
                      SELECT count(*) + 1
                      FROM commission_payment_batches
                      WHERE organization_id = p_org_id
                        AND period_start = p_period_start
                    )::text, 3, '0');

  -- Create the batch
  INSERT INTO commission_payment_batches (
    organization_id, batch_number, description,
    period_start, period_end, payment_date,
    status
  ) VALUES (
    p_org_id, v_batch_number, COALESCE(p_description, 'Auto-generated payout batch'),
    p_period_start, p_period_end, current_date,
    'draft'
  )
  RETURNING id INTO v_batch_id;

  -- Group available ledger entries by advisor and create payout items
  FOR v_advisor_row IN
    SELECT
      cl.advisor_id,
      sum(cl.amount) FILTER (WHERE cl.amount > 0) AS total_commissions,
      sum(cl.amount) FILTER (WHERE cl.amount < 0) AS total_chargebacks,
      sum(cl.amount) AS net_amount,
      array_agg(cl.id) AS ledger_ids
    FROM commission_ledger cl
    WHERE cl.organization_id = p_org_id
      AND cl.status = 'available'
      AND cl.created_at >= p_period_start::timestamptz
      AND cl.created_at < (p_period_end + interval '1 day')::timestamptz
    GROUP BY cl.advisor_id
    HAVING sum(cl.amount) > 0  -- Only create payouts for positive net amounts
  LOOP
    -- Create payout item using existing commission_payouts table
    INSERT INTO commission_payouts (
      organization_id, advisor_id,
      period_start, period_end,
      total_commissions,
      total_chargebacks,
      net_payout,
      status
    ) VALUES (
      p_org_id, v_advisor_row.advisor_id,
      p_period_start, p_period_end,
      COALESCE(v_advisor_row.total_commissions, 0),
      COALESCE(abs(v_advisor_row.total_chargebacks), 0),
      v_advisor_row.net_amount,
      'draft'
    )
    RETURNING id INTO v_payout_id;

    -- Link ledger entries to payout item
    INSERT INTO payout_item_ledger_links (payout_id, ledger_entry_id, amount)
    SELECT v_payout_id, unnest(v_advisor_row.ledger_ids), cl.amount
    FROM commission_ledger cl
    WHERE cl.id = ANY(v_advisor_row.ledger_ids);

    -- Mark ledger entries as scheduled
    UPDATE commission_ledger
    SET status = 'scheduled',
        payout_batch_id = v_batch_id,
        payout_id = v_payout_id,
        updated_at = now()
    WHERE id = ANY(v_advisor_row.ledger_ids)
      AND status = 'available';

    GET DIAGNOSTICS v_link_count = ROW_COUNT;

    v_total_amount := v_total_amount + v_advisor_row.net_amount;
    v_total_advisors := v_total_advisors + 1;
  END LOOP;

  -- Update batch totals
  UPDATE commission_payment_batches
  SET total_amount = v_total_amount,
      total_advisors = v_total_advisors,
      total_commissions = v_link_count
  WHERE id = v_batch_id;

  RETURN jsonb_build_object(
    'batch_id', v_batch_id,
    'batch_number', v_batch_number,
    'total_amount', v_total_amount,
    'total_advisors', v_total_advisors,
    'status', 'draft'
  );
END;
$$;


--
-- Name: create_payout_clawback(uuid, uuid, numeric, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_payout_clawback(p_org_id uuid, p_advisor_id uuid, p_amount numeric, p_reason text, p_commission_id uuid DEFAULT NULL::uuid, p_actor_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_adjustment_id  uuid;
  v_ledger_id      uuid;
  v_original_paid  numeric;
BEGIN
  IF p_amount <= 0 THEN
    RETURN jsonb_build_object('error', 'Clawback amount must be positive');
  END IF;

  -- If linked to a specific commission, verify it was paid and amount doesn't exceed
  IF p_commission_id IS NOT NULL THEN
    SELECT amount INTO v_original_paid
    FROM commission_ledger
    WHERE commission_id = p_commission_id
      AND status = 'paid';

    IF v_original_paid IS NULL THEN
      RETURN jsonb_build_object('error', 'Original commission not found in paid ledger entries');
    END IF;

    IF p_amount > v_original_paid THEN
      RETURN jsonb_build_object(
        'error', 'Clawback amount ($' || p_amount || ') exceeds paid amount ($' || v_original_paid || ')',
        'code', 'CLAWBACK_EXCEEDS_PAID'
      );
    END IF;

    -- Mark original ledger entry as clawback
    UPDATE commission_ledger
    SET status = 'clawback',
        updated_at = now()
    WHERE commission_id = p_commission_id
      AND status = 'paid';
  END IF;

  -- Create adjustment record
  INSERT INTO commission_adjustments (
    organization_id, advisor_id,
    adjustment_type, amount, description,
    commission_id, effective_period,
    status, approved_by, approved_at, created_by
  ) VALUES (
    p_org_id, p_advisor_id,
    'clawback', -p_amount, p_reason,
    p_commission_id, date_trunc('month', current_date)::date,
    'approved', p_actor_id, now(), p_actor_id
  )
  RETURNING id INTO v_adjustment_id;

  -- Audit
  INSERT INTO payout_audit_log (
    organization_id, event_type, entity_type, entity_id,
    actor_id, actor_type, amount, details
  ) VALUES (
    p_org_id, 'clawback_created', 'commission_adjustment', v_adjustment_id,
    p_actor_id, CASE WHEN p_actor_id IS NULL THEN 'system' ELSE 'user' END,
    -p_amount,
    jsonb_build_object(
      'reason', p_reason,
      'advisor_id', p_advisor_id,
      'commission_id', p_commission_id,
      'original_paid_amount', v_original_paid
    )
  );

  INSERT INTO financial_audit_log (
    organization_id, action, entity_type, entity_id,
    performed_by, details
  ) VALUES (
    p_org_id, 'clawback_created', 'commission_adjustment', v_adjustment_id,
    p_actor_id,
    jsonb_build_object(
      'amount', -p_amount,
      'reason', p_reason,
      'advisor_id', p_advisor_id
    )
  );

  RETURN jsonb_build_object(
    'adjustment_id', v_adjustment_id,
    'amount', -p_amount,
    'advisor_id', p_advisor_id,
    'reason', p_reason,
    'status', 'approved',
    'original_paid_amount', v_original_paid
  );
END;
$_$;


--
-- Name: create_payout_reversal(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_payout_reversal(p_ledger_entry_id uuid, p_reason text, p_actor_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_entry record;
  v_reversal_id uuid;
BEGIN
  SELECT * INTO v_entry
  FROM commission_ledger
  WHERE id = p_ledger_entry_id
  FOR UPDATE;

  IF v_entry IS NULL THEN
    RETURN jsonb_build_object('error', 'Ledger entry not found');
  END IF;

  IF v_entry.status NOT IN ('available', 'scheduled', 'paid') THEN
    RETURN jsonb_build_object('error', 'Entry cannot be reversed from status: ' || v_entry.status);
  END IF;

  -- Mark original entry as reversed
  UPDATE commission_ledger
  SET status = 'reversed',
      reversed_at = now(),
      reversed_reason = p_reason,
      updated_at = now()
  WHERE id = p_ledger_entry_id;

  -- Audit
  INSERT INTO payout_audit_log (
    organization_id, event_type, entity_type, entity_id,
    actor_id, actor_type,
    prev_status, new_status, amount, details
  ) VALUES (
    v_entry.organization_id, 'ledger_reversed', 'commission_ledger', p_ledger_entry_id,
    p_actor_id, CASE WHEN p_actor_id IS NULL THEN 'system' ELSE 'user' END,
    v_entry.status, 'reversed', v_entry.amount,
    jsonb_build_object('reason', p_reason, 'commission_id', v_entry.commission_id)
  );

  RETURN jsonb_build_object(
    'ledger_entry_id', p_ledger_entry_id,
    'status', 'reversed',
    'original_amount', v_entry.amount,
    'reason', p_reason,
    'advisor_id', v_entry.advisor_id
  );
END;
$$;


--
-- Name: create_signup_commission_on_enrollment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_signup_commission_on_enrollment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_advisor advisors%ROWTYPE;
  v_commission_amount numeric;
  v_idem_key text;
BEGIN
  IF NEW.status = 'approved' AND (OLD.status IS NULL OR OLD.status <> 'approved') THEN
    IF NEW.advisor_id IS NULL THEN
      RETURN NEW;
    END IF;

    SELECT * INTO v_advisor FROM advisors WHERE id = NEW.advisor_id;
    IF v_advisor IS NULL OR v_advisor.status <> 'active' THEN
      RETURN NEW;
    END IF;

    v_commission_amount := calculate_enrollment_commission(NEW.id, 'signup');
    IF v_commission_amount <= 0 THEN
      RETURN NEW;
    END IF;

    v_idem_key := 'signup_' || NEW.id::text || '_' || CURRENT_DATE::text;

    INSERT INTO commissions (
      organization_id,
      advisor_id,
      enrollment_id,
      member_id,
      commission_type,
      base_amount,
      commission_amount,
      commission_period,
      status,
      metadata
    ) VALUES (
      NEW.organization_id,
      NEW.advisor_id,
      NEW.id,
      NEW.primary_member_id,
      'signup',
      COALESCE(NEW.base_monthly_cost, 0),
      v_commission_amount,
      date_trunc('month', CURRENT_DATE)::date,
      'pending',
      jsonb_build_object('idempotency_key', v_idem_key, 'trigger', 'enrollment_approval')
    )
    ON CONFLICT DO NOTHING;
  END IF;

  RETURN NEW;
END;
$$;


