-- Name: create_staff_log_notification(uuid, uuid, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_staff_log_notification(p_user_id uuid, p_log_id uuid, p_type text, p_title text, p_message text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
