  RETURNING id INTO v_notification_id;
  
  RETURN v_notification_id;
END;
$$;


--
-- Name: create_team_invitation(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_team_invitation(p_org_id uuid, p_email text, p_role text DEFAULT 'staff'::text, p_expires_in_days integer DEFAULT 7) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_inviter_profile_id uuid;
  v_inviter_role text;
  v_invitation_id uuid;
  v_token text;
BEGIN
  -- Get inviter's profile
  SELECT id, role INTO v_inviter_profile_id, v_inviter_role
  FROM profiles
  WHERE user_id = auth.uid()
    AND organization_id = p_org_id
    AND is_active = true;

  IF v_inviter_profile_id IS NULL THEN
    RAISE EXCEPTION 'User is not a member of this organization';
  END IF;

  -- Check permission to invite
  IF v_inviter_role NOT IN ('owner', 'super_admin', 'admin') THEN
    RAISE EXCEPTION 'Insufficient permissions to invite team members';
  END IF;

  -- Prevent inviting roles higher than your own
  IF p_role = 'super_admin' AND v_inviter_role NOT IN ('owner', 'super_admin') THEN
    RAISE EXCEPTION 'Cannot invite super admin role';
  END IF;

  -- Check if email already exists in organization
  IF EXISTS (
    SELECT 1 FROM profiles
    WHERE organization_id = p_org_id
    AND email = p_email
    AND is_active = true
  ) THEN
    RAISE EXCEPTION 'User already exists in this organization';
  END IF;

  -- Check for existing pending invitation
  IF EXISTS (
    SELECT 1 FROM team_invitations
    WHERE organization_id = p_org_id
    AND email = p_email
    AND status = 'pending'
    AND expires_at > now()
  ) THEN
    RAISE EXCEPTION 'Pending invitation already exists for this email';
  END IF;

  -- Generate token
  v_token := generate_invitation_token();

  -- Create invitation
  INSERT INTO team_invitations (
    organization_id,
    email,
    role,
    token,
    expires_at,
    invited_by
  ) VALUES (
    p_org_id,
    p_email,
    p_role,
    v_token,
    now() + (p_expires_in_days || ' days')::interval,
    v_inviter_profile_id
  )
  RETURNING id INTO v_invitation_id;

  RETURN v_invitation_id;
END;
$$;


--
-- Name: create_ticket_from_message(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_ticket_from_message() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  new_ticket_id uuid;
  channel_config jsonb;
  auto_create boolean;
BEGIN
  -- Check if channel has auto_create_ticket enabled
  SELECT sc.auto_create_ticket, sc.config
  INTO auto_create, channel_config
  FROM support_channels sc
  WHERE sc.id = NEW.channel_id;
  
  -- Only create ticket if auto_create is enabled and no ticket exists
  IF auto_create AND NEW.ticket_id IS NULL AND NEW.sender_type = 'customer' THEN
    INSERT INTO tickets (
      subject,
      description,
      status,
      priority,
      origin,
      submitter_email,
      submitter_name
    ) VALUES (
      COALESCE(NEW.metadata->>'subject', 'New support request'),
      NEW.message_body,
      'new',
      'normal',
      CASE 
        WHEN (SELECT channel_type FROM support_channels WHERE id = NEW.channel_id) = 'email' THEN 'member'
        WHEN (SELECT channel_type FROM support_channels WHERE id = NEW.channel_id) = 'chat' THEN 'member'
        ELSE 'member'
      END,
      NEW.sender_email,
      NEW.sender_name
    ) RETURNING id INTO new_ticket_id;
    
    -- Update the message with the new ticket_id
    NEW.ticket_id := new_ticket_id;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: create_ticket_notification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_ticket_notification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ticket_record RECORD;
  v_notification_title text;
  v_notification_message text;
  v_watcher_count integer := 0;
BEGIN
  -- Only process non-internal comments
  IF NEW.is_internal = true THEN
    RETURN NEW;
  END IF;

  -- Get ticket details with minimal query
  BEGIN
    SELECT
      id,
      requester_id,
      assignee_id,
      submitted_by_concierge,
      subject
    INTO v_ticket_record
    FROM public.tickets
    WHERE id = NEW.ticket_id;

    IF NOT FOUND THEN
      RAISE NOTICE 'Ticket % not found for notification', NEW.ticket_id;
      RETURN NEW;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'Error fetching ticket: %', SQLERRM;
    RETURN NEW;
  END;

  -- Prepare notification content
  v_notification_title := 'New message on ticket';
  v_notification_message := LEFT(COALESCE(NEW.body, ''), 100);

  -- Notify requester (if different from author)
  IF v_ticket_record.requester_id IS NOT NULL
     AND v_ticket_record.requester_id != NEW.author_id THEN
    BEGIN
      INSERT INTO public.ticket_notifications (
        ticket_id, user_id, notification_type, title, message
      ) VALUES (
        NEW.ticket_id, v_ticket_record.requester_id, 'new_message',
        v_notification_title, v_notification_message
      );
    EXCEPTION WHEN OTHERS THEN
      RAISE NOTICE 'Failed to notify requester: %', SQLERRM;
    END;
  END IF;

  -- Notify assignee (if different from author and requester)
  IF v_ticket_record.assignee_id IS NOT NULL
     AND v_ticket_record.assignee_id != NEW.author_id
     AND v_ticket_record.assignee_id != COALESCE(v_ticket_record.requester_id, '00000000-0000-0000-0000-000000000000'::uuid) THEN
    BEGIN
      INSERT INTO public.ticket_notifications (
        ticket_id, user_id, notification_type, title, message
      ) VALUES (
        NEW.ticket_id, v_ticket_record.assignee_id, 'new_message',
        v_notification_title, v_notification_message
      );
    EXCEPTION WHEN OTHERS THEN
      RAISE NOTICE 'Failed to notify assignee: %', SQLERRM;
    END;
  END IF;

  -- Notify concierge (if applicable)
  IF v_ticket_record.submitted_by_concierge IS NOT NULL
     AND v_ticket_record.submitted_by_concierge != NEW.author_id THEN
    BEGIN
      INSERT INTO public.ticket_notifications (
        ticket_id, user_id, notification_type, title, message
      ) VALUES (
        NEW.ticket_id, v_ticket_record.submitted_by_concierge, 'new_message',
        'New message on ticket you submitted', v_notification_message
      );
    EXCEPTION WHEN OTHERS THEN
      RAISE NOTICE 'Failed to notify concierge: %', SQLERRM;
    END;
  END IF;

  -- Notify watchers (use SECURITY DEFINER to bypass RLS entirely)
  BEGIN
    WITH watcher_inserts AS (
      INSERT INTO public.ticket_notifications (
        ticket_id, user_id, notification_type, title, message
      )
      SELECT DISTINCT
        NEW.ticket_id,
        tw.user_id,
        'new_message',
        'New message on watched ticket',
        v_notification_message
      FROM public.ticket_watchers tw
      WHERE tw.ticket_id = NEW.ticket_id
        AND tw.user_id != NEW.author_id
        AND tw.user_id NOT IN (
          SELECT unnest(ARRAY[
            COALESCE(v_ticket_record.requester_id, '00000000-0000-0000-0000-000000000000'::uuid),
            COALESCE(v_ticket_record.assignee_id, '00000000-0000-0000-0000-000000000000'::uuid),
            COALESCE(v_ticket_record.submitted_by_concierge, '00000000-0000-0000-0000-000000000000'::uuid)
          ])
        )
      ON CONFLICT (ticket_id, user_id, notification_type) DO NOTHING
      RETURNING 1
    )
    SELECT count(*) INTO v_watcher_count FROM watcher_inserts;

    RAISE NOTICE 'Notified % watchers for ticket %', v_watcher_count, NEW.ticket_id;
  EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'Failed to notify watchers (non-fatal): %', SQLERRM;
    -- Do not fail the entire transaction
  END;

  RETURN NEW;
END;
$$;


