--
-- Name: crm_phone_lookup(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_phone_lookup(p_org_id uuid, p_query text, p_module_key text DEFAULT NULL::text, p_limit integer DEFAULT 25) RETURNS TABLE(id uuid, title text, email text, phone text, status text, module_id uuid, data jsonb, module_key text, module_name text, module_name_plural text, match_type text, rank real)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  v_digits text := regexp_replace(coalesce(p_query, ''), '\D', '', 'g');
  v_tail   text := right(v_digits, 10);
BEGIN
  IF length(v_digits) < 4 THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    r.id,
    r.title,
    r.email,
    r.phone,
    r.status,
    r.module_id,
    r.data,
    m.key          AS module_key,
    m.name         AS module_name,
    m.name_plural  AS module_name_plural,
    'exact'::text  AS match_type,
    CASE
      WHEN regexp_replace(coalesce(r.phone, ''), '\D', '', 'g') = v_digits THEN 2.50::real
      WHEN length(v_tail) = 10
        AND right(regexp_replace(coalesce(r.phone, ''), '\D', '', 'g'), 10) = v_tail THEN 2.30::real
      WHEN regexp_replace(coalesce(r.phone, ''), '\D', '', 'g') LIKE '%' || v_digits || '%' THEN 1.95::real
      ELSE 1.50::real
    END AS rank
  FROM public.crm_records r
  JOIN public.crm_modules m ON m.id = r.module_id
  WHERE r.organization_id = p_org_id
    AND (p_module_key IS NULL OR m.key = p_module_key)
    AND (
      regexp_replace(coalesce(r.phone, ''), '\D', '', 'g') LIKE '%' || v_digits || '%'
      OR (
        length(v_tail) = 10
        AND right(regexp_replace(coalesce(r.phone, ''), '\D', '', 'g'), 10) = v_tail
      )
    )
  ORDER BY rank DESC, r.updated_at DESC NULLS LAST, r.id
  LIMIT GREATEST(p_limit, 1);
END;
$$;


--
-- Name: FUNCTION crm_phone_lookup(p_org_id uuid, p_query text, p_module_key text, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.crm_phone_lookup(p_org_id uuid, p_query text, p_module_key text, p_limit integer) IS 'Digit-normalized phone search: indexed scan on r.phone. ORDER BY includes r.id so LIMIT is stable when rank and updated_at tie (see 202605020010).';


--
-- Name: crm_records_init_stage_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_records_init_stage_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.stage_updated_at IS NULL THEN
    NEW.stage_updated_at := COALESCE(NEW.updated_at, now());
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: crm_records_search_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_records_search_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  NEW.search := to_tsvector('english',
    coalesce(NEW.title, '') || ' ' ||
    coalesce(NEW.email, '') || ' ' ||
    coalesce(NEW.phone, '') || ' ' ||
    coalesce(NEW.status, '') || ' ' ||
    coalesce(NEW.data->>'first_name', '') || ' ' ||
    coalesce(NEW.data->>'last_name', '') || ' ' ||
    coalesce(NEW.data->>'spouse', '') || ' ' ||
    coalesce(NEW.data->>'spouse_name', '') || ' ' ||
    coalesce(NEW.data->>'child_1_name', '') || ' ' ||
    coalesce(NEW.data->>'child_2_name', '') || ' ' ||
    coalesce(NEW.data->>'child_3_name', '') || ' ' ||
    coalesce(NEW.data->>'child_4_name', '') || ' ' ||
    coalesce(NEW.data->>'child_5_name', '') || ' ' ||
    coalesce(NEW.data->>'contact_name', '') || ' ' ||
    coalesce(NEW.data->>'mailing_city', '') || ' ' ||
    coalesce(NEW.data->>'mailing_state', '') || ' ' ||
    coalesce(NEW.data->>'carrier', '') || ' ' ||
    coalesce(NEW.data->>'product', '') || ' ' ||
    coalesce(NEW.data->>'producer_name', '') || ' ' ||
    coalesce(NEW.group_name, '') || ' ' ||
    coalesce(CASE WHEN NEW.tobacco_user = true THEN 'tobacco smoker' ELSE '' END, '')
  );
  RETURN NEW;
END;
$$;


--
-- Name: crm_records_set_stage_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_records_set_stage_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Only stamp when stage actually changed (or moves between NULL and a value).
  IF NEW.stage IS DISTINCT FROM OLD.stage THEN
    NEW.stage_updated_at := now();
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: crm_smart_search(uuid, text, text, integer, real); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_smart_search(p_org_id uuid, p_query text, p_module_key text DEFAULT NULL::text, p_limit integer DEFAULT 25, p_similarity_threshold real DEFAULT 0.18) RETURNS TABLE(id uuid, title text, email text, phone text, status text, module_id uuid, data jsonb, module_key text, module_name text, module_name_plural text, match_type text, rank real)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  v_query        text := btrim(coalesce(p_query, ''));
  v_query_lower  text;
  v_clean        text;
  v_words        text[];
  v_tsquery_and  text;
  v_tsquery_or   text;
  v_digits       text;
  v_tail         text;
  v_word_len     int;
  v_thr          real := LEAST(GREATEST(p_similarity_threshold, 0.05::real), 0.9::real);
  v_cte_cap      int := 200;
BEGIN
  IF length(v_query) = 0 THEN
    RETURN;
  END IF;

  v_query_lower := lower(v_query);
  v_clean := lower(regexp_replace(v_query, '[^a-z0-9 ]', ' ', 'gi'));
  v_words := regexp_split_to_array(btrim(v_clean), '\s+');
  v_word_len := cardinality(v_words);

  SELECT string_agg(w || ':*', ' & ')
    INTO v_tsquery_and
    FROM unnest(v_words) AS w
   WHERE length(w) >= 2;

  SELECT string_agg(w || ':*', ' | ')
    INTO v_tsquery_or
    FROM unnest(v_words) AS w
   WHERE length(w) >= 2;

  v_digits := regexp_replace(v_query, '\D', '', 'g');
  v_tail   := right(v_digits, 10);

  RETURN QUERY
  WITH
  exact_hits AS (
    SELECT
      r.id,
      CASE
        WHEN lower(trim(coalesce(r.email, ''))) = v_query_lower THEN 2.85::real
        WHEN lower(trim(coalesce(r.title, ''))) = v_query_lower THEN 2.55::real
        WHEN length(v_digits) >= 7
          AND regexp_replace(coalesce(r.phone, ''), '\D', '', 'g') = v_digits THEN 2.45::real
        WHEN length(v_tail) = 10
          AND right(regexp_replace(coalesce(r.phone, ''), '\D', '', 'g'), 10) = v_tail THEN 2.30::real
        WHEN strpos(v_query_lower, '@') > 0
          AND lower(coalesce(r.email, '')) LIKE '%' || v_query_lower || '%' THEN 2.35::real
        ELSE 2.00::real
      END AS rank,
      'exact'::text AS match_type
    FROM public.crm_records r
    WHERE r.organization_id = p_org_id
      AND (
        lower(trim(coalesce(r.email, ''))) = v_query_lower
        OR lower(trim(coalesce(r.title, ''))) = v_query_lower
        OR (
          length(v_digits) >= 7
          AND regexp_replace(coalesce(r.phone, ''), '\D', '', 'g') = v_digits
        )
        OR (
          length(v_tail) = 10
          AND right(regexp_replace(coalesce(r.phone, ''), '\D', '', 'g'), 10) = v_tail
        )
        OR (
          strpos(v_query_lower, '@') > 0
          AND lower(coalesce(r.email, '')) LIKE '%' || v_query_lower || '%'
        )
      )
    LIMIT v_cte_cap
  ),
  fts_and_hits AS (
    SELECT
      r.id,
      ts_rank_cd(r.search, to_tsquery('english', v_tsquery_and)) + 1.05::real AS rank,
      'exact'::text AS match_type
    FROM public.crm_records r
    WHERE r.organization_id = p_org_id
      AND v_tsquery_and IS NOT NULL
      AND r.search @@ to_tsquery('english', v_tsquery_and)
    LIMIT v_cte_cap
  ),
  fts_or_hits AS (
    SELECT
      r.id,
      ts_rank_cd(r.search, to_tsquery('english', v_tsquery_or)) * 0.55::real + 0.72::real AS rank,
      'fuzzy'::text AS match_type
    FROM public.crm_records r
    WHERE r.organization_id = p_org_id
      AND v_tsquery_or IS NOT NULL
      AND v_word_len > 1
      AND r.search @@ to_tsquery('english', v_tsquery_or)
      AND NOT (v_tsquery_and IS NOT NULL AND r.search @@ to_tsquery('english', v_tsquery_and))
    LIMIT v_cte_cap
  ),
  fuzzy_hits AS (
    SELECT
      r.id,
      GREATEST(
        similarity(coalesce(r.title, ''), v_query),
        similarity(coalesce(r.email, ''), v_query),
        CASE
          WHEN length(v_digits) >= 4
          THEN similarity(regexp_replace(coalesce(r.phone, ''), '\D', '', 'g'), v_digits)
          ELSE 0::real
        END,
        similarity(
          coalesce(r.data->>'first_name', '') || ' ' ||
          coalesce(r.data->>'last_name', ''),
          v_query
        )
      )::real AS rank,
      'fuzzy'::text AS match_type
    FROM public.crm_records r
    WHERE r.organization_id = p_org_id
      AND (
        r.title % v_query
        OR r.email % v_query
        OR r.phone % v_query
        OR (
          coalesce(r.data->>'first_name', '') || ' ' ||
          coalesce(r.data->>'last_name', '')
        ) % v_query
      )
    LIMIT v_cte_cap
  ),
  phone_hits AS (
    SELECT
      r.id,
      1.85::real AS rank,
      'exact'::text AS match_type
    FROM public.crm_records r
    WHERE r.organization_id = p_org_id
      AND length(v_digits) >= 4
      AND regexp_replace(coalesce(r.phone, ''), '\D', '', 'g') LIKE '%' || v_digits || '%'
    LIMIT v_cte_cap
  ),
  combined AS (
    SELECT
      h.id,
      MAX(h.rank) AS rank,
      CASE
        WHEN bool_or(h.match_type = 'exact') THEN 'exact'
        ELSE 'fuzzy'
      END AS match_type
    FROM (
      SELECT * FROM exact_hits
      UNION ALL
      SELECT * FROM fts_and_hits
      UNION ALL
      SELECT * FROM fts_or_hits
      UNION ALL
      SELECT * FROM fuzzy_hits  WHERE rank >= v_thr
      UNION ALL
      SELECT * FROM phone_hits
    ) h
    GROUP BY h.id
  )
  SELECT
    r.id,
    r.title,
    r.email,
    r.phone,
    r.status,
    r.module_id,
    r.data,
    m.key          AS module_key,
    m.name         AS module_name,
    m.name_plural  AS module_name_plural,
    c.match_type,
    c.rank
  FROM combined c
  JOIN public.crm_records r ON r.id = c.id
  JOIN public.crm_modules m ON m.id = r.module_id
  WHERE (p_module_key IS NULL OR m.key = p_module_key)
  -- Deterministic ordering: rank desc, then updated_at desc, then id as a
  -- final tiebreaker so the same query always returns the same N records.
  -- Without the `r.id` term the same query was returning different 25-row
  -- subsets of common-name buckets (e.g. all 104 PIFH "Johnson" records
  -- share an `updated_at` from the org realignment migration), which made
  -- "Jake Johnson" appear and disappear between keystrokes.
  ORDER BY c.rank DESC, r.updated_at DESC NULLS LAST, r.id
  LIMIT GREATEST(p_limit, 1);
END;
$$;


--
-- Name: FUNCTION crm_smart_search(p_org_id uuid, p_query text, p_module_key text, p_limit integer, p_similarity_threshold real); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.crm_smart_search(p_org_id uuid, p_query text, p_module_key text, p_limit integer, p_similarity_threshold real) IS 'CRM smart search v6 (deterministic): same indexes/CTEs as v5 plus a final ORDER BY tiebreaker on r.id so common-name searches return the same set of N records every time.';


--
-- Name: current_profile_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_profile_id() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT id FROM public.profiles 
  WHERE user_id = auth.uid() 
  LIMIT 1;
$$;


--
-- Name: deactivate_team_member(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deactivate_team_member(p_profile_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_target_profile record;
  v_user_profile record;
BEGIN
  -- Get target profile
  SELECT * INTO v_target_profile
  FROM profiles
  WHERE id = p_profile_id;

  IF v_target_profile IS NULL THEN
    RAISE EXCEPTION 'Profile not found';
  END IF;

  -- Cannot deactivate owner
  IF v_target_profile.role = 'owner' THEN
    RAISE EXCEPTION 'Cannot deactivate organization owner';
  END IF;

  -- Get user's profile in the same org
  SELECT id, role INTO v_user_profile
  FROM profiles
  WHERE user_id = auth.uid()
    AND organization_id = v_target_profile.organization_id
    AND is_active = true;

  -- Check permissions
  IF v_user_profile IS NULL OR v_user_profile.role NOT IN ('owner', 'super_admin', 'admin') THEN
    RAISE EXCEPTION 'Insufficient permissions';
  END IF;

  -- Cannot deactivate yourself
  IF v_target_profile.id = v_user_profile.id THEN
    RAISE EXCEPTION 'Cannot deactivate yourself';
  END IF;

  -- Deactivate
  UPDATE profiles
  SET
    is_active = false,
    updated_at = now()
  WHERE id = p_profile_id;

  RETURN true;
END;
$$;


--
-- Name: decrypt_token(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decrypt_token(encrypted_token text, secret text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_encrypted bytea;
  v_key_bytes bytea;
  v_result bytea;
BEGIN
  v_encrypted := decode(encrypted_token, 'base64');
  v_key_bytes := decode(md5(secret), 'hex');
  v_result := v_encrypted;
  FOR i IN 0..octet_length(v_encrypted) - 1 LOOP
    v_result := set_byte(v_result, i,
      get_byte(v_encrypted, i) # get_byte(v_key_bytes, i % octet_length(v_key_bytes))
    );
  END LOOP;
  RETURN convert_from(v_result, 'UTF8');
END;
$$;


--
-- Name: deduplicate_contacts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deduplicate_contacts() RETURNS TABLE(duplicates_found integer, records_merged integer, records_deleted integer, name_phone_duplicates_found integer, name_phone_deleted integer)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org_id uuid;
  v_module_id uuid;
  v_dup RECORD;
  v_keeper_id uuid;
  v_dupe_rec RECORD;
  v_duplicates_found int := 0;
  v_records_merged int := 0;
  v_records_deleted int := 0;
  v_np_duplicates_found int := 0;
  v_np_deleted int := 0;
BEGIN
  SELECT id INTO v_org_id FROM organizations LIMIT 1;
  SELECT id INTO v_module_id FROM crm_modules
  WHERE organization_id = v_org_id AND key = 'contacts';

  -- Phase 1: Deduplicate by email
  FOR v_dup IN
    SELECT LOWER(email) AS norm_email, COUNT(*) AS cnt
    FROM crm_records
    WHERE organization_id = v_org_id AND module_id = v_module_id
      AND email IS NOT NULL AND email != ''
    GROUP BY LOWER(email) HAVING COUNT(*) > 1
    ORDER BY COUNT(*) DESC
  LOOP
    v_duplicates_found := v_duplicates_found + 1;
    SELECT id INTO v_keeper_id FROM crm_records
    WHERE organization_id = v_org_id AND module_id = v_module_id
      AND LOWER(email) = v_dup.norm_email
    ORDER BY updated_at DESC LIMIT 1;

    FOR v_dupe_rec IN
      SELECT id, data FROM crm_records
      WHERE organization_id = v_org_id AND module_id = v_module_id
        AND LOWER(email) = v_dup.norm_email AND id != v_keeper_id
      ORDER BY updated_at DESC
    LOOP
      UPDATE crm_records SET
        data = (
          SELECT COALESCE(jsonb_object_agg(key, value), '{}'::jsonb)
          FROM jsonb_each(
            COALESCE(v_dupe_rec.data, '{}'::jsonb) ||
            COALESCE((SELECT data FROM crm_records WHERE id = v_keeper_id), '{}'::jsonb)
          )
          WHERE value IS NOT NULL AND value != 'null'::jsonb AND value != '""'::jsonb
        ),
        updated_at = now()
      WHERE id = v_keeper_id;
      v_records_merged := v_records_merged + 1;
      DELETE FROM crm_records WHERE id = v_dupe_rec.id;
      v_records_deleted := v_records_deleted + 1;
    END LOOP;
  END LOOP;

  -- Phase 2: Deduplicate by name + phone
  FOR v_dup IN
    SELECT LOWER(data->>'first_name') AS norm_first,
           LOWER(data->>'last_name') AS norm_last,
           phone AS norm_phone, COUNT(*) AS cnt
    FROM crm_records
    WHERE organization_id = v_org_id AND module_id = v_module_id
      AND data->>'first_name' IS NOT NULL AND data->>'last_name' IS NOT NULL
      AND phone IS NOT NULL AND phone != ''
    GROUP BY LOWER(data->>'first_name'), LOWER(data->>'last_name'), phone
    HAVING COUNT(*) > 1
    ORDER BY COUNT(*) DESC
  LOOP
    v_np_duplicates_found := v_np_duplicates_found + 1;
    SELECT id INTO v_keeper_id FROM crm_records
    WHERE organization_id = v_org_id AND module_id = v_module_id
      AND LOWER(data->>'first_name') = v_dup.norm_first
      AND LOWER(data->>'last_name') = v_dup.norm_last
      AND phone = v_dup.norm_phone
    ORDER BY updated_at DESC LIMIT 1;

    FOR v_dupe_rec IN
      SELECT id, data FROM crm_records
      WHERE organization_id = v_org_id AND module_id = v_module_id
        AND LOWER(data->>'first_name') = v_dup.norm_first
        AND LOWER(data->>'last_name') = v_dup.norm_last
        AND phone = v_dup.norm_phone AND id != v_keeper_id
      ORDER BY updated_at DESC
    LOOP
      UPDATE crm_records SET
        data = (
          SELECT COALESCE(jsonb_object_agg(key, value), '{}'::jsonb)
          FROM jsonb_each(
            COALESCE(v_dupe_rec.data, '{}'::jsonb) ||
            COALESCE((SELECT data FROM crm_records WHERE id = v_keeper_id), '{}'::jsonb)
          )
          WHERE value IS NOT NULL AND value != 'null'::jsonb AND value != '""'::jsonb
        ),
        updated_at = now()
      WHERE id = v_keeper_id;
      DELETE FROM crm_records WHERE id = v_dupe_rec.id;
      v_np_deleted := v_np_deleted + 1;
    END LOOP;
  END LOOP;

  RETURN QUERY SELECT v_duplicates_found, v_records_merged, v_records_deleted, v_np_duplicates_found, v_np_deleted;
END;
$$;


--
-- Name: detect_payout_anomalies(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.detect_payout_anomalies(p_batch_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_batch          record;
  v_config         jsonb;
  v_spike_mult     numeric;
  v_payout_row     record;
  v_avg_amount     numeric;
  v_flags_raised   int := 0;
  v_dup_count      int := 0;
  v_results        jsonb := '[]'::jsonb;
BEGIN
  SELECT * INTO v_batch
  FROM commission_payment_batches
  WHERE id = p_batch_id;

  IF v_batch IS NULL THEN
    RETURN jsonb_build_object('error', 'Batch not found');
  END IF;

  v_config := get_payout_compliance_config(v_batch.organization_id);
  v_spike_mult := (v_config->>'spike_multiplier')::numeric;

  -- Check each payout item in the batch
  FOR v_payout_row IN
    SELECT
      cp.id AS payout_id,
      cp.advisor_id,
      cp.net_payout
    FROM commission_payouts cp
    WHERE cp.id IN (
      SELECT DISTINCT payout_id FROM commission_ledger
      WHERE payout_batch_id = p_batch_id AND payout_id IS NOT NULL
    )
  LOOP
    -- Calculate 3-month average for this advisor (excluding current batch)
    SELECT COALESCE(avg(cp2.net_payout), 0)
    INTO v_avg_amount
    FROM commission_payouts cp2
    WHERE cp2.advisor_id = v_payout_row.advisor_id
      AND cp2.status = 'paid'
      AND cp2.paid_at >= (current_date - interval '3 months')
      AND cp2.id <> v_payout_row.payout_id;

    -- Spike detection: only flag if there's a meaningful baseline
    IF v_avg_amount > 50  -- Minimum $50 baseline to avoid flagging tiny amounts
       AND v_payout_row.net_payout > (v_avg_amount * v_spike_mult)
    THEN
      INSERT INTO payout_fraud_flags (
        organization_id, advisor_id, batch_id,
        flag_type, severity,
        amount, baseline_amount, multiplier,
        details
      ) VALUES (
        v_batch.organization_id, v_payout_row.advisor_id, p_batch_id,
        'spike_detected',
        CASE
          WHEN v_payout_row.net_payout > v_avg_amount * 10 THEN 'critical'
          WHEN v_payout_row.net_payout > v_avg_amount * 5 THEN 'high'
          ELSE 'medium'
        END,
        v_payout_row.net_payout, v_avg_amount,
        round(v_payout_row.net_payout / v_avg_amount, 2),
        jsonb_build_object(
          'payout_id', v_payout_row.payout_id,
          'batch_number', v_batch.batch_number
        )
      );

      -- Audit log
      INSERT INTO payout_audit_log (
        organization_id, event_type, entity_type, entity_id,
        actor_type, amount, details
      ) VALUES (
        v_batch.organization_id, 'fraud_flag_raised', 'commission_payout', v_payout_row.payout_id,
        'system', v_payout_row.net_payout,
        jsonb_build_object(
          'flag_type', 'spike_detected',
          'baseline', v_avg_amount,
          'multiplier', round(v_payout_row.net_payout / v_avg_amount, 2)
        )
      );

      v_flags_raised := v_flags_raised + 1;
      v_results := v_results || jsonb_build_object(
        'advisor_id', v_payout_row.advisor_id,
        'amount', v_payout_row.net_payout,
        'baseline', v_avg_amount,
        'multiplier', round(v_payout_row.net_payout / v_avg_amount, 2)
      );
    END IF;

    -- Threshold breach detection
    IF v_payout_row.net_payout > (v_config->>'max_single_payout')::numeric THEN
      INSERT INTO payout_fraud_flags (
        organization_id, advisor_id, batch_id,
        flag_type, severity,
        amount, details
      ) VALUES (
        v_batch.organization_id, v_payout_row.advisor_id, p_batch_id,
        'threshold_breach', 'critical',
        v_payout_row.net_payout,
        jsonb_build_object(
          'threshold', v_config->>'max_single_payout',
          'payout_id', v_payout_row.payout_id
        )
      );
      v_flags_raised := v_flags_raised + 1;
    END IF;
  END LOOP;

  -- Duplicate bank account detection (if payment_reference populated)
  INSERT INTO payout_fraud_flags (
    organization_id, advisor_id, batch_id,
    flag_type, severity, details
  )
  SELECT
    v_batch.organization_id,
    cp.advisor_id,
    p_batch_id,
    'duplicate_bank',
    'high',
    jsonb_build_object(
      'payment_reference', cp.payment_reference,
      'other_advisors', (
        SELECT jsonb_agg(DISTINCT cp2.advisor_id)
        FROM commission_payouts cp2
        WHERE cp2.payment_reference = cp.payment_reference
          AND cp2.advisor_id <> cp.advisor_id
          AND cp2.organization_id = v_batch.organization_id
          AND cp2.status IN ('paid', 'processing')
      )
    )
  FROM commission_payouts cp
  WHERE cp.id IN (
    SELECT DISTINCT payout_id FROM commission_ledger
    WHERE payout_batch_id = p_batch_id AND payout_id IS NOT NULL
  )
  AND cp.payment_reference IS NOT NULL
  AND cp.payment_reference <> ''
  AND EXISTS (
    SELECT 1 FROM commission_payouts cp2
    WHERE cp2.payment_reference = cp.payment_reference
      AND cp2.advisor_id <> cp.advisor_id
      AND cp2.organization_id = v_batch.organization_id
      AND cp2.status IN ('paid', 'processing')
  );

  GET DIAGNOSTICS v_dup_count = ROW_COUNT;
  v_flags_raised := v_flags_raised + v_dup_count;

  RETURN jsonb_build_object(
    'batch_id', p_batch_id,
    'flags_raised', v_flags_raised,
    'spike_details', v_results,
    'checked_at', now()
  );
END;
$_$;


--
-- Name: dismiss_duplicate_pair(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dismiss_duplicate_pair(p_a_id uuid, p_b_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor_profile_id uuid;
  v_actor_org_id     uuid;
  v_actor_role       text;
  v_left_id          uuid;
  v_right_id         uuid;
  v_a_org_id         uuid;
  v_b_org_id         uuid;
BEGIN
  IF p_a_id IS NULL OR p_b_id IS NULL OR p_a_id = p_b_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Two different record ids are required');
  END IF;

  SELECT id, organization_id, crm_role
    INTO v_actor_profile_id, v_actor_org_id, v_actor_role
    FROM public.profiles
   WHERE user_id = auth.uid()
   LIMIT 1;

  IF v_actor_profile_id IS NULL OR v_actor_role NOT IN ('crm_admin', 'crm_manager') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Only CRM admins and managers can dismiss duplicate pairs');
  END IF;

  SELECT organization_id INTO v_a_org_id FROM public.crm_records WHERE id = p_a_id;
  SELECT organization_id INTO v_b_org_id FROM public.crm_records WHERE id = p_b_id;

  IF v_a_org_id IS NULL OR v_b_org_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'One or both records do not exist');
  END IF;

  IF v_a_org_id <> v_actor_org_id OR v_b_org_id <> v_actor_org_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Records must belong to your organization');
  END IF;

  IF v_a_org_id <> v_b_org_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Records must belong to the same organization');
  END IF;

  v_left_id  := LEAST(p_a_id, p_b_id);
  v_right_id := GREATEST(p_a_id, p_b_id);

  INSERT INTO public.crm_duplicate_dismissals (organization_id, left_record_id, right_record_id, dismissed_by, reason)
  VALUES (v_actor_org_id, v_left_id, v_right_id, v_actor_profile_id, NULLIF(TRIM(p_reason), ''))
  ON CONFLICT (organization_id, left_record_id, right_record_id) DO UPDATE
    SET dismissed_by = EXCLUDED.dismissed_by,
        dismissed_at = now(),
        reason       = EXCLUDED.reason;

  INSERT INTO public.crm_audit_log (organization_id, actor_id, entity, entity_id, action, diff)
  VALUES (
    v_actor_org_id,
    v_actor_profile_id,
    'record',
    v_left_id,
    'duplicate_dismissed',
    jsonb_build_object(
      'left_id',  v_left_id,
      'right_id', v_right_id,
      'reason',   NULLIF(TRIM(p_reason), '')
    )
  );

  RETURN jsonb_build_object('success', true, 'left_id', v_left_id, 'right_id', v_right_id);
END;
$$;


--
-- Name: drop_old_activity_log_partitions(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.drop_old_activity_log_partitions(retention_months integer DEFAULT 6) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  cutoff_date     date;
  rec             record;
  dropped_count   int := 0;
  p_year          int;
  p_month         int;
  p_start         date;
BEGIN
  cutoff_date := (date_trunc('month', now()) - (retention_months || ' months')::interval)::date;

  FOR rec IN
    SELECT inhrelid::regclass::text AS partition_name
      FROM pg_inherits
     WHERE inhparent = 'activity_log'::regclass
       AND inhrelid::regclass::text != 'activity_log_default'
     ORDER BY inhrelid::regclass::text
  LOOP
    -- Parse year/month from partition name: activity_log_yYYYYmMM
    IF rec.partition_name ~ 'activity_log_y\d{4}m\d{2}' THEN
      p_year  := substring(rec.partition_name FROM 'y(\d{4})')::int;
      p_month := substring(rec.partition_name FROM 'm(\d{2})')::int;
      p_start := make_date(p_year, p_month, 1);

      IF p_start < cutoff_date THEN
        EXECUTE format('DROP TABLE IF EXISTS %I', rec.partition_name);
        dropped_count := dropped_count + 1;
        RAISE NOTICE 'Dropped old activity_log partition: %', rec.partition_name;
      END IF;
    END IF;
  END LOOP;

  RETURN dropped_count;
END;
$$;


--
-- Name: FUNCTION drop_old_activity_log_partitions(retention_months integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.drop_old_activity_log_partitions(retention_months integer) IS 'Drops activity_log partitions older than N months. Returns the number of partitions dropped.';


