--
-- Name: encrypt_token(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.encrypt_token(token text, secret text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_token_bytes bytea;
  v_key_bytes bytea;
  v_result bytea;
BEGIN
  v_token_bytes := convert_to(token, 'UTF8');
  v_key_bytes := decode(md5(secret), 'hex');
  v_result := v_token_bytes;
  FOR i IN 0..octet_length(v_token_bytes) - 1 LOOP
    v_result := set_byte(v_result, i,
      get_byte(v_token_bytes, i) # get_byte(v_key_bytes, i % octet_length(v_key_bytes))
    );
  END LOOP;
  RETURN encode(v_result, 'base64');
END;
$$;


--
-- Name: enforce_no_phi(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_no_phi() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  -- Check ticket description field for PHI
  IF TG_TABLE_NAME = 'tickets' THEN
    IF NEW.description IS NOT NULL THEN
      IF NOT public.validate_free_text(NEW.description) THEN
        RAISE EXCEPTION 'PHI-like content detected in description. Please use secure forms for sensitive information.'
        USING ERRCODE = 'P0001',
        HINT = 'Remove Social Security Numbers, Medical Record Numbers, diagnoses, or dates of birth.';
      END IF;
    END IF;
    
    IF NEW.subject IS NOT NULL THEN
      IF NOT public.validate_free_text(NEW.subject) THEN
        RAISE EXCEPTION 'PHI-like content detected in subject. Please use secure forms for sensitive information.'
        USING ERRCODE = 'P0001',
        HINT = 'Remove Social Security Numbers, Medical Record Numbers, diagnoses, or dates of birth.';
      END IF;
    END IF;
  END IF;

  -- Check ticket comment body field for PHI
  IF TG_TABLE_NAME = 'ticket_comments' THEN
    IF NEW.body IS NOT NULL THEN
      IF NOT public.validate_free_text(NEW.body) THEN
        RAISE EXCEPTION 'PHI-like content detected in comment. Please use secure forms for sensitive information.'
        USING ERRCODE = 'P0001',
        HINT = 'Remove Social Security Numbers, Medical Record Numbers, diagnoses, or dates of birth.';
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION enforce_no_phi(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.enforce_no_phi() IS 'Trigger function to prevent PHI in tickets and comments';


--
-- Name: ensure_activity_log_partitions(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_activity_log_partitions(months_ahead integer DEFAULT 3) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  partition_date  date;
  partition_name  text;
  start_date      date;
  end_date        date;
BEGIN
  FOR i IN 0..months_ahead LOOP
    partition_date := date_trunc('month', now())::date + (i || ' months')::interval;
    partition_name := 'activity_log_y' || to_char(partition_date, 'YYYY') || 'm' || to_char(partition_date, 'MM');
    start_date     := partition_date;
    end_date       := (partition_date + '1 month'::interval)::date;

    IF NOT EXISTS (
      SELECT 1 FROM pg_class WHERE relname = partition_name
    ) THEN
      EXECUTE format(
        'CREATE TABLE IF NOT EXISTS %I PARTITION OF activity_log FOR VALUES FROM (%L) TO (%L)',
        partition_name, start_date, end_date
      );
      RAISE NOTICE 'Created activity_log partition: %', partition_name;
    END IF;
  END LOOP;
END;
$$;


--
-- Name: FUNCTION ensure_activity_log_partitions(months_ahead integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ensure_activity_log_partitions(months_ahead integer) IS 'Creates monthly activity_log partitions for the next N months. Safe to call repeatedly — skips existing partitions.';


--
-- Name: ensure_single_default_sender(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_single_default_sender() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.is_default = true THEN
    UPDATE email_sender_addresses
    SET is_default = false, updated_at = now()
    WHERE organization_id = NEW.organization_id
      AND id != NEW.id
      AND is_default = true;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: execute_payout_batch(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.execute_payout_batch(p_batch_id uuid, p_provider_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_batch           record;
  v_provider        record;
  v_payout_row      record;
  v_txn_id          uuid;
  v_items           jsonb := '[]'::jsonb;
  v_item_count      int := 0;
  v_already_exists  int;
BEGIN
  -- Lock the batch
  SELECT * INTO v_batch
  FROM commission_payment_batches
  WHERE id = p_batch_id
  FOR UPDATE;

  IF v_batch IS NULL THEN
    RETURN jsonb_build_object('error', 'Batch not found');
  END IF;

  -- Must be in processing state (approved)
  IF v_batch.status <> 'processing' THEN
    RETURN jsonb_build_object(
      'error', 'Batch must be in processing state. Current: ' || v_batch.status,
      'code', 'INVALID_STATE'
    );
  END IF;

  -- Check for already-completed execution (idempotency)
  IF v_batch.status = 'paid' THEN
    RETURN jsonb_build_object(
      'batch_id', p_batch_id,
      'status', 'paid',
      'already_completed', true
    );
  END IF;

  -- Resolve provider
  IF p_provider_id IS NOT NULL THEN
    SELECT * INTO v_provider
    FROM payment_providers
    WHERE id = p_provider_id
      AND organization_id = v_batch.organization_id
      AND is_active = true;
  ELSE
    -- Use org default provider
    SELECT * INTO v_provider
    FROM payment_providers
    WHERE organization_id = v_batch.organization_id
      AND is_default = true
      AND is_active = true;
  END IF;

  -- Fallback to manual if no provider configured
  IF v_provider IS NULL THEN
    -- Auto-create manual provider for this org
    INSERT INTO payment_providers (organization_id, provider_type, display_name, is_active, is_default)
    VALUES (v_batch.organization_id, 'manual', 'Manual Processing', true, true)
    ON CONFLICT DO NOTHING;

    SELECT * INTO v_provider
    FROM payment_providers
    WHERE organization_id = v_batch.organization_id
      AND is_default = true
      AND is_active = true;
  END IF;

  -- Create provider transaction records for each payout item
  FOR v_payout_row IN
    SELECT cp.id AS payout_id, cp.advisor_id, cp.net_payout
    FROM commission_payouts cp
    WHERE cp.id IN (
      SELECT DISTINCT payout_id FROM commission_ledger
      WHERE payout_batch_id = p_batch_id AND payout_id IS NOT NULL
    )
    AND cp.status = 'processing'
  LOOP
    -- Check if a non-failed transaction already exists (idempotency)
    SELECT count(*) INTO v_already_exists
    FROM payout_provider_transactions
    WHERE payout_item_id = v_payout_row.payout_id
      AND status <> 'failed';

    IF v_already_exists > 0 THEN
      CONTINUE; -- Skip — already has a pending/submitted/succeeded transaction
    END IF;

    -- Generate idempotency key: batch_id + payout_id + attempt
    INSERT INTO payout_provider_transactions (
      organization_id, payout_item_id, batch_id,
      provider_id, provider_type,
      idempotency_key, amount, currency, status
    ) VALUES (
      v_batch.organization_id,
      v_payout_row.payout_id,
      p_batch_id,
      v_provider.id,
      v_provider.provider_type,
      p_batch_id::text || ':' || v_payout_row.payout_id::text || ':' ||
        (SELECT count(*) + 1 FROM payout_provider_transactions WHERE payout_item_id = v_payout_row.payout_id),
      v_payout_row.net_payout,
      'usd',
      'pending'
    )
    RETURNING id INTO v_txn_id;

    v_items := v_items || jsonb_build_object(
      'txn_id', v_txn_id,
      'payout_item_id', v_payout_row.payout_id,
      'advisor_id', v_payout_row.advisor_id,
      'amount', v_payout_row.net_payout,
      'provider_type', v_provider.provider_type
    );

    v_item_count := v_item_count + 1;
  END LOOP;

  -- Log to payout_batch_logs
  INSERT INTO payout_batch_logs (
    organization_id, batch_id, action,
    actor_type, prev_status, new_status, details
  ) VALUES (
    v_batch.organization_id, p_batch_id, 'processing',
    'system', 'processing', 'processing',
    jsonb_build_object(
      'provider_type', v_provider.provider_type,
      'provider_id', v_provider.id,
      'items_to_process', v_item_count
    )
  );

  -- Audit log
  INSERT INTO payout_audit_log (
    organization_id, event_type, entity_type, entity_id,
    actor_type, amount, details
  ) VALUES (
    v_batch.organization_id, 'batch_processing', 'commission_payment_batch', p_batch_id,
    'system', v_batch.total_amount,
    jsonb_build_object(
      'provider_type', v_provider.provider_type,
      'items_to_process', v_item_count
    )
  );

  RETURN jsonb_build_object(
    'batch_id', p_batch_id,
    'provider_id', v_provider.id,
    'provider_type', v_provider.provider_type,
    'items', v_items,
    'item_count', v_item_count
  );
END;
$$;


--
-- Name: execute_report_aggregation(uuid, text, text, uuid, jsonb, text, jsonb, jsonb, jsonb, integer, integer, text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.execute_report_aggregation(p_org_id uuid, p_table text, p_org_column text DEFAULT 'organization_id'::text, p_module_id uuid DEFAULT NULL::uuid, p_filters jsonb DEFAULT '[]'::jsonb, p_filter_logic text DEFAULT 'and'::text, p_grouping jsonb DEFAULT '[]'::jsonb, p_aggregations jsonb DEFAULT '[]'::jsonb, p_sorting jsonb DEFAULT '[]'::jsonb, p_limit integer DEFAULT 1000, p_offset integer DEFAULT 0, p_product_type text DEFAULT NULL::text, p_advisor_id uuid DEFAULT NULL::uuid, p_include_downline boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_sql text;
  v_select text;
  v_where text;
  v_group_by text := '';
  v_order_by text := '';
  v_having text := '';
  v_result jsonb;
  v_count_result bigint;
  v_agg record;
  v_grp record;
  v_flt record;
  v_srt record;
  v_i int := 0;
  v_col_name text;
  v_allowed_tables text[] := ARRAY[
    'crm_records', 'crm_tasks', 'members', 'advisors',
    'enrollments', 'commissions', 'commission_rates', 'products'
  ];
  v_col_re text := '^[a-zA-Z_][a-zA-Z0-9_]*$';
BEGIN
  -- Validate table name (whitelist)
  IF p_table IS NULL OR NOT (p_table = ANY(v_allowed_tables)) THEN
    RAISE EXCEPTION 'Invalid table: %', p_table;
  END IF;

  -- Validate org column
  IF p_org_column NOT IN ('org_id', 'organization_id') THEN
    RAISE EXCEPTION 'Invalid org column: %', p_org_column;
  END IF;

  -- Tenant-key cutover: org_id == organization_id (sync-locked). Normalize the
  -- legacy column name to the canonical one so this RPC stays correct after the
  -- org_id column is dropped. Behavior-preserving today (values identical).
  p_org_column := 'organization_id';

  -- Build SELECT: group fields + aggregations
  v_select := '';

  -- Add grouping columns to SELECT
  FOR v_grp IN SELECT * FROM jsonb_array_elements(p_grouping)
  LOOP
    v_col_name := v_grp.value->>'field';
    IF v_col_name IS NULL OR v_col_name !~ v_col_re THEN
      CONTINUE;
    END IF;
    IF v_select != '' THEN v_select := v_select || ', '; END IF;
    v_select := v_select || format('%I', v_col_name);
    IF v_group_by != '' THEN v_group_by := v_group_by || ', '; END IF;
    v_group_by := v_group_by || format('%I', v_col_name);
  END LOOP;

  -- Add aggregation columns to SELECT
  FOR v_agg IN SELECT * FROM jsonb_array_elements(p_aggregations)
  LOOP
    v_col_name := v_agg.value->>'field';
    IF v_col_name IS NULL OR v_col_name !~ v_col_re THEN
      CONTINUE;
    END IF;

    IF v_select != '' THEN v_select := v_select || ', '; END IF;

    CASE (v_agg.value->>'function')
      WHEN 'count' THEN
        v_select := v_select || format('COUNT(%I) AS %I', v_col_name, 'count_' || v_col_name);
      WHEN 'sum' THEN
        v_select := v_select || format('SUM((%I)::numeric) AS %I', v_col_name, 'sum_' || v_col_name);
      WHEN 'avg' THEN
        v_select := v_select || format('ROUND(AVG((%I)::numeric), 2) AS %I', v_col_name, 'avg_' || v_col_name);
      WHEN 'min' THEN
        v_select := v_select || format('MIN(%I) AS %I', v_col_name, 'min_' || v_col_name);
      WHEN 'max' THEN
        v_select := v_select || format('MAX(%I) AS %I', v_col_name, 'max_' || v_col_name);
      ELSE
        CONTINUE;
    END CASE;
  END LOOP;

  -- Fallback: if no aggregations and no grouping, just count
  IF v_select = '' THEN
    v_select := 'COUNT(*) AS total_count';
  END IF;

  -- Build WHERE clause
  v_where := format('%I = %L', p_org_column, p_org_id);

  -- Module filter
  IF p_module_id IS NOT NULL THEN
    v_where := v_where || format(' AND module_id = %L', p_module_id);
  END IF;

  -- Product type filter
  IF p_product_type IS NOT NULL AND p_product_type != '' THEN
    v_where := v_where || format(' AND product_type = %L', p_product_type);
  END IF;

  -- Advisor filter (with optional downline via recursive CTE)
  IF p_advisor_id IS NOT NULL THEN
    IF p_include_downline THEN
      v_where := v_where || format(
        ' AND advisor_id IN (
          SELECT %L::uuid
          UNION ALL
          SELECT id FROM get_advisor_downline_ids(%L)
        )',
        p_advisor_id, p_advisor_id
      );
    ELSE
      v_where := v_where || format(' AND advisor_id = %L', p_advisor_id);
    END IF;
  END IF;

  -- Apply user-defined filters
  FOR v_flt IN SELECT * FROM jsonb_array_elements(p_filters)
  LOOP
    v_col_name := v_flt.value->>'field';
    IF v_col_name IS NULL OR v_col_name !~ v_col_re THEN
      CONTINUE;
    END IF;

    DECLARE
      v_op text := COALESCE(v_flt.value->>'operator', 'equals');
      v_val text := v_flt.value->>'value';
      v_val2 text := v_flt.value->>'value2';
      v_connector text := CASE WHEN p_filter_logic = 'or' THEN ' OR ' ELSE ' AND ' END;
    BEGIN
      CASE v_op
        WHEN 'equals', 'eq' THEN
          v_where := v_where || v_connector || format('%I = %L', v_col_name, v_val);
        WHEN 'not_equals', 'neq' THEN
          v_where := v_where || v_connector || format('%I != %L', v_col_name, v_val);
        WHEN 'contains', 'ilike' THEN
          v_where := v_where || v_connector || format('%I ILIKE %L', v_col_name, '%' || v_val || '%');
        WHEN 'not_contains' THEN
          v_where := v_where || v_connector || format('%I NOT ILIKE %L', v_col_name, '%' || v_val || '%');
        WHEN 'starts_with' THEN
          v_where := v_where || v_connector || format('%I ILIKE %L', v_col_name, v_val || '%');
        WHEN 'gt' THEN
          v_where := v_where || v_connector || format('%I > %L', v_col_name, v_val);
        WHEN 'gte' THEN
          v_where := v_where || v_connector || format('%I >= %L', v_col_name, v_val);
        WHEN 'lt' THEN
          v_where := v_where || v_connector || format('%I < %L', v_col_name, v_val);
        WHEN 'lte' THEN
          v_where := v_where || v_connector || format('%I <= %L', v_col_name, v_val);
        WHEN 'between' THEN
          v_where := v_where || v_connector || format('%I BETWEEN %L AND %L', v_col_name, v_val, v_val2);
        WHEN 'in', 'is_any_of' THEN
          -- Value is comma-separated
          v_where := v_where || v_connector || format('%I = ANY(string_to_array(%L, %L))', v_col_name, v_val, ',');
        WHEN 'is_empty', 'is_null' THEN
          v_where := v_where || v_connector || format('%I IS NULL', v_col_name);
        WHEN 'is_not_empty', 'is_not_null' THEN
          v_where := v_where || v_connector || format('%I IS NOT NULL', v_col_name);
        ELSE
          NULL; -- skip unknown operators
      END CASE;
    END;
  END LOOP;

  -- Build ORDER BY
  IF p_sorting IS NOT NULL AND jsonb_array_length(p_sorting) > 0 THEN
    FOR v_srt IN SELECT * FROM jsonb_array_elements(p_sorting)
    LOOP
      v_col_name := v_srt.value->>'column';
      IF v_col_name IS NULL OR v_col_name !~ v_col_re THEN
        CONTINUE;
      END IF;
      IF v_order_by != '' THEN v_order_by := v_order_by || ', '; END IF;
      v_order_by := v_order_by || format('%I %s', v_col_name,
        CASE WHEN (v_srt.value->>'direction') = 'desc' THEN 'DESC' ELSE 'ASC' END
      );
    END LOOP;
  END IF;

  -- Assemble query
  v_sql := 'SELECT ' || v_select || format(' FROM %I WHERE ', p_table) || v_where;

  IF v_group_by != '' THEN
    v_sql := v_sql || ' GROUP BY ' || v_group_by;
  END IF;

  IF v_order_by != '' THEN
    v_sql := v_sql || ' ORDER BY ' || v_order_by;
  ELSIF v_group_by != '' THEN
    v_sql := v_sql || ' ORDER BY ' || v_group_by;
  END IF;

  v_sql := v_sql || format(' LIMIT %s OFFSET %s', p_limit, p_offset);

  -- Execute and return as JSONB
  EXECUTE format(
    'SELECT COALESCE(jsonb_agg(row_to_json(t)), ''[]''::jsonb) FROM (%s) t',
    v_sql
  ) INTO v_result;

  -- Get total count for pagination
  IF v_group_by != '' THEN
    EXECUTE format(
      'SELECT COUNT(*) FROM (SELECT 1 FROM %I WHERE %s GROUP BY %s) sub',
      p_table, v_where, v_group_by
    ) INTO v_count_result;
  ELSE
    EXECUTE format('SELECT COUNT(*) FROM %I WHERE %s', p_table, v_where)
      INTO v_count_result;
  END IF;

  RETURN jsonb_build_object(
    'rows', v_result,
    'total', v_count_result
  );
END;
$_$;


--
-- Name: FUNCTION execute_report_aggregation(p_org_id uuid, p_table text, p_org_column text, p_module_id uuid, p_filters jsonb, p_filter_logic text, p_grouping jsonb, p_aggregations jsonb, p_sorting jsonb, p_limit integer, p_offset integer, p_product_type text, p_advisor_id uuid, p_include_downline boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.execute_report_aggregation(p_org_id uuid, p_table text, p_org_column text, p_module_id uuid, p_filters jsonb, p_filter_logic text, p_grouping jsonb, p_aggregations jsonb, p_sorting jsonb, p_limit integer, p_offset integer, p_product_type text, p_advisor_id uuid, p_include_downline boolean) IS 'Server-side report execution with GROUP BY, aggregations, capacity filtering, and downline support';


--
-- Name: execute_report_query(uuid, uuid, text, text, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.execute_report_query(p_org_id uuid, p_primary_module_id uuid, p_related_modules text DEFAULT '[]'::text, p_columns text DEFAULT '[]'::text, p_filters text DEFAULT '[]'::text, p_filter_logic text DEFAULT NULL::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_related jsonb;
  v_result jsonb;
  v_sql text;
  v_where text := '';
  v_joins text := '';
  v_select text := '';
  v_rm record;
  v_i int := 0;
  v_alias text;
  v_mod_id uuid;
  v_join_type text;
BEGIN
  v_related := p_related_modules::jsonb;

  -- Build base SELECT
  v_select := 'SELECT p.id, p.data AS primary_data, p.created_at, p.updated_at';

  -- Build JOINs for each related module
  FOR v_rm IN SELECT * FROM jsonb_array_elements(v_related)
  LOOP
    v_i := v_i + 1;
    v_alias := 'r' || v_i;
    v_mod_id := (v_rm.value->>'module_id')::uuid;
    v_join_type := COALESCE(v_rm.value->>'join_type', 'inclusive');

    -- Add related module data to SELECT
    v_select := v_select || format(
      ', %I.data AS %s_data',
      v_alias,
      COALESCE(v_rm.value->>'module_key', 'related' || v_i)
    );

    -- Build JOIN via crm_record_links
    IF v_join_type = 'exclusive' THEN
      v_joins := v_joins || format(
        ' INNER JOIN crm_record_links %s_link ON (%s_link.source_record_id = p.id OR %s_link.target_record_id = p.id)'
        || ' INNER JOIN crm_records %I ON (%I.id = CASE WHEN %s_link.source_record_id = p.id THEN %s_link.target_record_id ELSE %s_link.source_record_id END'
        || ' AND %I.module_id = %L AND %I.organization_id = %L)',
        v_alias, v_alias, v_alias,
        v_alias, v_alias, v_alias, v_alias, v_alias,
        v_alias, v_mod_id, v_alias, p_org_id
      );
    ELSE
      v_joins := v_joins || format(
        ' LEFT JOIN crm_record_links %s_link ON (%s_link.source_record_id = p.id OR %s_link.target_record_id = p.id)'
        || ' LEFT JOIN crm_records %I ON (%I.id = CASE WHEN %s_link.source_record_id = p.id THEN %s_link.target_record_id ELSE %s_link.source_record_id END'
        || ' AND %I.module_id = %L AND %I.organization_id = %L)',
        v_alias, v_alias, v_alias,
        v_alias, v_alias, v_alias, v_alias, v_alias,
        v_alias, v_mod_id, v_alias, p_org_id
      );
    END IF;
  END LOOP;

  -- Build WHERE clause
  v_where := format(' WHERE p.organization_id = %L AND p.module_id = %L', p_org_id, p_primary_module_id);

  -- Assemble final query
  v_sql := v_select
    || ' FROM crm_records p'
    || v_joins
    || v_where
    || ' ORDER BY p.created_at DESC'
    || format(' LIMIT %s OFFSET %s', p_limit, p_offset);

  -- Execute and return as JSONB array
  EXECUTE format('SELECT COALESCE(jsonb_agg(row_to_json(t)), ''[]''::jsonb) FROM (%s) t', v_sql)
    INTO v_result;

  RETURN v_result;
END;
$$;


--
-- Name: extract_mentions_from_comment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.extract_mentions_from_comment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_mention text;
  v_email text;
  v_user_id uuid;
BEGIN
  -- Extract email addresses with @ prefix (@user@example.com)
  FOR v_mention IN 
    SELECT DISTINCT regexp_matches[1]
    FROM regexp_matches(NEW.body, '@(\S+@\S+\.\S+)', 'g') AS regexp_matches
  LOOP
    v_email := v_mention;
    
    -- Find user by email
    SELECT id INTO v_user_id
    FROM profiles
    WHERE email = v_email
    LIMIT 1;
    
    -- Create mention if user found and not the author
    IF v_user_id IS NOT NULL AND v_user_id != NEW.author_id THEN
      INSERT INTO ticket_mentions (comment_id, mentioned_user_id)
      VALUES (NEW.id, v_user_id)
      ON CONFLICT (comment_id, mentioned_user_id) DO NOTHING;
    END IF;
  END LOOP;
  
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION extract_mentions_from_comment(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.extract_mentions_from_comment() IS 'Extracts @mentions from comment text and creates mention records for notifications';


--
-- Name: filter_records_by_related(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.filter_records_by_related(p_module_id uuid, p_related_type text, p_condition text, p_activity_type text DEFAULT NULL::text) RETURNS SETOF uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  CASE p_related_type

    -- Activities (crm_tasks, optionally filtered by activity_type)
    WHEN 'activities', 'appointments', 'calls', 'emails', 'tasks' THEN
      IF p_condition = 'has_any' THEN
        RETURN QUERY
          SELECT DISTINCT r.id FROM crm_records r
          WHERE r.module_id = p_module_id
            AND EXISTS (
              SELECT 1 FROM crm_tasks t
              WHERE t.record_id = r.id
                AND (p_activity_type IS NULL OR t.activity_type = p_activity_type)
            );
      ELSIF p_condition = 'has_none' THEN
        RETURN QUERY
          SELECT r.id FROM crm_records r
          WHERE r.module_id = p_module_id
            AND NOT EXISTS (
              SELECT 1 FROM crm_tasks t
              WHERE t.record_id = r.id
                AND (p_activity_type IS NULL OR t.activity_type = p_activity_type)
            );
      END IF;

    -- Notes
    WHEN 'notes' THEN
      IF p_condition = 'has_any' THEN
        RETURN QUERY
          SELECT DISTINCT r.id FROM crm_records r
          WHERE r.module_id = p_module_id
            AND EXISTS (SELECT 1 FROM crm_notes n WHERE n.record_id = r.id);
      ELSIF p_condition = 'has_none' THEN
        RETURN QUERY
          SELECT r.id FROM crm_records r
          WHERE r.module_id = p_module_id
            AND NOT EXISTS (SELECT 1 FROM crm_notes n WHERE n.record_id = r.id);
      END IF;

    -- Linked records via crm_record_links (leads, products, invoices, etc.)
    WHEN 'linked_records' THEN
      IF p_condition = 'has_any' THEN
        RETURN QUERY
          SELECT DISTINCT r.id FROM crm_records r
          WHERE r.module_id = p_module_id
            AND EXISTS (
              SELECT 1 FROM crm_record_links rl
              JOIN crm_records tr ON tr.id = rl.target_record_id
              JOIN crm_modules tm ON tm.id = tr.module_id
              WHERE rl.source_record_id = r.id
                AND (p_activity_type IS NULL OR tm.key = p_activity_type)
            );
      ELSIF p_condition = 'has_none' THEN
        RETURN QUERY
          SELECT r.id FROM crm_records r
          WHERE r.module_id = p_module_id
            AND NOT EXISTS (
              SELECT 1 FROM crm_record_links rl
              JOIN crm_records tr ON tr.id = rl.target_record_id
              JOIN crm_modules tm ON tm.id = tr.module_id
              WHERE rl.source_record_id = r.id
                AND (p_activity_type IS NULL OR tm.key = p_activity_type)
            );
      END IF;

    -- Linked by link_type (e.g. prospect_role)
    WHEN 'linked_by_type' THEN
      IF p_condition = 'has_any' THEN
        RETURN QUERY
          SELECT DISTINCT r.id FROM crm_records r
          WHERE r.module_id = p_module_id
            AND EXISTS (
              SELECT 1 FROM crm_record_links rl
              WHERE rl.source_record_id = r.id
                AND rl.link_type = p_activity_type
            );
      ELSIF p_condition = 'has_none' THEN
        RETURN QUERY
          SELECT r.id FROM crm_records r
          WHERE r.module_id = p_module_id
            AND NOT EXISTS (
              SELECT 1 FROM crm_record_links rl
              WHERE rl.source_record_id = r.id
                AND rl.link_type = p_activity_type
            );
      END IF;

    -- Meeting invitees (tasks with activity_type='meeting' that have attendees)
    WHEN 'meeting_invitees' THEN
      IF p_condition = 'has_any' THEN
        RETURN QUERY
          SELECT DISTINCT r.id FROM crm_records r
          WHERE r.module_id = p_module_id
            AND EXISTS (
              SELECT 1 FROM crm_tasks t
              WHERE t.record_id = r.id
                AND t.activity_type = 'meeting'
                AND t.attendees IS NOT NULL
                AND array_length(t.attendees, 1) > 0
            );
      ELSIF p_condition = 'has_none' THEN
        RETURN QUERY
          SELECT r.id FROM crm_records r
          WHERE r.module_id = p_module_id
            AND NOT EXISTS (
              SELECT 1 FROM crm_tasks t
              WHERE t.record_id = r.id
                AND t.activity_type = 'meeting'
                AND t.attendees IS NOT NULL
                AND array_length(t.attendees, 1) > 0
            );
      END IF;

    ELSE
      RETURN;
  END CASE;
END;
$$;


--
-- Name: filter_records_by_system_preset(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.filter_records_by_system_preset(p_module_id uuid, p_preset text, p_user_profile_id uuid DEFAULT NULL::uuid, p_value text DEFAULT NULL::text) RETURNS SETOF uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Authorization: caller must belong to the org that owns this module
  IF NOT EXISTS (
    SELECT 1 FROM crm_modules m
    JOIN profiles p ON p.organization_id = m.organization_id
    WHERE m.id = p_module_id
      AND p.user_id = auth.uid()
  ) THEN
    RETURN;
  END IF;

  CASE p_preset
    -- ══════════════════════════════════════════════════════════
    -- BUSINESS LANE FILTERS (query columns on crm_records)
    -- ══════════════════════════════════════════════════════════
    WHEN 'healthshare_records' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id AND r.market_type = 'healthshare';

    WHEN 'insurance_records' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id AND r.market_type = 'traditional_insurance';

    WHEN 'unclassified_records' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND (r.market_type IS NULL OR r.market_type = 'unknown');

    WHEN 'needs_review_records' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.normalization_status = 'needs_review';

    -- ══════════════════════════════════════════════════════════
    -- OWNER FILTER (from Filter by Owner combobox)
    -- ══════════════════════════════════════════════════════════
    WHEN 'owner_is' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND (
            r.owner_id = p_value::uuid
            OR r.canonical_advisor_id = p_value::uuid
          );

    -- ══════════════════════════════════════════════════════════
    -- ACTIVITY / ENGAGEMENT FILTERS
    -- ══════════════════════════════════════════════════════════
    WHEN 'touched_records' THEN
      RETURN QUERY
        SELECT DISTINCT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND (EXISTS (SELECT 1 FROM crm_tasks t WHERE t.record_id = r.id)
               OR EXISTS (SELECT 1 FROM crm_notes n WHERE n.record_id = r.id));

    WHEN 'untouched_records' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND NOT EXISTS (SELECT 1 FROM crm_tasks t WHERE t.record_id = r.id)
          AND NOT EXISTS (SELECT 1 FROM crm_notes n WHERE n.record_id = r.id);

    WHEN 'my_records' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id AND r.owner_id = p_user_profile_id;

    WHEN 'unassigned' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id AND r.owner_id IS NULL;

    -- ══════════════════════════════════════════════════════════
    -- DATE FILTERS
    -- ══════════════════════════════════════════════════════════
    WHEN 'created_today' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.created_at >= date_trunc('day', now())
          AND r.created_at < date_trunc('day', now()) + interval '1 day';

    WHEN 'created_this_week' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.created_at >= date_trunc('week', now())
          AND r.created_at < date_trunc('week', now()) + interval '1 week';

    WHEN 'modified_today' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.updated_at >= date_trunc('day', now())
          AND r.updated_at < date_trunc('day', now()) + interval '1 day';

    WHEN 'modified_this_week' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.updated_at >= date_trunc('week', now())
          AND r.updated_at < date_trunc('week', now()) + interval '1 week';

    -- ══════════════════════════════════════════════════════════
    -- TASK / NOTE FILTERS
    -- ══════════════════════════════════════════════════════════
    WHEN 'has_activities' THEN
      RETURN QUERY
        SELECT DISTINCT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND EXISTS (SELECT 1 FROM crm_tasks t WHERE t.record_id = r.id);

    WHEN 'no_activities' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND NOT EXISTS (SELECT 1 FROM crm_tasks t WHERE t.record_id = r.id);

    WHEN 'has_notes' THEN
      RETURN QUERY
        SELECT DISTINCT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND EXISTS (SELECT 1 FROM crm_notes n WHERE n.record_id = r.id);

    WHEN 'has_open_tasks' THEN
      RETURN QUERY
        SELECT DISTINCT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND EXISTS (
            SELECT 1 FROM crm_tasks t
            WHERE t.record_id = r.id AND t.status NOT IN ('completed', 'cancelled')
          );

    WHEN 'has_overdue_tasks' THEN
      RETURN QUERY
        SELECT DISTINCT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND EXISTS (
            SELECT 1 FROM crm_tasks t
            WHERE t.record_id = r.id
              AND t.status NOT IN ('completed', 'cancelled')
              AND t.due_at IS NOT NULL AND t.due_at < now()
          );

    -- ══════════════════════════════════════════════════════════
    -- RECORD STATE FILTERS
    -- ══════════════════════════════════════════════════════════
    WHEN 'locked' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND (r.data->>'is_locked')::boolean = true;

    -- ══════════════════════════════════════════════════════════
    -- CAMPAIGN / CADENCE / COMMUNICATION FILTERS
    -- These check for existence of related campaign/cadence data
    -- ══════════════════════════════════════════════════════════
    WHEN 'campaigns' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'campaign_source' IS NOT NULL;

    WHEN 'cadences' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'cadence_id' IS NOT NULL;

    WHEN 'chats' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'chat_count' IS NOT NULL
          AND (r.data->>'chat_count')::int > 0;

    WHEN 'website_activity' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'website_visits' IS NOT NULL
          AND (r.data->>'website_visits')::int > 0;

    -- ══════════════════════════════════════════════════════════
    -- VALUE-BASED FILTERS (use p_value parameter)
    -- ══════════════════════════════════════════════════════════
    WHEN 'record_action' THEN
      RETURN QUERY
        SELECT DISTINCT a.record_id FROM crm_audit_log a
        JOIN crm_records r ON r.id = a.record_id
        WHERE r.module_id = p_module_id AND a.action = COALESCE(p_value, 'update');

    WHEN 'related_records_action' THEN
      RETURN QUERY
        SELECT DISTINCT a.record_id FROM crm_audit_log a
        JOIN crm_records r ON r.id = a.record_id
        WHERE r.module_id = p_module_id
          AND a.action = COALESCE(p_value, 'update')
          AND a.changes->>'related' IS NOT NULL;

    WHEN 'scoring_rules' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'score' IS NOT NULL
          AND (r.data->>'score')::int >= COALESCE(p_value::int, 0);

    WHEN 'latest_email_status' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'latest_email_status' = COALESCE(p_value, 'sent');

    WHEN 'attended_by' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'attended_by' ILIKE '%' || COALESCE(p_value, '') || '%';

    WHEN 'browser' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'browser' ILIKE '%' || COALESCE(p_value, '') || '%';

    WHEN 'operating_system' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'operating_system' ILIKE '%' || COALESCE(p_value, '') || '%';

    WHEN 'portal_name' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'portal_name' ILIKE '%' || COALESCE(p_value, '') || '%';

    WHEN 'search_engine' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'search_engine' ILIKE '%' || COALESCE(p_value, '') || '%';

    WHEN 'referrer' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'referrer' ILIKE '%' || COALESCE(p_value, '') || '%';

    WHEN 'time_spent_minutes' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'time_spent_minutes' IS NOT NULL
          AND (r.data->>'time_spent_minutes')::numeric >= COALESCE(p_value::numeric, 0);

    WHEN 'time_visited' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'time_visited' IS NOT NULL
          AND (r.data->>'time_visited')::int >= COALESCE(p_value::int, 0);

    WHEN 'avg_time_spent_minutes' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'avg_time_spent_minutes' IS NOT NULL
          AND (r.data->>'avg_time_spent_minutes')::numeric >= COALESCE(p_value::numeric, 0);

    WHEN 'days_visited' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'days_visited' IS NOT NULL
          AND (r.data->>'days_visited')::int >= COALESCE(p_value::int, 0);

    WHEN 'first_page_visited' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'first_page_visited' ILIKE '%' || COALESCE(p_value, '') || '%';

    WHEN 'first_visit' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'first_visit' IS NOT NULL
          AND (r.data->>'first_visit')::date >= COALESCE(p_value::date, '1970-01-01');

    WHEN 'most_recent_visit' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'most_recent_visit' IS NOT NULL
          AND (r.data->>'most_recent_visit')::date >= COALESCE(p_value::date, '1970-01-01');

    WHEN 'number_of_chats' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'number_of_chats' IS NOT NULL
          AND (r.data->>'number_of_chats')::int >= COALESCE(p_value::int, 0);

    WHEN 'visitor_score' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'visitor_score' IS NOT NULL
          AND (r.data->>'visitor_score')::int >= COALESCE(p_value::int, 0);

    ELSE
      -- Unknown preset: return empty set
      RETURN;
  END CASE;
END;
$$;


--
-- Name: find_cheapest_in_network_provider(uuid, uuid, text, numeric, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.find_cheapest_in_network_provider(p_network_id uuid, p_procedure_id uuid, p_zip_code text, p_radius_miles numeric DEFAULT 50, p_limit integer DEFAULT 10) RETURNS TABLE(provider_location_id uuid, provider_name text, city text, state text, zip text, distance_miles numeric, network_tier text, tier_discount_pct numeric, cash_price numeric, discounted_price numeric, effective_price numeric, savings_vs_cash numeric, rating numeric, review_count integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_lat numeric;
  v_lng numeric;
BEGIN
  -- Resolve ZIP center
  SELECT pl.latitude, pl.longitude INTO v_lat, v_lng
  FROM provider_locations pl
  WHERE pl.zip = p_zip_code AND pl.latitude IS NOT NULL
  LIMIT 1;

  IF v_lat IS NULL THEN
    SELECT hl.latitude, hl.longitude INTO v_lat, v_lng
    FROM healthcare_locations hl
    WHERE hl.zip = p_zip_code AND hl.latitude IS NOT NULL
    LIMIT 1;
  END IF;

  RETURN QUERY
  SELECT
    pl.id                   AS provider_location_id,
    pl.name                 AS provider_name,
    pl.city,
    pl.state,
    pl.zip,
    CASE
      WHEN v_lat IS NOT NULL AND pl.latitude IS NOT NULL THEN
        ROUND(
          (3959.0 * acos(
            LEAST(1.0,
              cos(radians(v_lat)) * cos(radians(pl.latitude)) *
              cos(radians(pl.longitude) - radians(v_lng)) +
              sin(radians(v_lat)) * sin(radians(pl.latitude))
            )
          ))::numeric, 1
        )
      ELSE NULL
    END                     AS distance_miles,
    np.network_tier,
    np.tier_discount_pct,
    pp.cash_price,
    pp.discounted_price,
    ROUND(
      COALESCE(pp.discounted_price, pp.cash_price) *
      (1 - COALESCE(np.tier_discount_pct, 0) / 100.0), 2
    )                       AS effective_price,
    ROUND(
      pp.cash_price - (
        COALESCE(pp.discounted_price, pp.cash_price) *
        (1 - COALESCE(np.tier_discount_pct, 0) / 100.0)
      ), 2
    )                       AS savings_vs_cash,
    pl.rating,
    pl.review_count
  FROM network_providers np
  INNER JOIN provider_locations pl ON pl.id = np.provider_location_id
  INNER JOIN procedure_prices pp ON pp.provider_location_id = pl.id
  WHERE np.network_id = p_network_id
    AND pp.procedure_id = p_procedure_id
    AND np.is_active = true
    AND pl.is_active = true
    AND pp.is_active = true
    AND np.network_tier IN ('in_network_preferred', 'in_network')
    AND (np.end_date IS NULL OR np.end_date > CURRENT_DATE)
    AND (
      v_lat IS NULL OR pl.latitude IS NULL
      OR (3959.0 * acos(
          LEAST(1.0,
            cos(radians(v_lat)) * cos(radians(pl.latitude)) *
            cos(radians(pl.longitude) - radians(v_lng)) +
            sin(radians(v_lat)) * sin(radians(pl.latitude))
          )
        ) <= p_radius_miles)
    )
  ORDER BY
    ROUND(
      COALESCE(pp.discounted_price, pp.cash_price) *
      (1 - COALESCE(np.tier_discount_pct, 0) / 100.0), 2
    ) ASC,
    CASE np.network_tier
      WHEN 'in_network_preferred' THEN 1
      WHEN 'in_network' THEN 2
    END
  LIMIT p_limit;
END;
$$;


--
-- Name: FUNCTION find_cheapest_in_network_provider(p_network_id uuid, p_procedure_id uuid, p_zip_code text, p_radius_miles numeric, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.find_cheapest_in_network_provider(p_network_id uuid, p_procedure_id uuid, p_zip_code text, p_radius_miles numeric, p_limit integer) IS 'Find cheapest in-network provider for a procedure near a ZIP';


--
-- Name: find_or_create_contact_by_email(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.find_or_create_contact_by_email(p_org_id uuid, p_email text, p_name text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_contact_id uuid;
  v_contacts_module_id uuid;
BEGIN
  SELECT id INTO v_contacts_module_id
  FROM crm_modules
  WHERE organization_id = p_org_id AND key = 'Contacts';

  IF v_contacts_module_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT id INTO v_contact_id
  FROM crm_records
  WHERE organization_id = p_org_id
    AND module_id = v_contacts_module_id
    AND data->>'Email' = p_email
  LIMIT 1;

  IF v_contact_id IS NOT NULL THEN
    RETURN v_contact_id;
  END IF;

  INSERT INTO crm_records (organization_id, module_id, data, title)
  VALUES (
    p_org_id,
    v_contacts_module_id,
    jsonb_build_object('Email', p_email, 'First_Name', COALESCE(p_name, split_part(p_email, '@', 1))),
    COALESCE(p_name, p_email)
  )
  RETURNING id INTO v_contact_id;

  RETURN v_contact_id;
END;
$$;


--
-- Name: find_record_by_phone(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.find_record_by_phone(phone_raw text, phone_normalized text) RETURNS TABLE(id uuid, org_id uuid, phone text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Try indexed phone column first (exact match)
  RETURN QUERY
    SELECT r.id, r.organization_id, r.phone
    FROM crm_records r
    WHERE r.phone = phone_normalized
       OR r.phone = phone_raw
    LIMIT 1;

  IF FOUND THEN RETURN; END IF;

  -- Fall back to JSONB data fields
  RETURN QUERY
    SELECT r.id, r.organization_id, r.phone
    FROM crm_records r
    WHERE r.data->>'phone' = phone_raw
       OR r.data->>'phone' = phone_normalized
       OR r.data->>'mobile' = phone_raw
       OR r.data->>'mobile' = phone_normalized
    LIMIT 1;
END;
$$;


--
-- Name: find_ticket_by_number(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.find_ticket_by_number(ticket_number_prefix text) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ticket_id uuid;
BEGIN
  -- Find ticket where the first 8 characters of the ID match the prefix
  SELECT id INTO v_ticket_id
  FROM tickets
  WHERE substring(id::text, 1, 8) = ticket_number_prefix
  LIMIT 1;
  
  RETURN v_ticket_id;
END;
$$;


--
-- Name: FUNCTION find_ticket_by_number(ticket_number_prefix text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.find_ticket_by_number(ticket_number_prefix text) IS 'Finds a ticket by matching the 8-character ID prefix used in email subjects';


--
-- Name: fix_wrong_org_batch(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fix_wrong_org_batch(p_limit integer DEFAULT 1000) RETURNS TABLE(records_moved integer, notes_moved integer)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_correct_org uuid := 'ac6e7228-2ea0-4582-8464-562c3e8ac56e'::uuid;
  v_wrong_org uuid := '00000000-0000-0000-0000-000000000001'::uuid;
  v_correct_module uuid := '7913796d-bda6-4fff-b81d-5f707b06b71b'::uuid;
  v_wrong_module uuid := '5c26eeee-ec93-406d-94eb-1e947ee75aaa'::uuid;
  v_rec_moved int;
  v_note_moved int;
  v_ids uuid[];
BEGIN
  SELECT array_agg(id) INTO v_ids
  FROM (
    SELECT id FROM crm_records
    WHERE organization_id = v_wrong_org AND module_id = v_wrong_module
    LIMIT p_limit
  ) sub;

  IF v_ids IS NULL OR array_length(v_ids, 1) IS NULL THEN
    RETURN QUERY SELECT 0, 0;
    RETURN;
  END IF;

  UPDATE crm_records
  SET organization_id = v_correct_org, module_id = v_correct_module
  WHERE id = ANY(v_ids);
  GET DIAGNOSTICS v_rec_moved = ROW_COUNT;

  UPDATE crm_notes
  SET organization_id = v_correct_org
  WHERE organization_id = v_wrong_org
    AND record_id = ANY(v_ids);
  GET DIAGNOSTICS v_note_moved = ROW_COUNT;

  RETURN QUERY SELECT v_rec_moved, v_note_moved;
END;
$$;


--
-- Name: fix_wrong_org_records(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fix_wrong_org_records() RETURNS TABLE(records_moved integer, notes_moved integer)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_correct_org_id uuid := 'ac6e7228-2ea0-4582-8464-562c3e8ac56e'::uuid;
  v_wrong_org_id uuid := '00000000-0000-0000-0000-000000000001'::uuid;
  v_correct_contacts_module uuid := '7913796d-bda6-4fff-b81d-5f707b06b71b'::uuid;
  v_wrong_contacts_module uuid := '5c26eeee-ec93-406d-94eb-1e947ee75aaa'::uuid;
  v_records_moved int;
  v_notes_moved int;
BEGIN
  UPDATE crm_records
  SET organization_id = v_correct_org_id,
      module_id = v_correct_contacts_module
  WHERE organization_id = v_wrong_org_id
    AND module_id = v_wrong_contacts_module;
  GET DIAGNOSTICS v_records_moved = ROW_COUNT;

  UPDATE crm_notes
  SET organization_id = v_correct_org_id
  WHERE organization_id = v_wrong_org_id;
  GET DIAGNOSTICS v_notes_moved = ROW_COUNT;

  RETURN QUERY SELECT v_records_moved, v_notes_moved;
END;
$$;


--
-- Name: fn_audit_developer_hub_changes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_audit_developer_hub_changes() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO unified_audit_logs (
    organization_id, app_source, actor_id,
    action, action_category, risk_level, details, changes
  ) VALUES (
    COALESCE(NEW.organization_id, OLD.organization_id),
    'crm',
    COALESCE(
      (SELECT id FROM profiles WHERE user_id = (SELECT auth.uid()) LIMIT 1),
      NULL
    ),
    TG_TABLE_NAME || '.' || lower(TG_OP),
    'developer',
    CASE
      WHEN TG_TABLE_NAME = 'crm_api_keys' AND TG_OP = 'DELETE' THEN 'critical'
      WHEN TG_TABLE_NAME = 'crm_api_keys' THEN 'high'
      WHEN TG_TABLE_NAME = 'crm_webhooks' THEN 'medium'
      ELSE 'low'
    END,
    jsonb_build_object(
      'table', TG_TABLE_NAME,
      'entity_name', CASE
        WHEN TG_TABLE_NAME = 'crm_api_keys' THEN COALESCE(NEW.name, OLD.name)
        WHEN TG_TABLE_NAME = 'crm_webhooks' THEN COALESCE(NEW.name, OLD.name)
        ELSE NULL
      END,
      'scopes', CASE
        WHEN TG_TABLE_NAME = 'crm_api_keys' THEN to_jsonb(COALESCE(NEW.scopes, OLD.scopes))
        ELSE NULL
      END
    ),
    CASE TG_OP
      WHEN 'INSERT' THEN jsonb_build_object('new', to_jsonb(NEW))
      WHEN 'UPDATE' THEN jsonb_build_object('old', to_jsonb(OLD), 'new', to_jsonb(NEW))
      WHEN 'DELETE' THEN jsonb_build_object('old', to_jsonb(OLD))
    END
  );
  RETURN COALESCE(NEW, OLD);
END;
$$;


