--
-- Name: fn_authenticate_api_key(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_authenticate_api_key(p_key_hash text) RETURNS TABLE(key_id uuid, org_id uuid, key_name text, scopes text[], allowed_ips text[], rate_limit_rpm integer, environment text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_key RECORD;
BEGIN
  SELECT * INTO v_key
  FROM crm_api_keys
  WHERE crm_api_keys.key_hash = p_key_hash
    AND status = 'active'
    AND (expires_at IS NULL OR expires_at > now());

  IF v_key IS NULL THEN
    RETURN;
  END IF;

  -- Update last used
  UPDATE crm_api_keys
  SET last_used_at = now(),
      usage_count = usage_count + 1
  WHERE id = v_key.id;

  key_id := v_key.id;
  org_id := v_key.organization_id;
  key_name := v_key.name;
  scopes := v_key.scopes;
  allowed_ips := v_key.allowed_ips;
  rate_limit_rpm := v_key.rate_limit_rpm;
  environment := v_key.environment;
  RETURN NEXT;
END;
$$;


--
-- Name: FUNCTION fn_authenticate_api_key(p_key_hash text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_authenticate_api_key(p_key_hash text) IS 'Authenticates an API key by hash, updates usage stats, returns key metadata with scopes';


--
-- Name: fn_check_api_scope(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_check_api_scope(p_key_id uuid, p_scope text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_scopes text[];
BEGIN
  SELECT scopes INTO v_scopes
  FROM crm_api_keys
  WHERE id = p_key_id AND status = 'active';

  IF v_scopes IS NULL THEN
    RETURN false;
  END IF;

  -- crm.admin grants all scopes
  IF 'crm.admin' = ANY(v_scopes) THEN
    RETURN true;
  END IF;

  -- crm.write grants crm.read
  IF p_scope = 'crm.read' AND 'crm.write' = ANY(v_scopes) THEN
    RETURN true;
  END IF;

  -- Direct scope match
  RETURN p_scope = ANY(v_scopes);
END;
$$;


--
-- Name: FUNCTION fn_check_api_scope(p_key_id uuid, p_scope text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_check_api_scope(p_key_id uuid, p_scope text) IS 'Checks if an API key has a specific scope (crm.admin grants all, crm.write grants crm.read)';


--
-- Name: fn_cleanup_api_logs(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_cleanup_api_logs(p_retain_days integer DEFAULT 90) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_deleted int;
BEGIN
  DELETE FROM crm_api_logs
  WHERE created_at < now() - (p_retain_days || ' days')::interval;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  -- Also clean old webhook deliveries
  DELETE FROM crm_webhook_deliveries
  WHERE created_at < now() - (p_retain_days || ' days')::interval;

  RETURN v_deleted;
END;
$$;


--
-- Name: FUNCTION fn_cleanup_api_logs(p_retain_days integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_cleanup_api_logs(p_retain_days integer) IS 'Removes API logs and webhook deliveries older than N days (default 90)';


