--
-- Name: crm_webhooks; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.crm_webhooks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    name text NOT NULL,
    description text,
    url text NOT NULL,
    events text[] DEFAULT '{}'::text[] NOT NULL,
    secret text NOT NULL,
    auth_type text DEFAULT 'hmac_sha256'::text NOT NULL,
    auth_value text,
    custom_headers jsonb DEFAULT '{}'::jsonb,
    module_id uuid,
    filters jsonb DEFAULT '{}'::jsonb,
    timeout_ms integer DEFAULT 10000 NOT NULL,
    max_retries integer DEFAULT 3 NOT NULL,
    retry_interval_seconds integer DEFAULT 60 NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    is_verified boolean DEFAULT false NOT NULL,
    verified_at timestamp with time zone,
    delivery_count bigint DEFAULT 0 NOT NULL,
    success_count bigint DEFAULT 0 NOT NULL,
    failure_count bigint DEFAULT 0 NOT NULL,
    last_triggered_at timestamp with time zone,
    last_success_at timestamp with time zone,
    last_failure_at timestamp with time zone,
    last_error text,
    consecutive_failures integer DEFAULT 0 NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT crm_webhooks_auth_type_check CHECK ((auth_type = ANY (ARRAY['hmac_sha256'::text, 'basic'::text, 'bearer'::text, 'none'::text]))),
    CONSTRAINT crm_webhooks_events_check CHECK ((events <@ ARRAY['record.created'::text, 'record.updated'::text, 'record.deleted'::text, 'record.stage_changed'::text, 'contact.created'::text, 'contact.updated'::text, 'contact.deleted'::text, 'deal.created'::text, 'deal.updated'::text, 'deal.won'::text, 'deal.lost'::text, 'task.created'::text, 'task.completed'::text, 'note.created'::text, 'import.completed'::text, 'export.completed'::text, 'pipeline.stage_changed'::text, 'signal.fired'::text, 'signal.resolved'::text, 'extension.installed'::text, 'extension.uninstalled'::text, 'api_key.created'::text, 'api_key.revoked'::text])),
    CONSTRAINT crm_webhooks_status_check CHECK ((status = ANY (ARRAY['active'::text, 'disabled'::text, 'failed'::text, 'suspended'::text])))
);


