--
-- Name: fn_install_extension(uuid, uuid, uuid, jsonb, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_install_extension(p_org_id uuid, p_extension_id uuid, p_installed_by uuid, p_config jsonb DEFAULT '{}'::jsonb, p_granted_scopes text[] DEFAULT '{}'::text[]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ext RECORD;
  v_install_id uuid;
  v_existing uuid;
BEGIN
  -- Get extension
  SELECT * INTO v_ext FROM crm_extensions WHERE id = p_extension_id AND status = 'published';
  IF v_ext IS NULL THEN
    RAISE EXCEPTION 'Extension not found or not published';
  END IF;

  -- Check if already installed
  SELECT id INTO v_existing
  FROM crm_extension_installs
  WHERE organization_id = p_org_id AND extension_id = p_extension_id;

  IF v_existing IS NOT NULL THEN
    -- Re-enable if previously disabled
    UPDATE crm_extension_installs
    SET status = CASE WHEN v_ext.is_free THEN 'active'
                      WHEN v_ext.trial_days > 0 THEN 'trial'
                      ELSE 'active'
                 END,
        config = COALESCE(NULLIF(p_config::text, '{}')::jsonb, config),
        granted_scopes = CASE WHEN array_length(p_granted_scopes, 1) > 0
                              THEN p_granted_scopes
                              ELSE granted_scopes
                         END,
        enabled_at = now(),
        disabled_at = NULL,
        error_message = NULL,
        updated_at = now()
    WHERE id = v_existing;
    RETURN v_existing;
  END IF;

  -- Create new install
  INSERT INTO crm_extension_installs (
    organization_id, extension_id, installed_version, config,
    granted_scopes, status, installed_by, enabled_at,
    trial_ends_at
  ) VALUES (
    p_org_id, p_extension_id, v_ext.version,
    COALESCE(NULLIF(p_config::text, '{}')::jsonb, v_ext.default_config),
    CASE WHEN array_length(p_granted_scopes, 1) > 0
         THEN p_granted_scopes
         ELSE v_ext.required_scopes
    END,
    CASE WHEN v_ext.is_free THEN 'active'
         WHEN v_ext.trial_days > 0 THEN 'trial'
         ELSE 'active'
    END,
    p_installed_by,
    now(),
    CASE WHEN v_ext.trial_days > 0 AND NOT v_ext.is_free
         THEN now() + (v_ext.trial_days || ' days')::interval
         ELSE NULL
    END
  )
  RETURNING id INTO v_install_id;

  -- Increment install count
  UPDATE crm_extensions
  SET install_count = install_count + 1
  WHERE id = p_extension_id;

  RETURN v_install_id;
END;
$$;


--
-- Name: FUNCTION fn_install_extension(p_org_id uuid, p_extension_id uuid, p_installed_by uuid, p_config jsonb, p_granted_scopes text[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_install_extension(p_org_id uuid, p_extension_id uuid, p_installed_by uuid, p_config jsonb, p_granted_scopes text[]) IS 'Installs an extension for an organization with config and scopes. Re-enables if previously installed.';


--
-- Name: fn_record_webhook_delivery(uuid, text, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_record_webhook_delivery(p_webhook_id uuid, p_event_type text, p_status text, p_response_status integer DEFAULT NULL::integer, p_duration_ms integer DEFAULT NULL::integer, p_error text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Update webhook stats
  UPDATE crm_webhooks
  SET delivery_count = delivery_count + 1,
      last_triggered_at = now(),
      success_count = CASE WHEN p_status = 'success' THEN success_count + 1 ELSE success_count END,
      failure_count = CASE WHEN p_status = 'failed' THEN failure_count + 1 ELSE failure_count END,
      last_success_at = CASE WHEN p_status = 'success' THEN now() ELSE last_success_at END,
      last_failure_at = CASE WHEN p_status = 'failed' THEN now() ELSE last_failure_at END,
      last_error = CASE WHEN p_status = 'failed' THEN p_error ELSE last_error END,
      consecutive_failures = CASE
        WHEN p_status = 'success' THEN 0
        WHEN p_status = 'failed' THEN consecutive_failures + 1
        ELSE consecutive_failures
      END,
      -- Auto-suspend after 10 consecutive failures
      status = CASE
        WHEN p_status = 'failed' AND consecutive_failures >= 9 THEN 'suspended'
        ELSE status
      END,
      updated_at = now()
  WHERE id = p_webhook_id;
END;
$$;


--
-- Name: FUNCTION fn_record_webhook_delivery(p_webhook_id uuid, p_event_type text, p_status text, p_response_status integer, p_duration_ms integer, p_error text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_record_webhook_delivery(p_webhook_id uuid, p_event_type text, p_status text, p_response_status integer, p_duration_ms integer, p_error text) IS 'Records a webhook delivery attempt, updates stats, and auto-suspends after 10 consecutive failures';


--
-- Name: fn_uninstall_extension(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_uninstall_extension(p_org_id uuid, p_extension_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_deleted int;
BEGIN
  DELETE FROM crm_extension_installs
  WHERE organization_id = p_org_id
    AND extension_id = p_extension_id;

  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  IF v_deleted > 0 THEN
    UPDATE crm_extensions
    SET install_count = GREATEST(install_count - 1, 0)
    WHERE id = p_extension_id;
  END IF;

  RETURN v_deleted > 0;
END;
$$;


--
-- Name: FUNCTION fn_uninstall_extension(p_org_id uuid, p_extension_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_uninstall_extension(p_org_id uuid, p_extension_id uuid) IS 'Uninstalls an extension and decrements the install count';


--
-- Name: fn_update_extension_rating(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_update_extension_rating() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE crm_extensions
  SET rating_avg = (
        SELECT COALESCE(AVG(rating), 0)
        FROM crm_extension_reviews
        WHERE extension_id = COALESCE(NEW.extension_id, OLD.extension_id)
      ),
      rating_count = (
        SELECT COUNT(*)
        FROM crm_extension_reviews
        WHERE extension_id = COALESCE(NEW.extension_id, OLD.extension_id)
      )
  WHERE id = COALESCE(NEW.extension_id, OLD.extension_id);

  RETURN COALESCE(NEW, OLD);
END;
$$;


