--
-- Name: generate_billing_schedule_on_enrollment_active(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_billing_schedule_on_enrollment_active() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_billing_day int;
  v_first_billing date;
  v_idem_key text;
BEGIN
  IF NEW.status = 'approved' AND (OLD.status IS NULL OR OLD.status <> 'approved') THEN
    v_billing_day := COALESCE(NEW.permanent_bill_day, 20);

    v_first_billing := compute_first_billing_date(
      COALESCE(NEW.effective_date, CURRENT_DATE)
    );

    v_idem_key := 'enrollment_activate_' || NEW.id::text || '_' || v_first_billing::text;

    INSERT INTO billing_schedules (
      organization_id,
      enrollment_id,
      member_id,
      amount,
      frequency,
      billing_day,
      start_date,
      next_billing_date,
      status,
      idempotency_key
    ) VALUES (
      NEW.organization_id,
      NEW.id,
      NEW.primary_member_id,
      COALESCE(NEW.base_monthly_cost, 0),
      'monthly',
      v_billing_day,
      v_first_billing,
      v_first_billing,
      'active',
      v_idem_key
    )
    ON CONFLICT (idempotency_key) DO NOTHING;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: generate_enrollment_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_enrollment_code() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  new_code text;
  code_exists boolean;
BEGIN
  IF NEW.enrollment_code IS NULL THEN
    LOOP
      new_code := LPAD(FLOOR(RANDOM() * 900000 + 100000)::text, 6, '0');
      SELECT EXISTS(SELECT 1 FROM advisors WHERE enrollment_code = new_code) INTO code_exists;
      EXIT WHEN NOT code_exists;
    END LOOP;
    NEW.enrollment_code := new_code;
  END IF;
  RETURN NEW;
END;
$$;


