--
-- Name: generate_invoice_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_invoice_number() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  year_prefix text;
  next_number integer;
BEGIN
  IF NEW.invoice_number IS NULL THEN
    year_prefix := TO_CHAR(NOW(), 'YYYY');
    
    SELECT COALESCE(MAX(
      NULLIF(REGEXP_REPLACE(invoice_number, '^INV-' || year_prefix || '-', ''), '')::integer
    ), 0) + 1
    INTO next_number
    FROM invoices
    WHERE organization_id = NEW.organization_id
      AND invoice_number LIKE 'INV-' || year_prefix || '-%';
    
    NEW.invoice_number := 'INV-' || year_prefix || '-' || LPAD(next_number::text, 6, '0');
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: generate_invoice_number(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_invoice_number(org_id uuid) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  next_num integer;
  year_prefix text;
BEGIN
  year_prefix := to_char(CURRENT_DATE, 'YYYY');

  SELECT COALESCE(MAX(NULLIF(regexp_replace(invoice_number, '[^0-9]', '', 'g'), '')::integer), 0) + 1
  INTO next_num
  FROM invoices
  WHERE organization_id = org_id
    AND invoice_number LIKE 'INV-' || year_prefix || '-%';

  RETURN 'INV-' || year_prefix || '-' || LPAD(next_num::text, 4, '0');
END;
$$;


