--
-- Name: get_actuarial_experience(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_actuarial_experience(p_org_id uuid, p_months integer DEFAULT 24) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller_id   uuid := auth.uid();
  v_start_date  timestamptz;
  v_result      jsonb;
BEGIN
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM profiles
    WHERE user_id = v_caller_id
      AND organization_id = p_org_id
  ) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  IF p_months < 1 OR p_months > 60 THEN
    p_months := 24;
  END IF;

  v_start_date := DATE_TRUNC('month', CURRENT_DATE) - (p_months - 1) * INTERVAL '1 month';

  SELECT jsonb_build_object(
    'monthlyExperience',     (SELECT public._actuarial_monthly(p_org_id, v_start_date)),
    'needsByType',           (SELECT public._actuarial_needs_by_type(p_org_id, v_start_date)),
    'contributionAdequacy',  (SELECT public._actuarial_contributions(p_org_id, v_start_date)),
    'ageBandExperience',     (SELECT public._actuarial_age_bands(p_org_id, v_start_date)),
    'exposureDevelopment',   (SELECT public._actuarial_exposure_dev(p_org_id, v_start_date)),
    'summary',               (SELECT public._actuarial_summary(p_org_id, v_start_date)),
    'periodMonths', p_months,
    'generatedAt', now()
  ) INTO v_result;

  RETURN v_result;
END;
$$;


--
-- Name: get_admin_console_stats(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_admin_console_stats(p_org_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_today_start   timestamptz := date_trunc('day', now());
  v_today_end     timestamptz := v_today_start + interval '1 day';
  v_month_start   timestamptz := date_trunc('month', now());
  v_48h_ago       timestamptz := now() - interval '48 hours';
  v_24h_ago       timestamptz := now() - interval '24 hours';

  v_total_members       int := 0;
  v_active_members      int := 0;
  v_new_members_month   int := 0;
  v_inactive_month      int := 0;
  v_retention_rate      int := 0;
  v_total_agents        int := 0;
  v_active_agents       int := 0;
  v_pending_agents      int := 0;
  v_total_enrollments   int := 0;
  v_pending_review      int := 0;
  v_approved_today      int := 0;
  v_rejected_today      int := 0;
  v_started_today       int := 0;
  v_expiring_soon       int := 0;
  v_total_draft         int := 0;
  v_collected_today     numeric(12,2) := 0;
  v_mrr                 numeric(12,2) := 0;
  v_failed_today        int := 0;
  v_pending_ach         int := 0;
  v_last_payment_at     timestamptz;
  v_pending_commissions numeric(12,2) := 0;
  v_paid_this_month     numeric(12,2) := 0;
  v_pending_payouts     int := 0;
  v_failed_jobs_24h     int := 0;
  v_running_jobs        int := 0;
  v_pending_jobs        int := 0;
  v_pipeline_leads      bigint := 0;
  v_pipeline_draft      int := 0;
  v_pipeline_in_progress int := 0;
  v_pipeline_submitted  int := 0;
  v_pipeline_approved   int := 0;
  v_work_queue          jsonb := '[]'::jsonb;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM profiles
    WHERE user_id = auth.uid()
      AND organization_id = p_org_id
      AND role IN ('admin', 'owner')
  ) THEN
    RAISE EXCEPTION 'Unauthorized: admin or owner access required';
  END IF;

  SELECT COUNT(*) INTO v_total_members FROM members WHERE organization_id = p_org_id;
  SELECT COUNT(*) INTO v_active_members FROM members WHERE organization_id = p_org_id AND status = 'active';
  SELECT COUNT(*) INTO v_new_members_month FROM members WHERE organization_id = p_org_id AND created_at >= v_month_start;
  SELECT COUNT(*) INTO v_inactive_month FROM members WHERE organization_id = p_org_id AND status = 'inactive' AND updated_at >= v_month_start;
  IF v_total_members > 0 THEN
    v_retention_rate := ROUND((v_active_members::numeric / v_total_members) * 100);
  END IF;

  SELECT COUNT(*) INTO v_total_agents FROM advisors WHERE organization_id = p_org_id;
  SELECT COUNT(*) INTO v_active_agents FROM advisors WHERE organization_id = p_org_id AND status = 'active';
  SELECT COUNT(*) INTO v_pending_agents FROM advisors WHERE organization_id = p_org_id AND status = 'pending';

  SELECT COUNT(*) INTO v_total_enrollments FROM enrollments WHERE organization_id = p_org_id;
  SELECT COUNT(*) INTO v_pending_review FROM enrollments WHERE organization_id = p_org_id AND status = 'submitted';
  SELECT COUNT(*) INTO v_approved_today FROM enrollments WHERE organization_id = p_org_id AND status = 'approved' AND updated_at >= v_today_start AND updated_at < v_today_end;
  SELECT COUNT(*) INTO v_rejected_today FROM enrollments WHERE organization_id = p_org_id AND status = 'rejected' AND updated_at >= v_today_start AND updated_at < v_today_end;
  SELECT COUNT(*) INTO v_started_today FROM enrollments WHERE organization_id = p_org_id AND created_at >= v_today_start AND created_at < v_today_end;
  SELECT COUNT(*) INTO v_expiring_soon FROM enrollments WHERE organization_id = p_org_id AND status IN ('draft', 'in_progress') AND created_at < v_48h_ago;
  SELECT COUNT(*) INTO v_total_draft FROM enrollments WHERE organization_id = p_org_id AND status = 'draft';

  SELECT COALESCE(SUM(amount), 0) INTO v_collected_today FROM billing_transactions WHERE organization_id = p_org_id AND status = 'success' AND processed_at >= v_today_start AND processed_at < v_today_end AND transaction_type = 'charge';
  SELECT COALESCE(SUM(amount), 0) INTO v_mrr FROM billing_schedules WHERE organization_id = p_org_id AND status = 'active';
  SELECT COUNT(*) INTO v_failed_today FROM billing_failures WHERE organization_id = p_org_id AND created_at >= v_today_start AND created_at < v_today_end AND resolved = false;
  SELECT COUNT(*) INTO v_pending_ach FROM billing_transactions WHERE organization_id = p_org_id AND status = 'pending';
  SELECT MAX(processed_at) INTO v_last_payment_at FROM billing_transactions WHERE organization_id = p_org_id AND status = 'success';

  SELECT COALESCE(SUM(commission_amount), 0) INTO v_pending_commissions FROM commission_transactions WHERE organization_id = p_org_id AND status = 'pending';
  SELECT COALESCE(SUM(commission_amount), 0) INTO v_paid_this_month FROM commission_transactions WHERE organization_id = p_org_id AND status = 'paid' AND paid_at >= v_month_start;
  SELECT COUNT(*) INTO v_pending_payouts FROM commission_payouts WHERE organization_id = p_org_id AND status = 'pending';

  SELECT COUNT(*) INTO v_failed_jobs_24h FROM job_runs WHERE organization_id = p_org_id AND status = 'failed' AND created_at >= v_24h_ago;
  SELECT COUNT(*) INTO v_running_jobs FROM job_runs WHERE organization_id = p_org_id AND status = 'running';
  SELECT COUNT(*) INTO v_pending_jobs FROM job_runs WHERE organization_id = p_org_id AND status = 'pending';

  SELECT COUNT(*) INTO v_pipeline_leads FROM leads WHERE organization_id = p_org_id;
  SELECT
    COUNT(*) FILTER (WHERE status = 'draft'),
    COUNT(*) FILTER (WHERE status = 'in_progress'),
    COUNT(*) FILTER (WHERE status = 'submitted'),
    COUNT(*) FILTER (WHERE status = 'approved')
  INTO v_pipeline_draft, v_pipeline_in_progress, v_pipeline_submitted, v_pipeline_approved
  FROM enrollments WHERE organization_id = p_org_id;

  -- Work queue — every subquery's ORDER BY now ends in `id` so the LIMIT
  -- cutoff is reproducible across calls. Without this, the admin console
  -- shows a different set of "top 3 billing failures" / "top 2 jobs" /
  -- etc. each time the page is loaded if rows happen to share timestamps.
  WITH queue_items AS (
    (
      SELECT bf.id::text AS id, 'billing_failure' AS type,
             'Payment Failed — ' || COALESCE(m.first_name || ' ' || m.last_name, 'Unknown') AS title,
             'ACH rejected · $' || bf.amount::text AS subtitle,
             1 AS priority, bf.created_at
        FROM billing_failures bf
        LEFT JOIN members m ON m.id = bf.member_id
       WHERE bf.organization_id = p_org_id AND bf.resolved = false
       ORDER BY bf.created_at DESC, bf.id DESC LIMIT 3
    )
    UNION ALL
    (
      SELECT jr.id::text, 'failed_job',
             'Job Failed — ' || jr.job_name,
             COALESCE(jr.error_message, 'Unknown error'),
             1, jr.created_at
        FROM job_runs jr
       WHERE jr.organization_id = p_org_id AND jr.status = 'failed' AND jr.created_at >= v_24h_ago
       ORDER BY jr.created_at DESC, jr.id DESC LIMIT 2
    )
    UNION ALL
    (
      SELECT e.id::text, 'enrollment_review',
             'Review — ' || COALESCE(m.first_name || ' ' || m.last_name, 'Unknown'),
             'Submitted ' || to_char(e.updated_at, 'Mon DD'),
             2, e.updated_at
        FROM enrollments e
        LEFT JOIN members m ON m.id = e.primary_member_id
       WHERE e.organization_id = p_org_id AND e.status = 'submitted'
       ORDER BY e.updated_at ASC, e.id ASC LIMIT 3
    )
    UNION ALL
    (
      SELECT cp.id::text, 'commission_payout',
             'Payout — ' || COALESCE(a.first_name || ' ' || a.last_name, 'Unknown'),
             '$' || cp.net_payout::text || ' pending approval',
             2, cp.created_at
        FROM commission_payouts cp
        LEFT JOIN advisors a ON a.id = cp.advisor_id
       WHERE cp.organization_id = p_org_id AND cp.status = 'pending'
       ORDER BY cp.created_at ASC, cp.id ASC LIMIT 2
    )
    UNION ALL
    (
      SELECT t.id::text, 'overdue_task',
             COALESCE(t.title, 'Untitled Task'),
             'Due ' || to_char(t.due_date, 'Mon DD'),
             3, t.due_date
        FROM tasks t
       WHERE t.organization_id = p_org_id
         AND t.status NOT IN ('completed', 'cancelled')
         AND t.due_date < now()
       ORDER BY t.due_date ASC, t.id ASC LIMIT 3
    )
  )
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id', qi.id,
        'type', qi.type,
        'title', qi.title,
        'subtitle', qi.subtitle,
        'priority', qi.priority,
        'createdAt', qi.created_at
      )
      ORDER BY qi.priority, qi.created_at ASC, qi.id
    ),
    '[]'::jsonb
  )
  INTO v_work_queue
  FROM (
    SELECT *
      FROM queue_items
     ORDER BY priority, created_at ASC, id
     LIMIT 10
  ) qi;

  RETURN jsonb_build_object(
    'memberStats', jsonb_build_object('total', v_total_members, 'active', v_active_members, 'newThisMonth', v_new_members_month, 'inactiveThisMonth', v_inactive_month, 'retentionRate', v_retention_rate),
    'agentStats', jsonb_build_object('total', v_total_agents, 'active', v_active_agents, 'pendingOnboarding', v_pending_agents),
    'enrollmentStats', jsonb_build_object('total', v_total_enrollments, 'pendingReview', v_pending_review, 'approvedToday', v_approved_today, 'rejectedToday', v_rejected_today, 'startedToday', v_started_today, 'expiringSoon', v_expiring_soon, 'totalDraft', v_total_draft),
    'billingStats', jsonb_build_object('collectedToday', v_collected_today, 'mrr', v_mrr, 'failedToday', v_failed_today, 'pendingAch', v_pending_ach, 'lastPaymentAt', v_last_payment_at),
    'commissionStats', jsonb_build_object('pendingAmount', v_pending_commissions, 'paidThisMonth', v_paid_this_month, 'pendingPayouts', v_pending_payouts),
    'systemStats', jsonb_build_object('failedJobs24h', v_failed_jobs_24h, 'runningJobs', v_running_jobs, 'pendingJobs', v_pending_jobs),
    'pipelineCounts', jsonb_build_object('leads', v_pipeline_leads, 'draft', v_pipeline_draft, 'inProgress', v_pipeline_in_progress, 'submitted', v_pipeline_submitted, 'approved', v_pipeline_approved),
    'workQueue', v_work_queue
  );
END;
$_$;


--
-- Name: FUNCTION get_admin_console_stats(p_org_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_admin_console_stats(p_org_id uuid) IS 'Admin console stats RPC. Work-queue subqueries use ORDER BY <col>, id so the LIMIT N cutoff is deterministic across calls (industry-standard pagination practice).';


--
-- Name: get_advisor_achievements(uuid, uuid, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_advisor_achievements(p_advisor_id uuid, p_org_id uuid, p_limit integer DEFAULT 20, p_unacked_only boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(row_data ORDER BY earned_at DESC), '[]'::jsonb) INTO v_result
  FROM (
    SELECT jsonb_build_object(
      'id',               aa.id,
      'achievement_type', aa.achievement_type,
      'title',            aa.title,
      'description',      aa.description,
      'capacity_scope',   aa.capacity_scope,
      'period_month',     aa.period_month,
      'metric_value',     aa.metric_value,
      'prev_value',       aa.prev_value,
      'new_value',        aa.new_value,
      'acknowledged',     aa.acknowledged,
      'earned_at',        aa.earned_at
    ) AS row_data,
    aa.earned_at
    FROM advisor_achievements aa
    WHERE aa.advisor_id = p_advisor_id
      AND aa.organization_id = p_org_id
      AND (NOT p_unacked_only OR aa.acknowledged = false)
    ORDER BY aa.earned_at DESC
    LIMIT p_limit
  ) sub;

  RETURN jsonb_build_object(
    'achievements', v_result,
    'unacknowledged_count', (
      SELECT count(*) FROM advisor_achievements
      WHERE advisor_id = p_advisor_id
        AND organization_id = p_org_id
        AND acknowledged = false
    )
  );
END;
$$;


--
-- Name: get_advisor_analytics(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_advisor_analytics(p_advisor_id uuid, p_org_id uuid, p_months integer DEFAULT 12) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_result       jsonb;
  v_personal     jsonb;
  v_downline     jsonb;
  v_monthly      jsonb;
  v_top_downline jsonb;
  v_cutoff       date := (date_trunc('month', current_date) - (p_months || ' months')::interval)::date;
BEGIN
  -- Personal metrics (from MV)
  SELECT jsonb_build_object(
    'total_commissions',    COALESCE(sum(total_commissions), 0),
    'paid_commissions',     COALESCE(sum(paid_commissions), 0),
    'pending_commissions',  COALESCE(sum(pending_commissions), 0),
    'total_enrollments',    COALESCE(sum(total_enrollments), 0),
    'signup_commissions',   COALESCE(sum(signup_commissions), 0),
    'monthly_commissions',  COALESCE(sum(monthly_commissions), 0),
    'override_commissions', COALESCE(sum(override_commissions), 0),
    'avg_commission',       COALESCE(avg(NULLIF(total_commissions, 0)), 0)
  ) INTO v_personal
  FROM mv_advisor_monthly_performance
  WHERE advisor_id = p_advisor_id
    AND organization_id = p_org_id
    AND month >= v_cutoff;

  -- Downline aggregate metrics (from MV using existing downline function)
  SELECT jsonb_build_object(
    'total_commissions',    COALESCE(sum(total_commissions), 0),
    'total_enrollments',    COALESCE(sum(total_enrollments), 0),
    'active_advisors',      count(DISTINCT advisor_id),
    'avg_per_advisor',      COALESCE(avg(total_commissions), 0)
  ) INTO v_downline
  FROM mv_advisor_monthly_performance
  WHERE advisor_id IN (SELECT id FROM get_advisor_downline_ids(p_advisor_id))
    AND organization_id = p_org_id
    AND month >= v_cutoff;

  -- Monthly trend (personal + downline combined)
  SELECT COALESCE(jsonb_agg(row_data ORDER BY month), '[]'::jsonb) INTO v_monthly
  FROM (
    SELECT
      m.month,
      jsonb_build_object(
        'month',               m.month,
        'personal_commissions', COALESCE(sum(CASE WHEN m.advisor_id = p_advisor_id THEN m.total_commissions ELSE 0 END), 0),
        'downline_commissions', COALESCE(sum(CASE WHEN m.advisor_id != p_advisor_id THEN m.total_commissions ELSE 0 END), 0),
        'personal_enrollments', COALESCE(sum(CASE WHEN m.advisor_id = p_advisor_id THEN m.total_enrollments ELSE 0 END), 0),
        'downline_enrollments', COALESCE(sum(CASE WHEN m.advisor_id != p_advisor_id THEN m.total_enrollments ELSE 0 END), 0),
        'total_commissions',    COALESCE(sum(m.total_commissions), 0)
      ) AS row_data
    FROM mv_advisor_monthly_performance m
    WHERE (m.advisor_id = p_advisor_id
           OR m.advisor_id IN (SELECT id FROM get_advisor_downline_ids(p_advisor_id)))
      AND m.organization_id = p_org_id
      AND m.month >= v_cutoff
    GROUP BY m.month
  ) sub;

  -- Top 5 downline performers
  SELECT COALESCE(jsonb_agg(row_data ORDER BY total_commissions DESC), '[]'::jsonb) INTO v_top_downline
  FROM (
    SELECT jsonb_build_object(
      'advisor_id',        m.advisor_id,
      'first_name',        a.first_name,
      'last_name',         a.last_name,
      'email',             a.email,
      'commission_tier',   a.commission_tier,
      'total_commissions', sum(m.total_commissions),
      'total_enrollments', sum(m.total_enrollments)
    ) AS row_data,
    sum(m.total_commissions) AS total_commissions
    FROM mv_advisor_monthly_performance m
    JOIN advisors a ON a.id = m.advisor_id
    WHERE m.advisor_id IN (SELECT id FROM get_advisor_downline_ids(p_advisor_id))
      AND m.organization_id = p_org_id
      AND m.month >= v_cutoff
    GROUP BY m.advisor_id, a.first_name, a.last_name, a.email, a.commission_tier
    ORDER BY sum(m.total_commissions) DESC
    LIMIT 5
  ) sub;

  -- Assemble result
  v_result := jsonb_build_object(
    'personal',     COALESCE(v_personal, '{}'::jsonb),
    'downline',     COALESCE(v_downline, '{}'::jsonb),
    'monthly',      COALESCE(v_monthly, '[]'::jsonb),
    'top_downline', COALESCE(v_top_downline, '[]'::jsonb)
  );

  RETURN v_result;
END;
$$;


--
-- Name: get_advisor_downline_count(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_advisor_downline_count(p_advisor_id uuid) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
WITH RECURSIVE downline AS (
  SELECT id FROM advisors WHERE parent_advisor_id = p_advisor_id

  UNION ALL

  SELECT a.id
  FROM advisors a
  JOIN downline d ON a.parent_advisor_id = d.id
)
SELECT COUNT(*)::integer FROM downline;
$$;


--
-- Name: get_advisor_downline_ids(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_advisor_downline_ids(p_advisor_id uuid) RETURNS SETOF uuid
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
WITH RECURSIVE downline AS (
  SELECT id FROM advisors WHERE parent_advisor_id = p_advisor_id

  UNION ALL

  SELECT a.id
  FROM advisors a
  JOIN downline d ON a.parent_advisor_id = d.id
)
SELECT id FROM downline;
$$;


--
-- Name: FUNCTION get_advisor_downline_ids(p_advisor_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_advisor_downline_ids(p_advisor_id uuid) IS 'Returns all descendant advisor IDs in the hierarchy tree';


--
-- Name: get_advisor_upline(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_advisor_upline(p_advisor_id uuid, p_max_levels integer DEFAULT 5) RETURNS TABLE(level integer, advisor_id uuid, parent_advisor_id uuid, commission_eligible boolean, commission_tier_id uuid)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH RECURSIVE chain AS (
    -- Seed: the parent of the source advisor (level 1)
    SELECT
      1 AS level,
      a.id              AS advisor_id,
      a.parent_advisor_id,
      a.commission_eligible,
      a.commission_tier_id
    FROM public.advisors a
    JOIN public.advisors src ON src.id = p_advisor_id
    WHERE a.id = src.parent_advisor_id

    UNION ALL

    -- Walk up: each step grabs the parent of the previous level
    SELECT
      c.level + 1,
      a.id,
      a.parent_advisor_id,
      a.commission_eligible,
      a.commission_tier_id
    FROM chain c
    JOIN public.advisors a ON a.id = c.parent_advisor_id
    WHERE c.level < p_max_levels
      AND c.parent_advisor_id IS NOT NULL
  )
  SELECT level, advisor_id, parent_advisor_id, commission_eligible, commission_tier_id
    FROM chain
   ORDER BY level;
$$;


--
-- Name: FUNCTION get_advisor_upline(p_advisor_id uuid, p_max_levels integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_advisor_upline(p_advisor_id uuid, p_max_levels integer) IS 'Returns the upline parent chain for an advisor up to p_max_levels deep. One round-trip replaces the N+1 fetch loop in commission-service.';


--
-- Name: advisors; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.advisors (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    profile_id uuid,
    parent_advisor_id uuid,
    first_name text NOT NULL,
    last_name text NOT NULL,
    email text NOT NULL,
    phone text,
    license_number text,
    license_states text[] DEFAULT '{}'::text[],
    status text DEFAULT 'pending'::text NOT NULL,
    commission_tier text,
    custom_fields jsonb DEFAULT '{}'::jsonb,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    advisor_code text NOT NULL,
    agency_name text,
    npn text,
    contract_date date,
    termination_date date,
    primary_channel text,
    comp_level text,
    commission_tier_id uuid,
    override_rate_pct numeric(5,2),
    personal_production numeric(12,2) DEFAULT 0,
    team_production numeric(12,2) DEFAULT 0,
    lifetime_production numeric(12,2) DEFAULT 0,
    enrollment_code text,
    company_name text,
    website_url text,
    logo_url text,
    logo_size text DEFAULT 'medium'::text,
    primary_color text DEFAULT '#1e40af'::text,
    secondary_color text DEFAULT '#3b82f6'::text,
    header_bg_color text DEFAULT '#1e3a8a'::text,
    header_text_color text DEFAULT '#ffffff'::text,
    street_address text,
    apartment text,
    city text,
    state text,
    zip_code text,
    country text DEFAULT 'USA'::text,
    commission_eligible boolean DEFAULT true,
    agent_role text DEFAULT 'Agent'::text,
    agent_level_id uuid,
    commission_hold boolean DEFAULT false,
    commission_hold_reason text,
    total_lifetime_commissions numeric(12,2) DEFAULT 0,
    current_month_commissions numeric(12,2) DEFAULT 0,
    pending_commissions numeric(12,2) DEFAULT 0,
    producer_code text,
    admin123_agent_id text,
    producer_type text,
    mobile_phone text,
    master_click_funnel text,
    mpb_certified boolean DEFAULT false,
    mpb_eo_current boolean DEFAULT false,
    crm_owner boolean DEFAULT false,
    referring_affiliate_id uuid,
    setup_fee_waived boolean DEFAULT false,
    compliance_training_completed date,
    producer_owner_id uuid,
    capacities text[] DEFAULT '{}'::text[],
    full_name text GENERATED ALWAYS AS (TRIM(BOTH FROM ((COALESCE(first_name, ''::text) || ' '::text) || COALESCE(last_name, ''::text)))) STORED,
    is_active boolean GENERATED ALWAYS AS ((status = 'active'::text)) STORED,
    CONSTRAINT advisors_agent_role_check CHECK ((agent_role = ANY (ARRAY['Agent'::text, 'Agency'::text]))),
    CONSTRAINT advisors_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'active'::text, 'inactive'::text, 'terminated'::text])))
);


