--
-- Name: get_advisors_by_capacity(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_advisors_by_capacity(p_org_id uuid, p_product_type text) RETURNS SETOF public.advisors
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_product_type IS NULL THEN
    -- No filter — return all active advisors
    RETURN QUERY
    SELECT * FROM advisors
    WHERE organization_id = p_org_id
      AND status = 'active'
    ORDER BY last_name, first_name;
  ELSE
    -- Filter by capacity (include advisors with empty capacities for backward compat)
    RETURN QUERY
    SELECT * FROM advisors
    WHERE organization_id = p_org_id
      AND status = 'active'
      AND (
        capacities = '{}'
        OR capacities IS NULL
        OR p_product_type = ANY(capacities)
      )
    ORDER BY last_name, first_name;
  END IF;
END;
$$;


--
-- Name: get_age_up_out_summary(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_age_up_out_summary(p_org_id uuid, p_days_ahead integer DEFAULT 90) RETURNS TABLE(status text, event_type text, count bigint, earliest_event_date date, latest_event_date date)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    auo.status,
    auo.event_type,
    COUNT(*) as count,
    MIN(auo.event_date) as earliest_event_date,
    MAX(auo.event_date) as latest_event_date
  FROM public.age_up_out_results auo
  WHERE auo.organization_id = p_org_id
    AND auo.event_date <= (CURRENT_DATE + p_days_ahead)
    AND auo.action_required = true
  GROUP BY auo.status, auo.event_type
  ORDER BY auo.status, auo.event_type;
END;
$$;


--
-- Name: get_agency_analytics(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_agency_analytics(p_org_id uuid, p_months integer DEFAULT 12) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_cutoff  date := (date_trunc('month', current_date) - (p_months || ' months')::interval)::date;
  v_result  jsonb;
  v_summary jsonb;
  v_by_type jsonb;
  v_top_advisors jsonb;
  v_monthly jsonb;
BEGIN
  -- Agency summary
  SELECT jsonb_build_object(
    'total_production',   COALESCE(sum(total_commissions), 0),
    'total_enrollments',  COALESCE(sum(total_enrollments), 0),
    'active_advisors',    count(DISTINCT advisor_id),
    'paid_commissions',   COALESCE(sum(paid_commissions), 0),
    'pending_commissions', COALESCE(sum(pending_commissions), 0)
  ) INTO v_summary
  FROM mv_advisor_monthly_performance
  WHERE organization_id = p_org_id AND month >= v_cutoff;

  -- By product type
  SELECT COALESCE(jsonb_agg(row_data), '[]'::jsonb) INTO v_by_type
  FROM (
    SELECT jsonb_build_object(
      'product_type', product_type,
      'total_commissions', COALESCE(sum(total_commissions), 0),
      'total_enrollments', COALESCE(sum(total_enrollments), 0)
    ) AS row_data
    FROM mv_advisor_monthly_performance
    WHERE organization_id = p_org_id AND month >= v_cutoff
    GROUP BY product_type
  ) sub;

  -- Top 5 advisors by production
  SELECT COALESCE(jsonb_agg(row_data ORDER BY total DESC), '[]'::jsonb) INTO v_top_advisors
  FROM (
    SELECT jsonb_build_object(
      'advisor_id', m.advisor_id,
      'first_name', a.first_name,
      'last_name', a.last_name,
      'commission_tier', a.commission_tier,
      'total_commissions', sum(m.total_commissions),
      'total_enrollments', sum(m.total_enrollments)
    ) AS row_data,
    sum(m.total_commissions) AS total
    FROM mv_advisor_monthly_performance m
    JOIN advisors a ON a.id = m.advisor_id
    WHERE m.organization_id = p_org_id AND m.month >= v_cutoff
    GROUP BY m.advisor_id, a.first_name, a.last_name, a.commission_tier
    ORDER BY sum(m.total_commissions) DESC
    LIMIT 5
  ) sub;

  -- Monthly trend
  SELECT COALESCE(jsonb_agg(row_data ORDER BY month), '[]'::jsonb) INTO v_monthly
  FROM (
    SELECT jsonb_build_object(
      'month', month,
      'total_commissions', COALESCE(sum(total_commissions), 0),
      'total_enrollments', COALESCE(sum(total_enrollments), 0),
      'active_advisors', count(DISTINCT advisor_id)
    ) AS row_data, month
    FROM mv_advisor_monthly_performance
    WHERE organization_id = p_org_id AND month >= v_cutoff
    GROUP BY month
  ) sub;

  v_result := jsonb_build_object(
    'summary', COALESCE(v_summary, '{}'::jsonb),
    'by_product', COALESCE(v_by_type, '[]'::jsonb),
    'top_advisors', COALESCE(v_top_advisors, '[]'::jsonb),
    'monthly', COALESCE(v_monthly, '[]'::jsonb)
  );

  RETURN v_result;
END;
$$;


--
-- Name: get_agency_members(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_agency_members(p_agency_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(row_data ORDER BY a.last_name, a.first_name), '[]'::jsonb)
  INTO v_result
  FROM (
    SELECT jsonb_build_object(
      'id',             au.id,
      'advisor_id',     au.advisor_id,
      'role',           au.role,
      'status',         au.status,
      'joined_at',      au.joined_at,
      'first_name',     a.first_name,
      'last_name',      a.last_name,
      'email',          a.email,
      'phone',          a.phone,
      'commission_tier', a.commission_tier,
      'capacities',     a.capacities,
      'agent_role',     a.agent_role
    ) AS row_data
    FROM agency_users au
    JOIN advisors a ON a.id = au.advisor_id
    WHERE au.agency_id = p_agency_id
      AND au.status = 'active'
  ) sub;

  RETURN v_result;
END;
$$;


--
-- Name: get_agency_scoped_analytics(uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_agency_scoped_analytics(p_agency_id uuid, p_months integer DEFAULT 12, p_capacity_scope text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_cutoff  date := (date_trunc('month', current_date) - (p_months || ' months')::interval)::date;
  v_org_id  uuid;
  v_summary jsonb;
  v_by_type jsonb;
  v_top_advisors jsonb;
  v_monthly jsonb;
BEGIN
  -- Get org_id for this agency
  SELECT organization_id INTO v_org_id FROM agencies WHERE id = p_agency_id;

  -- Agency summary (filtered to agency members only)
  SELECT jsonb_build_object(
    'total_production',   COALESCE(sum(m.total_commissions), 0),
    'total_enrollments',  COALESCE(sum(m.total_enrollments), 0),
    'active_advisors',    count(DISTINCT m.advisor_id),
    'paid_commissions',   COALESCE(sum(m.paid_commissions), 0),
    'pending_commissions', COALESCE(sum(m.pending_commissions), 0)
  ) INTO v_summary
  FROM mv_advisor_monthly_performance m
  JOIN agency_users au ON au.advisor_id = m.advisor_id AND au.agency_id = p_agency_id AND au.status = 'active'
  WHERE m.organization_id = v_org_id
    AND m.month >= v_cutoff
    AND (p_capacity_scope IS NULL OR m.product_type = p_capacity_scope);

  -- By product type
  SELECT COALESCE(jsonb_agg(row_data), '[]'::jsonb) INTO v_by_type
  FROM (
    SELECT jsonb_build_object(
      'product_type',      m.product_type,
      'total_commissions', COALESCE(sum(m.total_commissions), 0),
      'total_enrollments', COALESCE(sum(m.total_enrollments), 0)
    ) AS row_data
    FROM mv_advisor_monthly_performance m
    JOIN agency_users au ON au.advisor_id = m.advisor_id AND au.agency_id = p_agency_id AND au.status = 'active'
    WHERE m.organization_id = v_org_id
      AND m.month >= v_cutoff
      AND (p_capacity_scope IS NULL OR m.product_type = p_capacity_scope)
    GROUP BY m.product_type
  ) sub;

  -- Top 5 advisors
  SELECT COALESCE(jsonb_agg(row_data ORDER BY total DESC), '[]'::jsonb) INTO v_top_advisors
  FROM (
    SELECT jsonb_build_object(
      'advisor_id',       m.advisor_id,
      'first_name',       a.first_name,
      'last_name',        a.last_name,
      'commission_tier',  a.commission_tier,
      'total_commissions', sum(m.total_commissions),
      'total_enrollments', sum(m.total_enrollments)
    ) AS row_data,
    sum(m.total_commissions) AS total
    FROM mv_advisor_monthly_performance m
    JOIN agency_users au ON au.advisor_id = m.advisor_id AND au.agency_id = p_agency_id AND au.status = 'active'
    JOIN advisors a ON a.id = m.advisor_id
    WHERE m.organization_id = v_org_id
      AND m.month >= v_cutoff
      AND (p_capacity_scope IS NULL OR m.product_type = p_capacity_scope)
    GROUP BY m.advisor_id, a.first_name, a.last_name, a.commission_tier
    ORDER BY sum(m.total_commissions) DESC
    LIMIT 5
  ) sub;

  -- Monthly trend
  SELECT COALESCE(jsonb_agg(row_data ORDER BY month), '[]'::jsonb) INTO v_monthly
  FROM (
    SELECT jsonb_build_object(
      'month',             m.month,
      'total_commissions', COALESCE(sum(m.total_commissions), 0),
      'total_enrollments', COALESCE(sum(m.total_enrollments), 0),
      'active_advisors',   count(DISTINCT m.advisor_id)
    ) AS row_data, m.month
    FROM mv_advisor_monthly_performance m
    JOIN agency_users au ON au.advisor_id = m.advisor_id AND au.agency_id = p_agency_id AND au.status = 'active'
    WHERE m.organization_id = v_org_id
      AND m.month >= v_cutoff
      AND (p_capacity_scope IS NULL OR m.product_type = p_capacity_scope)
    GROUP BY m.month
  ) sub;

  RETURN jsonb_build_object(
    'agency_id', p_agency_id,
    'summary', COALESCE(v_summary, '{}'::jsonb),
    'by_product', COALESCE(v_by_type, '[]'::jsonb),
    'top_advisors', COALESCE(v_top_advisors, '[]'::jsonb),
    'monthly', COALESCE(v_monthly, '[]'::jsonb)
  );
END;
$$;


--
-- Name: get_agent_sla_performance(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_agent_sla_performance(p_start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_date timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(agent_id uuid, agent_name text, agent_email text, total_tickets bigint, first_response_met bigint, first_response_percentage numeric, resolution_met bigint, resolution_percentage numeric, avg_first_response_minutes numeric, avg_resolution_minutes numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    p.id AS agent_id,
    COALESCE(p.full_name, p.email) AS agent_name,
    p.email AS agent_email,
    COUNT(sm.id)::bigint AS total_tickets,
    COUNT(*) FILTER (WHERE sm.first_response_met = true)::bigint AS first_response_met,
    ROUND(COUNT(*) FILTER (WHERE sm.first_response_met = true)::numeric / NULLIF(COUNT(sm.id)::numeric, 0) * 100, 2) AS first_response_percentage,
    COUNT(*) FILTER (WHERE sm.resolution_met = true)::bigint AS resolution_met,
    ROUND(COUNT(*) FILTER (WHERE sm.resolution_met = true)::numeric / NULLIF(COUNT(sm.id)::numeric, 0) * 100, 2) AS resolution_percentage,
    ROUND(AVG(sm.first_response_duration_minutes), 0) AS avg_first_response_minutes,
    ROUND(AVG(sm.resolution_duration_minutes), 0) AS avg_resolution_minutes
  FROM public.profiles p
  LEFT JOIN public.sla_metrics sm ON sm.assigned_agent_id = p.id
    AND (p_start_date IS NULL OR sm.ticket_created_at >= p_start_date)
    AND (p_end_date IS NULL OR sm.ticket_created_at <= p_end_date)
  WHERE p.role IN ('staff', 'agent', 'admin', 'super_admin')
  GROUP BY p.id, p.full_name, p.email
  HAVING COUNT(sm.id) > 0
  ORDER BY resolution_percentage DESC NULLS LAST;
END;
$$;


--
-- Name: get_agent_tree_data(uuid, uuid[], uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_agent_tree_data(p_module_id uuid, p_owner_ids uuid[] DEFAULT NULL::uuid[], p_canonical_advisor_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(agent_name text, record_count bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT
    COALESCE(
      NULLIF(TRIM(r.normalized_agent_name), ''),
      NULLIF(TRIM(r.data->>'agent'), ''),
      NULLIF(TRIM(r.data->>'producer_name'), ''),
      'Unassigned'
    ) AS agent_name,
    COUNT(r.id) AS record_count
  FROM crm_records r
  WHERE r.module_id = p_module_id
    AND (
      (p_owner_ids IS NULL AND p_canonical_advisor_ids IS NULL)
      OR r.owner_id = ANY(p_owner_ids)
      OR r.canonical_advisor_id = ANY(p_canonical_advisor_ids)
    )
  GROUP BY agent_name
  ORDER BY agent_name;
$$;


--
-- Name: get_agent_workload(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_agent_workload(p_agent_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller_org uuid;
  v_agent_org uuid;
BEGIN
  SELECT organization_id INTO v_caller_org FROM profiles WHERE user_id = auth.uid() LIMIT 1;
  SELECT organization_id INTO v_agent_org FROM profiles WHERE id = p_agent_id LIMIT 1;
  IF v_caller_org IS NULL OR v_agent_org IS NULL OR v_caller_org != v_agent_org THEN
    RETURN 0;
  END IF;
  RETURN (
    SELECT COUNT(*)::int
    FROM tickets t
    WHERE t.assigned_to_profile_id = p_agent_id
      AND t.status NOT IN ('closed', 'resolved')
  );
END;
$$;


--
-- Name: get_approval_detail(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_approval_detail(p_approval_id uuid) RETURNS TABLE(id uuid, org_id uuid, process_id uuid, process_name text, process_description text, process_steps jsonb, record_id uuid, record_title text, record_data jsonb, module_id uuid, module_key text, module_name text, status text, current_step integer, context jsonb, action_payload jsonb, entity_snapshot jsonb, requested_by uuid, requested_by_name text, resolved_by uuid, resolved_by_name text, resolved_at timestamp with time zone, applied_at timestamp with time zone, expires_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Validate caller belongs to the approval's org
  IF NOT EXISTS (
    SELECT 1 FROM crm_approvals ca
    JOIN profiles p ON p.organization_id = ca.organization_id
    WHERE ca.id = p_approval_id AND p.user_id = auth.uid()
  ) THEN
    RETURN; -- empty set
  END IF;

  RETURN QUERY
    SELECT
      a.id,
      a.organization_id,
      a.process_id,
      p.name AS process_name,
      p.description AS process_description,
      p.steps AS process_steps,
      a.record_id,
      r.title AS record_title,
      r.data AS record_data,
      m.id AS module_id,
      m.key AS module_key,
      m.name AS module_name,
      a.status,
      a.current_step,
      a.context,
      a.action_payload,
      a.entity_snapshot,
      a.requested_by,
      pr.full_name AS requested_by_name,
      a.resolved_by,
      pres.full_name AS resolved_by_name,
      a.resolved_at,
      a.applied_at,
      a.expires_at,
      a.created_at,
      a.updated_at
    FROM crm_approvals a
    JOIN crm_approval_processes p ON a.process_id = p.id
    JOIN crm_records r ON a.record_id = r.id
    JOIN crm_modules m ON r.module_id = m.id
    LEFT JOIN profiles pr ON a.requested_by = pr.id
    LEFT JOIN profiles pres ON a.resolved_by = pres.id
    WHERE a.id = p_approval_id;
END;
$$;


--
-- Name: get_approval_inbox(uuid, uuid, text, text, text, boolean, boolean, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_approval_inbox(p_org_id uuid, p_profile_id uuid, p_user_role text, p_status text DEFAULT NULL::text, p_entity_type text DEFAULT NULL::text, p_assigned_to_me boolean DEFAULT false, p_requested_by_me boolean DEFAULT false, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, process_id uuid, process_name text, record_id uuid, record_title text, module_key text, module_name text, status text, current_step integer, total_steps integer, context jsonb, requested_by uuid, requested_by_name text, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Use table-qualified column to avoid ambiguity with output column "id"
  IF NOT EXISTS (
    SELECT 1 FROM profiles prf
    WHERE prf.user_id = auth.uid()
      AND prf.organization_id = p_org_id
      AND prf.id = p_profile_id
  ) THEN
    RETURN;
  END IF;

  RETURN QUERY
    SELECT
      a.id,
      a.process_id,
      ap.name AS process_name,
      a.record_id,
      r.title AS record_title,
      m.key AS module_key,
      m.name AS module_name,
      a.status,
      a.current_step,
      jsonb_array_length(ap.steps)::int AS total_steps,
      a.context,
      a.requested_by,
      pr.full_name AS requested_by_name,
      a.created_at,
      a.updated_at
    FROM crm_approvals a
    JOIN crm_approval_processes ap ON a.process_id = ap.id
    JOIN crm_records r ON a.record_id = r.id
    JOIN crm_modules m ON r.module_id = m.id
    LEFT JOIN profiles pr ON a.requested_by = pr.id
    WHERE a.organization_id = p_org_id
      AND (p_status IS NULL OR a.status = p_status)
      AND (p_entity_type IS NULL OR m.key = p_entity_type)
      AND (
        NOT p_assigned_to_me
        OR EXISTS (
          SELECT 1 FROM jsonb_array_elements(ap.steps) WITH ORDINALITY AS s(step, idx)
          WHERE (s.idx - 1) = a.current_step
            AND (
              s.step->>'approver_profile_id' = p_profile_id::text
              OR (s.step->>'approver_role' IS NOT NULL AND s.step->>'approver_role' = p_user_role)
            )
        )
      )
      AND (NOT p_requested_by_me OR a.requested_by = p_profile_id)
    ORDER BY a.created_at DESC
    LIMIT p_limit
    OFFSET p_offset;
END;
$$;


--
-- Name: crm_approval_rules; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.crm_approval_rules (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    module_id uuid NOT NULL,
    process_id uuid NOT NULL,
    name text NOT NULL,
    description text,
    trigger_type text NOT NULL,
    trigger_config jsonb DEFAULT '{}'::jsonb NOT NULL,
    conditions jsonb DEFAULT '{"logic": "AND", "conditions": []}'::jsonb NOT NULL,
    priority integer DEFAULT 100,
    is_enabled boolean DEFAULT true,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    organization_id uuid,
    CONSTRAINT crm_approval_rules_trigger_type_check CHECK ((trigger_type = ANY (ARRAY['field_change'::text, 'stage_transition'::text, 'record_delete'::text, 'record_create'::text, 'field_threshold'::text])))
);


--
-- Name: TABLE crm_approval_rules; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.crm_approval_rules IS 'Rules that determine when approval processes are triggered';


--
-- Name: COLUMN crm_approval_rules.trigger_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.crm_approval_rules.trigger_type IS 'What action triggers the approval check';


--
-- Name: COLUMN crm_approval_rules.trigger_config; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.crm_approval_rules.trigger_config IS 'Trigger-specific config: {field?, stage_from?, stage_to?, threshold?}';


--
-- Name: COLUMN crm_approval_rules.conditions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.crm_approval_rules.conditions IS 'Rule DSL: {logic: AND|OR, conditions: [{field, operator, value}]}';


--
-- Name: get_approval_rules_for_module(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_approval_rules_for_module(p_module_id uuid, p_trigger_type text DEFAULT NULL::text) RETURNS SETOF public.crm_approval_rules
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM crm_modules m
    JOIN profiles p ON p.organization_id = m.organization_id
    WHERE m.id = p_module_id AND p.user_id = auth.uid()
  ) THEN
    RETURN; -- empty set
  END IF;

  RETURN QUERY
    SELECT * FROM crm_approval_rules
    WHERE module_id = p_module_id
      AND is_enabled = true
      AND (p_trigger_type IS NULL OR trigger_type = p_trigger_type)
    ORDER BY priority ASC, created_at ASC;
END;
$$;


--
-- Name: get_available_services(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_available_services(p_zip_code text, p_category text DEFAULT NULL::text, p_plan_category text DEFAULT NULL::text) RETURNS TABLE(service_id uuid, service_code text, service_name text, service_category text, description text, provider_network text, icon text, color text, coverage_level text, location_count bigint, nearest_location jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH matched_areas AS (
    -- Direct ZIP match
    SELECT
      sa.service_id,
      sa.coverage_level,
      sa.location_id
    FROM healthcare_service_areas sa
    WHERE sa.zip_code = p_zip_code
      AND sa.is_active = true
      AND (sa.end_date IS NULL OR sa.end_date > CURRENT_DATE)
      AND sa.effective_date <= CURRENT_DATE
  ),
  service_locations AS (
    SELECT
      ma.service_id,
      ma.coverage_level,
      COUNT(DISTINCT hl.id) AS loc_count,
      -- Pick nearest location (first by city match, then alphabetical)
      (
        SELECT jsonb_build_object(
          'id', nearest.id,
          'name', nearest.name,
          'address', nearest.address_line1,
          'city', nearest.city,
          'state', nearest.state,
          'zip', nearest.zip,
          'phone', nearest.phone,
          'latitude', nearest.latitude,
          'longitude', nearest.longitude,
          'telehealth_capable', nearest.telehealth_capable,
          'accepting_new_patients', nearest.accepting_new_patients
        )
        FROM healthcare_locations nearest
        WHERE nearest.id = ma.location_id
          AND nearest.is_active = true
        LIMIT 1
      ) AS nearest_loc
    FROM matched_areas ma
    LEFT JOIN healthcare_locations hl
      ON hl.id = ma.location_id AND hl.is_active = true
    GROUP BY ma.service_id, ma.coverage_level, ma.location_id
  )
  SELECT
    hs.id AS service_id,
    hs.service_code,
    hs.service_name,
    hs.service_category,
    hs.description,
    hs.provider_network,
    hs.icon,
    hs.color,
    COALESCE(sl.coverage_level, 'full') AS coverage_level,
    COALESCE(sl.loc_count, 0) AS location_count,
    sl.nearest_loc AS nearest_location
  FROM healthcare_services hs
  INNER JOIN service_locations sl ON sl.service_id = hs.id
  WHERE hs.is_active = true
    AND hs.is_public = true
    AND (p_category IS NULL OR hs.service_category = p_category)
    AND (
      p_plan_category IS NULL
      OR hs.eligibility_rules = '{}'::jsonb
      OR hs.eligibility_rules->'plan_categories' IS NULL
      OR hs.eligibility_rules->'plan_categories' @> to_jsonb(p_plan_category)
    )
  ORDER BY hs.sort_order, hs.service_name;
END;
$$;


--
-- Name: FUNCTION get_available_services(p_zip_code text, p_category text, p_plan_category text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_available_services(p_zip_code text, p_category text, p_plan_category text) IS 'ZIP-based service lookup: returns available healthcare services with location info';


--
-- Name: get_billing_summary(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_billing_summary(p_org_id uuid, p_start_date timestamp with time zone, p_end_date timestamp with time zone) RETURNS TABLE(total_collected numeric, total_refunded numeric, total_declined numeric, transaction_count bigint, success_count bigint, failed_count bigint, refund_count bigint, avg_transaction numeric, by_payment_method jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH txn_stats AS (
    SELECT
      COALESCE(SUM(CASE WHEN bt.status = 'success' AND bt.transaction_type = 'charge' THEN bt.amount ELSE 0 END), 0) as collected,
      COALESCE(SUM(CASE WHEN bt.transaction_type = 'refund' THEN bt.amount ELSE 0 END), 0) as refunded,
      COALESCE(SUM(CASE WHEN bt.status = 'failed' THEN bt.amount ELSE 0 END), 0) as declined,
      COUNT(*) as total_count,
      COUNT(*) FILTER (WHERE bt.status = 'success') as success_cnt,
      COUNT(*) FILTER (WHERE bt.status = 'failed') as failed_cnt,
      COUNT(*) FILTER (WHERE bt.transaction_type = 'refund') as refund_cnt,
      COALESCE(AVG(CASE WHEN bt.status = 'success' AND bt.transaction_type = 'charge' THEN bt.amount END), 0) as avg_txn
    FROM billing_transactions bt
    WHERE bt.organization_id = p_org_id
      AND bt.created_at >= p_start_date
      AND bt.created_at < p_end_date
  ),
  method_stats AS (
    SELECT
      COALESCE(pp.payment_type, 'unknown') as method,
      COUNT(*) as cnt,
      COALESCE(SUM(CASE WHEN bt.status = 'success' THEN bt.amount ELSE 0 END), 0) as amt
    FROM billing_transactions bt
    LEFT JOIN payment_profiles pp ON bt.payment_profile_id = pp.id
    WHERE bt.organization_id = p_org_id
      AND bt.created_at >= p_start_date
      AND bt.created_at < p_end_date
    GROUP BY pp.payment_type
  )
  SELECT
    ts.collected,
    ts.refunded,
    ts.declined,
    ts.total_count,
    ts.success_cnt,
    ts.failed_cnt,
    ts.refund_cnt,
    ts.avg_txn,
    COALESCE((SELECT jsonb_object_agg(ms.method, jsonb_build_object('count', ms.cnt, 'amount', ms.amt)) FROM method_stats ms), '{}'::jsonb)
  FROM txn_stats ts;
END;
$$;


--
-- Name: get_busy_slots(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_busy_slots(p_owner_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS TABLE(busy_start timestamp with time zone, busy_end timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT ce.start_time, ce.end_time
  FROM calendar_events ce
  WHERE ce.owner_id = p_owner_id
    AND ce.status = 'confirmed'
    AND ce.start_time < p_end
    AND ce.end_time > p_start
  ORDER BY ce.start_time;
END;
$$;


--
-- Name: calendar_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.calendar_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    connection_id uuid NOT NULL,
    owner_id uuid NOT NULL,
    external_id text NOT NULL,
    external_calendar_id text NOT NULL,
    provider text NOT NULL,
    title text NOT NULL,
    description text,
    location text,
    start_time timestamp with time zone NOT NULL,
    end_time timestamp with time zone NOT NULL,
    timezone text,
    is_all_day boolean DEFAULT false NOT NULL,
    is_recurring boolean DEFAULT false NOT NULL,
    recurrence_rule text,
    recurring_event_id text,
    organizer_email text,
    organizer_name text,
    attendees jsonb DEFAULT '[]'::jsonb,
    meeting_url text,
    meeting_provider text,
    status text DEFAULT 'confirmed'::text NOT NULL,
    visibility text DEFAULT 'default'::text,
    linked_contact_id uuid,
    linked_deal_id uuid,
    linked_task_id uuid,
    etag text,
    raw_data jsonb,
    last_synced_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    organization_id uuid
);


--
-- Name: get_calendar_events_range(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_calendar_events_range(p_owner_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS SETOF public.calendar_events
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT ce.*
  FROM calendar_events ce
  WHERE ce.owner_id = p_owner_id
    AND ce.status != 'cancelled'
    AND (
      (ce.start_time >= p_start AND ce.start_time < p_end)
      OR (ce.end_time > p_start AND ce.end_time <= p_end)
      OR (ce.start_time <= p_start AND ce.end_time >= p_end)
    )
  ORDER BY ce.start_time;
END;
$$;


--
-- Name: get_campaign_stats(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_campaign_stats(p_campaign_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_stats json;
BEGIN
  SELECT json_build_object(
    'total', total_recipients,
    'sent', sent_count,
    'delivered', delivered_count,
    'opened', opened_count,
    'clicked', clicked_count,
    'bounced', bounced_count,
    'unsubscribed', unsubscribed_count,
    'failed', failed_count,
    'pending', total_recipients - sent_count,
    'delivery_rate', CASE WHEN sent_count > 0
      THEN ROUND((delivered_count::numeric / sent_count) * 100, 2) ELSE 0 END,
    'open_rate', CASE WHEN delivered_count > 0
      THEN ROUND((opened_count::numeric / delivered_count) * 100, 2) ELSE 0 END,
    'click_rate', CASE WHEN delivered_count > 0
      THEN ROUND((clicked_count::numeric / delivered_count) * 100, 2) ELSE 0 END,
    'bounce_rate', CASE WHEN sent_count > 0
      THEN ROUND((bounced_count::numeric / sent_count) * 100, 2) ELSE 0 END
  ) INTO v_stats
  FROM email_campaigns
  WHERE id = p_campaign_id;

  RETURN v_stats;
END;
$$;


--
-- Name: get_change_feed_stats(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_change_feed_stats(p_org_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_stats jsonb;
BEGIN
  SELECT jsonb_build_object(
    'total_today', COUNT(*) FILTER (WHERE created_at >= CURRENT_DATE),
    'critical_count', COUNT(*) FILTER (WHERE severity = 'critical' AND reconciliation_status IN ('none', 'pending')),
    'high_count', COUNT(*) FILTER (WHERE severity = 'high' AND reconciliation_status IN ('none', 'pending')),
    'pending_review', COUNT(*) FILTER (WHERE requires_review = true AND reconciliation_status IN ('none', 'pending')),
    'sync_conflicts', COUNT(*) FILTER (WHERE sync_status = 'conflict')
  ) INTO v_stats
  FROM change_events
  WHERE organization_id = p_org_id
  AND created_at >= CURRENT_DATE - INTERVAL '7 days';

  RETURN COALESCE(v_stats, '{}'::jsonb);
END;
$$;


--
-- Name: FUNCTION get_change_feed_stats(p_org_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_change_feed_stats(p_org_id uuid) IS 'Returns summary statistics for the change intelligence dashboard';


