    AND status = 'active';
$$;


--
-- Name: get_command_console_stats(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_command_console_stats(p_org_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_today_start   timestamptz := date_trunc('day', now());
  v_today_end     timestamptz := v_today_start + interval '1 day';
  v_48h_ago       timestamptz := now() - interval '48 hours';
  v_seven_days    timestamptz := now() - interval '7 days';

  -- Enrollment stats
  v_started_today       int := 0;
  v_submitted_today     int := 0;
  v_activated_today     int := 0;
  v_pending_underwriting int := 0;
  v_docs_required       int := 0;
  v_activation_delayed  int := 0;
  v_rejected_count      int := 0;
  v_expiring_soon       int := 0;
  v_total_draft         int := 0;

  -- Billing stats
  v_collected_today     numeric(12,2) := 0;
  v_mrr                 numeric(12,2) := 0;
  v_failed_today        int := 0;
  v_pending_ach         int := 0;
  v_last_payment_at     timestamptz;

  -- Pipeline counts
  v_pipeline_leads      bigint := 0;
  v_pipeline_draft      int := 0;
  v_pipeline_in_progress int := 0;
  v_pipeline_submitted  int := 0;
  v_pipeline_approved   int := 0;
  v_pipeline_rejected   int := 0;
  v_pipeline_cancelled  int := 0;

  -- Operations stats
  v_overdue_tasks       int := 0;
  v_at_risk_deals       int := 0;

  -- Work queue
  v_work_queue          jsonb := '[]'::jsonb;
BEGIN
  -- ── Authorization: caller must belong to the target organization ──
  IF NOT EXISTS (
    SELECT 1 FROM profiles
    WHERE user_id = auth.uid()
      AND organization_id = p_org_id
  ) THEN
    RAISE EXCEPTION 'Unauthorized: caller does not belong to this organization';
  END IF;

  -- ── Authorization: p_user_id must match the authenticated user ──
  IF NOT EXISTS (
    SELECT 1 FROM profiles
    WHERE user_id = auth.uid()
      AND id = p_user_id
  ) THEN
    RAISE EXCEPTION 'Unauthorized: p_user_id does not match authenticated user';
  END IF;

  -- =========================================================================
  -- ENROLLMENT STATS
  -- =========================================================================

  SELECT COUNT(*) INTO v_started_today
  FROM enrollments
  WHERE organization_id = p_org_id
    AND created_at >= v_today_start
    AND created_at < v_today_end;

  SELECT COUNT(*) INTO v_submitted_today
  FROM enrollments
  WHERE organization_id = p_org_id
    AND status = 'submitted'
    AND updated_at >= v_today_start
    AND updated_at < v_today_end;

  SELECT COUNT(*) INTO v_activated_today
  FROM enrollments
  WHERE organization_id = p_org_id
    AND status = 'approved'
    AND updated_at >= v_today_start
    AND updated_at < v_today_end;

  SELECT COUNT(*) INTO v_pending_underwriting
  FROM enrollments
  WHERE organization_id = p_org_id
    AND status = 'submitted';

  SELECT COUNT(DISTINCT es.enrollment_id) INTO v_docs_required
  FROM enrollment_steps es
  JOIN enrollments e ON e.id = es.enrollment_id
  WHERE es.organization_id = p_org_id
    AND es.is_completed = false
    AND e.status NOT IN ('approved', 'rejected', 'cancelled');

  SELECT COUNT(*) INTO v_activation_delayed
  FROM enrollments
  WHERE organization_id = p_org_id
    AND status = 'approved'
    AND effective_date IS NULL;

  SELECT COUNT(*) INTO v_rejected_count
  FROM enrollments
  WHERE organization_id = p_org_id
    AND status = 'rejected';

  SELECT COUNT(*) INTO v_expiring_soon
  FROM enrollments
  WHERE organization_id = p_org_id
    AND status IN ('draft', 'in_progress')
    AND created_at < v_48h_ago;

  SELECT COUNT(*) INTO v_total_draft
  FROM enrollments
  WHERE organization_id = p_org_id
    AND status = 'draft';

  -- =========================================================================
  -- BILLING STATS
  -- =========================================================================

  SELECT COALESCE(SUM(amount), 0) INTO v_collected_today
  FROM billing_transactions
  WHERE organization_id = p_org_id
    AND status = 'success'
    AND processed_at >= v_today_start
    AND processed_at < v_today_end
    AND transaction_type = 'charge';

  SELECT COALESCE(SUM(amount), 0) INTO v_mrr
  FROM billing_schedules
  WHERE organization_id = p_org_id
    AND status = 'active';

  SELECT COUNT(*) INTO v_failed_today
  FROM billing_failures
  WHERE organization_id = p_org_id
    AND created_at >= v_today_start
    AND created_at < v_today_end
    AND resolved = false;

  SELECT COUNT(*) INTO v_pending_ach
  FROM billing_transactions
  WHERE organization_id = p_org_id
    AND status = 'pending';

  SELECT MAX(processed_at) INTO v_last_payment_at
  FROM billing_transactions
  WHERE organization_id = p_org_id
    AND status = 'success';

  -- =========================================================================
  -- PIPELINE COUNTS
  -- =========================================================================

  SELECT COUNT(*) INTO v_pipeline_leads
  FROM leads
  WHERE organization_id = p_org_id;

  SELECT
    COUNT(*) FILTER (WHERE status = 'draft') ,
    COUNT(*) FILTER (WHERE status = 'in_progress'),
    COUNT(*) FILTER (WHERE status = 'submitted'),
    COUNT(*) FILTER (WHERE status = 'approved'),
    COUNT(*) FILTER (WHERE status = 'rejected'),
    COUNT(*) FILTER (WHERE status = 'cancelled')
  INTO
    v_pipeline_draft,
    v_pipeline_in_progress,
    v_pipeline_submitted,
    v_pipeline_approved,
    v_pipeline_rejected,
    v_pipeline_cancelled
  FROM enrollments
  WHERE organization_id = p_org_id;

  -- =========================================================================
  -- OPERATIONS STATS (now scoped by org_id — fixes C-3)
  -- =========================================================================

  SELECT COUNT(*) INTO v_overdue_tasks
  FROM crm_tasks
  WHERE assigned_to = p_user_id
    AND organization_id = p_org_id
    AND status != 'completed'
    AND due_at < now();

  SELECT COUNT(*) INTO v_at_risk_deals
  FROM crm_records r
  JOIN crm_modules m ON m.id = r.module_id
  WHERE m.organization_id = p_org_id
    AND m.key = 'deals'
    AND r.updated_at < v_seven_days
    AND r.data->>'stage' NOT IN ('Closed Won', 'Closed Lost', 'closed_won', 'closed_lost');

  -- =========================================================================
  -- WORK QUEUE (now scoped by org_id on tasks — fixes C-3)
  -- =========================================================================

  WITH queue_items AS (
    (
      SELECT
        bf.id::text AS id,
        'billing_failure' AS type,
        'Payment Failed — ' || COALESCE(m.first_name || ' ' || m.last_name, 'Unknown') AS title,
        'ACH rejected · $' || bf.amount::text AS subtitle,
        1 AS priority,
        bf.created_at
      FROM billing_failures bf
      LEFT JOIN members m ON m.id = bf.member_id
      WHERE bf.organization_id = p_org_id
        AND bf.resolved = false
      ORDER BY bf.created_at DESC
      LIMIT 3
    )

    UNION ALL

    (
      SELECT
        e.id::text AS id,
        'enrollment_review' AS type,
        'Review Application — ' || COALESCE(m.first_name || ' ' || m.last_name, 'Unknown') AS title,
        'Submitted ' || to_char(e.updated_at, 'Mon DD') AS subtitle,
        2 AS priority,
        e.updated_at AS created_at
      FROM enrollments e
      LEFT JOIN members m ON m.id = e.primary_member_id
      WHERE e.organization_id = p_org_id
        AND e.status = 'submitted'
      ORDER BY e.updated_at ASC
      LIMIT 3
    )

    UNION ALL

    (
      SELECT
        e.id::text AS id,
        'docs_pending' AS type,
        'Missing Docs — ' || COALESCE(m.first_name || ' ' || m.last_name, 'Unknown') AS title,
        es.step_key || ' incomplete' AS subtitle,
        3 AS priority,
        es.created_at
      FROM enrollment_steps es
      JOIN enrollments e ON e.id = es.enrollment_id
      LEFT JOIN members m ON m.id = e.primary_member_id
      WHERE es.organization_id = p_org_id
        AND es.is_completed = false
        AND e.status NOT IN ('approved', 'rejected', 'cancelled')
      ORDER BY es.created_at ASC
      LIMIT 3
    )

    UNION ALL

    (
      SELECT
        t.id::text AS id,
        'overdue_task' AS type,
        COALESCE(t.title, 'Untitled Task') AS title,
        'Due ' || to_char(t.due_at, 'Mon DD') AS subtitle,
        4 AS priority,
        t.due_at AS created_at
      FROM crm_tasks t
      WHERE t.assigned_to = p_user_id
        AND t.organization_id = p_org_id
        AND t.status != 'completed'
        AND t.due_at < now()
      ORDER BY t.due_at ASC
      LIMIT 3
    )
  )
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', qi.id,
      'type', qi.type,
      'title', qi.title,
      'subtitle', qi.subtitle,
      'priority', qi.priority,
      'createdAt', qi.created_at
    )
    ORDER BY qi.priority, qi.created_at ASC
  ), '[]'::jsonb)
  INTO v_work_queue
  FROM (SELECT * FROM queue_items ORDER BY priority, created_at ASC LIMIT 8) qi;

  -- =========================================================================
  -- RETURN COMBINED RESULT
  -- =========================================================================

  RETURN jsonb_build_object(
    'enrollmentStats', jsonb_build_object(
      'startedToday', v_started_today,
      'submittedToday', v_submitted_today,
      'activatedToday', v_activated_today,
      'pendingUnderwriting', v_pending_underwriting,
      'docsRequired', v_docs_required,
      'activationDelayed', v_activation_delayed,
      'rejectedCount', v_rejected_count,
      'expiringSoon', v_expiring_soon,
      'totalDraft', v_total_draft
    ),
    'billingStats', jsonb_build_object(
      'collectedToday', v_collected_today,
      'mrr', v_mrr,
      'failedToday', v_failed_today,
      'pendingAch', v_pending_ach,
      'lastSuccessfulPaymentAt', v_last_payment_at
    ),
    'pipelineCounts', jsonb_build_object(
      'leads', v_pipeline_leads,
      'draft', v_pipeline_draft,
      'inProgress', v_pipeline_in_progress,
      'submitted', v_pipeline_submitted,
      'approved', v_pipeline_approved,
      'rejected', v_pipeline_rejected,
      'cancelled', v_pipeline_cancelled
    ),
    'operationsStats', jsonb_build_object(
      'overdueTasks', v_overdue_tasks,
      'atRiskDeals', v_at_risk_deals
    ),
    'workQueue', v_work_queue
  );
END;
$_$;


--
-- Name: get_commission_summary(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_commission_summary(p_organization_id uuid, p_period_start date, p_period_end date) RETURNS TABLE(total_earned numeric, total_paid numeric, total_pending numeric, total_bonuses numeric, count_transactions integer, count_bonuses integer, avg_commission numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    COALESCE(SUM(c.amount), 0) as total_earned,
    COALESCE(SUM(CASE WHEN c.status = 'paid' THEN c.amount ELSE 0 END), 0) as total_paid,
    COALESCE(SUM(CASE WHEN c.status = 'pending' THEN c.amount ELSE 0 END), 0) as total_pending,
    COALESCE(SUM(CASE WHEN c.is_bonus = true THEN c.amount ELSE 0 END), 0) as total_bonuses,
    COUNT(*)::integer as count_transactions,
    COUNT(CASE WHEN c.is_bonus = true THEN 1 END)::integer as count_bonuses,
    COALESCE(AVG(c.amount), 0) as avg_commission
  FROM commissions c
  WHERE c.organization_id = p_organization_id
    AND c.commission_period >= to_char(p_period_start, 'YYYY-MM')
    AND c.commission_period <= to_char(p_period_end, 'YYYY-MM');
END;
$$;


--
-- Name: get_commission_summary_by_product_type(uuid, uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_commission_summary_by_product_type(p_advisor_id uuid, p_org_id uuid, p_period_start date DEFAULT NULL::date, p_period_end date DEFAULT NULL::date) RETURNS TABLE(product_type text, total_commissions numeric, commission_count bigint, avg_commission numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    COALESCE(c.product_type, 'unclassified') AS product_type,
    COALESCE(SUM(c.commission_amount), 0) AS total_commissions,
    COUNT(*) AS commission_count,
    COALESCE(AVG(c.commission_amount), 0) AS avg_commission
  FROM commissions c
  WHERE c.advisor_id = p_advisor_id
    AND c.organization_id = p_org_id
    AND (p_period_start IS NULL OR c.commission_period >= p_period_start)
    AND (p_period_end IS NULL OR c.commission_period <= p_period_end)
  GROUP BY COALESCE(c.product_type, 'unclassified')
  ORDER BY total_commissions DESC;
END;
$$;


--
-- Name: get_component_status_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_component_status_summary() RETURNS TABLE(component_name text, current_status text, last_check timestamp with time zone, uptime_24h numeric, avg_latency_24h numeric, incident_count_24h bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH latest_checks AS (
    SELECT DISTINCT ON (shl.component_name)
      shl.component_name,
      shl.status,
      shl.checked_at,
      shl.latency_ms
    FROM system_health_logs shl
    ORDER BY shl.component_name, shl.checked_at DESC
  ),
  uptime_calc AS (
    SELECT
      shl.component_name,
      ROUND(
        (COUNT(*) FILTER (WHERE status = 'healthy')::numeric / NULLIF(COUNT(*)::numeric, 0)) * 100,
        2
      ) as uptime_pct,
      ROUND(AVG(latency_ms)::numeric, 2) as avg_lat
    FROM system_health_logs shl
    WHERE checked_at >= NOW() - INTERVAL '24 hours'
    GROUP BY shl.component_name
  ),
  incident_counts AS (
    SELECT
      si.component_name,
      COUNT(*) as incidents
    FROM system_incidents si
    WHERE si.detected_at >= NOW() - INTERVAL '24 hours'
    GROUP BY si.component_name
  )
  SELECT
    lc.component_name,
    lc.status as current_status,
    lc.checked_at as last_check,
    COALESCE(uc.uptime_pct, 0) as uptime_24h,
    COALESCE(uc.avg_lat, 0) as avg_latency_24h,
    COALESCE(ic.incidents, 0) as incident_count_24h
  FROM latest_checks lc
  LEFT JOIN uptime_calc uc ON lc.component_name = uc.component_name
  LEFT JOIN incident_counts ic ON lc.component_name = ic.component_name
  ORDER BY lc.component_name;
END;
$$;


--
-- Name: get_crm_dashboard_stats(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_crm_dashboard_stats(p_org_id uuid, p_module_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
  v_mod_id uuid;
BEGIN
  -- Default to contacts module if not specified
  IF p_module_id IS NULL THEN
    SELECT id INTO v_mod_id FROM crm_modules
    WHERE organization_id = p_org_id AND key = 'contacts' LIMIT 1;
  ELSE
    v_mod_id := p_module_id;
  END IF;

  SELECT jsonb_build_object(
    -- Total counts
    'total_records', count(*),
    'total_individual', count(*) FILTER (WHERE record_type = 'individual'),
    'total_group', count(*) FILTER (WHERE record_type = 'group'),

    -- By plan type
    'healthshare', count(*) FILTER (WHERE market_type = 'healthshare'),
    'traditional_insurance', count(*) FILTER (WHERE market_type = 'traditional_insurance'),
    'unknown_plan_type', count(*) FILTER (WHERE market_type = 'unknown' OR market_type IS NULL),

    -- Tobacco
    'tobacco_users', count(*) FILTER (WHERE tobacco_user = true AND record_type = 'individual'),
    'non_tobacco', count(*) FILTER (WHERE tobacco_user = false AND record_type = 'individual'),
    'tobacco_unknown', count(*) FILTER (WHERE tobacco_user IS NULL AND record_type = 'individual'),

    -- Normalization / review
    'normalized', count(*) FILTER (WHERE normalization_status = 'normalized'),
    'needs_review', count(*) FILTER (WHERE normalization_status = 'needs_review'),
    'needs_classification', count(*) FILTER (WHERE market_type = 'unknown' OR market_type IS NULL),

    -- Carrier
    'with_carrier', count(*) FILTER (WHERE carrier_id IS NOT NULL),
    'missing_carrier', count(*) FILTER (WHERE carrier_id IS NULL AND record_type = 'individual'),

    -- Advisor assignment
    'with_advisor', count(*) FILTER (WHERE canonical_advisor_id IS NOT NULL OR normalized_advisor_name IS NOT NULL),
    'unassigned_advisor', count(*) FILTER (WHERE canonical_advisor_id IS NULL AND normalized_advisor_name IS NULL AND record_type = 'individual'),

    -- Import source
    'from_zoho', count(*) FILTER (WHERE import_source = 'zoho_csv'),
    'from_csv', count(*) FILTER (WHERE import_source = 'csv_import'),
    'manual_entry', count(*) FILTER (WHERE import_source = 'manual' OR import_source IS NULL),

    -- Time-based
    'created_last_7d', count(*) FILTER (WHERE created_at >= now() - interval '7 days'),
    'created_last_30d', count(*) FILTER (WHERE created_at >= now() - interval '30 days'),
    'updated_last_7d', count(*) FILTER (WHERE updated_at >= now() - interval '7 days')
  ) INTO v_result
  FROM crm_records
  WHERE organization_id = p_org_id
    AND (v_mod_id IS NULL OR module_id = v_mod_id);

  RETURN v_result;
END;
$$;


--
-- Name: get_daily_log_entry_count(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_daily_log_entry_count(log_id uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COUNT(*)::integer
  FROM public.daily_log_entries
  WHERE daily_log_id = log_id;
$$;


--
-- Name: get_dashboard_hero_stats(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_dashboard_hero_stats(p_org_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_today_start timestamptz := date_trunc('day', now());
  v_today_end   timestamptz := v_today_start + interval '1 day';
  v_seven_days  timestamptz := now() - interval '7 days';
  v_todays_task_count int;
  v_overdue_count int;
  v_at_risk_count int;
  v_new_this_week bigint;
BEGIN
  -- Validate caller belongs to org AND matches p_user_id
  IF NOT EXISTS (
    SELECT 1 FROM profiles
    WHERE user_id = auth.uid()
      AND organization_id = p_org_id
      AND id = p_user_id
  ) THEN
    RETURN jsonb_build_object(
      'todaysTaskCount', 0, 'overdueCount', 0,
      'atRiskCount', 0, 'newThisWeek', 0
    );
  END IF;

  SELECT COUNT(*) INTO v_todays_task_count
  FROM crm_tasks
  WHERE assigned_to = p_user_id
    AND status != 'completed'
    AND due_at >= v_today_start
    AND due_at < v_today_end;

  SELECT COUNT(*) INTO v_overdue_count
  FROM crm_tasks
  WHERE assigned_to = p_user_id
    AND status != 'completed'
    AND due_at < now();

  SELECT COUNT(*) INTO v_at_risk_count
  FROM crm_records r
  JOIN crm_modules m ON m.id = r.module_id
  WHERE m.organization_id = p_org_id
    AND m.key = 'deals'
    AND r.updated_at < v_seven_days
    AND r.data->>'stage' NOT IN ('Closed Won', 'Closed Lost', 'closed_won', 'closed_lost');

  SELECT COUNT(*) INTO v_new_this_week
  FROM crm_records r
  JOIN crm_modules m ON m.id = r.module_id
  WHERE m.organization_id = p_org_id
    AND m.is_enabled = true
    AND r.created_at >= v_seven_days;

  RETURN jsonb_build_object(
    'todaysTaskCount', v_todays_task_count,
    'overdueCount', v_overdue_count,
    'atRiskCount', v_at_risk_count,
    'newThisWeek', v_new_this_week
  );
END;
$$;


--
-- Name: crm_deal_stages; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.crm_deal_stages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    name text NOT NULL,
    key text NOT NULL,
    color text DEFAULT '#6366f1'::text,
    probability integer DEFAULT 0,
    is_won boolean DEFAULT false,
    is_lost boolean DEFAULT false,
    display_order integer DEFAULT 0,
    is_active boolean DEFAULT true,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    wip_limit integer,
    organization_id uuid,
    CONSTRAINT crm_deal_stages_check CHECK ((NOT (is_won AND is_lost))),
    CONSTRAINT crm_deal_stages_probability_check CHECK (((probability >= 0) AND (probability <= 100))),
    CONSTRAINT crm_deal_stages_wip_limit_check CHECK (((wip_limit IS NULL) OR (wip_limit >= 0)))
);


--
-- Name: TABLE crm_deal_stages; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.crm_deal_stages IS 'Configurable deal pipeline stages per organization';


--
-- Name: COLUMN crm_deal_stages.probability; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.crm_deal_stages.probability IS 'Win probability percentage (0-100)';


--
-- Name: COLUMN crm_deal_stages.is_won; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.crm_deal_stages.is_won IS 'True if this is a closed-won stage';


--
-- Name: COLUMN crm_deal_stages.is_lost; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.crm_deal_stages.is_lost IS 'True if this is a closed-lost stage';


--
-- Name: COLUMN crm_deal_stages.wip_limit; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.crm_deal_stages.wip_limit IS 'Optional per-stage WIP cap. The UI surfaces a warning when the column has more active deals than this value. NULL disables the cap.';


--
-- Name: get_deal_stages(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_deal_stages(p_org_id uuid) RETURNS SETOF public.crm_deal_stages
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM profiles WHERE user_id = auth.uid() AND organization_id = p_org_id
  ) THEN
    RETURN; -- empty set, no information leakage
  END IF;

  RETURN QUERY
    SELECT * FROM crm_deal_stages
    WHERE organization_id = p_org_id AND is_active = true
    ORDER BY display_order;
END;
$$;


--
-- Name: get_declined_today(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_declined_today(p_org_id uuid) RETURNS TABLE(id uuid, member_id uuid, member_name text, member_email text, amount numeric, decline_code text, decline_category text, error_message text, payment_method text, last_four text, retry_count integer, created_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT
    t.id,
    t.member_id,
    m.first_name || ' ' || m.last_name as member_name,
    m.email as member_email,
    t.amount,
    t.decline_code,
    t.decline_category,
    t.error_message,
    pp.payment_type as payment_method,
    pp.last_four,
    t.retry_count,
    t.created_at
  FROM billing_transactions t
  LEFT JOIN members m ON m.id = t.member_id
  LEFT JOIN payment_profiles pp ON pp.id = t.payment_profile_id
  WHERE t.organization_id = p_org_id
    AND t.status = 'failed'
    AND t.created_at >= CURRENT_DATE
    AND t.created_at < CURRENT_DATE + INTERVAL '1 day'
  ORDER BY t.created_at DESC;
$$;


--
-- Name: get_default_processor(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_default_processor(p_org_id uuid) RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT id FROM payment_processors
  WHERE organization_id = p_org_id
    AND is_active = true
    AND is_default = true
  LIMIT 1;
$$;


