--
-- Name: get_executive_kpis(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_executive_kpis(p_org_id uuid, p_month date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_month       date := COALESCE(p_month, date_trunc('month', current_date)::date);
  v_prev_month  date := (v_month - interval '1 month')::date;
  v_current     record;
  v_previous    record;
  v_top         record;
  v_growth      jsonb;
  v_agencies    jsonb;
  v_franchise   jsonb;
BEGIN
  -- Current month KPIs
  SELECT * INTO v_current
  FROM executive_kpi_mv
  WHERE org_id = p_org_id AND month = v_month;

  -- Previous month for growth calc
  SELECT * INTO v_previous
  FROM executive_kpi_mv
  WHERE org_id = p_org_id AND month = v_prev_month;

  -- Top advisor
  SELECT * INTO v_top
  FROM executive_top_advisor_mv
  WHERE org_id = p_org_id AND month = v_month;

  -- Growth rates
  v_growth := jsonb_build_object(
    'commission_growth_pct',
      CASE WHEN COALESCE(v_previous.total_commission, 0) > 0
           THEN ROUND(((COALESCE(v_current.total_commission, 0) - v_previous.total_commission)
                  / v_previous.total_commission * 100)::numeric, 1)
           ELSE 0 END,
    'policy_growth_pct',
      CASE WHEN COALESCE(v_previous.total_policies, 0) > 0
           THEN ROUND(((COALESCE(v_current.total_policies, 0) - v_previous.total_policies)::numeric
                  / v_previous.total_policies * 100)::numeric, 1)
           ELSE 0 END,
    'advisor_growth_pct',
      CASE WHEN COALESCE(v_previous.total_advisors, 0) > 0
           THEN ROUND(((COALESCE(v_current.total_advisors, 0) - v_previous.total_advisors)::numeric
                  / v_previous.total_advisors * 100)::numeric, 1)
           ELSE 0 END
  );

  -- Agency breakdown (top 10 agencies by production)
  SELECT COALESCE(jsonb_agg(row_data ORDER BY total DESC), '[]'::jsonb)
  INTO v_agencies
  FROM (
    SELECT jsonb_build_object(
      'agency_id',        ag.id,
      'agency_name',      ag.name,
      'total_commission', SUM(m.total_commissions),
      'total_policies',   SUM(m.total_enrollments),
      'advisor_count',    COUNT(DISTINCT m.advisor_id)
    ) AS row_data,
    SUM(m.total_commissions) AS total
    FROM mv_advisor_monthly_performance m
    JOIN agency_users au ON au.advisor_id = m.advisor_id AND au.status = 'active'
    JOIN agencies ag ON ag.id = au.agency_id AND ag.organization_id = p_org_id AND ag.status = 'active'
    WHERE m.organization_id = p_org_id
      AND m.month = v_month
      AND m.product_type IN ('health_share', 'health_insurance')
    GROUP BY ag.id, ag.name
    ORDER BY SUM(m.total_commissions) DESC
    LIMIT 10
  ) sub;

  -- Franchise breakdown (if parent org)
  SELECT COALESCE(jsonb_agg(row_data ORDER BY total DESC), '[]'::jsonb)
  INTO v_franchise
  FROM (
    SELECT jsonb_build_object(
      'child_org_id',     k.org_id,
      'child_org_name',   o.name,
      'total_commission', k.total_commission,
      'total_policies',   k.total_policies,
      'total_advisors',   k.total_advisors
    ) AS row_data,
    k.total_commission AS total
    FROM executive_kpi_mv k
    JOIN organizations o ON o.id = k.org_id
    WHERE k.org_id IN (
      SELECT child_org_id FROM org_relationships
      WHERE parent_org_id = p_org_id AND status = 'active'
    )
    AND k.month = v_month
  ) sub;

  RETURN jsonb_build_object(
    'month', v_month,
    'revenue', jsonb_build_object(
      'total_commission',    COALESCE(v_current.total_commission, 0),
      'paid_commission',     COALESCE(v_current.paid_commission, 0),
      'pending_commission',  COALESCE(v_current.pending_commission, 0),
      'avg_per_advisor',     ROUND(COALESCE(v_current.avg_commission_per_advisor, 0)::numeric, 2)
    ),
    'production', jsonb_build_object(
      'total_policies',      COALESCE(v_current.total_policies, 0),
      'total_advisors',      COALESCE(v_current.total_advisors, 0),
      'health_share_policies',  COALESCE(v_current.health_share_policies, 0),
      'insurance_policies',     COALESCE(v_current.insurance_policies, 0)
    ),
    'growth', v_growth,
    'top_advisor', CASE WHEN v_top.top_advisor_id IS NOT NULL THEN
      jsonb_build_object(
        'advisor_id',    v_top.top_advisor_id,
        'name',          v_top.top_advisor_first_name || ' ' || v_top.top_advisor_last_name,
        'score',         v_top.top_advisor_score,
        'commissions',   v_top.top_advisor_commissions,
        'tier',          v_top.top_advisor_tier
      )
    ELSE NULL END,
    'capacity_split', jsonb_build_object(
      'health_share_commission',  COALESCE(v_current.health_share_commission, 0),
      'insurance_commission',     COALESCE(v_current.insurance_commission, 0),
      'health_share_ratio',
        CASE WHEN COALESCE(v_current.total_commission, 0) > 0
             THEN ROUND((COALESCE(v_current.health_share_commission, 0)
                    / v_current.total_commission * 100)::numeric, 1)
             ELSE 0 END,
      'insurance_ratio',
        CASE WHEN COALESCE(v_current.total_commission, 0) > 0
             THEN ROUND((COALESCE(v_current.insurance_commission, 0)
                    / v_current.total_commission * 100)::numeric, 1)
             ELSE 0 END
    ),
    'agency_breakdown', v_agencies,
    'franchise_breakdown', v_franchise
  );
END;
$$;


--
-- Name: get_franchise_analytics(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_franchise_analytics(p_parent_org_id uuid, p_months integer DEFAULT 12) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cutoff      date := (date_trunc('month', current_date) - (p_months || ' months')::interval)::date;
  v_caller_org  uuid;
  v_summary     jsonb;
  v_by_child    jsonb;
  v_by_product  jsonb;
  v_monthly     jsonb;
BEGIN
  -- Verify caller belongs to the parent org
  v_caller_org := (SELECT get_user_organization_id());
  IF v_caller_org != p_parent_org_id THEN
    RAISE EXCEPTION 'ACCESS_DENIED: caller org (%) != parent org (%)', v_caller_org, p_parent_org_id;
  END IF;

  -- Aggregated summary across ALL delegated children
  SELECT jsonb_build_object(
    'total_production',   COALESCE(sum(m.total_commissions), 0),
    'total_enrollments',  COALESCE(sum(m.total_enrollments), 0),
    'active_advisors',    count(DISTINCT m.advisor_id),
    'child_org_count',    count(DISTINCT m.organization_id),
    'paid_commissions',   COALESCE(sum(m.paid_commissions), 0),
    'pending_commissions', COALESCE(sum(m.pending_commissions), 0)
  ) INTO v_summary
  FROM mv_advisor_monthly_performance m
  WHERE m.organization_id IN (
    SELECT child_org_id FROM org_delegations
    WHERE parent_org_id = p_parent_org_id
      AND status = 'active'
      AND (expires_at IS NULL OR expires_at > now())
      AND (permissions->>'view_aggregated_analytics')::boolean = true
  )
  AND m.month >= v_cutoff;

  -- Per-child org breakdown (aggregated, no individual advisors)
  SELECT COALESCE(jsonb_agg(row_data ORDER BY total DESC), '[]'::jsonb) INTO v_by_child
  FROM (
    SELECT jsonb_build_object(
      'org_id',             m.organization_id,
      'org_name',           o.name,
      'total_commissions',  COALESCE(sum(m.total_commissions), 0),
      'total_enrollments',  COALESCE(sum(m.total_enrollments), 0),
      'active_advisors',    count(DISTINCT m.advisor_id),
      'paid_commissions',   COALESCE(sum(m.paid_commissions), 0)
    ) AS row_data,
    sum(m.total_commissions) AS total
    FROM mv_advisor_monthly_performance m
    JOIN organizations o ON o.id = m.organization_id
    WHERE m.organization_id IN (
      SELECT child_org_id FROM org_delegations
      WHERE parent_org_id = p_parent_org_id
        AND status = 'active'
        AND (expires_at IS NULL OR expires_at > now())
        AND (permissions->>'view_aggregated_analytics')::boolean = true
    )
    AND m.month >= v_cutoff
    GROUP BY m.organization_id, o.name
  ) sub;

  -- Product type breakdown (aggregated across children)
  SELECT COALESCE(jsonb_agg(row_data), '[]'::jsonb) INTO v_by_product
  FROM (
    SELECT jsonb_build_object(
      'product_type',      m.product_type,
      'total_commissions', COALESCE(sum(m.total_commissions), 0),
      'total_enrollments', COALESCE(sum(m.total_enrollments), 0)
    ) AS row_data
    FROM mv_advisor_monthly_performance m
    WHERE m.organization_id IN (
      SELECT child_org_id FROM org_delegations
      WHERE parent_org_id = p_parent_org_id
        AND status = 'active'
        AND (expires_at IS NULL OR expires_at > now())
        AND (permissions->>'view_aggregated_analytics')::boolean = true
    )
    AND m.month >= v_cutoff
    GROUP BY m.product_type
  ) sub;

  -- Monthly trend (aggregated across children)
  SELECT COALESCE(jsonb_agg(row_data ORDER BY month), '[]'::jsonb) INTO v_monthly
  FROM (
    SELECT jsonb_build_object(
      'month',             m.month,
      'total_commissions', COALESCE(sum(m.total_commissions), 0),
      'total_enrollments', COALESCE(sum(m.total_enrollments), 0),
      'active_advisors',   count(DISTINCT m.advisor_id),
      'active_orgs',       count(DISTINCT m.organization_id)
    ) AS row_data, m.month
    FROM mv_advisor_monthly_performance m
    WHERE m.organization_id IN (
      SELECT child_org_id FROM org_delegations
      WHERE parent_org_id = p_parent_org_id
        AND status = 'active'
        AND (expires_at IS NULL OR expires_at > now())
        AND (permissions->>'view_aggregated_analytics')::boolean = true
    )
    AND m.month >= v_cutoff
    GROUP BY m.month
  ) sub;

  RETURN jsonb_build_object(
    'parent_org_id', p_parent_org_id,
    'summary', COALESCE(v_summary, '{}'::jsonb),
    'by_child_org', COALESCE(v_by_child, '[]'::jsonb),
    'by_product', COALESCE(v_by_product, '[]'::jsonb),
    'monthly', COALESCE(v_monthly, '[]'::jsonb)
  );
END;
$$;


--
-- Name: get_franchise_child_analytics(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_franchise_child_analytics(p_parent_org_id uuid, p_child_org_id uuid, p_months integer DEFAULT 12) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cutoff      date := (date_trunc('month', current_date) - (p_months || ' months')::interval)::date;
  v_caller_org  uuid;
  v_can_view    boolean;
  v_can_roster  boolean;
  v_summary     jsonb;
  v_monthly     jsonb;
  v_top_advisors jsonb := '[]'::jsonb;
BEGIN
  -- Verify caller belongs to parent org
  v_caller_org := (SELECT get_user_organization_id());
  IF v_caller_org != p_parent_org_id THEN
    RAISE EXCEPTION 'ACCESS_DENIED: caller org mismatch';
  END IF;

  -- Check delegation
  v_can_view := has_delegation(p_parent_org_id, p_child_org_id, 'view_aggregated_analytics');
  IF NOT v_can_view THEN
    RAISE EXCEPTION 'NO_DELEGATION: no active analytics delegation for this child org';
  END IF;

  v_can_roster := has_delegation(p_parent_org_id, p_child_org_id, 'view_individual_advisors');

  -- Summary for this child
  SELECT jsonb_build_object(
    'total_production',   COALESCE(sum(m.total_commissions), 0),
    'total_enrollments',  COALESCE(sum(m.total_enrollments), 0),
    'active_advisors',    count(DISTINCT m.advisor_id),
    'paid_commissions',   COALESCE(sum(m.paid_commissions), 0),
    'pending_commissions', COALESCE(sum(m.pending_commissions), 0)
  ) INTO v_summary
  FROM mv_advisor_monthly_performance m
  WHERE m.organization_id = p_child_org_id
    AND m.month >= v_cutoff;

  -- Monthly trend
  SELECT COALESCE(jsonb_agg(row_data ORDER BY month), '[]'::jsonb) INTO v_monthly
  FROM (
    SELECT jsonb_build_object(
      'month',             m.month,
      'total_commissions', COALESCE(sum(m.total_commissions), 0),
      'total_enrollments', COALESCE(sum(m.total_enrollments), 0),
      'active_advisors',   count(DISTINCT m.advisor_id)
    ) AS row_data, m.month
    FROM mv_advisor_monthly_performance m
    WHERE m.organization_id = p_child_org_id
      AND m.month >= v_cutoff
    GROUP BY m.month
  ) sub;

  -- Top advisors (only if roster permission granted)
  IF v_can_roster THEN
    SELECT COALESCE(jsonb_agg(row_data ORDER BY total DESC), '[]'::jsonb) INTO v_top_advisors
    FROM (
      SELECT jsonb_build_object(
        'advisor_id',       m.advisor_id,
        'first_name',       a.first_name,
        'last_name',        a.last_name,
        'total_commissions', sum(m.total_commissions),
        'total_enrollments', sum(m.total_enrollments)
      ) AS row_data,
      sum(m.total_commissions) AS total
      FROM mv_advisor_monthly_performance m
      JOIN advisors a ON a.id = m.advisor_id
      WHERE m.organization_id = p_child_org_id
        AND m.month >= v_cutoff
      GROUP BY m.advisor_id, a.first_name, a.last_name
      ORDER BY sum(m.total_commissions) DESC
      LIMIT 10
    ) sub;
  END IF;

  RETURN jsonb_build_object(
    'child_org_id', p_child_org_id,
    'summary', COALESCE(v_summary, '{}'::jsonb),
    'monthly', COALESCE(v_monthly, '[]'::jsonb),
    'top_advisors', v_top_advisors,
    'permissions', jsonb_build_object(
      'can_view_roster', v_can_roster
    )
  );
END;
$$;


--
-- Name: get_group_demographics(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_group_demographics(p_org_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller_id uuid := auth.uid();
  v_result    jsonb;
BEGIN
  -- Validate caller is authenticated
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Validate caller belongs to the requested org
  IF NOT EXISTS (
    SELECT 1 FROM profiles
    WHERE user_id = v_caller_id
      AND organization_id = p_org_id
  ) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  SELECT jsonb_build_object(
    'memberDemographics', (SELECT public._demographics_members(p_org_id)),
    'enrollmentDemographics', (SELECT public._demographics_enrollments(p_org_id)),
    'healthUtilization', (SELECT public._demographics_health(p_org_id)),
    'agentDemographics', (SELECT public._demographics_agents(p_org_id)),
    'generatedAt', now()
  ) INTO v_result;

  RETURN v_result;
END;
$$;


--
-- Name: get_growth_metrics(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_growth_metrics(p_org_id uuid, p_advisor_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_current_month date := date_trunc('month', current_date)::date;
  v_prev_month    date := (date_trunc('month', current_date) - interval '1 month')::date;
  v_current       record;
  v_previous      record;
  v_result        jsonb;
BEGIN
  IF p_advisor_id IS NOT NULL THEN
    -- Advisor-specific growth
    SELECT
      COALESCE(sum(total_commissions), 0) AS commissions,
      COALESCE(sum(total_enrollments), 0) AS enrollments
    INTO v_current
    FROM mv_advisor_monthly_performance
    WHERE advisor_id = p_advisor_id
      AND organization_id = p_org_id
      AND month = v_current_month;

    SELECT
      COALESCE(sum(total_commissions), 0) AS commissions,
      COALESCE(sum(total_enrollments), 0) AS enrollments
    INTO v_previous
    FROM mv_advisor_monthly_performance
    WHERE advisor_id = p_advisor_id
      AND organization_id = p_org_id
      AND month = v_prev_month;
  ELSE
    -- Org-wide growth
    SELECT
      COALESCE(sum(total_commissions), 0) AS commissions,
      COALESCE(sum(total_enrollments), 0) AS enrollments
    INTO v_current
    FROM mv_org_monthly_dashboard
    WHERE organization_id = p_org_id
      AND month = v_current_month;

    SELECT
      COALESCE(sum(total_commissions), 0) AS commissions,
      COALESCE(sum(total_enrollments), 0) AS enrollments
    INTO v_previous
    FROM mv_org_monthly_dashboard
    WHERE organization_id = p_org_id
      AND month = v_prev_month;
  END IF;

  v_result := jsonb_build_object(
    'current_month', jsonb_build_object(
      'commissions', v_current.commissions,
      'enrollments', v_current.enrollments
    ),
    'previous_month', jsonb_build_object(
      'commissions', v_previous.commissions,
      'enrollments', v_previous.enrollments
    ),
    'growth_pct', jsonb_build_object(
      'commissions', CASE
        WHEN v_previous.commissions > 0
        THEN round(((v_current.commissions - v_previous.commissions) / v_previous.commissions * 100)::numeric, 1)
        ELSE 0
      END,
      'enrollments', CASE
        WHEN v_previous.enrollments > 0
        THEN round(((v_current.enrollments - v_previous.enrollments)::numeric / v_previous.enrollments * 100)::numeric, 1)
        ELSE 0
      END
    )
  );

  RETURN v_result;
END;
$$;


--
-- Name: get_invoice_generation_summary(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_invoice_generation_summary(p_organization_id uuid) RETURNS TABLE(total_generated integer, total_amount numeric, retro_count integer, retro_amount numeric, last_generation_date timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    COALESCE(SUM(j.successful_invoices), 0)::integer as total_generated,
    COALESCE(SUM(j.total_amount), 0) as total_amount,
    COUNT(CASE WHEN j.is_retro = true THEN 1 END)::integer as retro_count,
    COALESCE(SUM(CASE WHEN j.is_retro = true THEN j.total_amount ELSE 0 END), 0) as retro_amount,
    MAX(j.completed_at) as last_generation_date
  FROM invoice_generation_jobs j
  WHERE j.organization_id = p_organization_id
    AND j.status = 'completed';
END;
$$;


--
-- Name: get_leaderboard(uuid, date, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_leaderboard(p_org_id uuid, p_month date DEFAULT (date_trunc('month'::text, (CURRENT_DATE)::timestamp with time zone))::date, p_limit integer DEFAULT 10, p_capacity_scope text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(row_data ORDER BY rank_position), '[]'::jsonb) INTO v_result
  FROM (
    SELECT jsonb_build_object(
      'advisor_id',         r.advisor_id,
      'first_name',         a.first_name,
      'last_name',          a.last_name,
      'email',              a.email,
      'commission_tier',    a.commission_tier,
      'capacities',         a.capacities,
      'rank_position',      r.rank_position,
      'tier',               r.tier,
      'capacity_scope',     r.capacity_scope,
      'production_score',   r.production_score,
      'total_commissions',  r.total_commissions,
      'total_enrollments',  r.total_enrollments,
      'downline_production', r.downline_production,
      'growth_rate_pct',    r.growth_rate_pct,
      'rank_change',        r.rank_change,
      'streak_months',      r.streak_months,
      'next_tier_gap',      r.next_tier_gap
    ) AS row_data,
    r.rank_position
    FROM advisor_rankings r
    JOIN advisors a ON a.id = r.advisor_id
    WHERE r.organization_id = p_org_id
      AND r.period_month = p_month
      AND r.capacity_scope IS NOT DISTINCT FROM p_capacity_scope
    ORDER BY r.rank_position
    LIMIT p_limit
  ) sub;

  RETURN jsonb_build_object(
    'leaderboard', v_result,
    'month', p_month,
    'capacity_scope', p_capacity_scope,
    'total_ranked', (
      SELECT count(*) FROM advisor_rankings
      WHERE organization_id = p_org_id
        AND period_month = p_month
        AND capacity_scope IS NOT DISTINCT FROM p_capacity_scope
    )
  );
END;
$$;


--
-- Name: get_least_busy_agent(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_least_busy_agent(org_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_agent_id uuid;
  v_effective_org uuid;
BEGIN
  v_effective_org := COALESCE(org_id, (SELECT organization_id FROM profiles WHERE user_id = auth.uid() LIMIT 1));
  IF v_effective_org IS NULL THEN RETURN NULL; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM profiles WHERE user_id = auth.uid() AND organization_id = v_effective_org
  ) THEN RETURN NULL; END IF;
  SELECT p.id INTO v_agent_id
  FROM profiles p
  WHERE p.organization_id = v_effective_org
    AND p.role IN ('agent', 'it', 'staff', 'admin')
  ORDER BY (
    SELECT COUNT(*)
    FROM tickets t
    WHERE t.assigned_to_profile_id = p.id
      AND t.status NOT IN ('closed', 'resolved')
  ) ASC
  LIMIT 1;
  RETURN v_agent_id;
EXCEPTION WHEN undefined_column THEN
  RETURN NULL;
END;
$$;


--
-- Name: get_linked_records(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_linked_records(p_record_id uuid) RETURNS TABLE(link_id uuid, link_type text, is_primary boolean, direction text, record_id uuid, record_title text, record_module_key text, record_module_name text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM crm_records r
    JOIN profiles p ON p.organization_id = r.organization_id
    WHERE r.id = p_record_id AND p.user_id = auth.uid()
  ) THEN
    RETURN; -- empty set
  END IF;

  RETURN QUERY
    SELECT
      l.id AS link_id,
      l.link_type,
      l.is_primary,
      'outbound'::text AS direction,
      r2.id AS record_id,
      r2.title AS record_title,
      m.key AS record_module_key,
      m.name AS record_module_name,
      l.created_at
    FROM crm_record_links l
    JOIN crm_records r2 ON l.target_record_id = r2.id
    JOIN crm_modules m ON r2.module_id = m.id
    WHERE l.source_record_id = p_record_id

    UNION ALL

    SELECT
      l.id AS link_id,
      l.link_type,
      l.is_primary,
      'inbound'::text AS direction,
      r2.id AS record_id,
      r2.title AS record_title,
      m.key AS record_module_key,
      m.name AS record_module_name,
      l.created_at
    FROM crm_record_links l
    JOIN crm_records r2 ON l.source_record_id = r2.id
    JOIN crm_modules m ON r2.module_id = m.id
    WHERE l.target_record_id = p_record_id

    ORDER BY created_at DESC;
END;
$$;


--
-- Name: get_member_default_payment_profile(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_member_default_payment_profile(p_member_id uuid) RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT id FROM payment_profiles
  WHERE member_id = p_member_id
    AND is_active = true
    AND is_default = true
  LIMIT 1;
$$;


--
-- Name: get_members_by_advisor(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_members_by_advisor(p_org_id uuid, p_limit integer DEFAULT 20) RETURNS TABLE(advisor_name text, record_count bigint, healthshare_count bigint, insurance_count bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT
    COALESCE(NULLIF(TRIM(r.normalized_advisor_name), ''), 'Unassigned') AS advisor_name,
    count(*) AS record_count,
    count(*) FILTER (WHERE r.market_type = 'healthshare') AS healthshare_count,
    count(*) FILTER (WHERE r.market_type = 'traditional_insurance') AS insurance_count
  FROM crm_records r
  WHERE r.organization_id = p_org_id
    AND r.record_type = 'individual'
  GROUP BY 1
  ORDER BY record_count DESC
  LIMIT p_limit;
$$;


--
-- Name: get_members_by_age_range(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_members_by_age_range(p_org_id uuid) RETURNS TABLE(age_bucket text, record_count bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT
    COALESCE(r.age_range, 'Unknown') AS age_bucket,
    count(*) AS record_count
  FROM crm_records r
  WHERE r.organization_id = p_org_id
    AND r.record_type = 'individual'
  GROUP BY 1
  ORDER BY
    CASE COALESCE(r.age_range, 'Unknown')
      WHEN '0-17' THEN 1
      WHEN '18-25' THEN 2
      WHEN '26-34' THEN 3
      WHEN '35-44' THEN 4
      WHEN '45-54' THEN 5
      WHEN '55-64' THEN 6
      WHEN '65+' THEN 7
      ELSE 8
    END;
$$;


--
-- Name: get_members_by_carrier(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_members_by_carrier(p_org_id uuid, p_limit integer DEFAULT 20) RETURNS TABLE(carrier_name text, carrier_type text, record_count bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT
    COALESCE(ic.carrier_name, 'No Carrier Assigned') AS carrier_name,
    COALESCE(ic.carrier_type, 'unknown') AS carrier_type,
    count(*) AS record_count
  FROM crm_records r
  LEFT JOIN insurance_carriers ic ON ic.id = r.carrier_id
  WHERE r.organization_id = p_org_id
    AND r.record_type = 'individual'
  GROUP BY ic.carrier_name, ic.carrier_type
  ORDER BY record_count DESC
  LIMIT p_limit;
$$;


--
-- Name: get_members_by_status(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_members_by_status(p_org_id uuid) RETURNS TABLE(member_status text, record_count bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT
    COALESCE(NULLIF(TRIM(r.status), ''), 'No Status') AS member_status,
    count(*) AS record_count
  FROM crm_records r
  WHERE r.organization_id = p_org_id
    AND r.record_type = 'individual'
  GROUP BY 1
  ORDER BY record_count DESC;
$$;


--
-- Name: crm_blueprints; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.crm_blueprints (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    module_id uuid NOT NULL,
    name text NOT NULL,
    description text,
    is_enabled boolean DEFAULT true,
    is_default boolean DEFAULT false,
    stages jsonb DEFAULT '[]'::jsonb NOT NULL,
    transitions jsonb DEFAULT '[]'::jsonb NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    organization_id uuid
);


--
-- Name: TABLE crm_blueprints; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.crm_blueprints IS 'Blueprint definitions for stage gating and transitions';


--
-- Name: COLUMN crm_blueprints.stages; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.crm_blueprints.stages IS 'JSON array: [{key, label, order, color?}]';


--
-- Name: COLUMN crm_blueprints.transitions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.crm_blueprints.transitions IS 'JSON array: [{from, to, required_fields, actions, requires_approval, require_reason}]';


--
-- Name: get_module_blueprint(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_module_blueprint(p_module_id uuid) RETURNS public.crm_blueprints
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT * FROM crm_blueprints 
  WHERE module_id = p_module_id 
    AND is_enabled = true
    AND is_default = true
  LIMIT 1;
$$;


--
-- Name: get_module_stats(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_module_stats(p_org_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
  v_one_week_ago timestamptz := now() - interval '7 days';
BEGIN
  -- Validate caller belongs to org
  IF NOT EXISTS (
    SELECT 1 FROM profiles WHERE user_id = auth.uid() AND organization_id = p_org_id
  ) THEN
    RETURN '[]'::jsonb;
  END IF;

  WITH module_counts AS (
    SELECT
      m.key AS module_key,
      COALESCE(m.name_plural, m.name || 's') AS module_name,
      COUNT(r.id) AS total_records,
      COUNT(r.id) FILTER (WHERE r.created_at >= v_one_week_ago) AS created_this_week
    FROM crm_modules m
    LEFT JOIN crm_records r ON r.module_id = m.id
    WHERE m.organization_id = p_org_id AND m.is_enabled = true
    GROUP BY m.key, m.name, m.name_plural
  ),
  legacy_leads AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE created_at >= v_one_week_ago) AS this_week
    FROM leads
    WHERE organization_id = p_org_id
  ),
  legacy_members AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE created_at >= v_one_week_ago) AS this_week
    FROM members
    WHERE organization_id = p_org_id
  )
  SELECT jsonb_agg(
    jsonb_build_object(
      'moduleKey', mc.module_key,
      'moduleName', mc.module_name,
      'totalRecords', mc.total_records +
        CASE mc.module_key
          WHEN 'leads' THEN COALESCE((SELECT total FROM legacy_leads), 0)
          WHEN 'contacts' THEN COALESCE((SELECT total FROM legacy_members), 0)
          ELSE 0
        END,
      'createdThisWeek', mc.created_this_week +
        CASE mc.module_key
          WHEN 'leads' THEN COALESCE((SELECT this_week FROM legacy_leads), 0)
          WHEN 'contacts' THEN COALESCE((SELECT this_week FROM legacy_members), 0)
          ELSE 0
        END
    )
  ) INTO v_result
  FROM module_counts mc;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;


--
-- Name: get_my_advisor_id(); Type: FUNCTION; Schema: public; Owner: -
