--
-- Name: agencies; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.agencies (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    owner_advisor_id uuid NOT NULL,
    name text NOT NULL,
    code text,
    status text DEFAULT 'active'::text NOT NULL,
    logo_url text,
    primary_color text DEFAULT '#1e40af'::text,
    secondary_color text DEFAULT '#3b82f6'::text,
    header_bg_color text DEFAULT '#1e3a8a'::text,
    header_text_color text DEFAULT '#ffffff'::text,
    company_name text,
    website_url text,
    phone text,
    email text,
    address jsonb DEFAULT '{}'::jsonb,
    settings jsonb DEFAULT '{}'::jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT agencies_status_check CHECK ((status = ANY (ARRAY['active'::text, 'inactive'::text, 'suspended'::text])))
);


--
-- Name: get_my_agencies(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_agencies() RETURNS SETOF public.agencies
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  RETURN QUERY
  SELECT ag.*
  FROM agencies ag
  JOIN agency_users au ON au.agency_id = ag.id
  WHERE au.advisor_id = (SELECT get_user_advisor_id())
    AND au.status = 'active'
    AND ag.status = 'active';
END;
$$;


--
-- Name: get_my_ranking(uuid, uuid, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_ranking(p_advisor_id uuid, p_org_id uuid, p_month date DEFAULT (date_trunc('month'::text, (CURRENT_DATE)::timestamp with time zone))::date, p_capacity_scope text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_ranking record;
  v_total   int;
BEGIN
  SELECT * INTO v_ranking
  FROM advisor_rankings
  WHERE advisor_id = p_advisor_id
    AND organization_id = p_org_id
    AND period_month = p_month
    AND capacity_scope IS NOT DISTINCT FROM p_capacity_scope;

  SELECT count(*) INTO v_total
  FROM advisor_rankings
  WHERE organization_id = p_org_id
    AND period_month = p_month
    AND capacity_scope IS NOT DISTINCT FROM p_capacity_scope;

  IF v_ranking IS NULL THEN
    RETURN jsonb_build_object('ranked', false, 'total_ranked', v_total);
  END IF;

  RETURN jsonb_build_object(
    'ranked',              true,
    'rank_position',       v_ranking.rank_position,
    'total_ranked',        v_total,
    'tier',                v_ranking.tier,
    'capacity_scope',      v_ranking.capacity_scope,
    'production_score',    v_ranking.production_score,
    'total_commissions',   v_ranking.total_commissions,
    'total_enrollments',   v_ranking.total_enrollments,
    'downline_production', v_ranking.downline_production,
    'growth_rate_pct',     v_ranking.growth_rate_pct,
    'rank_change',         v_ranking.rank_change,
    'streak_months',       v_ranking.streak_months,
    'next_tier_gap',       v_ranking.next_tier_gap,
    'commission_score',    v_ranking.commission_score,
    'enrollment_score',    v_ranking.enrollment_score,
    'downline_score',      v_ranking.downline_score,
    'growth_score',        v_ranking.growth_score
  );
END;
$$;


--
-- Name: get_nearby_locations(text, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_nearby_locations(p_zip_code text, p_service_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 20) RETURNS TABLE(location_id uuid, name text, location_type text, address text, city text, state text, zip text, phone text, latitude numeric, longitude numeric, telehealth_capable boolean, accepting_new_patients boolean, services jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT DISTINCT
    hl.id AS location_id,
    hl.name,
    hl.location_type,
    hl.address_line1 AS address,
    hl.city,
    hl.state,
    hl.zip,
    hl.phone,
    hl.latitude,
    hl.longitude,
    hl.telehealth_capable,
    hl.accepting_new_patients,
    (
      SELECT jsonb_agg(jsonb_build_object(
        'service_id', hs2.id,
        'service_name', hs2.service_name,
        'service_category', hs2.service_category
      ))
      FROM healthcare_location_services hls2
      JOIN healthcare_services hs2 ON hs2.id = hls2.service_id AND hs2.is_active = true
      WHERE hls2.location_id = hl.id
    ) AS services
  FROM healthcare_locations hl
  INNER JOIN healthcare_service_areas sa ON sa.location_id = hl.id
  WHERE sa.zip_code = p_zip_code
    AND sa.is_active = true
    AND hl.is_active = true
    AND (sa.end_date IS NULL OR sa.end_date > CURRENT_DATE)
    AND (p_service_id IS NULL OR sa.service_id = p_service_id)
  ORDER BY hl.name
  LIMIT p_limit;
END;
$$;


--
-- Name: FUNCTION get_nearby_locations(p_zip_code text, p_service_id uuid, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_nearby_locations(p_zip_code text, p_service_id uuid, p_limit integer) IS 'Find healthcare locations serving a given ZIP code, optionally filtered by service';


--
-- Name: get_network_coverage_score(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_network_coverage_score(p_network_id uuid, p_zip_code text DEFAULT NULL::text, p_state text DEFAULT NULL::text) RETURNS TABLE(network_id uuid, network_name text, network_type text, zip_code text, total_providers bigint, preferred_providers bigint, specialty_coverage jsonb, coverage_score numeric, coverage_grade text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    pn.id                AS network_id,
    pn.network_name,
    pn.network_type,
    ncz.zip_code,
    ncz.provider_count::bigint  AS total_providers,
    ncz.preferred_count::bigint AS preferred_providers,
    ncz.specialty_coverage,
    ncz.coverage_score,
    CASE
      WHEN ncz.coverage_score >= 90 THEN 'A'
      WHEN ncz.coverage_score >= 70 THEN 'B'
      WHEN ncz.coverage_score >= 50 THEN 'C'
      WHEN ncz.coverage_score >= 30 THEN 'D'
      ELSE 'F'
    END                  AS coverage_grade
  FROM provider_networks pn
  INNER JOIN network_coverage_zips ncz ON ncz.network_id = pn.id
  WHERE pn.id = p_network_id
    AND (p_zip_code IS NULL OR ncz.zip_code = p_zip_code)
    AND (p_state IS NULL OR ncz.state = p_state)
  ORDER BY ncz.coverage_score DESC;
END;
$$;


--
-- Name: get_next_round_robin_agent(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_next_round_robin_agent(p_rule_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_config jsonb;
  v_users uuid[];
  v_cursor int;
  v_next_agent uuid;
BEGIN
  -- Get rule config
  SELECT config INTO v_config
  FROM crm_assignment_rules
  WHERE id = p_rule_id AND is_enabled = true;

  IF v_config IS NULL THEN
    RETURN NULL;
  END IF;

  -- Extract users and cursor
  v_users := ARRAY(SELECT jsonb_array_elements_text(v_config->'users')::uuid);
  v_cursor := COALESCE((v_config->>'cursor')::int, 0);

  IF array_length(v_users, 1) IS NULL OR array_length(v_users, 1) = 0 THEN
    RETURN NULL;
  END IF;

  -- Get next agent
  v_next_agent := v_users[(v_cursor % array_length(v_users, 1)) + 1];

  -- Update cursor
  UPDATE crm_assignment_rules
  SET config = config || jsonb_build_object('cursor', (v_cursor + 1) % array_length(v_users, 1))
  WHERE id = p_rule_id;

  RETURN v_next_agent;
END;
$$;


--
-- Name: get_onedrive_pending_files(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_onedrive_pending_files(p_user_id uuid) RETURNS TABLE(file_id uuid, filename text, storage_path text, byte_size bigint, mime_type text, sha256 text, onedrive_id text, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    f.id as file_id,
    f.filename,
    f.storage_path,
    f.byte_size,
    f.mime_type,
    f.sha256,
    f.onedrive_id,
    f.created_at,
    f.updated_at
  FROM public.files f
  WHERE f.owner_id = p_user_id
    AND f.onedrive_sync_status IN ('not_synced', 'error')
  ORDER BY f.created_at DESC
  LIMIT 100;
END;
$$;


--
-- Name: get_org_by_slug(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_org_by_slug(p_slug text) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT o.id FROM organizations o
  JOIN profiles p ON p.organization_id = o.id
  WHERE o.slug = p_slug AND p.user_id = auth.uid()
  LIMIT 1;
$$;


--
-- Name: get_org_dashboard_analytics(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_org_dashboard_analytics(p_org_id uuid, p_months integer DEFAULT 12) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_result  jsonb;
  v_summary jsonb;
  v_monthly jsonb;
  v_by_type jsonb;
  v_cutoff  date := (date_trunc('month', current_date) - (p_months || ' months')::interval)::date;
BEGIN
  -- Overall summary
  SELECT jsonb_build_object(
    'total_commissions',  COALESCE(sum(total_commissions), 0),
    'paid_amount',        COALESCE(sum(paid_amount), 0),
    'pending_amount',     COALESCE(sum(pending_amount), 0),
    'approved_amount',    COALESCE(sum(approved_amount), 0),
    'total_enrollments',  COALESCE(sum(total_enrollments), 0),
    'active_advisors',    COALESCE(sum(active_advisors), 0),
    'avg_commission',     COALESCE(avg(NULLIF(avg_commission, 0)), 0)
  ) INTO v_summary
  FROM mv_org_monthly_dashboard
  WHERE organization_id = p_org_id
    AND month >= v_cutoff;

  -- Monthly trend
  SELECT COALESCE(jsonb_agg(row_data ORDER BY month), '[]'::jsonb) INTO v_monthly
  FROM (
    SELECT jsonb_build_object(
      'month',             month,
      'total_commissions', COALESCE(sum(total_commissions), 0),
      'total_enrollments', COALESCE(sum(total_enrollments), 0),
      'active_advisors',   COALESCE(sum(active_advisors), 0),
      'paid_amount',       COALESCE(sum(paid_amount), 0)
    ) AS row_data, month
    FROM mv_org_monthly_dashboard
    WHERE organization_id = p_org_id
      AND month >= v_cutoff
    GROUP BY month
  ) sub;

  -- Breakdown by product type
  SELECT COALESCE(jsonb_agg(row_data), '[]'::jsonb) INTO v_by_type
  FROM (
    SELECT jsonb_build_object(
      'product_type',      product_type,
      'total_commissions', COALESCE(sum(total_commissions), 0),
      'total_enrollments', COALESCE(sum(total_enrollments), 0),
      'commission_count',  COALESCE(sum(commission_count), 0)
    ) AS row_data
    FROM mv_org_monthly_dashboard
    WHERE organization_id = p_org_id
      AND month >= v_cutoff
    GROUP BY product_type
  ) sub;

  v_result := jsonb_build_object(
    'summary',    COALESCE(v_summary, '{}'::jsonb),
    'monthly',    COALESCE(v_monthly, '[]'::jsonb),
    'by_product', COALESCE(v_by_type, '[]'::jsonb)
  );

  RETURN v_result;
END;
$$;


--
-- Name: get_parent_org_ids(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_parent_org_ids(p_child_org_id uuid) RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT parent_org_id
  FROM org_relationships
  WHERE child_org_id = p_child_org_id
    AND status = 'active';
$$;


--
-- Name: get_payables_summary(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_payables_summary(p_organization_id uuid, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date) RETURNS TABLE(total_pending numeric, total_approved numeric, total_paid numeric, total_overdue numeric, count_pending integer, count_approved integer, count_paid integer, count_overdue integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    COALESCE(SUM(CASE WHEN status = 'pending' THEN amount ELSE 0 END), 0) as total_pending,
    COALESCE(SUM(CASE WHEN status = 'approved' THEN amount ELSE 0 END), 0) as total_approved,
    COALESCE(SUM(CASE WHEN status = 'paid' THEN amount ELSE 0 END), 0) as total_paid,
    COALESCE(SUM(CASE WHEN status IN ('pending', 'approved') AND due_date < CURRENT_DATE THEN amount ELSE 0 END), 0) as total_overdue,
    COUNT(CASE WHEN status = 'pending' THEN 1 END)::INTEGER as count_pending,
    COUNT(CASE WHEN status = 'approved' THEN 1 END)::INTEGER as count_approved,
    COUNT(CASE WHEN status = 'paid' THEN 1 END)::INTEGER as count_paid,
    COUNT(CASE WHEN status IN ('pending', 'approved') AND due_date < CURRENT_DATE THEN 1 END)::INTEGER as count_overdue
  FROM payables
  WHERE organization_id = p_organization_id
    AND (p_start_date IS NULL OR created_at >= p_start_date)
    AND (p_end_date IS NULL OR created_at <= p_end_date);
END;
$$;


--
-- Name: get_payout_compliance_config(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_payout_compliance_config(p_org_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_settings jsonb;
BEGIN
  SELECT COALESCE(settings->'payout_compliance', '{}'::jsonb)
  INTO v_settings
  FROM organizations
  WHERE id = p_org_id;

  -- Apply defaults
  RETURN jsonb_build_object(
    -- Amount above which creator cannot self-approve
    'self_approve_threshold', COALESCE((v_settings->>'self_approve_threshold')::numeric, 5000),
    -- Amount above which 2-person approval is required
    'dual_approve_threshold', COALESCE((v_settings->>'dual_approve_threshold')::numeric, 25000),
    -- Max single payout amount (hard cap)
    'max_single_payout', COALESCE((v_settings->>'max_single_payout')::numeric, 100000),
    -- Spike detection: flag if payout is N× the advisor's 3-month average
    'spike_multiplier', COALESCE((v_settings->>'spike_multiplier')::numeric, 3.0),
    -- Whether export requires logging
    'log_exports', COALESCE((v_settings->>'log_exports')::boolean, true)
  );
END;
$$;


--
-- Name: get_pending_approvals_count(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_pending_approvals_count(p_user_id uuid) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_profile_id uuid;
  v_crm_role text;
  v_count int;
BEGIN
  -- Get profile info
  SELECT id, crm_role INTO v_profile_id, v_crm_role
  FROM profiles 
  WHERE user_id = p_user_id 
  LIMIT 1;
  
  IF v_profile_id IS NULL THEN
    RETURN 0;
  END IF;
  
  -- Count pending approvals where user is an approver
  SELECT COUNT(*) INTO v_count
  FROM crm_approvals a
  JOIN crm_approval_processes p ON a.process_id = p.id
  WHERE a.status = 'pending'
    AND (
      -- User is explicitly in the current step
      (p.steps->a.current_step->>'type' = 'user' AND p.steps->a.current_step->>'value' = v_profile_id::text)
      OR
      -- User's role matches the current step
      (p.steps->a.current_step->>'type' = 'role' AND p.steps->a.current_step->>'value' = v_crm_role)
    );
  
  RETURN v_count;
END;
$$;


