CREATE TABLE public.integration_jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    job_type text NOT NULL,
    payload jsonb NOT NULL,
    run_at timestamp with time zone DEFAULT now() NOT NULL,
    priority integer DEFAULT 0,
    status text DEFAULT 'pending'::text NOT NULL,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    attempts integer DEFAULT 0,
    max_attempts integer DEFAULT 3,
    last_error text,
    next_retry_at timestamp with time zone,
    source_event_id uuid,
    source_rule_id uuid,
    idempotency_key text,
    metadata jsonb DEFAULT '{}'::jsonb,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    organization_id uuid
);


--
-- Name: TABLE integration_jobs; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.integration_jobs IS 'Scheduled and queued jobs for automation';


--
-- Name: get_pending_jobs(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_pending_jobs(p_limit integer DEFAULT 100) RETURNS SETOF public.integration_jobs
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  UPDATE integration_jobs
  SET status = 'running', started_at = now(), attempts = attempts + 1
  WHERE id IN (
    SELECT id FROM integration_jobs
    WHERE status = 'pending'
      AND run_at <= now()
    ORDER BY priority DESC, run_at ASC
    LIMIT p_limit
    FOR UPDATE SKIP LOCKED
  )
  RETURNING *;
END;
$$;


--
-- Name: get_pending_scheduler_jobs(integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_pending_scheduler_jobs(p_limit integer DEFAULT 100, p_job_types text[] DEFAULT NULL::text[]) RETURNS TABLE(id uuid, org_id uuid, job_type text, entity_type text, entity_id uuid, record_id uuid, run_at timestamp with time zone, attempts integer, max_attempts integer, payload jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    j.id,
    j.organization_id,
    j.job_type,
    j.entity_type,
    j.entity_id,
    j.record_id,
    j.run_at,
    j.attempts,
    j.max_attempts,
    j.payload
  FROM crm_scheduler_jobs j
  WHERE j.status = 'pending'
    AND j.run_at <= now()
    AND (p_job_types IS NULL OR j.job_type = ANY(p_job_types))
  ORDER BY j.run_at ASC
  LIMIT p_limit
  FOR UPDATE SKIP LOCKED;
END;
$$;


--
-- Name: get_product_features(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_product_features(p_plan_id uuid) RETURNS TABLE(feature_id uuid, name text, description text, category text, icon text, is_included boolean, custom_value text, custom_description text, is_highlighted boolean, sort_order integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT
    f.id as feature_id,
    f.name,
    COALESCE(m.custom_description, f.description) as description,
    f.category,
    f.icon,
    COALESCE(m.is_included, true) as is_included,
    m.custom_value,
    m.custom_description,
    f.is_highlighted,
    COALESCE(m.sort_order, f.sort_order) as sort_order
  FROM product_features_library f
  JOIN product_feature_mappings m ON m.feature_id = f.id
  WHERE m.plan_id = p_plan_id
  ORDER BY COALESCE(m.sort_order, f.sort_order);
$$;


--
-- Name: get_product_price(uuid, uuid, integer, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_product_price(p_product_id uuid, p_iua_id uuid, p_age integer, p_benefit_type_id uuid, p_is_tobacco_user boolean DEFAULT false) RETURNS numeric
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_age_bracket_id uuid;
  v_base_price numeric;
  v_tobacco_surcharge numeric;
  v_tobacco_percent numeric;
BEGIN
  SELECT id INTO v_age_bracket_id
  FROM product_age_brackets
  WHERE product_id = p_product_id
    AND p_age >= min_age
    AND p_age <= max_age
    AND COALESCE(is_active, true) = true
  LIMIT 1;

  IF v_age_bracket_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT price, COALESCE(tobacco_surcharge, 0), COALESCE(tobacco_surcharge_percent, 0)
  INTO v_base_price, v_tobacco_surcharge, v_tobacco_percent
  FROM product_pricing_matrix
  WHERE product_id = p_product_id
    AND iua_id = p_iua_id
    AND age_bracket_id = v_age_bracket_id
    AND benefit_type_id = p_benefit_type_id
    AND COALESCE(effective_date, CURRENT_DATE) <= CURRENT_DATE
    AND (end_date IS NULL OR end_date > CURRENT_DATE)
  ORDER BY effective_date DESC NULLS LAST
  LIMIT 1;

  IF v_base_price IS NULL THEN
    RETURN NULL;
  END IF;

  IF p_is_tobacco_user THEN
    IF v_tobacco_percent > 0 THEN
      v_base_price := v_base_price * (1 + v_tobacco_percent / 100);
    ELSE
      v_base_price := v_base_price + v_tobacco_surcharge;
    END IF;
  END IF;

  RETURN v_base_price;
END;
$$;


--
-- Name: get_record_counts_by_advisor(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_record_counts_by_advisor(p_module_id uuid, p_advisor_ids uuid[]) RETURNS TABLE(advisor_id uuid, record_count bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT
    r.canonical_advisor_id AS advisor_id,
    COUNT(r.id)            AS record_count
  FROM crm_records r
  WHERE r.module_id = p_module_id
    AND r.canonical_advisor_id = ANY(p_advisor_ids)
  GROUP BY r.canonical_advisor_id;
$$;


--
-- Name: get_record_stage_history(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_record_stage_history(p_record_id uuid) RETURNS TABLE(id uuid, from_stage text, to_stage text, duration_seconds integer, changed_by uuid, changed_by_name text, reason text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM crm_records r
    JOIN profiles p ON p.organization_id = r.organization_id
    WHERE r.id = p_record_id AND p.user_id = auth.uid()
  ) THEN
    RETURN; -- empty set
  END IF;

  RETURN QUERY
    SELECT
      h.id,
      h.from_stage,
      h.to_stage,
      h.duration_seconds,
      h.changed_by,
      p.full_name AS changed_by_name,
      h.reason,
      h.created_at
    FROM crm_deal_stage_history h
    LEFT JOIN profiles p ON h.changed_by = p.id
    WHERE h.record_id = p_record_id
    ORDER BY h.created_at DESC;
END;
$$;


--
-- Name: get_revenue_share_rules(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_revenue_share_rules(p_parent_org_id uuid, p_child_org_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id',             rs.id,
      'percentage',     rs.percentage,
      'applies_to',     rs.applies_to,
      'capacity_scope', rs.capacity_scope,
      'effective_from', rs.effective_from,
      'effective_to',   rs.effective_to
    ) ORDER BY rs.applies_to, rs.capacity_scope
  ), '[]'::jsonb)
  FROM franchise_revenue_shares rs
  WHERE rs.parent_org_id = p_parent_org_id
    AND rs.child_org_id = p_child_org_id
    AND rs.status = 'active'
    AND rs.effective_from <= CURRENT_DATE
    AND (rs.effective_to IS NULL OR rs.effective_to >= CURRENT_DATE);
$$;


--
-- Name: get_score_config(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_score_config(p_org_id uuid, p_capacity_scope text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_config record;
BEGIN
  -- Try exact match first (capacity-specific config)
  SELECT * INTO v_config
  FROM advisor_score_config
  WHERE organization_id = p_org_id
    AND (
      (p_capacity_scope IS NULL AND capacity_scope IS NULL)
      OR capacity_scope = p_capacity_scope
    )
  LIMIT 1;

  -- Fallback to org default (capacity_scope IS NULL)
  IF v_config IS NULL AND p_capacity_scope IS NOT NULL THEN
    SELECT * INTO v_config
    FROM advisor_score_config
    WHERE organization_id = p_org_id
      AND capacity_scope IS NULL
    LIMIT 1;
  END IF;

  -- Return config or defaults
  RETURN jsonb_build_object(
    'commission_weight', COALESCE(v_config.commission_weight, 1.0),
    'enrollment_weight', COALESCE(v_config.enrollment_weight, 50.0),
    'downline_weight',   COALESCE(v_config.downline_weight, 0.3),
    'growth_weight',     COALESCE(v_config.growth_weight, 200.0),
    'tier_bronze_max',   COALESCE(v_config.tier_bronze_max, 500),
    'tier_silver_max',   COALESCE(v_config.tier_silver_max, 2000),
    'tier_gold_max',     COALESCE(v_config.tier_gold_max, 5000),
    'tier_platinum_max', COALESCE(v_config.tier_platinum_max, 15000)
  );
END;
$$;


--
-- Name: get_sla_compliance_percentage(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_sla_compliance_percentage(p_start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_date timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(total_tickets bigint, first_response_met bigint, first_response_percentage numeric, resolution_met bigint, resolution_percentage numeric, overall_met bigint, overall_percentage numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    COUNT(*)::bigint AS total_tickets,
    COUNT(*) FILTER (WHERE sm.first_response_met = true)::bigint AS first_response_met,
    ROUND(COUNT(*) FILTER (WHERE sm.first_response_met = true)::numeric / NULLIF(COUNT(*)::numeric, 0) * 100, 2) AS first_response_percentage,
    COUNT(*) FILTER (WHERE sm.resolution_met = true)::bigint AS resolution_met,
    ROUND(COUNT(*) FILTER (WHERE sm.resolution_met = true)::numeric / NULLIF(COUNT(*)::numeric, 0) * 100, 2) AS resolution_percentage,
    COUNT(*) FILTER (WHERE sm.overall_breach = false AND sm.sla_status = 'met')::bigint AS overall_met,
    ROUND(COUNT(*) FILTER (WHERE sm.overall_breach = false AND sm.sla_status = 'met')::numeric / NULLIF(COUNT(*)::numeric, 0) * 100, 2) AS overall_percentage
  FROM public.sla_metrics sm
  WHERE (p_start_date IS NULL OR sm.ticket_created_at >= p_start_date)
    AND (p_end_date IS NULL OR sm.ticket_created_at <= p_end_date);
END;
$$;


--
-- Name: crm_validation_rules; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.crm_validation_rules (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    module_id uuid NOT NULL,
    name text NOT NULL,
    description text,
    rule_type text NOT NULL,
    target_field text NOT NULL,
    conditions jsonb DEFAULT '{"logic": "AND", "conditions": []}'::jsonb NOT NULL,
    config jsonb DEFAULT '{}'::jsonb NOT NULL,
    error_message text DEFAULT 'Validation failed'::text NOT NULL,
    applies_on text[] DEFAULT ARRAY['create'::text, 'update'::text, 'stage_change'::text] NOT NULL,
    stage_triggers jsonb,
    priority integer DEFAULT 100,
    is_enabled boolean DEFAULT true,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    organization_id uuid,
    CONSTRAINT crm_validation_rules_rule_type_check CHECK ((rule_type = ANY (ARRAY['required_if'::text, 'format'::text, 'range'::text, 'comparison'::text, 'unique'::text, 'custom'::text])))
);


--
-- Name: TABLE crm_validation_rules; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.crm_validation_rules IS 'Configurable field-level and cross-field validation rules';


--
-- Name: COLUMN crm_validation_rules.rule_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.crm_validation_rules.rule_type IS 'Type: required_if, format, range, comparison, unique, custom';


--
-- Name: COLUMN crm_validation_rules.target_field; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.crm_validation_rules.target_field IS 'Field key being validated';


--
-- Name: COLUMN crm_validation_rules.conditions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.crm_validation_rules.conditions IS 'JSONB conditions determining when rule applies';


--
-- Name: COLUMN crm_validation_rules.config; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.crm_validation_rules.config IS 'Rule-specific config: pattern, min, max, compare_field, etc.';


--
-- Name: COLUMN crm_validation_rules.applies_on; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.crm_validation_rules.applies_on IS 'Triggers: create, update, stage_change';


--
-- Name: COLUMN crm_validation_rules.stage_triggers; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.crm_validation_rules.stage_triggers IS 'Optional: {from_stages: [], to_stages: []} for stage-specific rules';


--
-- Name: get_stage_validation_rules(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_stage_validation_rules(p_module_id uuid, p_from_stage text, p_to_stage text) RETURNS SETOF public.crm_validation_rules
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT * FROM crm_validation_rules
  WHERE module_id = p_module_id
    AND is_enabled = true
    AND 'stage_change' = ANY(applies_on)
    AND (
      -- No stage triggers = applies to all stage changes
      stage_triggers IS NULL
      OR
      -- From stage matches (or empty from_stages = any)
      (
        (stage_triggers->>'from_stages' IS NULL OR stage_triggers->'from_stages' = '[]'::jsonb OR 
         p_from_stage = ANY(SELECT jsonb_array_elements_text(stage_triggers->'from_stages')))
        AND
        (stage_triggers->>'to_stages' IS NULL OR stage_triggers->'to_stages' = '[]'::jsonb OR 
         p_to_stage = ANY(SELECT jsonb_array_elements_text(stage_triggers->'to_stages')))
      )
    )
  ORDER BY priority ASC, created_at ASC;
END;
$$;


--
-- Name: get_super_admin_active_org(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_super_admin_active_org() RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_profile_id uuid;
  v_is_super boolean;
  v_active_org uuid;
BEGIN
  SELECT id, is_super_admin 
  INTO v_profile_id, v_is_super
  FROM public.profiles 
  WHERE user_id = auth.uid() 
  LIMIT 1;
  
  IF v_is_super IS NOT TRUE THEN
    RETURN NULL;
  END IF;
  
  SELECT active_organization_id INTO v_active_org
  FROM public.super_admin_sessions
  WHERE profile_id = v_profile_id;
  
  RETURN v_active_org;
END;
$$;


--
-- Name: FUNCTION get_super_admin_active_org(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_super_admin_active_org() IS 'Gets the active organization for the current super admin session';


--
-- Name: get_system_health_trends(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_system_health_trends(p_hours integer DEFAULT 24) RETURNS TABLE(hour_bucket timestamp with time zone, component_name text, avg_latency_ms numeric, status_counts jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    date_trunc('hour', checked_at) as hour_bucket,
    shl.component_name,
    ROUND(AVG(latency_ms)::numeric, 2) as avg_latency_ms,
    jsonb_build_object(
      'healthy', COUNT(*) FILTER (WHERE status = 'healthy'),
      'warning', COUNT(*) FILTER (WHERE status = 'warning'),
      'error', COUNT(*) FILTER (WHERE status = 'error')
    ) as status_counts
  FROM system_health_logs shl
  WHERE checked_at >= NOW() - (p_hours || ' hours')::interval
  GROUP BY date_trunc('hour', checked_at), shl.component_name
  ORDER BY hour_bucket DESC, shl.component_name;
END;
$$;


--
-- Name: get_team_members(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_team_members(p_org_id uuid) RETURNS TABLE(id uuid, user_id uuid, email text, full_name text, display_name text, avatar_url text, role text, is_active boolean, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Verify user has access to this organization
  IF NOT EXISTS (
    SELECT 1 FROM profiles
    WHERE profiles.user_id = auth.uid()
      AND profiles.organization_id = p_org_id
      AND profiles.is_active = true
  ) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  RETURN QUERY
  SELECT
    p.id,
    p.user_id,
    p.email,
    p.full_name,
    p.display_name,
    p.avatar_url,
    p.role,
    p.is_active,
    p.created_at,
    p.updated_at
  FROM profiles p
  WHERE p.organization_id = p_org_id
  ORDER BY
    CASE p.role
      WHEN 'owner' THEN 1
      WHEN 'super_admin' THEN 2
      WHEN 'admin' THEN 3
      WHEN 'advisor' THEN 4
      WHEN 'staff' THEN 5
    END,
    p.full_name;
END;
$$;


--
-- Name: get_ticket_requester_email(uuid); Type: FUNCTION; Schema: public; Owner: -
