--
-- Name: get_user_sender_addresses(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_sender_addresses(p_profile_id uuid) RETURNS TABLE(id uuid, email text, name text, domain text, is_default boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org_id uuid;
  v_allowed_domain_ids uuid[];
BEGIN
  -- Use table alias to avoid ambiguity with output column "id"
  SELECT prf.organization_id INTO v_org_id FROM profiles prf WHERE prf.id = p_profile_id;
  SELECT ues.allowed_domain_ids INTO v_allowed_domain_ids FROM user_email_settings ues WHERE ues.profile_id = p_profile_id;

  IF v_allowed_domain_ids IS NULL OR array_length(v_allowed_domain_ids, 1) IS NULL THEN
    RETURN QUERY
    SELECT esa.id, esa.email, esa.name, ed.domain, esa.is_default
    FROM email_sender_addresses esa
    JOIN email_domains ed ON esa.domain_id = ed.id
    WHERE esa.organization_id = v_org_id
      AND ed.status = 'verified'
      AND esa.is_verified = true
    ORDER BY esa.is_default DESC, esa.email;
  ELSE
    RETURN QUERY
    SELECT esa.id, esa.email, esa.name, ed.domain, esa.is_default
    FROM email_sender_addresses esa
    JOIN email_domains ed ON esa.domain_id = ed.id
    WHERE esa.organization_id = v_org_id
      AND ed.id = ANY(v_allowed_domain_ids)
      AND ed.status = 'verified'
      AND esa.is_verified = true
    ORDER BY esa.is_default DESC, esa.email;
  END IF;
END;
$$;


--
-- Name: get_validation_rules_for_module(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_validation_rules_for_module(p_module_id uuid, p_trigger text DEFAULT NULL::text) RETURNS SETOF public.crm_validation_rules
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT * FROM crm_validation_rules
  WHERE module_id = p_module_id
    AND is_enabled = true
    AND (p_trigger IS NULL OR p_trigger = ANY(applies_on))
  ORDER BY priority ASC, created_at ASC;
END;
$$;


--
-- Name: get_vendor_cost(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_vendor_cost(p_product_id uuid, p_iua_id uuid, p_age_bracket_id uuid, p_benefit_type_id uuid) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT cost
  FROM vendor_costs
  WHERE product_id = p_product_id
    AND (iua_id IS NULL OR iua_id = p_iua_id)
    AND (age_bracket_id IS NULL OR age_bracket_id = p_age_bracket_id)
    AND (benefit_type_id IS NULL OR benefit_type_id = p_benefit_type_id)
    AND COALESCE(effective_date, CURRENT_DATE) <= CURRENT_DATE
    AND (end_date IS NULL OR end_date > CURRENT_DATE)
  ORDER BY effective_date DESC NULLS LAST
  LIMIT 1;
$$;


--
-- Name: get_vendor_eligibility_summary(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_vendor_eligibility_summary(p_org_id uuid, p_vendor_code text DEFAULT NULL::text) RETURNS TABLE(vendor_code text, total_runs bigint, successful_runs bigint, failed_runs bigint, last_run_at timestamp with time zone, last_success_at timestamp with time zone, avg_duration_ms numeric, total_members_checked bigint, total_eligible bigint, total_ineligible bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    ver.vendor_code,
    COUNT(*) as total_runs,
    COUNT(*) FILTER (WHERE ver.status = 'completed') as successful_runs,
    COUNT(*) FILTER (WHERE ver.status = 'failed') as failed_runs,
    MAX(ver.created_at) as last_run_at,
    MAX(ver.created_at) FILTER (WHERE ver.status = 'completed') as last_success_at,
    AVG(ver.duration_ms)::numeric as avg_duration_ms,
    COALESCE(SUM(ver.members_checked), 0) as total_members_checked,
    COALESCE(SUM(ver.members_eligible), 0) as total_eligible,
    COALESCE(SUM(ver.members_ineligible), 0) as total_ineligible
  FROM public.vendor_eligibility_runs ver
  WHERE ver.organization_id = p_org_id
    AND (p_vendor_code IS NULL OR ver.vendor_code = p_vendor_code)
  GROUP BY ver.vendor_code
  ORDER BY ver.vendor_code;
END;
$$;


--
-- Name: get_vendor_stats(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_vendor_stats(p_org_id uuid) RETURNS TABLE(total_vendors bigint, active_vendors bigint, files_in_progress bigint, changes_last_7_days bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    (SELECT COUNT(*) FROM vendors WHERE organization_id = p_org_id)::bigint as total_vendors,
    (SELECT COUNT(*) FROM vendors WHERE organization_id = p_org_id AND status = 'active')::bigint as active_vendors,
    (SELECT COUNT(*) FROM vendor_files WHERE organization_id = p_org_id AND status IN ('pending', 'validating', 'processing'))::bigint as files_in_progress,
    (SELECT COUNT(*) FROM vendor_changes WHERE organization_id = p_org_id AND detected_at > now() - interval '7 days')::bigint as changes_last_7_days;
END;
$$;


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO public.profiles (id, full_name)
  VALUES (NEW.id, COALESCE(NEW.raw_user_meta_data->>'full_name', ''))
  ON CONFLICT (id) DO UPDATE
    SET full_name = EXCLUDED.full_name;
  RETURN NEW;
END;
$$;


--
-- Name: has_crm_permission(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_crm_permission(p_user_id uuid, p_permission_key text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM crm_user_roles ur
    JOIN crm_role_permissions rp ON rp.role_id = ur.role_id
    JOIN crm_permissions p ON p.id = rp.permission_id
    WHERE ur.user_id = p_user_id
      AND p.key = p_permission_key
  );
$$;


--
-- Name: FUNCTION has_crm_permission(p_user_id uuid, p_permission_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.has_crm_permission(p_user_id uuid, p_permission_key text) IS 'Check if a user has a specific granular permission via their assigned roles.';


--
-- Name: has_crm_role(uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_crm_role(p_org_id uuid, p_roles text[]) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_super boolean;
BEGIN
  -- 1. Super admin short-circuit (unchanged).
  SELECT is_super_admin INTO v_is_super
  FROM public.profiles
  WHERE user_id = auth.uid()
  LIMIT 1;

  IF v_is_super = true THEN
    RETURN true;
  END IF;

  -- 2. Legacy profile path (unchanged).
  IF EXISTS (
    SELECT 1 FROM public.profiles
    WHERE user_id = auth.uid()
      AND organization_id = p_org_id
      AND crm_role = ANY(p_roles)
  ) THEN
    RETURN true;
  END IF;

  -- 3. organization_members path with membership-role to crm-role mapping.
  RETURN EXISTS (
    SELECT 1 FROM public.organization_members
    WHERE user_id = auth.uid()
      AND organization_id = p_org_id
      AND is_active = true
      AND (
        role IN ('owner', 'super_admin', 'admin')
        OR (role = 'staff' AND ('crm_agent' = ANY(p_roles) OR 'crm_viewer' = ANY(p_roles)))
        OR (role = 'read_only' AND 'crm_viewer' = ANY(p_roles))
      )
  );
END;
$$;


--
-- Name: has_delegation(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_delegation(p_parent_org_id uuid, p_child_org_id uuid, p_permission text DEFAULT 'view_aggregated_analytics'::text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1
    FROM org_delegations d
    JOIN org_relationships r
      ON r.parent_org_id = d.parent_org_id
     AND r.child_org_id = d.child_org_id
     AND r.status = 'active'
    WHERE d.parent_org_id = p_parent_org_id
      AND d.child_org_id = p_child_org_id
      AND d.status = 'active'
      AND (d.expires_at IS NULL OR d.expires_at > now())
      AND (d.permissions->>p_permission)::boolean = true
  );
END;
$$;


--
-- Name: has_pending_approval(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_pending_approval(p_record_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM crm_approvals 
    WHERE record_id = p_record_id 
    AND status = 'pending'
  );
$$;


--
-- Name: has_permission(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_permission(p_permission_key text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role text;
BEGIN
  SELECT role INTO v_role FROM profiles WHERE user_id = auth.uid() LIMIT 1;

  IF v_role IS NULL THEN
    RETURN false;
  END IF;

  -- Super admin has all permissions
  IF v_role = 'super_admin' THEN
    RETURN true;
  END IF;

  RETURN EXISTS (
    SELECT 1
    FROM role_permissions rp
    JOIN permissions p ON p.id = rp.permission_id
    WHERE rp.role = v_role
      AND p.key = p_permission_key
  );
END;
$$;


--
-- Name: has_role(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_role(role_in text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT EXISTS(
    SELECT 1 
    FROM public.profiles 
    WHERE id = auth.uid() 
      AND role = role_in
  );
$$;


--
-- Name: FUNCTION has_role(role_in text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.has_role(role_in text) IS 'Check if current authenticated user has specified role';


