--
-- Name: health_check(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.health_check() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'status', 'healthy',
    'timestamp', now(),
    'database', current_database(),
    'version', version(),
    'connections', (SELECT count(*) FROM pg_stat_activity),
    'tables', (SELECT count(*) FROM pg_tables WHERE schemaname = 'public'),
    'rls_enabled_tables', (
      SELECT count(*) FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = 'public' AND c.relkind = 'r' AND c.relrowsecurity = true
    )
  ) INTO v_result;

  RETURN v_result;
END;
$$;


--
-- Name: FUNCTION health_check(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.health_check() IS 'Returns database health status for monitoring';


