--
-- Name: is_crm_member(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_crm_member(p_org_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_super boolean;
BEGIN
  -- 1. Super admin short-circuit (unchanged).
  SELECT is_super_admin INTO v_is_super
  FROM public.profiles
  WHERE user_id = auth.uid()
  LIMIT 1;

  IF v_is_super = true THEN
    RETURN true;
  END IF;

  -- 2. Legacy profile path (unchanged).
  IF EXISTS (
    SELECT 1 FROM public.profiles
    WHERE user_id = auth.uid()
      AND organization_id = p_org_id
      AND crm_role IS NOT NULL
  ) THEN
    RETURN true;
  END IF;

  -- 3. organization_members path — any active member of the org.
  RETURN EXISTS (
    SELECT 1 FROM public.organization_members
    WHERE user_id = auth.uid()
      AND organization_id = p_org_id
      AND is_active = true
  );
END;
$$;


