--
-- Name: log_activity(text, text, text, text, text, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_activity(p_action text, p_category text, p_entity_type text DEFAULT NULL::text, p_entity_id text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_ip_address text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id           uuid;
  v_org_id       uuid;
  v_actor_id     uuid;
  v_actor_email  text;
  v_actor_role   text;
  v_ip           inet;
BEGIN
  -- Resolve current user context from JWT
  SELECT p.organization_id, p.id, p.email, COALESCE(p.crm_role, p.role)
    INTO v_org_id, v_actor_id, v_actor_email, v_actor_role
    FROM profiles p
   WHERE p.user_id = auth.uid()
   LIMIT 1;

  -- System category events can work without an authenticated user
  IF v_org_id IS NULL AND p_category != 'system' THEN
    RAISE EXCEPTION 'Organization context required for non-system activity logs';
  END IF;

  -- Safely cast ip_address text to inet (NULL on bad input)
  BEGIN
    v_ip := p_ip_address::inet;
  EXCEPTION WHEN OTHERS THEN
    v_ip := NULL;
  END;

  INSERT INTO activity_log (
    organization_id, actor_id, actor_email, actor_role,
    action, category, entity_type, entity_id,
    description, metadata, ip_address, user_agent
  ) VALUES (
    COALESCE(v_org_id, '00000000-0000-0000-0000-000000000000'::uuid),
    v_actor_id, v_actor_email, v_actor_role,
    p_action, p_category, p_entity_type, p_entity_id,
    p_description, p_metadata, v_ip, p_user_agent
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: FUNCTION log_activity(p_action text, p_category text, p_entity_type text, p_entity_id text, p_description text, p_metadata jsonb, p_ip_address text, p_user_agent text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.log_activity(p_action text, p_category text, p_entity_type text, p_entity_id text, p_description text, p_metadata jsonb, p_ip_address text, p_user_agent text) IS 'Lightweight RPC to insert an activity log entry. Resolves actor from auth context automatically.';


--
-- Name: log_admin_activity(text, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_admin_activity(p_entity_type text, p_entity_id uuid, p_action text, p_description text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_activity_id uuid;
  v_org_id uuid;
  v_profile_id uuid;
BEGIN
  -- Get current user's organization and profile
  SELECT organization_id, id INTO v_org_id, v_profile_id
  FROM profiles
  WHERE user_id = auth.uid()
  LIMIT 1;
  
  IF v_org_id IS NULL THEN
    RETURN NULL;
  END IF;
  
  INSERT INTO admin_activity_log (
    organization_id,
    actor_profile_id,
    entity_type,
    entity_id,
    action,
    description,
    metadata
  ) VALUES (
    v_org_id,
    v_profile_id,
    p_entity_type,
    p_entity_id,
    p_action,
    p_description,
    p_metadata
  )
  RETURNING id INTO v_activity_id;
  
  RETURN v_activity_id;
END;
$$;


--
-- Name: log_admin_activity(text, uuid, text, text, jsonb, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_admin_activity(p_entity_type text, p_entity_id uuid, p_action text, p_description text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_organization_id uuid DEFAULT NULL::uuid, p_actor_profile_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_activity_id uuid;
  v_org_id      uuid := p_organization_id;
  v_profile_id  uuid := p_actor_profile_id;
BEGIN
  -- Fallback path: look up org + profile from the calling user's session
  -- when explicit values weren't supplied.
  IF v_org_id IS NULL OR v_profile_id IS NULL THEN
    SELECT organization_id, id
      INTO v_org_id, v_profile_id
      FROM public.profiles
     WHERE user_id = auth.uid()
     LIMIT 1;
  END IF;

  IF v_org_id IS NULL THEN
    -- Nothing to log against — silent return preserves old behaviour.
    RETURN NULL;
  END IF;

  INSERT INTO public.admin_activity_log (
    organization_id,
    actor_profile_id,
    entity_type,
    entity_id,
    action,
    description,
    metadata
  ) VALUES (
    v_org_id,
    v_profile_id,
    p_entity_type,
    p_entity_id,
    p_action,
    p_description,
    COALESCE(p_metadata, '{}'::jsonb)
  )
  RETURNING id INTO v_activity_id;

  RETURN v_activity_id;
END;
$$;


--
-- Name: FUNCTION log_admin_activity(p_entity_type text, p_entity_id uuid, p_action text, p_description text, p_metadata jsonb, p_organization_id uuid, p_actor_profile_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.log_admin_activity(p_entity_type text, p_entity_id uuid, p_action text, p_description text, p_metadata jsonb, p_organization_id uuid, p_actor_profile_id uuid) IS 'Inserts a row into admin_activity_log. p_organization_id + p_actor_profile_id should be passed explicitly when the caller already knows them (every admin API route does); they fall back to a lookup by auth.uid() when omitted.';


--
-- Name: log_advisor_changes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_advisor_changes() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor_id uuid;
  v_action text;
  v_old_data jsonb;
  v_new_data jsonb;
  v_changes jsonb;
BEGIN
  -- Get actor from session
  v_actor_id := current_profile_id();

  IF TG_OP = 'INSERT' THEN
    v_action := 'create';
    v_new_data := row_to_json(NEW)::jsonb;

    INSERT INTO agent_audit_log (organization_id, actor_id, action, entity_type, entity_id, new_data)
    VALUES (NEW.organization_id, v_actor_id, v_action, 'advisor', NEW.id, v_new_data);

  ELSIF TG_OP = 'UPDATE' THEN
    v_action := 'update';
    v_old_data := row_to_json(OLD)::jsonb;
    v_new_data := row_to_json(NEW)::jsonb;

    -- Calculate changes
    SELECT jsonb_object_agg(key, jsonb_build_object('old', v_old_data->key, 'new', v_new_data->key))
    INTO v_changes
    FROM jsonb_object_keys(v_new_data) AS key
    WHERE v_old_data->key IS DISTINCT FROM v_new_data->key
      AND key NOT IN ('updated_at');

    IF v_changes IS NOT NULL AND v_changes != '{}'::jsonb THEN
      INSERT INTO agent_audit_log (organization_id, actor_id, action, entity_type, entity_id, old_data, new_data, changes)
      VALUES (NEW.organization_id, v_actor_id, v_action, 'advisor', NEW.id, v_old_data, v_new_data, v_changes);
    END IF;

  ELSIF TG_OP = 'DELETE' THEN
    v_action := 'delete';
    v_old_data := row_to_json(OLD)::jsonb;

    INSERT INTO agent_audit_log (organization_id, actor_id, action, entity_type, entity_id, old_data)
    VALUES (OLD.organization_id, v_actor_id, v_action, 'advisor', OLD.id, v_old_data);
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;


