--
-- Name: log_audit_event(text, text, text, text, text, text, uuid, text, jsonb, jsonb, inet, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_audit_event(p_app_source text, p_action text, p_action_category text, p_risk_level text DEFAULT 'low'::text, p_target_entity_type text DEFAULT NULL::text, p_target_entity_id text DEFAULT NULL::text, p_target_user_id uuid DEFAULT NULL::uuid, p_description text DEFAULT NULL::text, p_details jsonb DEFAULT '{}'::jsonb, p_changes jsonb DEFAULT '{}'::jsonb, p_ip_address inet DEFAULT NULL::inet, p_user_agent text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text, p_session_id text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_audit_id uuid;
  v_org_id uuid;
  v_actor_id uuid;
  v_actor_role text;
  v_actor_email text;
BEGIN
  -- Get current user's profile
  SELECT
    p.organization_id,
    p.id,
    COALESCE(p.crm_role, p.role),
    p.email
  INTO v_org_id, v_actor_id, v_actor_role, v_actor_email
  FROM profiles p
  WHERE p.user_id = auth.uid()
  LIMIT 1;

  -- Allow system events without authenticated user
  IF v_org_id IS NULL AND p_app_source != 'system' THEN
    RAISE EXCEPTION 'Organization context required for non-system events';
  END IF;

  INSERT INTO unified_audit_logs (
    organization_id,
    app_source,
    actor_id,
    actor_role,
    actor_email,
    target_user_id,
    target_entity_type,
    target_entity_id,
    action,
    action_category,
    description,
    risk_level,
    ip_address,
    user_agent,
    request_id,
    session_id,
    details,
    changes
  ) VALUES (
    COALESCE(v_org_id, '00000000-0000-0000-0000-000000000000'::uuid),
    p_app_source,
    v_actor_id,
    v_actor_role,
    v_actor_email,
    p_target_user_id,
    p_target_entity_type,
    p_target_entity_id,
    p_action,
    p_action_category,
    p_description,
    p_risk_level,
    p_ip_address,
    p_user_agent,
    p_request_id,
    p_session_id,
    p_details,
    p_changes
  )
  RETURNING id INTO v_audit_id;

  RETURN v_audit_id;
END;
$$;


