--
-- Name: log_pricing_changes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_pricing_changes() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org_id uuid;
  v_plan_id uuid;
  v_changes jsonb;
BEGIN
  -- Get plan_id and then organization_id
  IF TG_OP = 'DELETE' THEN
    v_plan_id := OLD.plan_id;
  ELSE
    v_plan_id := NEW.plan_id;
  END IF;

  SELECT organization_id INTO v_org_id FROM plans WHERE id = v_plan_id;

  -- Build changes object
  IF TG_OP = 'INSERT' THEN
    v_changes := to_jsonb(NEW);
  ELSIF TG_OP = 'UPDATE' THEN
    v_changes := jsonb_build_object(
      'old', to_jsonb(OLD),
      'new', to_jsonb(NEW)
    );
  ELSE
    v_changes := to_jsonb(OLD);
  END IF;

  INSERT INTO product_audit_log (
    organization_id,
    plan_id,
    action,
    entity_type,
    entity_id,
    changes,
    user_id
  ) VALUES (
    v_org_id,
    v_plan_id,
    'pricing_' || lower(TG_OP),
    'pricing',
    CASE WHEN TG_OP = 'DELETE' THEN OLD.id ELSE NEW.id END,
    v_changes,
    auth.uid()
  );

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


