      'processor_type', COALESCE(NEW.processor_type, OLD.processor_type),
      'is_active', COALESCE(NEW.is_active, OLD.is_active),
      'environment', COALESCE(NEW.environment, OLD.environment)
    ),
    auth.uid()
  );

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


