--
-- Name: log_profile_role_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_profile_role_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  old_role text;
  new_role text;
BEGIN
  IF (TG_OP = 'UPDATE') THEN
    IF NEW.role IS DISTINCT FROM OLD.role THEN
      old_role := OLD.role::text;
      new_role := NEW.role::text;
      
      INSERT INTO public.audit_logs(actor_id, target_user_id, action, details)
      VALUES (
        auth.uid(),
        NEW.id,
        'update_role',
        jsonb_build_object(
          'from_role', old_role,
          'to_role', new_role,
          'email', NEW.email,
          'changed_at', now()
        )
      );
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: log_report_run(uuid, uuid, uuid, integer, integer, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_report_run(p_report_id uuid, p_org_id uuid, p_user_id uuid, p_duration_ms integer, p_row_count integer, p_status text DEFAULT 'completed'::text, p_error_message text DEFAULT NULL::text, p_filters_used jsonb DEFAULT '[]'::jsonb, p_export_format text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_history_id uuid;
BEGIN
  -- Validate caller belongs to org and matches user_id
  IF NOT EXISTS (
    SELECT 1 FROM profiles
    WHERE user_id = auth.uid()
      AND organization_id = p_org_id
      AND id = p_user_id
  ) THEN
    RAISE EXCEPTION 'Unauthorized: caller does not match p_user_id or does not belong to org';
  END IF;

  INSERT INTO public.report_run_history (
    report_id, organization_id, executed_by, duration_ms, row_count,
    status, error_message, filters_used, export_format
  ) VALUES (
    p_report_id, p_org_id, p_user_id, p_duration_ms, p_row_count,
    p_status, p_error_message, p_filters_used, p_export_format
  )
  RETURNING id INTO v_history_id;

  IF p_status = 'completed' THEN
    PERFORM public.increment_report_run_count(p_report_id);
  END IF;

  RETURN v_history_id;
END;
$$;


