--
-- Name: map_role_from_groups(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.map_role_from_groups(groups text[]) RETURNS public.user_role
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  WITH mapped AS (
    SELECT role FROM public.sso_group_roles
    WHERE group_name = ANY(groups)
  )
  SELECT COALESCE((
    SELECT role FROM mapped
    ORDER BY public.role_rank(role) DESC
    LIMIT 1
  ), 'member');
$$;


