--
-- Name: mark_payout_failed(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_payout_failed(p_batch_id uuid, p_reason text DEFAULT 'Payment processing failed'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_batch record;
  v_count int;
  v_payout_ids uuid[];
BEGIN
  SELECT * INTO v_batch
  FROM commission_payment_batches
  WHERE id = p_batch_id
  FOR UPDATE;

  IF v_batch IS NULL THEN
    RETURN jsonb_build_object('error', 'Batch not found');
  END IF;

  -- Collect payout IDs BEFORE nullifying the batch reference
  SELECT array_agg(DISTINCT cl.payout_id) INTO v_payout_ids
  FROM commission_ledger cl
  WHERE cl.payout_batch_id = p_batch_id
    AND cl.payout_id IS NOT NULL;

  -- Release ledger entries
  UPDATE commission_ledger
  SET status = 'available',
      payout_batch_id = NULL,
      payout_id = NULL,
      updated_at = now()
  WHERE payout_batch_id = p_batch_id
    AND status = 'scheduled';

  GET DIAGNOSTICS v_count = ROW_COUNT;

  -- Mark payout items as failed (using pre-collected IDs)
  UPDATE commission_payouts
  SET status = 'failed',
      notes = p_reason,
      updated_at = now()
  WHERE id = ANY(COALESCE(v_payout_ids, '{}'));

  UPDATE commission_payment_batches
  SET status = 'failed',
      notes = p_reason,
      updated_at = now()
  WHERE id = p_batch_id;

  -- Financial audit
  INSERT INTO financial_audit_log (
    organization_id, action, entity_type, entity_id, details
  ) VALUES (
    v_batch.organization_id, 'payout_failed', 'commission_payment_batch', p_batch_id,
    jsonb_build_object(
      'batch_number', v_batch.batch_number,
      'reason', p_reason,
      'ledger_entries_released', v_count
    )
  );

  -- Batch logs
  INSERT INTO payout_batch_logs (
    organization_id, batch_id, action,
    actor_type, prev_status, new_status, details
  ) VALUES (
    v_batch.organization_id, p_batch_id, 'failed',
    'system', v_batch.status, 'failed',
    jsonb_build_object(
      'batch_number', v_batch.batch_number,
      'reason', p_reason,
      'ledger_entries_released', v_count
    )
  );

  -- Immutable audit
  INSERT INTO payout_audit_log (
    organization_id, event_type, entity_type, entity_id,
    actor_type, prev_status, new_status, amount, details
  ) VALUES (
    v_batch.organization_id, 'batch_failed', 'commission_payment_batch', p_batch_id,
    'system', v_batch.status, 'failed', v_batch.total_amount,
    jsonb_build_object(
      'reason', p_reason,
      'ledger_entries_released', v_count
    )
  );

  RETURN jsonb_build_object(
    'batch_id', p_batch_id,
    'status', 'failed',
    'reason', p_reason,
    'ledger_entries_released', v_count
  );
END;
$$;


--
-- Name: mark_payout_paid(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_payout_paid(p_batch_id uuid, p_processed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_batch record;
  v_count int;
  v_open_flags int;
BEGIN
  SELECT * INTO v_batch
  FROM commission_payment_batches
  WHERE id = p_batch_id
  FOR UPDATE;

  IF v_batch IS NULL THEN
    RETURN jsonb_build_object('error', 'Batch not found');
  END IF;

  IF v_batch.status NOT IN ('draft', 'approved', 'processing') THEN
    RETURN jsonb_build_object('error', 'Batch is not in a payable state: ' || v_batch.status);
  END IF;

  -- Check for unresolved fraud flags
  SELECT count(*) INTO v_open_flags
  FROM payout_fraud_flags
  WHERE batch_id = p_batch_id
    AND status IN ('open', 'investigating');

  IF v_open_flags > 0 THEN
    RETURN jsonb_build_object(
      'error', 'Batch has ' || v_open_flags || ' unresolved fraud flag(s). Resolve or dismiss before paying.',
      'code', 'FRAUD_FLAGS_OPEN',
      'open_flags', v_open_flags
    );
  END IF;

  -- Mark ledger entries as paid
  UPDATE commission_ledger
  SET status = 'paid', updated_at = now()
  WHERE payout_batch_id = p_batch_id
    AND status = 'scheduled';

  GET DIAGNOSTICS v_count = ROW_COUNT;

  -- Mark payout items as paid
  UPDATE commission_payouts
  SET status = 'paid',
      paid_at = now(),
      updated_at = now()
  WHERE id IN (
    SELECT DISTINCT payout_id FROM commission_ledger
    WHERE payout_batch_id = p_batch_id
  );

  -- Mark batch as paid
  UPDATE commission_payment_batches
  SET status = 'paid',
      processed_by = p_processed_by,
      processed_at = now(),
      updated_at = now()
  WHERE id = p_batch_id;

  -- Financial audit log
  INSERT INTO financial_audit_log (
    organization_id, action, entity_type, entity_id,
    performed_by, details
  ) VALUES (
    v_batch.organization_id, 'payout_completed', 'commission_payment_batch', p_batch_id,
    p_processed_by,
    jsonb_build_object(
      'batch_number', v_batch.batch_number,
      'total_amount', v_batch.total_amount,
      'ledger_entries_paid', v_count
    )
  );

  -- Payout batch logs
  INSERT INTO payout_batch_logs (
    organization_id, batch_id, action,
    actor_id, actor_type,
    prev_status, new_status, details
  ) VALUES (
    v_batch.organization_id, p_batch_id, 'paid',
    p_processed_by, CASE WHEN p_processed_by IS NULL THEN 'system' ELSE 'user' END,
    v_batch.status, 'paid',
    jsonb_build_object(
      'batch_number', v_batch.batch_number,
      'total_amount', v_batch.total_amount,
      'ledger_entries_paid', v_count
    )
  );

  -- Immutable audit log
  INSERT INTO payout_audit_log (
    organization_id, event_type, entity_type, entity_id,
    actor_id, actor_type, prev_status, new_status,
    amount, details
  ) VALUES (
    v_batch.organization_id, 'batch_paid', 'commission_payment_batch', p_batch_id,
    p_processed_by, CASE WHEN p_processed_by IS NULL THEN 'system' ELSE 'user' END,
    v_batch.status, 'paid',
    v_batch.total_amount,
    jsonb_build_object(
      'batch_number', v_batch.batch_number,
      'ledger_entries_paid', v_count
    )
  );

  RETURN jsonb_build_object(
    'batch_id', p_batch_id,
    'status', 'paid',
    'ledger_entries_paid', v_count,
    'paid_at', now()
  );
END;
$$;


--
-- Name: match_sla_policy(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_sla_policy(ticket_data jsonb) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  matched_policy_id uuid;
BEGIN
  SELECT id INTO matched_policy_id
  FROM sla_policies
  WHERE is_active = true
  AND (
    conditions = '{}'::jsonb
    OR (
      (conditions->>'priority' IS NULL OR ticket_data->>'priority' = ANY(SELECT jsonb_array_elements_text(conditions->'priority')))
    )
  )
  ORDER BY priority ASC
  LIMIT 1;
  
  RETURN matched_policy_id;
END;
$$;


--
-- Name: merge_crm_records(uuid, uuid, uuid, jsonb, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merge_crm_records(p_keeper_id uuid, p_duplicate_id uuid, p_user_id uuid, p_merged_data jsonb DEFAULT NULL::jsonb, p_merged_status text DEFAULT NULL::text, p_merged_email text DEFAULT NULL::text, p_merged_phone text DEFAULT NULL::text, p_merged_owner uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_keeper       crm_records%ROWTYPE;
  v_duplicate    crm_records%ROWTYPE;
  v_user_org     uuid;
  v_final_data   jsonb;
  v_final_status text;
  v_final_email  text;
  v_final_phone  text;
  v_final_owner  uuid;
  v_final_title  text;
  v_moved_notes  int := 0;
  v_moved_tasks  int := 0;
  v_moved_attach int := 0;
  v_moved_links  int := 0;
BEGIN
  IF p_keeper_id = p_duplicate_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Keeper and duplicate must be different records');
  END IF;

  SELECT * INTO v_keeper    FROM crm_records WHERE id = p_keeper_id    FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Keeper record not found');
  END IF;

  SELECT * INTO v_duplicate FROM crm_records WHERE id = p_duplicate_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Duplicate record not found');
  END IF;

  SELECT organization_id INTO v_user_org FROM profiles WHERE id = p_user_id;
  IF v_user_org IS NULL OR v_user_org <> v_keeper.organization_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized for this organization');
  END IF;

  IF v_keeper.organization_id    <> v_duplicate.organization_id    THEN
    RETURN jsonb_build_object('success', false, 'error', 'Records belong to different organizations');
  END IF;
  IF v_keeper.module_id <> v_duplicate.module_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Records belong to different modules');
  END IF;

  v_final_data := COALESCE(
    p_merged_data,
    (
      SELECT COALESCE(jsonb_object_agg(k, v), '{}'::jsonb)
      FROM (
        SELECT
          k,
          CASE
            WHEN (v_keeper.data -> k) IS NULL
                 OR v_keeper.data ->> k IS NULL
                 OR v_keeper.data ->> k = ''
              THEN v_duplicate.data -> k
            ELSE v_keeper.data -> k
          END AS v
        FROM (
          SELECT DISTINCT k FROM (
            SELECT jsonb_object_keys(COALESCE(v_keeper.data,    '{}'::jsonb)) AS k
            UNION
            SELECT jsonb_object_keys(COALESCE(v_duplicate.data, '{}'::jsonb)) AS k
          ) keys
        ) all_keys
      ) merged
      WHERE v IS NOT NULL
    )
  );

  v_final_email  := COALESCE(NULLIF(p_merged_email, ''), NULLIF(v_keeper.email, ''), NULLIF(v_duplicate.email, ''));
  v_final_phone  := COALESCE(NULLIF(p_merged_phone, ''), NULLIF(v_keeper.phone, ''), NULLIF(v_duplicate.phone, ''));
  v_final_owner  := COALESCE(p_merged_owner, v_keeper.owner_id, v_duplicate.owner_id);
  v_final_title  := COALESCE(NULLIF(v_keeper.title, ''), NULLIF(v_duplicate.title, ''));

  v_final_status := COALESCE(
    NULLIF(p_merged_status, ''),
    CASE
      WHEN v_keeper.status    = 'Active' THEN v_keeper.status
      WHEN v_duplicate.status = 'Active' THEN v_duplicate.status
      ELSE COALESCE(NULLIF(v_keeper.status, ''), NULLIF(v_duplicate.status, ''))
    END
  );

  UPDATE crm_notes SET record_id = p_keeper_id WHERE record_id = p_duplicate_id;
  GET DIAGNOSTICS v_moved_notes = ROW_COUNT;

  -- legacy notes table (record_id is uuid in this DB; previously cast to text by mistake)
  BEGIN
    EXECUTE 'UPDATE public.notes SET record_id = $1 WHERE record_id = $2'
      USING p_keeper_id, p_duplicate_id;
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    NULL;
  END;

  UPDATE crm_tasks       SET record_id = p_keeper_id WHERE record_id = p_duplicate_id;
  GET DIAGNOSTICS v_moved_tasks = ROW_COUNT;

  UPDATE crm_attachments SET record_id = p_keeper_id WHERE record_id = p_duplicate_id;
  GET DIAGNOSTICS v_moved_attach = ROW_COUNT;

  DELETE FROM crm_record_links
   WHERE source_record_id = p_duplicate_id
     AND EXISTS (
       SELECT 1 FROM crm_record_links kl
        WHERE kl.source_record_id = p_keeper_id
          AND kl.target_record_id = crm_record_links.target_record_id
          AND kl.link_type        = crm_record_links.link_type
     );
  UPDATE crm_record_links SET source_record_id = p_keeper_id WHERE source_record_id = p_duplicate_id;

  DELETE FROM crm_record_links
   WHERE target_record_id = p_duplicate_id
     AND EXISTS (
       SELECT 1 FROM crm_record_links kl
        WHERE kl.target_record_id = p_keeper_id
          AND kl.source_record_id = crm_record_links.source_record_id
          AND kl.link_type        = crm_record_links.link_type
     );
  UPDATE crm_record_links SET target_record_id = p_keeper_id WHERE target_record_id = p_duplicate_id;
  DELETE FROM crm_record_links WHERE source_record_id = target_record_id;

  GET DIAGNOSTICS v_moved_links = ROW_COUNT;

  DO $blk$
  DECLARE
    r record;
    sql text;
  BEGIN
    FOR r IN
      SELECT
        tc.table_schema,
        tc.table_name,
        kcu.column_name
      FROM information_schema.table_constraints tc
      JOIN information_schema.key_column_usage kcu
        ON tc.constraint_name = kcu.constraint_name
       AND tc.table_schema    = kcu.table_schema
      JOIN information_schema.constraint_column_usage ccu
        ON ccu.constraint_name = tc.constraint_name
       AND ccu.table_schema    = tc.table_schema
      WHERE tc.constraint_type = 'FOREIGN KEY'
        AND ccu.table_schema   = 'public'
        AND ccu.table_name     = 'crm_records'
        AND ccu.column_name    = 'id'
        AND NOT (tc.table_name IN ('crm_notes','crm_tasks','crm_attachments','crm_record_links'))
    LOOP
      BEGIN
        sql := format('UPDATE %I.%I SET %I = $1 WHERE %I = $2',
          r.table_schema, r.table_name, r.column_name, r.column_name);
        EXECUTE sql USING p_keeper_id, p_duplicate_id;
      EXCEPTION WHEN unique_violation THEN
        sql := format('DELETE FROM %I.%I WHERE %I = $1',
          r.table_schema, r.table_name, r.column_name);
        EXECUTE sql USING p_duplicate_id;
      WHEN others THEN
        RAISE WARNING 'merge_crm_records: skipped %.%.%: %',
          r.table_schema, r.table_name, r.column_name, SQLERRM;
      END;
    END LOOP;
  END;
  $blk$;

  UPDATE crm_records
  SET data       = v_final_data,
      email      = v_final_email,
      phone      = v_final_phone,
      status     = v_final_status,
      owner_id   = v_final_owner,
      title      = v_final_title,
      updated_at = now()
  WHERE id = p_keeper_id;

  DELETE FROM crm_records WHERE id = p_duplicate_id;

  BEGIN
    INSERT INTO crm_audit_log (organization_id, actor_id, entity, entity_id, action, diff)
    VALUES (
      v_keeper.organization_id, p_user_id, 'record', p_keeper_id, 'merge',
      jsonb_build_object(
        'kept_id',           p_keeper_id,
        'deleted_id',        p_duplicate_id,
        'deleted_snapshot',  to_jsonb(v_duplicate),
        'moved_notes',       v_moved_notes,
        'moved_tasks',       v_moved_tasks,
        'moved_attachments', v_moved_attach,
        'moved_links',       v_moved_links,
        'merged_at',         now()
      )
    );
  EXCEPTION WHEN others THEN
    RAISE WARNING 'merge_crm_records: audit insert failed: %', SQLERRM;
  END;

  RETURN jsonb_build_object('success', true,
    'kept_id', p_keeper_id, 'deleted_id', p_duplicate_id,
    'moved_notes', v_moved_notes, 'moved_tasks', v_moved_tasks,
    'moved_attachments', v_moved_attach, 'moved_links', v_moved_links);

EXCEPTION WHEN others THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$_$;


--
-- Name: FUNCTION merge_crm_records(p_keeper_id uuid, p_duplicate_id uuid, p_user_id uuid, p_merged_data jsonb, p_merged_status text, p_merged_email text, p_merged_phone text, p_merged_owner uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.merge_crm_records(p_keeper_id uuid, p_duplicate_id uuid, p_user_id uuid, p_merged_data jsonb, p_merged_status text, p_merged_email text, p_merged_phone text, p_merged_owner uuid) IS 'Merges two crm_records into one, moving every child row onto the keeper. Used by the Merge Duplicate dialog on the record detail page. See migration 202604210002 for the full contract.';


--
-- Name: needs_apply_sla(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.needs_apply_sla() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  days_to_target integer;
BEGIN
  -- ========================================
  -- Track status change time
  -- ========================================
  IF TG_OP = 'INSERT' THEN
    -- Set initial status change timestamp
    IF NEW.last_status_change_at IS NULL THEN
      NEW.last_status_change_at := now();
    END IF;

    -- Set default target dates if not provided
    -- SLA durations can be configured per organization in org_settings.sla_config
    -- Defaults: 3 days for initial review, 45 days for completion
    IF NEW.target_initial_review_date IS NULL THEN
      NEW.target_initial_review_date := (current_date + COALESCE(
        (SELECT (settings->'sla_config'->>'initial_review_days')::int
         FROM public.organizations
         WHERE id = NEW.organization_id),
        3  -- Production default: 3 business days
      ));
    END IF;

    IF NEW.target_completion_date IS NULL THEN
      NEW.target_completion_date := (current_date + COALESCE(
        (SELECT (settings->'sla_config'->>'completion_days')::int
         FROM public.organizations
         WHERE id = NEW.organization_id),
        45  -- Production default: 45 days (industry standard)
      ));
    END IF;

    -- Also set sla_target_date if not set (for backwards compatibility)
    IF NEW.sla_target_date IS NULL THEN
      NEW.sla_target_date := NEW.target_completion_date;
    END IF;

  ELSIF TG_OP = 'UPDATE' THEN
    -- Track when status changes
    IF NEW.status IS DISTINCT FROM OLD.status THEN
      NEW.last_status_change_at := now();
    END IF;
  END IF;

  -- ========================================
  -- Compute urgency_light
  -- ========================================

  -- Terminal/completed statuses are always green (no outstanding SLA)
  IF NEW.status IN ('paid', 'closed', 'denied', 'cancelled') THEN
    NEW.urgency_light := 'green';
    RETURN NEW;
  END IF;

  -- If no target date, default to green unless explicitly set
  IF NEW.target_completion_date IS NULL THEN
    IF NEW.urgency_light IS NULL THEN
      NEW.urgency_light := 'green';
    END IF;
    RETURN NEW;
  END IF;

  -- Compute days to target completion (today-based simple SLA)
  days_to_target := NEW.target_completion_date - current_date;

  -- Apply urgency thresholds
  -- Thresholds can be configured per organization in org_settings.sla_config
  -- Defaults: green (5+ days), orange (0-4 days), red (overdue)
  -- Note: Customize urgency_green_days in organization settings to adjust threshold
  IF days_to_target >= COALESCE(
    (SELECT (settings->'sla_config'->>'urgency_green_days')::int
     FROM public.organizations
     WHERE id = NEW.organization_id),
    5  -- Production default: 5+ days = green
  ) THEN
    NEW.urgency_light := 'green';   -- Comfortably on track
  ELSIF days_to_target >= 0 THEN
    NEW.urgency_light := 'orange';  -- Approaching deadline
  ELSE
    NEW.urgency_light := 'red';     -- Past target date (overdue)
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION needs_apply_sla(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.needs_apply_sla() IS 'Trigger function that manages SLA logic for needs: sets default target dates, tracks status changes, and computes urgency_light based on target_completion_date.';


--
-- Name: notify_assignee_on_assignment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_assignee_on_assignment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_assignee record;
  v_requester record;
BEGIN
  -- Only notify if assignee changed
  IF NEW.assignee_id IS NULL OR 
     (OLD.assignee_id IS NOT NULL AND OLD.assignee_id = NEW.assignee_id) THEN
    RETURN NEW;
  END IF;
  
  -- Get assignee details
  SELECT id, full_name, email INTO v_assignee
  FROM profiles
  WHERE id = NEW.assignee_id;
  
  IF v_assignee IS NULL THEN
    RETURN NEW;
  END IF;
  
  -- Get requester details
  SELECT full_name, email INTO v_requester
  FROM profiles
  WHERE id = NEW.requester_id;
  
  -- Create in-app notification for assignee
  INSERT INTO ticket_notifications (
    ticket_id,
    user_id,
    notification_type,
    title,
    message
  ) VALUES (
    NEW.id,
    v_assignee.id,
    'assignment',
    'New Ticket Assigned to You',
    'Ticket #' || substring(NEW.id::text, 1, 8) || ' - ' || NEW.subject || ' has been assigned to you.'
  );
  
  -- Send email to requester if they have an email
  IF v_requester.email IS NOT NULL AND v_requester.email != '' THEN
    INSERT INTO ticket_email_notifications (
      ticket_id,
      recipient_email,
      recipient_name,
      notification_type,
      subject,
      body_text,
      status,
      metadata
    ) VALUES (
      NEW.id,
      v_requester.email,
      COALESCE(v_requester.full_name, NEW.submitter_name, 'Valued Customer'),
      'ticket_assigned',
      'Your Support Ticket Has Been Assigned - #' || substring(NEW.id::text, 1, 8),
      'Hello ' || COALESCE(v_requester.full_name, NEW.submitter_name, 'Valued Customer') || ',

Your support ticket has been assigned to ' || v_assignee.full_name || ' for resolution.

Ticket Details:
- Ticket ID: #' || substring(NEW.id::text, 1, 8) || '
- Subject: ' || NEW.subject || '
- Assigned To: ' || v_assignee.full_name || '
- Priority: ' || NEW.priority || '

' || v_assignee.full_name || ' will review your request and get back to you shortly.

Thank you for your patience.

Best regards,
MPB Health Support Team',
      'pending',
      jsonb_build_object(
        'assignee_id', v_assignee.id,
        'assignee_name', v_assignee.full_name,
        'triggered_by', 'assignment'
      )
    );
  END IF;
  
  -- Log activity
  PERFORM create_activity_log_entry(
    NEW.id,
    'assigned',
    NEW.assignee_id,
    jsonb_build_object(
      'old_assignee_id', OLD.assignee_id,
      'new_assignee_id', NEW.assignee_id,
      'assignee_name', v_assignee.full_name
    )
  );
  
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION notify_assignee_on_assignment(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.notify_assignee_on_assignment() IS 'Notifies assignee via in-app notification and sends email to requester when ticket is assigned';


--
-- Name: notify_member_on_need_status_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_member_on_need_status_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_title text;
  v_category text := 'need';
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    v_title := CASE NEW.status
      WHEN 'in_review'  THEN 'Your need is now under review'
      WHEN 'processing' THEN 'Your need is being processed'
      WHEN 'paid'       THEN 'Sharing has been completed for your need'
      WHEN 'closed'     THEN 'Your need has been closed'
      ELSE 'Update on your need'
    END;

    INSERT INTO member_notifications (
      organization_id, member_id, title, body, category, priority, action_url
    ) VALUES (
      NEW.organization_id,
      NEW.member_id,
      v_title,
      'Status changed from ' || COALESCE(OLD.status, 'new') || ' to ' || NEW.status,
      v_category,
      CASE WHEN NEW.status IN ('paid','in_review') THEN 'high' ELSE 'normal' END,
      '/needs/' || NEW.id::text
    );
  END IF;
  RETURN NEW;
END $$;


--
-- Name: notify_staff_log_assignment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_staff_log_assignment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF (TG_OP = 'INSERT') THEN
    PERFORM public.create_staff_log_notification(
      NEW.staff_id,
      NEW.log_id,
      'assignment',
      'You have been assigned to a log',
      'You have been assigned as ' || NEW.role || ' to log #' || (SELECT log_number FROM public.staff_logs WHERE id = NEW.log_id),
      jsonb_build_object('assignment_id', NEW.id, 'role', NEW.role)
    );
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: notify_staff_log_mentions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_staff_log_mentions() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  mentioned_user uuid;
BEGIN
  IF (TG_OP = 'INSERT' AND NEW.mentions IS NOT NULL) THEN
    FOREACH mentioned_user IN ARRAY NEW.mentions
    LOOP
      PERFORM public.create_staff_log_notification(
        mentioned_user,
        NEW.log_id,
        'mention',
        'You were mentioned in a comment',
        'You were mentioned in a comment on log #' || (SELECT log_number FROM public.staff_logs WHERE id = NEW.log_id),
        jsonb_build_object('comment_id', NEW.id)
      );
    END LOOP;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: notify_staff_log_status_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_staff_log_status_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF (TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM NEW.status) THEN
    -- Notify assigned user
    IF NEW.assigned_to IS NOT NULL THEN
      PERFORM public.create_staff_log_notification(
        NEW.assigned_to,
        NEW.id,
        'status_change',
        'Log status changed',
        'Log #' || NEW.log_number || ' status changed from ' || OLD.status || ' to ' || NEW.status,
        jsonb_build_object('old_status', OLD.status, 'new_status', NEW.status)
      );
    END IF;
    
    -- Notify creator if different from assigned
    IF NEW.created_by IS NOT NULL AND NEW.created_by != NEW.assigned_to THEN
      PERFORM public.create_staff_log_notification(
        NEW.created_by,
        NEW.id,
        'status_change',
        'Log status changed',
        'Log #' || NEW.log_number || ' status changed from ' || OLD.status || ' to ' || NEW.status,
        jsonb_build_object('old_status', OLD.status, 'new_status', NEW.status)
      );
    END IF;
    
    -- Notify all watchers
    PERFORM public.create_staff_log_notification(
      w.user_id,
      NEW.id,
      'status_change',
      'Log status changed',
      'Log #' || NEW.log_number || ' status changed from ' || OLD.status || ' to ' || NEW.status,
      jsonb_build_object('old_status', OLD.status, 'new_status', NEW.status)
    )
    FROM public.staff_log_watchers w
    WHERE w.log_id = NEW.id 
    AND w.user_id NOT IN (COALESCE(NEW.assigned_to, '00000000-0000-0000-0000-000000000000'::uuid), COALESCE(NEW.created_by, '00000000-0000-0000-0000-000000000000'::uuid));
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: notify_ticket_status_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_ticket_status_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_email text;
  v_name text;
  v_notification_type notification_type;
  v_subject text;
  v_body text;
BEGIN
  IF (NEW.status IN ('resolved', 'closed') AND OLD.status != NEW.status) THEN
    v_email := get_ticket_requester_email(NEW.id);

    IF v_email IS NULL OR v_email = '' THEN
      RETURN NEW;
    END IF;

    v_name := get_ticket_requester_name(NEW.id);

    IF NEW.status = 'resolved' THEN
      v_notification_type := 'ticket_resolved';
      v_subject := 'Your Support Ticket Has Been Resolved - #' || substring(NEW.id::text, 1, 8);
      v_body := 'Hello ' || v_name || ',

We are pleased to inform you that your support ticket has been resolved.

Ticket Details:
- Ticket ID: #' || substring(NEW.id::text, 1, 8) || '
- Subject: ' || NEW.subject || '
- Status: Resolved
- Resolution Date: ' || to_char(NEW.updated_at, 'Mon DD, YYYY at HH:MI AM') || '

If you have any additional questions or concerns, please feel free to reply to this ticket or contact our support team.

Thank you for your patience.

Best regards,
MPB Health Support Team';
    ELSE
      v_notification_type := 'ticket_closed';
      v_subject := 'Your Support Ticket Has Been Closed - #' || substring(NEW.id::text, 1, 8);
      v_body := 'Hello ' || v_name || ',

Your support ticket has been closed.

Ticket Details:
- Ticket ID: #' || substring(NEW.id::text, 1, 8) || '
- Subject: ' || NEW.subject || '
- Status: Closed
- Closed Date: ' || to_char(NEW.updated_at, 'Mon DD, YYYY at HH:MI AM') || '

If you need further assistance, please open a new ticket or contact our support team.

Thank you for your patience.

Best regards,
MPB Health Support Team';
    END IF;

    INSERT INTO ticket_email_notifications (
      ticket_id,
      recipient_email,
      recipient_name,
      notification_type,
      subject,
      body_text,
      status,
      metadata
    ) VALUES (
      NEW.id,
      v_email,
      v_name,
      v_notification_type,
      v_subject,
      v_body,
      'pending',
      jsonb_build_object(
        'old_status', OLD.status,
        'new_status', NEW.status,
        'ticket_subject', NEW.subject,
        'ticket_priority', NEW.priority,
        'ticket_category', NEW.category
      )
    );
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION notify_ticket_status_change(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.notify_ticket_status_change() IS 'Trigger function that creates email notification when ticket status changes to resolved or closed';


