--
-- Name: notify_workflow_on_ticket_updated(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_workflow_on_ticket_updated() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF OLD.status IS DISTINCT FROM NEW.status OR 
     OLD.priority IS DISTINCT FROM NEW.priority OR
     OLD.assignee_id IS DISTINCT FROM NEW.assignee_id THEN
    
    PERFORM trigger_workflows_for_event(
      'ticket.updated',
      jsonb_build_object(
        'ticket_id', NEW.id,
        'subject', NEW.subject,
        'old_status', OLD.status,
        'new_status', NEW.status,
        'old_priority', OLD.priority,
        'new_priority', NEW.priority,
        'old_assignee_id', OLD.assignee_id,
        'new_assignee_id', NEW.assignee_id,
        'updated_at', NEW.updated_at
      )
    );
  END IF;
  
  RETURN NEW;
END;
$$;


