--
-- Name: preview_round_robin_assignments(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_round_robin_assignments(p_rule_id uuid, p_count integer DEFAULT 5) RETURNS TABLE(assignment_position integer, advisor_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_config jsonb;
  v_users uuid[];
  v_cursor int;
  v_len int;
BEGIN
  -- Get rule config
  SELECT config INTO v_config
  FROM crm_assignment_rules
  WHERE id = p_rule_id;

  IF v_config IS NULL THEN
    RETURN;
  END IF;

  -- Extract users and cursor
  v_users := ARRAY(SELECT jsonb_array_elements_text(v_config->'users')::uuid);
  v_cursor := COALESCE((v_config->>'cursor')::int, 0);
  v_len := array_length(v_users, 1);

  IF v_len IS NULL OR v_len = 0 THEN
    RETURN;
  END IF;

  -- Generate preview
  FOR i IN 0..(p_count - 1) LOOP
    assignment_position := i + 1;
    advisor_id := v_users[((v_cursor + i) % v_len) + 1];
    RETURN NEXT;
  END LOOP;

  RETURN;
END;
$$;


--
-- Name: purge_expired_idempotency_keys(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_expired_idempotency_keys() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    deleted_count integer;
BEGIN
    WITH deleted AS (
        DELETE FROM public.crm_idempotency_keys
        WHERE expires_at < now()
        RETURNING 1
    )
    SELECT count(*) INTO deleted_count FROM deleted;
    RETURN deleted_count;
END;
$$;


--
-- Name: FUNCTION purge_expired_idempotency_keys(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.purge_expired_idempotency_keys() IS 'Removes crm_idempotency_keys rows whose expires_at is in the past. Safe to call on a schedule (every 15 min).';


--
-- Name: queue_daily_log_report(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_daily_log_report() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_email text;
  v_user_name text;
BEGIN
  -- Only trigger when ended_at is set (transitioning from NULL to a value)
  IF OLD.ended_at IS NULL AND NEW.ended_at IS NOT NULL THEN

    -- Get user details
    SELECT email, full_name INTO v_user_email, v_user_name
    FROM public.profiles
    WHERE id = NEW.user_id;

    -- Create report record for email processing
    INSERT INTO public.daily_log_reports (
      daily_log_id,
      user_id,
      recipient_email,
      report_type,
      email_status,
      report_data
    ) VALUES (
      NEW.id,
      NEW.user_id,
      'vrt@mympb.com',
      'end_of_day',
      'pending',
      jsonb_build_object(
        'user_email', v_user_email,
        'user_name', v_user_name,
        'work_date', NEW.work_date,
        'started_at', NEW.started_at,
        'ended_at', NEW.ended_at,
        'highlights', NEW.highlights,
        'blockers', NEW.blockers,
        'summary', NEW.summary
      )
    );

  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: queue_integration_job(uuid, text, jsonb, timestamp with time zone, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_integration_job(p_org_id uuid, p_job_type text, p_payload jsonb, p_run_at timestamp with time zone DEFAULT now(), p_source_event_id uuid DEFAULT NULL::uuid, p_source_rule_id uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_job_id uuid;
BEGIN
  IF p_idempotency_key IS NOT NULL THEN
    SELECT id INTO v_job_id
    FROM integration_jobs
    WHERE idempotency_key = p_idempotency_key
      AND status NOT IN ('failed', 'cancelled');

    IF v_job_id IS NOT NULL THEN
      RETURN v_job_id;
    END IF;
  END IF;

  INSERT INTO integration_jobs (
    organization_id, job_type, payload, run_at, source_event_id, source_rule_id, idempotency_key
  ) VALUES (
    p_org_id, p_job_type, p_payload, p_run_at, p_source_event_id, p_source_rule_id, p_idempotency_key
  )
  RETURNING id INTO v_job_id;

  RETURN v_job_id;
END;
$$;


--
-- Name: reactivate_team_member(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reactivate_team_member(p_profile_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_target_profile record;
  v_user_profile record;
BEGIN
  -- Get target profile
  SELECT * INTO v_target_profile
  FROM profiles
  WHERE id = p_profile_id;

  IF v_target_profile IS NULL THEN
    RAISE EXCEPTION 'Profile not found';
  END IF;

  -- Get user's profile in the same org
  SELECT id, role INTO v_user_profile
  FROM profiles
  WHERE user_id = auth.uid()
    AND organization_id = v_target_profile.organization_id
    AND is_active = true;

  -- Check permissions
  IF v_user_profile IS NULL OR v_user_profile.role NOT IN ('owner', 'super_admin', 'admin') THEN
    RAISE EXCEPTION 'Insufficient permissions';
  END IF;

  -- Reactivate
  UPDATE profiles
  SET
    is_active = true,
    updated_at = now()
  WHERE id = p_profile_id;

  RETURN true;
END;
$$;


--
-- Name: recalc_crm_commission_summary(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalc_crm_commission_summary(p_member_id uuid, p_org_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_record_id           uuid;
  v_count               int;
  v_total_amount        numeric(12,2);
  v_pending_amount      numeric(12,2);
  v_paid_amount         numeric(12,2);
  v_last_transaction_at timestamptz;
BEGIN
  IF p_member_id IS NULL OR p_org_id IS NULL THEN
    RETURN;
  END IF;

  -- Find the linked CRM contact record (created/maintained by sync_member_to_crm).
  SELECT cr.id
    INTO v_record_id
    FROM public.crm_records cr
    JOIN public.crm_modules m ON m.id = cr.module_id
   WHERE m.organization_id = p_org_id
     AND m.key   = 'contacts'
     AND cr.organization_id = p_org_id
     AND cr.data->>'linked_member_id' = p_member_id::text
   ORDER BY cr.updated_at DESC NULLS LAST
   LIMIT 1;

  IF v_record_id IS NULL THEN
    RETURN;  -- No CRM record to update yet; sync_member_to_crm will eventually create one.
  END IF;

  -- Aggregate every commission transaction for this member.
  SELECT
    COUNT(*),
    COALESCE(SUM(commission_amount), 0),
    COALESCE(SUM(commission_amount) FILTER (WHERE status IN ('pending', 'approved', 'held')), 0),
    COALESCE(SUM(commission_amount) FILTER (WHERE status = 'paid'), 0),
    MAX(updated_at)
    INTO v_count, v_total_amount, v_pending_amount, v_paid_amount, v_last_transaction_at
    FROM public.commission_transactions
   WHERE member_id = p_member_id
     AND organization_id = p_org_id;

  UPDATE public.crm_records
     SET data = COALESCE(data, '{}'::jsonb) || jsonb_build_object(
       'commission_summary', jsonb_build_object(
         'count',                v_count,
         'total_amount',         v_total_amount,
         'pending_amount',       v_pending_amount,
         'paid_amount',          v_paid_amount,
         'last_transaction_at',  v_last_transaction_at
       )
     ),
     updated_at = now()
   WHERE id = v_record_id;
END;
$$;


--
-- Name: FUNCTION recalc_crm_commission_summary(p_member_id uuid, p_org_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.recalc_crm_commission_summary(p_member_id uuid, p_org_id uuid) IS 'Recomputes the commission_summary aggregate inside crm_records.data for a member. Called by the commission_transactions trigger on insert/update/delete.';


--
-- Name: recalculate_queue_positions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalculate_queue_positions() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  WITH ranked_calls AS (
    SELECT
      id,
      ROW_NUMBER() OVER (ORDER BY priority ASC, created_at ASC) as new_position
    FROM call_queue
    WHERE status = 'waiting'
  )
  UPDATE call_queue
  SET queue_position = ranked_calls.new_position
  FROM ranked_calls
  WHERE call_queue.id = ranked_calls.id;

  RETURN NEW;
END;
$$;


--
-- Name: recompute_advisor_tier_on_membership_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_advisor_tier_on_membership_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_advisor_id uuid;
  v_org_id uuid;
  v_active_count int;
  v_new_level_id uuid;
BEGIN
  v_advisor_id := COALESCE(NEW.advisor_id, OLD.advisor_id);
  v_org_id := COALESCE(NEW.organization_id, OLD.organization_id);

  IF v_advisor_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT COUNT(*) INTO v_active_count
  FROM enrollments
  WHERE advisor_id = v_advisor_id
    AND status = 'approved';

  SELECT id INTO v_new_level_id
  FROM agent_levels
  WHERE organization_id = v_org_id
    AND is_active = true
    AND min_active_members <= v_active_count
    AND (max_active_members IS NULL OR max_active_members >= v_active_count)
  ORDER BY level_rank DESC
  LIMIT 1;

  IF v_new_level_id IS NOT NULL THEN
    UPDATE advisors
    SET agent_level_id = v_new_level_id,
        updated_at = now()
    WHERE id = v_advisor_id
      AND (agent_level_id IS DISTINCT FROM v_new_level_id);
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: recompute_network_coverage_zip(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_network_coverage_zip(p_network_id uuid, p_zip_code text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_provider_count integer := 0;
  v_preferred_count integer := 0;
  v_specialty jsonb := '{}'::jsonb;
  v_score numeric := 0;
  v_state text;
  v_categories_covered integer := 0;
  v_max_categories constant integer := 10;
BEGIN
  -- Count active in-network providers whose location ZIP matches
  SELECT COUNT(*), COUNT(*) FILTER (WHERE np.network_tier = 'in_network_preferred')
  INTO v_provider_count, v_preferred_count
  FROM network_providers np
  LEFT JOIN healthcare_locations hl ON hl.id = np.healthcare_location_id
  LEFT JOIN provider_locations pl ON pl.id = np.provider_location_id
  WHERE np.network_id = p_network_id
    AND np.is_active = true
    AND np.network_tier IN ('in_network_preferred', 'in_network')
    AND (hl.zip = p_zip_code OR pl.zip = p_zip_code);

  -- Compute specialty tag distribution
  SELECT COALESCE(jsonb_object_agg(tag, cnt), '{}'::jsonb)
  INTO v_specialty
  FROM (
    SELECT unnest(np.specialty_tags) AS tag, COUNT(*) AS cnt
    FROM network_providers np
    LEFT JOIN healthcare_locations hl ON hl.id = np.healthcare_location_id
    LEFT JOIN provider_locations pl ON pl.id = np.provider_location_id
    WHERE np.network_id = p_network_id
      AND np.is_active = true
      AND (hl.zip = p_zip_code OR pl.zip = p_zip_code)
    GROUP BY unnest(np.specialty_tags)
  ) sub;

  -- Count unique categories covered
  SELECT COUNT(DISTINCT tag) INTO v_categories_covered
  FROM (
    SELECT unnest(np.specialty_tags) AS tag
    FROM network_providers np
    LEFT JOIN healthcare_locations hl ON hl.id = np.healthcare_location_id
    LEFT JOIN provider_locations pl ON pl.id = np.provider_location_id
    WHERE np.network_id = p_network_id
      AND np.is_active = true
      AND (hl.zip = p_zip_code OR pl.zip = p_zip_code)
  ) sub;

  -- Resolve state from ZIP
  SELECT COALESCE(hl.state, pl.state) INTO v_state
  FROM network_providers np
  LEFT JOIN healthcare_locations hl ON hl.id = np.healthcare_location_id
  LEFT JOIN provider_locations pl ON pl.id = np.provider_location_id
  WHERE np.network_id = p_network_id
    AND (hl.zip = p_zip_code OR pl.zip = p_zip_code)
  LIMIT 1;

  -- Score formula:
  -- 40% provider depth (capped at 20 providers = full marks)
  -- 30% category breadth (categories_covered / max_categories)
  -- 30% preferred tier ratio
  v_score := ROUND(
    (LEAST(v_provider_count, 20) / 20.0) * 40 +
    (LEAST(v_categories_covered, v_max_categories)::numeric / v_max_categories) * 30 +
    (CASE WHEN v_provider_count > 0 THEN v_preferred_count::numeric / v_provider_count ELSE 0 END) * 30
  , 2);

  -- Upsert
  INSERT INTO network_coverage_zips (
    network_id, zip_code, state, provider_count, preferred_count,
    specialty_coverage, coverage_score, last_computed_at
  ) VALUES (
    p_network_id, p_zip_code, v_state, v_provider_count, v_preferred_count,
    v_specialty, v_score, now()
  )
  ON CONFLICT (network_id, zip_code) DO UPDATE SET
    state = EXCLUDED.state,
    provider_count = EXCLUDED.provider_count,
    preferred_count = EXCLUDED.preferred_count,
    specialty_coverage = EXCLUDED.specialty_coverage,
    coverage_score = EXCLUDED.coverage_score,
    last_computed_at = EXCLUDED.last_computed_at;
END;
$$;


--
-- Name: reconcile_payouts(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_payouts(p_batch_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_batch        record;
  v_row          record;
  v_total        int := 0;
  v_matched      int := 0;
  v_discrepancy  int := 0;
  v_missing      int := 0;
BEGIN
  SELECT * INTO v_batch
  FROM commission_payment_batches
  WHERE id = p_batch_id;

  IF v_batch IS NULL THEN
    RETURN jsonb_build_object('error', 'Batch not found');
  END IF;

  -- Compare each payout item against its provider transaction
  FOR v_row IN
    SELECT
      cp.id AS payout_item_id,
      cp.net_payout AS expected_amount,
      cp.status AS payout_status,
      pt.id AS provider_txn_id,
      pt.amount AS provider_amount,
      pt.status AS provider_status,
      pt.provider_transaction_id
    FROM commission_payouts cp
    LEFT JOIN payout_provider_transactions pt
      ON pt.payout_item_id = cp.id
      AND pt.status <> 'failed'
    WHERE cp.id IN (
      SELECT DISTINCT payout_id FROM commission_ledger
      WHERE payout_batch_id = p_batch_id AND payout_id IS NOT NULL
    )
  LOOP
    v_total := v_total + 1;

    IF v_row.provider_txn_id IS NULL THEN
      -- No provider transaction found
      INSERT INTO payout_reconciliation_logs (
        organization_id, batch_id, payout_item_id,
        expected_amount, discrepancy_flag, discrepancy_type,
        expected_status, actual_status, details
      ) VALUES (
        v_batch.organization_id, p_batch_id, v_row.payout_item_id,
        v_row.expected_amount, true, 'missing_provider_txn',
        v_row.payout_status, NULL,
        jsonb_build_object('note', 'No provider transaction record found')
      );
      v_missing := v_missing + 1;

    ELSIF v_row.expected_amount <> v_row.provider_amount THEN
      -- Amount mismatch
      INSERT INTO payout_reconciliation_logs (
        organization_id, batch_id, payout_item_id, provider_txn_id,
        expected_amount, actual_amount,
        discrepancy_flag, discrepancy_type,
        expected_status, actual_status, details
      ) VALUES (
        v_batch.organization_id, p_batch_id, v_row.payout_item_id, v_row.provider_txn_id,
        v_row.expected_amount, v_row.provider_amount,
        true, 'amount_mismatch',
        v_row.payout_status, v_row.provider_status,
        jsonb_build_object(
          'difference', v_row.expected_amount - v_row.provider_amount,
          'provider_transaction_id', v_row.provider_transaction_id
        )
      );
      v_discrepancy := v_discrepancy + 1;

    ELSIF v_row.payout_status = 'paid' AND v_row.provider_status <> 'succeeded' THEN
      -- Status mismatch: payout says paid but provider hasn't confirmed
      INSERT INTO payout_reconciliation_logs (
        organization_id, batch_id, payout_item_id, provider_txn_id,
        expected_amount, actual_amount,
        discrepancy_flag, discrepancy_type,
        expected_status, actual_status, details
      ) VALUES (
        v_batch.organization_id, p_batch_id, v_row.payout_item_id, v_row.provider_txn_id,
        v_row.expected_amount, v_row.provider_amount,
        true, 'status_mismatch',
        v_row.payout_status, v_row.provider_status,
        jsonb_build_object(
          'provider_transaction_id', v_row.provider_transaction_id,
          'note', 'Payout marked paid but provider has not confirmed'
        )
      );
      v_discrepancy := v_discrepancy + 1;

    ELSE
      -- All good
      INSERT INTO payout_reconciliation_logs (
        organization_id, batch_id, payout_item_id, provider_txn_id,
        expected_amount, actual_amount,
        discrepancy_flag,
        expected_status, actual_status
      ) VALUES (
        v_batch.organization_id, p_batch_id, v_row.payout_item_id, v_row.provider_txn_id,
        v_row.expected_amount, v_row.provider_amount,
        false,
        v_row.payout_status, v_row.provider_status
      );
      v_matched := v_matched + 1;
    END IF;
  END LOOP;

  -- Log reconciliation run
  INSERT INTO payout_audit_log (
    organization_id, event_type, entity_type, entity_id,
    actor_type, details
  ) VALUES (
    v_batch.organization_id, 'batch_reconciled', 'commission_payment_batch', p_batch_id,
    'system',
    jsonb_build_object(
      'total_items', v_total,
      'matched', v_matched,
      'discrepancies', v_discrepancy,
      'missing', v_missing,
      'batch_number', v_batch.batch_number
    )
  );

  RETURN jsonb_build_object(
    'batch_id', p_batch_id,
    'batch_number', v_batch.batch_number,
    'total_items', v_total,
    'matched', v_matched,
    'discrepancies', v_discrepancy,
    'missing_provider_txn', v_missing,
    'reconciled_at', now()
  );
END;
$$;


--
-- Name: record_change_event(uuid, text, text, text, text, uuid, text, text, text, jsonb, jsonb, uuid, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_change_event(p_org_id uuid, p_source_type text, p_source_name text, p_change_type text, p_entity_type text, p_entity_id uuid, p_entity_title text, p_title text, p_description text DEFAULT NULL::text, p_diff jsonb DEFAULT NULL::jsonb, p_payload jsonb DEFAULT '{}'::jsonb, p_actor_id uuid DEFAULT NULL::uuid, p_actor_type text DEFAULT 'user'::text, p_severity text DEFAULT NULL::text, p_requires_review boolean DEFAULT NULL::boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_severity text;
  v_requires_review boolean;
  v_change_id uuid;
  v_actor_name text;
BEGIN
  IF p_severity IS NULL THEN
    v_severity := CASE
      WHEN p_change_type IN ('termination', 'integration_error') THEN 'critical'
      WHEN p_change_type IN ('plan_change', 'sync_conflict') OR p_change_type LIKE 'status_change:inactive%' THEN 'high'
      WHEN p_change_type IN ('enrollment', 'member_new') THEN 'medium'
      WHEN p_change_type = 'create' THEN 'low'
      ELSE 'info'
    END;
  ELSE
    v_severity := p_severity;
  END IF;

  IF p_requires_review IS NULL THEN
    v_requires_review := v_severity IN ('critical', 'high') OR p_change_type IN ('termination', 'plan_change');
  ELSE
    v_requires_review := p_requires_review;
  END IF;

  IF p_actor_id IS NOT NULL THEN
    SELECT full_name INTO v_actor_name FROM profiles WHERE id = p_actor_id;
  END IF;

  INSERT INTO change_events (
    organization_id, source_type, source_name, change_type, entity_type, entity_id,
    entity_title, title, description, diff, payload, actor_id, actor_name,
    actor_type, severity, requires_review, reconciliation_status
  ) VALUES (
    p_org_id, p_source_type, p_source_name, p_change_type, p_entity_type, p_entity_id,
    p_entity_title, p_title, p_description, p_diff, p_payload, p_actor_id, v_actor_name,
    p_actor_type, v_severity, v_requires_review,
    CASE WHEN v_requires_review THEN 'pending' ELSE 'none' END
  )
  RETURNING id INTO v_change_id;

  RETURN v_change_id;
END;
$$;


--
-- Name: FUNCTION record_change_event(p_org_id uuid, p_source_type text, p_source_name text, p_change_type text, p_entity_type text, p_entity_id uuid, p_entity_title text, p_title text, p_description text, p_diff jsonb, p_payload jsonb, p_actor_id uuid, p_actor_type text, p_severity text, p_requires_review boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.record_change_event(p_org_id uuid, p_source_type text, p_source_name text, p_change_type text, p_entity_type text, p_entity_id uuid, p_entity_title text, p_title text, p_description text, p_diff jsonb, p_payload jsonb, p_actor_id uuid, p_actor_type text, p_severity text, p_requires_review boolean) IS 'Helper function to record change events with automatic severity calculation';


--
-- Name: record_provider_result(uuid, text, text, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_provider_result(p_txn_id uuid, p_status text, p_provider_txn_id text DEFAULT NULL::text, p_raw_response jsonb DEFAULT '{}'::jsonb, p_failure_reason text DEFAULT NULL::text, p_failure_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_txn    record;
  v_batch  record;
BEGIN
  -- Lock the transaction row
  SELECT * INTO v_txn
  FROM payout_provider_transactions
  WHERE id = p_txn_id
  FOR UPDATE;

  IF v_txn IS NULL THEN
    RETURN jsonb_build_object('error', 'Provider transaction not found');
  END IF;

  -- Idempotency: already in terminal state
  IF v_txn.status IN ('succeeded', 'reversed') THEN
    RETURN jsonb_build_object(
      'txn_id', p_txn_id,
      'status', v_txn.status,
      'already_terminal', true
    );
  END IF;

  -- Update the provider transaction
  UPDATE payout_provider_transactions
  SET status = p_status,
      provider_transaction_id = COALESCE(p_provider_txn_id, provider_transaction_id),
      raw_response = p_raw_response,
      failure_reason = p_failure_reason,
      failure_code = p_failure_code,
      submitted_at = CASE WHEN p_status = 'submitted' THEN now() ELSE submitted_at END,
      completed_at = CASE WHEN p_status IN ('succeeded', 'failed') THEN now() ELSE completed_at END,
      updated_at = now()
  WHERE id = p_txn_id;

  -- If succeeded, update payout item status
  IF p_status = 'succeeded' THEN
    UPDATE commission_payouts
    SET payment_reference = p_provider_txn_id,
        payment_method = v_txn.provider_type,
        updated_at = now()
    WHERE id = v_txn.payout_item_id;
  END IF;

  -- If failed, update payout item
  IF p_status = 'failed' THEN
    UPDATE commission_payouts
    SET notes = COALESCE(notes || '; ', '') || 'Provider error: ' || COALESCE(p_failure_reason, 'unknown'),
        updated_at = now()
    WHERE id = v_txn.payout_item_id;
  END IF;

  -- Check if all items in the batch are now terminal
  SELECT * INTO v_batch
  FROM commission_payment_batches
  WHERE id = v_txn.batch_id;

  DECLARE
    v_total     int;
    v_succeeded int;
    v_failed    int;
  BEGIN
    SELECT
      count(*),
      count(*) FILTER (WHERE status = 'succeeded'),
      count(*) FILTER (WHERE status = 'failed')
    INTO v_total, v_succeeded, v_failed
    FROM payout_provider_transactions
    WHERE batch_id = v_txn.batch_id;

    -- All items processed?
    IF (v_succeeded + v_failed) = v_total AND v_total > 0 THEN
      IF v_failed = 0 THEN
        -- All succeeded → mark batch paid
        PERFORM mark_payout_paid(v_txn.batch_id);
      ELSE
        -- Partial or full failure
        INSERT INTO payout_batch_logs (
          organization_id, batch_id, action,
          actor_type, prev_status, new_status, details
        ) VALUES (
          v_batch.organization_id, v_txn.batch_id, 'processing',
          'system', 'processing', 'processing',
          jsonb_build_object(
            'note', 'Partial execution complete',
            'succeeded', v_succeeded,
            'failed', v_failed,
            'total', v_total
          )
        );
      END IF;
    END IF;
  END;

  RETURN jsonb_build_object(
    'txn_id', p_txn_id,
    'payout_item_id', v_txn.payout_item_id,
    'status', p_status,
    'provider_transaction_id', p_provider_txn_id
  );
END;
$$;


--
-- Name: record_tracking_event(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_tracking_event(p_tracking_id uuid, p_event_type text, p_ip_address text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text, p_clicked_url text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_recipient email_campaign_recipients%ROWTYPE;
  v_campaign email_campaigns%ROWTYPE;
BEGIN
  -- Find recipient by tracking ID
  SELECT * INTO v_recipient
  FROM email_campaign_recipients
  WHERE tracking_id = p_tracking_id;

  IF v_recipient.id IS NULL THEN
    RETURN json_build_object('success', false, 'error', 'Tracking ID not found');
  END IF;

  -- Get campaign
  SELECT * INTO v_campaign
  FROM email_campaigns
  WHERE id = v_recipient.campaign_id;

  -- Record the event
  INSERT INTO campaign_tracking_events (
    organization_id, campaign_id, recipient_id, tracking_id,
    event_type, ip_address, user_agent, clicked_url
  ) VALUES (
    v_campaign.organization_id, v_recipient.campaign_id, v_recipient.id, p_tracking_id,
    p_event_type, p_ip_address, p_user_agent, p_clicked_url
  );

  -- Update recipient stats
  IF p_event_type = 'open' THEN
    UPDATE email_campaign_recipients
    SET
      opened_at = COALESCE(opened_at, now()),
      last_opened_at = now(),
      open_count = open_count + 1,
      status = CASE WHEN status NOT IN ('clicked', 'unsubscribed') THEN 'opened' ELSE status END
    WHERE id = v_recipient.id;

    -- Update campaign stats (only increment unique opens)
    IF v_recipient.opened_at IS NULL THEN
      UPDATE email_campaigns
      SET opened_count = opened_count + 1
      WHERE id = v_recipient.campaign_id;
    END IF;

  ELSIF p_event_type = 'click' THEN
    UPDATE email_campaign_recipients
    SET
      clicked_at = COALESCE(clicked_at, now()),
      last_clicked_at = now(),
      click_count = click_count + 1,
      opened_at = COALESCE(opened_at, now()), -- click implies open
      status = CASE WHEN status != 'unsubscribed' THEN 'clicked' ELSE status END
    WHERE id = v_recipient.id;

    -- Update campaign stats (only increment unique clicks)
    IF v_recipient.clicked_at IS NULL THEN
      UPDATE email_campaigns
      SET
        clicked_count = clicked_count + 1,
        opened_count = CASE WHEN v_recipient.opened_at IS NULL
                       THEN opened_count + 1 ELSE opened_count END
      WHERE id = v_recipient.campaign_id;
    END IF;

  ELSIF p_event_type = 'unsubscribe' THEN
    UPDATE email_campaign_recipients
    SET
      unsubscribed_at = now(),
      status = 'unsubscribed'
    WHERE id = v_recipient.id;

    UPDATE email_campaigns
    SET unsubscribed_count = unsubscribed_count + 1
    WHERE id = v_recipient.campaign_id;
  END IF;

  RETURN json_build_object('success', true);
END;
$$;


--
-- Name: recover_zoho_notes_for_org(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recover_zoho_notes_for_org(p_org_id uuid, p_since timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(inserted_count integer, total_considered integer, duplicate_count integer, orphan_parent_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_inserted int := 0;
  v_dupes    int := 0;
  v_total    int := 0;
  v_orphans  int := 0;
BEGIN
  IF p_org_id IS NULL THEN
    RAISE EXCEPTION 'p_org_id is required';
  END IF;

  -- ------------------------------------------------------------------------
  -- Working set: every staged row that has a body and resolves to a current
  -- crm_records.id in the requested org.
  -- ------------------------------------------------------------------------
  CREATE TEMP TABLE _zoho_notes_work ON COMMIT DROP AS
  SELECT
    s.row_num,
    r.id                                                        AS crm_record_id,
    p_org_id                                                    AS org_id,
    trim(s.note_content)                                        AS body,
    COALESCE(
      NULLIF(s.created_time, '')::timestamp AT TIME ZONE 'America/Denver',
      now()
    )                                                           AS created_at
  FROM import_notes_staging s
  JOIN crm_records r
    ON r.organization_id = p_org_id
   AND (
         r.data->>'zoho_record_id' = s.parent_id
      OR r.data->>'zoho_record_id' = 'zcrm_' || s.parent_id
      OR replace(r.data->>'zoho_record_id', 'zcrm_', '') = s.parent_id
     )
  WHERE s.note_content IS NOT NULL
    AND trim(s.note_content) <> ''
    AND (p_since IS NULL OR NULLIF(s.created_time, '')::timestamp >= p_since);

  SELECT count(*) INTO v_total FROM _zoho_notes_work;

  -- ------------------------------------------------------------------------
  -- Drop rows whose body already exists on the same record near the same time.
  -- ------------------------------------------------------------------------
  DELETE FROM _zoho_notes_work t
  USING crm_notes n
  WHERE n.record_id = t.crm_record_id
    AND n.body = t.body
    AND n.created_at BETWEEN t.created_at - interval '1 minute'
                          AND t.created_at + interval '1 minute';

  GET DIAGNOSTICS v_dupes = ROW_COUNT;

  -- ------------------------------------------------------------------------
  -- Insert.
  -- ------------------------------------------------------------------------
  INSERT INTO crm_notes (organization_id, record_id, body, is_pinned, created_by, created_at, updated_at)
  SELECT
    t.org_id,
    t.crm_record_id,
    t.body,
    false,
    NULL::uuid,
    t.created_at,
    now()
  FROM _zoho_notes_work t;

  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  -- ------------------------------------------------------------------------
  -- Count staging rows whose parent record we couldn't match.
  -- ------------------------------------------------------------------------
  SELECT count(*)
    INTO v_orphans
  FROM import_notes_staging s
  LEFT JOIN crm_records r
    ON r.organization_id = p_org_id
   AND (
         r.data->>'zoho_record_id' = s.parent_id
      OR r.data->>'zoho_record_id' = 'zcrm_' || s.parent_id
      OR replace(r.data->>'zoho_record_id', 'zcrm_', '') = s.parent_id
     )
  WHERE r.id IS NULL
    AND s.note_content IS NOT NULL
    AND trim(s.note_content) <> ''
    AND (p_since IS NULL OR NULLIF(s.created_time, '')::timestamp >= p_since);

  RETURN QUERY SELECT v_inserted, v_total, v_dupes, v_orphans;
END
$$;


--
-- Name: FUNCTION recover_zoho_notes_for_org(p_org_id uuid, p_since timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.recover_zoho_notes_for_org(p_org_id uuid, p_since timestamp with time zone) IS 'Promotes import_notes_staging rows into crm_notes for the given org. Idempotent.';


--
-- Name: refresh_advisor_commission_summary(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_advisor_commission_summary(p_org_id uuid DEFAULT NULL::uuid, p_month date DEFAULT (date_trunc('month'::text, (CURRENT_DATE)::timestamp with time zone))::date) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_count int := 0;
BEGIN
  INSERT INTO advisor_commission_summary (
    organization_id, advisor_id, period_month,
    total_commissions, paid_commissions, pending_commissions, approved_commissions,
    signup_commissions, monthly_commissions, override_commissions, bonus_commissions,
    total_enrollments, commission_count,
    total_base_amount,
    total_adjustments_positive, total_adjustments_negative,
    updated_at
  )
  SELECT
    c.organization_id,
    c.advisor_id,
    date_trunc('month', c.commission_period::date)::date AS period_month,
    COALESCE(sum(c.commission_amount), 0),
    COALESCE(sum(c.commission_amount) FILTER (WHERE c.status = 'paid'), 0),
    COALESCE(sum(c.commission_amount) FILTER (WHERE c.status = 'pending'), 0),
    COALESCE(sum(c.commission_amount) FILTER (WHERE c.status = 'approved'), 0),
    COALESCE(sum(c.commission_amount) FILTER (WHERE c.commission_type = 'signup'), 0),
    COALESCE(sum(c.commission_amount) FILTER (WHERE c.commission_type = 'monthly'), 0),
    COALESCE(sum(c.commission_amount) FILTER (WHERE c.commission_type = 'override'), 0),
    COALESCE(sum(c.commission_amount) FILTER (WHERE c.commission_type = 'bonus'), 0),
    count(DISTINCT c.enrollment_id),
    count(c.id),
    COALESCE(sum(c.base_amount), 0),
    COALESCE((
      SELECT sum(adj.amount)
      FROM commission_adjustments adj
      WHERE adj.advisor_id = c.advisor_id
        AND adj.organization_id = c.organization_id
        AND adj.status = 'approved'
        AND adj.effective_period = date_trunc('month', c.commission_period::date)::date
        AND adj.amount > 0
    ), 0),
    COALESCE((
      SELECT sum(abs(adj.amount))
      FROM commission_adjustments adj
      WHERE adj.advisor_id = c.advisor_id
        AND adj.organization_id = c.organization_id
        AND adj.status = 'approved'
        AND adj.effective_period = date_trunc('month', c.commission_period::date)::date
        AND adj.amount < 0
    ), 0),
    now()
  FROM commissions c
  WHERE date_trunc('month', c.commission_period::date)::date = p_month
    AND (p_org_id IS NULL OR c.organization_id = p_org_id)
  GROUP BY c.organization_id, c.advisor_id, date_trunc('month', c.commission_period::date)::date
  ON CONFLICT (advisor_id, period_month)
  DO UPDATE SET
    total_commissions = EXCLUDED.total_commissions,
    paid_commissions = EXCLUDED.paid_commissions,
    pending_commissions = EXCLUDED.pending_commissions,
    approved_commissions = EXCLUDED.approved_commissions,
    signup_commissions = EXCLUDED.signup_commissions,
    monthly_commissions = EXCLUDED.monthly_commissions,
    override_commissions = EXCLUDED.override_commissions,
    bonus_commissions = EXCLUDED.bonus_commissions,
    total_enrollments = EXCLUDED.total_enrollments,
    commission_count = EXCLUDED.commission_count,
    total_base_amount = EXCLUDED.total_base_amount,
    total_adjustments_positive = EXCLUDED.total_adjustments_positive,
    total_adjustments_negative = EXCLUDED.total_adjustments_negative,
    updated_at = now();

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


--
-- Name: refresh_advisor_rankings(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_advisor_rankings(p_org_id uuid DEFAULT NULL::uuid, p_month date DEFAULT (date_trunc('month'::text, (CURRENT_DATE)::timestamp with time zone))::date) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_prev_month    date := (p_month - interval '1 month')::date;
  v_count         int := 0;
  v_cap_count     int;
  v_cap           text;
  v_caps          text[] := ARRAY[NULL, 'health_insurance', 'health_share'];
  v_config        jsonb;
  v_cw            numeric; -- commission weight
  v_ew            numeric; -- enrollment weight
  v_dw            numeric; -- downline weight
  v_gw            numeric; -- growth weight
  v_tb            numeric; -- tier bronze max
  v_ts            numeric; -- tier silver max
  v_tg            numeric; -- tier gold max
  v_tp            numeric; -- tier platinum max
BEGIN
  -- Process each capacity scope
  FOREACH v_cap IN ARRAY v_caps
  LOOP
    -- Load org config for this capacity
    v_config := get_score_config(COALESCE(p_org_id, '00000000-0000-0000-0000-000000000000'::uuid), v_cap);
    v_cw := (v_config->>'commission_weight')::numeric;
    v_ew := (v_config->>'enrollment_weight')::numeric;
    v_dw := (v_config->>'downline_weight')::numeric;
    v_gw := (v_config->>'growth_weight')::numeric;
    v_tb := (v_config->>'tier_bronze_max')::numeric;
    v_ts := (v_config->>'tier_silver_max')::numeric;
    v_tg := (v_config->>'tier_gold_max')::numeric;
    v_tp := (v_config->>'tier_platinum_max')::numeric;

    INSERT INTO advisor_rankings (
      organization_id, advisor_id, period_month, capacity_scope,
      commission_score, enrollment_score, downline_score, growth_score,
      production_score, rank_position, tier,
      total_commissions, total_enrollments, downline_production, growth_rate_pct,
      streak_months, prev_rank, rank_change, next_tier_gap,
      calculated_at
    )
    SELECT
      sub.organization_id,
      sub.advisor_id,
      p_month,
      v_cap,
      sub.commission_score,
      sub.enrollment_score,
      sub.downline_score,
      sub.growth_score,
      sub.production_score,
      row_number() OVER (
        PARTITION BY sub.organization_id
        ORDER BY sub.production_score DESC
      )::int AS rank_position,
      CASE
        WHEN sub.production_score >= v_tp THEN 'elite'
        WHEN sub.production_score >= v_tg THEN 'platinum'
        WHEN sub.production_score >= v_ts THEN 'gold'
        WHEN sub.production_score >= v_tb THEN 'silver'
        ELSE 'bronze'
      END AS tier,
      sub.total_commissions,
      sub.total_enrollments,
      sub.downline_production,
      sub.growth_rate_pct,
      -- Streak: consecutive months in gold+ tier
      COALESCE((
        SELECT prev.streak_months + 1
        FROM advisor_rankings prev
        WHERE prev.advisor_id = sub.advisor_id
          AND prev.period_month = v_prev_month
          AND prev.capacity_scope IS NOT DISTINCT FROM v_cap
          AND prev.tier IN ('gold', 'platinum', 'elite')
      ), 0),
      -- Previous rank
      (SELECT prev.rank_position FROM advisor_rankings prev
       WHERE prev.advisor_id = sub.advisor_id
         AND prev.period_month = v_prev_month
         AND prev.capacity_scope IS NOT DISTINCT FROM v_cap),
      -- Rank change (positive = improved)
      COALESCE((
        SELECT prev.rank_position
        FROM advisor_rankings prev
        WHERE prev.advisor_id = sub.advisor_id
          AND prev.period_month = v_prev_month
          AND prev.capacity_scope IS NOT DISTINCT FROM v_cap
      ), 0) - row_number() OVER (
        PARTITION BY sub.organization_id ORDER BY sub.production_score DESC
      )::int,
      -- Next tier gap
      CASE
        WHEN sub.production_score >= v_tp THEN 0
        WHEN sub.production_score >= v_tg THEN v_tp - sub.production_score
        WHEN sub.production_score >= v_ts THEN v_tg - sub.production_score
        WHEN sub.production_score >= v_tb THEN v_ts - sub.production_score
        ELSE v_tb - sub.production_score
      END,
      now()
    FROM (
      SELECT
        m.organization_id,
        m.advisor_id,
        -- Score components using configurable weights
        COALESCE(sum(m.total_commissions), 0) * v_cw AS commission_score,
        COALESCE(sum(m.total_enrollments), 0) * v_ew AS enrollment_score,
        COALESCE((
          SELECT sum(dm.total_commissions) * v_dw
          FROM mv_advisor_monthly_performance dm
          WHERE dm.advisor_id IN (SELECT id FROM get_advisor_downline_ids(m.advisor_id))
            AND dm.organization_id = m.organization_id
            AND dm.month = p_month
            AND (v_cap IS NULL OR dm.product_type = v_cap)
        ), 0) AS downline_score,
        -- Growth rate vs prev month
        CASE
          WHEN COALESCE((
            SELECT sum(pm.total_commissions)
            FROM mv_advisor_monthly_performance pm
            WHERE pm.advisor_id = m.advisor_id
              AND pm.organization_id = m.organization_id
              AND pm.month = v_prev_month
              AND (v_cap IS NULL OR pm.product_type = v_cap)
          ), 0) > 0
          THEN (
            (COALESCE(sum(m.total_commissions), 0) -
             COALESCE((
               SELECT sum(pm.total_commissions)
               FROM mv_advisor_monthly_performance pm
               WHERE pm.advisor_id = m.advisor_id
                 AND pm.organization_id = m.organization_id
                 AND pm.month = v_prev_month
                 AND (v_cap IS NULL OR pm.product_type = v_cap)
             ), 0))
            / NULLIF(COALESCE((
               SELECT sum(pm.total_commissions)
               FROM mv_advisor_monthly_performance pm
               WHERE pm.advisor_id = m.advisor_id
                 AND pm.organization_id = m.organization_id
                 AND pm.month = v_prev_month
                 AND (v_cap IS NULL OR pm.product_type = v_cap)
            ), 0), 0) * v_gw
          )
          ELSE 0
        END AS growth_score,
        -- Composite production score
        COALESCE(sum(m.total_commissions), 0) * v_cw
          + COALESCE(sum(m.total_enrollments), 0) * v_ew
          + COALESCE((
              SELECT sum(dm.total_commissions) * v_dw
              FROM mv_advisor_monthly_performance dm
              WHERE dm.advisor_id IN (SELECT id FROM get_advisor_downline_ids(m.advisor_id))
                AND dm.organization_id = m.organization_id
                AND dm.month = p_month
                AND (v_cap IS NULL OR dm.product_type = v_cap)
            ), 0)
          + CASE
              WHEN COALESCE((
                SELECT sum(pm.total_commissions)
                FROM mv_advisor_monthly_performance pm
                WHERE pm.advisor_id = m.advisor_id
                  AND pm.organization_id = m.organization_id
                  AND pm.month = v_prev_month
                  AND (v_cap IS NULL OR pm.product_type = v_cap)
              ), 0) > 0
              THEN (
                (COALESCE(sum(m.total_commissions), 0) -
                 COALESCE((
                   SELECT sum(pm.total_commissions)
                   FROM mv_advisor_monthly_performance pm
                   WHERE pm.advisor_id = m.advisor_id
                     AND pm.organization_id = m.organization_id
                     AND pm.month = v_prev_month
                     AND (v_cap IS NULL OR pm.product_type = v_cap)
                 ), 0))
                / NULLIF(COALESCE((
                   SELECT sum(pm.total_commissions)
                   FROM mv_advisor_monthly_performance pm
                   WHERE pm.advisor_id = m.advisor_id
                     AND pm.organization_id = m.organization_id
                     AND pm.month = v_prev_month
                     AND (v_cap IS NULL OR pm.product_type = v_cap)
                ), 0), 0) * v_gw
              )
              ELSE 0
            END
        AS production_score,
        -- Raw values
        COALESCE(sum(m.total_commissions), 0) AS total_commissions,
        COALESCE(sum(m.total_enrollments), 0)::int AS total_enrollments,
        COALESCE((
          SELECT sum(dm.total_commissions)
          FROM mv_advisor_monthly_performance dm
          WHERE dm.advisor_id IN (SELECT id FROM get_advisor_downline_ids(m.advisor_id))
            AND dm.organization_id = m.organization_id
            AND dm.month = p_month
            AND (v_cap IS NULL OR dm.product_type = v_cap)
        ), 0) AS downline_production,
        -- Growth rate pct
        CASE
          WHEN COALESCE((
            SELECT sum(pm.total_commissions)
            FROM mv_advisor_monthly_performance pm
            WHERE pm.advisor_id = m.advisor_id
              AND pm.organization_id = m.organization_id
              AND pm.month = v_prev_month
              AND (v_cap IS NULL OR pm.product_type = v_cap)
          ), 0) > 0
          THEN round((
            (COALESCE(sum(m.total_commissions), 0) -
             COALESCE((
               SELECT sum(pm.total_commissions)
               FROM mv_advisor_monthly_performance pm
               WHERE pm.advisor_id = m.advisor_id
                 AND pm.organization_id = m.organization_id
                 AND pm.month = v_prev_month
                 AND (v_cap IS NULL OR pm.product_type = v_cap)
             ), 0))
            / NULLIF(COALESCE((
               SELECT sum(pm.total_commissions)
               FROM mv_advisor_monthly_performance pm
               WHERE pm.advisor_id = m.advisor_id
                 AND pm.organization_id = m.organization_id
                 AND pm.month = v_prev_month
                 AND (v_cap IS NULL OR pm.product_type = v_cap)
            ), 0), 0) * 100
          )::numeric, 1)
          ELSE 0
        END AS growth_rate_pct
      FROM mv_advisor_monthly_performance m
      WHERE m.month = p_month
        AND (p_org_id IS NULL OR m.organization_id = p_org_id)
        AND (v_cap IS NULL OR m.product_type = v_cap)
      GROUP BY m.organization_id, m.advisor_id
    ) sub
    ON CONFLICT (advisor_id, period_month, COALESCE(capacity_scope, '__all__'))
    DO UPDATE SET
      commission_score  = EXCLUDED.commission_score,
      enrollment_score  = EXCLUDED.enrollment_score,
      downline_score    = EXCLUDED.downline_score,
      growth_score      = EXCLUDED.growth_score,
      production_score  = EXCLUDED.production_score,
      rank_position     = EXCLUDED.rank_position,
      tier              = EXCLUDED.tier,
      total_commissions = EXCLUDED.total_commissions,
      total_enrollments = EXCLUDED.total_enrollments,
      downline_production = EXCLUDED.downline_production,
      growth_rate_pct   = EXCLUDED.growth_rate_pct,
      streak_months     = EXCLUDED.streak_months,
      prev_rank         = EXCLUDED.prev_rank,
      rank_change       = EXCLUDED.rank_change,
      next_tier_gap     = EXCLUDED.next_tier_gap,
      calculated_at     = now();

    GET DIAGNOSTICS v_cap_count = ROW_COUNT;
    v_count := v_count + v_cap_count;

    -- Generate achievements for tier promotions in this capacity
    INSERT INTO advisor_achievements (
      organization_id, advisor_id, achievement_type,
      title, description,
      capacity_scope, period_month,
      metric_value, prev_value, new_value
    )
    SELECT
      r.organization_id,
      r.advisor_id,
      'tier_promotion',
      initcap(r.tier) || ' Tier Achieved!',
      'Promoted from ' || COALESCE(initcap(prev.tier), 'unranked') || ' to ' || initcap(r.tier)
        || CASE WHEN v_cap IS NOT NULL THEN ' (' || replace(v_cap, '_', ' ') || ')' ELSE '' END,
      v_cap,
      p_month,
      r.production_score,
      prev.tier,
      r.tier
    FROM advisor_rankings r
    LEFT JOIN advisor_rankings prev
      ON prev.advisor_id = r.advisor_id
      AND prev.period_month = v_prev_month
      AND prev.capacity_scope IS NOT DISTINCT FROM v_cap
    WHERE r.period_month = p_month
      AND r.capacity_scope IS NOT DISTINCT FROM v_cap
      AND (p_org_id IS NULL OR r.organization_id = p_org_id)
      -- Tier actually improved
      AND (
        (prev.tier IS NULL AND r.tier IS NOT NULL)
        OR (
          CASE prev.tier
            WHEN 'bronze' THEN 1 WHEN 'silver' THEN 2
            WHEN 'gold' THEN 3 WHEN 'platinum' THEN 4 WHEN 'elite' THEN 5 ELSE 0
          END
          <
          CASE r.tier
            WHEN 'bronze' THEN 1 WHEN 'silver' THEN 2
            WHEN 'gold' THEN 3 WHEN 'platinum' THEN 4 WHEN 'elite' THEN 5 ELSE 0
          END
        )
      )
      -- Don't duplicate: no achievement already logged for this advisor+month+cap
      AND NOT EXISTS (
        SELECT 1 FROM advisor_achievements aa
        WHERE aa.advisor_id = r.advisor_id
          AND aa.period_month = p_month
          AND aa.achievement_type = 'tier_promotion'
          AND aa.capacity_scope IS NOT DISTINCT FROM v_cap
      );

    -- Streak milestones (3, 6, 12 months)
    INSERT INTO advisor_achievements (
      organization_id, advisor_id, achievement_type,
      title, description,
      capacity_scope, period_month, metric_value
    )
    SELECT
      r.organization_id,
      r.advisor_id,
      'streak_milestone',
      r.streak_months || '-Month Top Performer Streak!',
      'Maintained Gold tier or above for ' || r.streak_months || ' consecutive months',
      v_cap,
      p_month,
      r.streak_months
    FROM advisor_rankings r
    WHERE r.period_month = p_month
      AND r.capacity_scope IS NOT DISTINCT FROM v_cap
      AND (p_org_id IS NULL OR r.organization_id = p_org_id)
      AND r.streak_months IN (3, 6, 12, 24)
      AND NOT EXISTS (
        SELECT 1 FROM advisor_achievements aa
        WHERE aa.advisor_id = r.advisor_id
          AND aa.period_month = p_month
          AND aa.achievement_type = 'streak_milestone'
          AND aa.capacity_scope IS NOT DISTINCT FROM v_cap
      );

    -- Top producer badge (rank #1)
    INSERT INTO advisor_achievements (
      organization_id, advisor_id, achievement_type,
      title, description,
      capacity_scope, period_month, metric_value
    )
    SELECT
      r.organization_id,
      r.advisor_id,
      'top_producer',
      '#1 Producer' || CASE WHEN v_cap IS NOT NULL THEN ' — ' || replace(v_cap, '_', ' ') ELSE '' END || '!',
      'Ranked #1 in production for ' || to_char(p_month, 'Month YYYY'),
      v_cap,
      p_month,
      r.production_score
    FROM advisor_rankings r
    WHERE r.period_month = p_month
      AND r.capacity_scope IS NOT DISTINCT FROM v_cap
      AND r.rank_position = 1
      AND (p_org_id IS NULL OR r.organization_id = p_org_id)
      AND NOT EXISTS (
        SELECT 1 FROM advisor_achievements aa
        WHERE aa.advisor_id = r.advisor_id
          AND aa.period_month = p_month
          AND aa.achievement_type = 'top_producer'
          AND aa.capacity_scope IS NOT DISTINCT FROM v_cap
      );

  END LOOP;

  RETURN v_count;
END;
$$;


--
-- Name: refresh_executive_views(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_executive_views() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_start timestamptz;
  v_kpi_ms int;
  v_top_ms int;
BEGIN
  v_start := clock_timestamp();
  REFRESH MATERIALIZED VIEW CONCURRENTLY executive_kpi_mv;
  v_kpi_ms := EXTRACT(MILLISECONDS FROM clock_timestamp() - v_start)::int;

  v_start := clock_timestamp();
  REFRESH MATERIALIZED VIEW CONCURRENTLY executive_top_advisor_mv;
  v_top_ms := EXTRACT(MILLISECONDS FROM clock_timestamp() - v_start)::int;

  RETURN jsonb_build_object(
    'executive_kpi_mv_ms', v_kpi_ms,
    'executive_top_advisor_mv_ms', v_top_ms,
    'refreshed_at', now()
  );
END;
$$;


