--
-- Name: replace_plan_fees(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.replace_plan_fees(p_rate_set_id uuid, p_fees jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_inserted int := 0;
BEGIN
  DELETE FROM public.plan_fees WHERE rate_set_id = p_rate_set_id;

  IF p_fees IS NOT NULL AND jsonb_typeof(p_fees) = 'array' AND jsonb_array_length(p_fees) > 0 THEN
    INSERT INTO public.plan_fees (
      rate_set_id,
      label,
      fee_type,
      amount,
      applies_to,
      enabled,
      sort_order
    )
    SELECT
      p_rate_set_id,
      e->>'label',
      e->>'fee_type',
      (e->>'amount')::numeric,
      COALESCE(e->>'applies_to', 'quote'),
      COALESCE((e->>'enabled')::boolean, true),
      COALESCE((e->>'sort_order')::int, 0)
    FROM jsonb_array_elements(p_fees) AS e;

    GET DIAGNOSTICS v_inserted = ROW_COUNT;
  END IF;

  RETURN v_inserted;
END;
$$;


--
-- Name: FUNCTION replace_plan_fees(p_rate_set_id uuid, p_fees jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.replace_plan_fees(p_rate_set_id uuid, p_fees jsonb) IS 'Atomic replace of plan_fees for a rate set — same delete+insert guarantees.';


--
-- Name: replace_plan_rate_entries(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.replace_plan_rate_entries(p_rate_set_id uuid, p_entries jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_inserted int := 0;
BEGIN
  DELETE FROM public.plan_rate_entries WHERE rate_set_id = p_rate_set_id;

  IF p_entries IS NOT NULL
     AND jsonb_typeof(p_entries) = 'array'
     AND jsonb_array_length(p_entries) > 0
  THEN
    INSERT INTO public.plan_rate_entries (
      rate_set_id,
      coverage_tier,
      age_band_id,
      person_type,
      rate_type,
      amount
    )
    SELECT
      p_rate_set_id,
      e->>'coverage_tier',
      COALESCE(e->>'age_band_id', '_flat'),
      COALESCE(e->>'person_type', 'primary'),
      COALESCE(e->>'rate_type', 'banded'),
      COALESCE((e->>'amount')::numeric, 0)
    FROM jsonb_array_elements(p_entries) AS e;

    GET DIAGNOSTICS v_inserted = ROW_COUNT;
  END IF;

  RETURN v_inserted;
END;
$$;


--
-- Name: FUNCTION replace_plan_rate_entries(p_rate_set_id uuid, p_entries jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.replace_plan_rate_entries(p_rate_set_id uuid, p_entries jsonb) IS 'Atomic replace of plan_rate_entries for a rate set — delete + insert run in one transaction so a failed insert rolls back the delete. Caller passes a JSONB array of {coverage_tier, age_band_id?, person_type?, rate_type?, amount}.';


