--
-- Name: resolve_fraud_flag(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_fraud_flag(p_flag_id uuid, p_actor_id uuid, p_status text, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_flag record;
BEGIN
  IF p_status NOT IN ('resolved', 'dismissed') THEN
    RETURN jsonb_build_object('error', 'Status must be resolved or dismissed');
  END IF;

  SELECT * INTO v_flag
  FROM payout_fraud_flags
  WHERE id = p_flag_id
  FOR UPDATE;

  IF v_flag IS NULL THEN
    RETURN jsonb_build_object('error', 'Flag not found');
  END IF;

  IF v_flag.status NOT IN ('open', 'investigating') THEN
    RETURN jsonb_build_object('error', 'Flag already ' || v_flag.status);
  END IF;

  UPDATE payout_fraud_flags
  SET status = p_status,
      resolved_by = p_actor_id,
      resolved_at = now(),
      resolution_notes = p_notes
  WHERE id = p_flag_id;

  INSERT INTO payout_audit_log (
    organization_id, event_type, entity_type, entity_id,
    actor_id, actor_type, details
  ) VALUES (
    v_flag.organization_id, 'fraud_flag_resolved', 'commission_payout',
    COALESCE(v_flag.batch_id, v_flag.id),
    p_actor_id, 'user',
    jsonb_build_object(
      'flag_id', p_flag_id,
      'flag_type', v_flag.flag_type,
      'resolution', p_status,
      'notes', p_notes
    )
  );

  RETURN jsonb_build_object(
    'flag_id', p_flag_id,
    'status', p_status,
    'resolved_by', p_actor_id
  );
END;
$$;


--
-- Name: revoke_franchise_relationship(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_franchise_relationship(p_parent_org_id uuid, p_child_org_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_del_count int;
BEGIN
  -- Verify caller is in parent org
  IF (SELECT get_user_organization_id()) != p_parent_org_id THEN
    RAISE EXCEPTION 'ACCESS_DENIED: must be in parent org';
  END IF;

  -- Terminate relationship
  UPDATE org_relationships
  SET status = 'terminated', updated_at = now()
  WHERE parent_org_id = p_parent_org_id AND child_org_id = p_child_org_id;

  -- Revoke all delegations
  UPDATE org_delegations
  SET status = 'revoked', updated_at = now()
  WHERE parent_org_id = p_parent_org_id AND child_org_id = p_child_org_id
    AND status = 'active';

  GET DIAGNOSTICS v_del_count = ROW_COUNT;

  RETURN jsonb_build_object(
    'status', 'terminated',
    'delegations_revoked', v_del_count
  );
END;
$$;


--
-- Name: revoke_team_invitation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_team_invitation(p_invitation_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_invitation record;
  v_user_profile record;
BEGIN
  -- Get invitation
  SELECT * INTO v_invitation
  FROM team_invitations
  WHERE id = p_invitation_id;

  IF v_invitation IS NULL THEN
    RAISE EXCEPTION 'Invitation not found';
  END IF;

  -- Get user's profile in the same org
  SELECT id, role INTO v_user_profile
  FROM profiles
  WHERE user_id = auth.uid()
    AND organization_id = v_invitation.organization_id
    AND is_active = true;

  IF v_user_profile IS NULL OR v_user_profile.role NOT IN ('owner', 'super_admin', 'admin') THEN
    RAISE EXCEPTION 'Insufficient permissions';
  END IF;

  -- Revoke invitation
  UPDATE team_invitations
  SET
    status = 'revoked',
    updated_at = now()
  WHERE id = p_invitation_id
    AND status = 'pending';

  RETURN true;
END;
$$;


--
-- Name: rls_auto_enable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rls_auto_enable() RETURNS event_trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$$;


--
-- Name: role_at_least(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.role_at_least(u uuid, min_role text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT public.role_rank(p.role::text) >= public.role_rank(min_role)
  FROM public.profiles p
  WHERE p.id = u;
$$;


--
-- Name: role_at_least(uuid, public.user_role); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.role_at_least(u uuid, min_role public.user_role) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT public.role_at_least(u, min_role::text);
$$;


--
-- Name: role_rank(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.role_rank(r text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT CASE r
    WHEN 'super_admin' THEN 6
    WHEN 'admin' THEN 5
    WHEN 'it' THEN 4
    WHEN 'staff' THEN 3
    WHEN 'advisor' THEN 2
    WHEN 'agent' THEN 3
    WHEN 'requester' THEN 1
    ELSE 1
  END;
$$;


--
-- Name: role_rank(public.user_role); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.role_rank(r public.user_role) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT public.role_rank(r::text);
$$;


--
-- Name: rpc_advisor_active_members_report(uuid, uuid[], boolean, text[], text[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_advisor_active_members_report(p_org_id uuid, p_advisor_ids uuid[] DEFAULT NULL::uuid[], p_include_downline boolean DEFAULT false, p_states text[] DEFAULT NULL::text[], p_plan_names text[] DEFAULT NULL::text[], p_plan_types text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_advisor_ids uuid[];
  v_result jsonb;
BEGIN
  IF p_advisor_ids IS NOT NULL AND p_include_downline THEN
    SELECT array_agg(DISTINCT aid) INTO v_advisor_ids
    FROM (
      SELECT unnest(p_advisor_ids) AS aid
      UNION
      SELECT dl FROM unnest(p_advisor_ids) AS root_id,
        LATERAL get_advisor_downline_ids(root_id) AS dl
    ) expanded;
  ELSE
    v_advisor_ids := p_advisor_ids;
  END IF;

  SELECT jsonb_build_object(
    'rows', COALESCE(jsonb_agg(row_data ORDER BY active_members DESC), '[]'::jsonb),
    'total', COUNT(*)
  ) INTO v_result
  FROM (
    SELECT
      a.id AS advisor_id,
      COUNT(m.id) AS active_members,
      jsonb_build_object(
        'advisor_id', a.id,
        'advisor_name', a.first_name || ' ' || a.last_name,
        'advisor_email', a.email,
        'agency_name', a.agency_name,
        'commission_tier', a.commission_tier,
        'active_members', COUNT(m.id),
        'states', jsonb_agg(DISTINCT m.state) FILTER (WHERE m.state IS NOT NULL),
        'plan_breakdown', jsonb_object_agg(
          COALESCE(e.metadata->>'plan_name', 'Unknown'),
          1
        ) FILTER (WHERE e.id IS NOT NULL)
      ) AS row_data
    FROM advisors a
    LEFT JOIN members m ON m.advisor_id = a.id
      AND m.status = 'active'
      AND (p_states IS NULL OR m.state = ANY(p_states))
    LEFT JOIN enrollments e ON e.member_id = m.id AND e.status = 'active'
    WHERE a.organization_id = p_org_id
      AND (v_advisor_ids IS NULL OR a.id = ANY(v_advisor_ids))
    GROUP BY a.id, a.first_name, a.last_name, a.email, a.agency_name, a.commission_tier
  ) sub;

  RETURN v_result;
END;
$$;


--
-- Name: FUNCTION rpc_advisor_active_members_report(p_org_id uuid, p_advisor_ids uuid[], p_include_downline boolean, p_states text[], p_plan_names text[], p_plan_types text[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rpc_advisor_active_members_report(p_org_id uuid, p_advisor_ids uuid[], p_include_downline boolean, p_states text[], p_plan_names text[], p_plan_types text[]) IS 'Active members per advisor with plan details';


--
-- Name: rpc_advisor_cancellations_report(uuid, uuid[], boolean, date, date, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_advisor_cancellations_report(p_org_id uuid, p_advisor_ids uuid[] DEFAULT NULL::uuid[], p_include_downline boolean DEFAULT false, p_date_start date DEFAULT NULL::date, p_date_end date DEFAULT NULL::date, p_states text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_advisor_ids uuid[];
  v_result jsonb;
BEGIN
  IF p_advisor_ids IS NOT NULL AND p_include_downline THEN
    SELECT array_agg(DISTINCT aid) INTO v_advisor_ids
    FROM (
      SELECT unnest(p_advisor_ids) AS aid
      UNION
      SELECT dl FROM unnest(p_advisor_ids) AS root_id,
        LATERAL get_advisor_downline_ids(root_id) AS dl
    ) expanded;
  ELSE
    v_advisor_ids := p_advisor_ids;
  END IF;

  SELECT jsonb_build_object(
    'rows', COALESCE(jsonb_agg(row_data ORDER BY cancellation_rate DESC), '[]'::jsonb),
    'total', COUNT(*)
  ) INTO v_result
  FROM (
    SELECT
      a.id AS advisor_id,
      CASE WHEN total_count > 0
        THEN ROUND((cancelled_count::numeric / total_count) * 100, 2)
        ELSE 0
      END AS cancellation_rate,
      jsonb_build_object(
        'advisor_id', a.id,
        'advisor_name', a.first_name || ' ' || a.last_name,
        'advisor_email', a.email,
        'agency_name', a.agency_name,
        'total_members', total_count,
        'active_members', active_count,
        'cancelled_count', cancelled_count,
        'terminated_count', terminated_count,
        'cancellation_rate', CASE WHEN total_count > 0
          THEN ROUND((cancelled_count::numeric / total_count) * 100, 2)
          ELSE 0 END
      ) AS row_data
    FROM advisors a
    LEFT JOIN LATERAL (
      SELECT
        COUNT(m.id) AS total_count,
        COUNT(m.id) FILTER (WHERE m.status = 'active') AS active_count,
        COUNT(m.id) FILTER (WHERE m.status IN ('cancelled', 'inactive')) AS cancelled_count,
        COUNT(m.id) FILTER (WHERE m.status = 'terminated') AS terminated_count
      FROM members m
      WHERE m.advisor_id = a.id
        AND (p_states IS NULL OR m.state = ANY(p_states))
        AND (p_date_start IS NULL OR m.termination_date >= p_date_start OR m.status = 'active')
        AND (p_date_end IS NULL OR m.termination_date <= p_date_end OR m.status = 'active')
    ) counts ON true
    WHERE a.organization_id = p_org_id
      AND (v_advisor_ids IS NULL OR a.id = ANY(v_advisor_ids))
  ) sub;

  RETURN v_result;
END;
$$;


--
-- Name: FUNCTION rpc_advisor_cancellations_report(p_org_id uuid, p_advisor_ids uuid[], p_include_downline boolean, p_date_start date, p_date_end date, p_states text[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rpc_advisor_cancellations_report(p_org_id uuid, p_advisor_ids uuid[], p_include_downline boolean, p_date_start date, p_date_end date, p_states text[]) IS 'Cancellations by advisor with churn rate';


--
-- Name: rpc_advisor_enrollment_report(uuid, uuid[], boolean, date, date, text[], text[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_advisor_enrollment_report(p_org_id uuid, p_advisor_ids uuid[] DEFAULT NULL::uuid[], p_include_downline boolean DEFAULT false, p_date_start date DEFAULT NULL::date, p_date_end date DEFAULT NULL::date, p_states text[] DEFAULT NULL::text[], p_plan_names text[] DEFAULT NULL::text[], p_statuses text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_advisor_ids uuid[];
  v_result jsonb;
BEGIN
  -- Expand downline if requested
  IF p_advisor_ids IS NOT NULL AND p_include_downline THEN
    SELECT array_agg(DISTINCT aid) INTO v_advisor_ids
    FROM (
      SELECT unnest(p_advisor_ids) AS aid
      UNION
      SELECT dl FROM unnest(p_advisor_ids) AS root_id,
        LATERAL get_advisor_downline_ids(root_id) AS dl
    ) expanded;
  ELSE
    v_advisor_ids := p_advisor_ids;
  END IF;

  SELECT jsonb_build_object(
    'rows', COALESCE(jsonb_agg(row_data ORDER BY total_enrollments DESC), '[]'::jsonb),
    'total', COUNT(*)
  ) INTO v_result
  FROM (
    SELECT
      a.id AS advisor_id,
      a.first_name || ' ' || a.last_name AS advisor_name,
      a.email AS advisor_email,
      a.agency_name,
      a.commission_tier,
      COUNT(e.id) AS total_enrollments,
      COUNT(e.id) FILTER (WHERE e.status = 'active') AS active_count,
      COUNT(e.id) FILTER (WHERE e.status = 'pending') AS pending_count,
      COUNT(e.id) FILTER (WHERE e.status = 'cancelled') AS cancelled_count,
      COUNT(e.id) FILTER (WHERE e.status = 'terminated') AS terminated_count,
      COUNT(e.id) FILTER (WHERE e.status = 'inactive') AS inactive_count,
      jsonb_build_object(
        'advisor_id', a.id,
        'advisor_name', a.first_name || ' ' || a.last_name,
        'advisor_email', a.email,
        'agency_name', a.agency_name,
        'commission_tier', a.commission_tier,
        'total_enrollments', COUNT(e.id),
        'active', COUNT(e.id) FILTER (WHERE e.status = 'active'),
        'pending', COUNT(e.id) FILTER (WHERE e.status = 'pending'),
        'cancelled', COUNT(e.id) FILTER (WHERE e.status = 'cancelled'),
        'terminated', COUNT(e.id) FILTER (WHERE e.status = 'terminated'),
        'inactive', COUNT(e.id) FILTER (WHERE e.status = 'inactive')
      ) AS row_data
    FROM advisors a
    LEFT JOIN enrollments e ON e.advisor_id = a.id
      AND (p_date_start IS NULL OR e.enrollment_date >= p_date_start)
      AND (p_date_end IS NULL OR e.enrollment_date <= p_date_end)
      AND (p_statuses IS NULL OR e.status = ANY(p_statuses))
    LEFT JOIN members m ON e.member_id = m.id
      AND (p_states IS NULL OR m.state = ANY(p_states))
    WHERE a.organization_id = p_org_id
      AND (v_advisor_ids IS NULL OR a.id = ANY(v_advisor_ids))
      AND (p_states IS NULL OR m.id IS NOT NULL)
    GROUP BY a.id, a.first_name, a.last_name, a.email, a.agency_name, a.commission_tier
  ) sub;

  RETURN v_result;
END;
$$;


--
-- Name: FUNCTION rpc_advisor_enrollment_report(p_org_id uuid, p_advisor_ids uuid[], p_include_downline boolean, p_date_start date, p_date_end date, p_states text[], p_plan_names text[], p_statuses text[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rpc_advisor_enrollment_report(p_org_id uuid, p_advisor_ids uuid[], p_include_downline boolean, p_date_start date, p_date_end date, p_states text[], p_plan_names text[], p_statuses text[]) IS 'Enrollments grouped by advisor with status breakdown';


--
-- Name: rpc_advisor_retention_widget(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_advisor_retention_widget(p_org_id uuid, p_months integer DEFAULT 6) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE v_result jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'month', TO_CHAR(month_date, 'YYYY-MM'),
      'retention_rate', ROUND(
        CASE WHEN total_count > 0
          THEN (active_count::numeric / total_count) * 100
          ELSE 0
        END, 1),
      'active_count', active_count,
      'total_count', total_count
    ) ORDER BY month_date
  ), '[]'::jsonb)
  INTO v_result
  FROM (
    SELECT
      gs.month_date,
      COUNT(m.id) AS total_count,
      COUNT(m.id) FILTER (WHERE
        m.status = 'active'
        OR (m.termination_date IS NOT NULL AND m.termination_date > gs.month_date + interval '1 month')
      ) AS active_count
    FROM generate_series(
      date_trunc('month', CURRENT_DATE - (p_months || ' months')::interval)::date,
      date_trunc('month', CURRENT_DATE)::date,
      '1 month'::interval
    ) AS gs(month_date)
    LEFT JOIN members m ON m.organization_id = p_org_id
      AND m.effective_date <= gs.month_date + interval '1 month'
      AND (m.termination_date IS NULL OR m.termination_date >= gs.month_date)
    LEFT JOIN advisors a ON a.id = m.advisor_id AND a.organization_id = p_org_id
    WHERE a.id IS NOT NULL  -- Only count members with advisors
    GROUP BY gs.month_date
  ) monthly;

  RETURN jsonb_build_object('months', v_result);
END;
$$;


--
-- Name: FUNCTION rpc_advisor_retention_widget(p_org_id uuid, p_months integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rpc_advisor_retention_widget(p_org_id uuid, p_months integer) IS 'Monthly retention time-series for dashboard widget';


--
-- Name: rpc_advisor_revenue_report(uuid, uuid[], boolean, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_advisor_revenue_report(p_org_id uuid, p_advisor_ids uuid[] DEFAULT NULL::uuid[], p_include_downline boolean DEFAULT false, p_date_start date DEFAULT NULL::date, p_date_end date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_advisor_ids uuid[];
  v_result jsonb;
BEGIN
  IF p_advisor_ids IS NOT NULL AND p_include_downline THEN
    SELECT array_agg(DISTINCT aid) INTO v_advisor_ids
    FROM (
      SELECT unnest(p_advisor_ids) AS aid
      UNION
      SELECT dl FROM unnest(p_advisor_ids) AS root_id,
        LATERAL get_advisor_downline_ids(root_id) AS dl
    ) expanded;
  ELSE
    v_advisor_ids := p_advisor_ids;
  END IF;

  SELECT jsonb_build_object(
    'rows', COALESCE(jsonb_agg(row_data ORDER BY gross_commissions DESC), '[]'::jsonb),
    'total', COUNT(*)
  ) INTO v_result
  FROM (
    SELECT
      a.id AS advisor_id,
      COALESCE(SUM(s.gross_commissions), 0) AS gross_commissions,
      jsonb_build_object(
        'advisor_id', a.id,
        'advisor_name', a.first_name || ' ' || a.last_name,
        'advisor_email', a.email,
        'agency_name', a.agency_name,
        'commission_tier', a.commission_tier,
        'signup_commissions', COALESCE(SUM(s.signup_commissions), 0),
        'monthly_commissions', COALESCE(SUM(s.monthly_commissions), 0),
        'override_commissions', COALESCE(SUM(s.override_commissions), 0),
        'bonus_commissions', COALESCE(SUM(s.bonus_commissions), 0),
        'adjustments', COALESCE(SUM(s.adjustments), 0),
        'clawbacks', COALESCE(SUM(s.clawbacks), 0),
        'gross_commissions', COALESCE(SUM(s.gross_commissions), 0),
        'net_commissions', COALESCE(SUM(s.net_commissions), 0),
        'total_enrollments', COALESCE(SUM(s.total_enrollments), 0),
        'active_members', MAX(s.active_members)
      ) AS row_data
    FROM advisors a
    LEFT JOIN advisor_commission_summary s ON s.advisor_id = a.id
      AND (p_date_start IS NULL OR s.period_month >= p_date_start)
      AND (p_date_end IS NULL OR s.period_month <= p_date_end)
    WHERE a.organization_id = p_org_id
      AND (v_advisor_ids IS NULL OR a.id = ANY(v_advisor_ids))
    GROUP BY a.id, a.first_name, a.last_name, a.email, a.agency_name, a.commission_tier
  ) sub;

  RETURN v_result;
END;
$$;


--
-- Name: FUNCTION rpc_advisor_revenue_report(p_org_id uuid, p_advisor_ids uuid[], p_include_downline boolean, p_date_start date, p_date_end date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rpc_advisor_revenue_report(p_org_id uuid, p_advisor_ids uuid[], p_include_downline boolean, p_date_start date, p_date_end date) IS 'Commission revenue per advisor by type';


--
-- Name: rpc_lowest_churn_advisors_widget(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_lowest_churn_advisors_widget(p_org_id uuid, p_limit integer DEFAULT 5) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE v_result jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(row_data ORDER BY churn_rate ASC), '[]'::jsonb)
  INTO v_result
  FROM (
    SELECT
      jsonb_build_object(
        'advisor_id', a.id,
        'name', a.first_name || ' ' || a.last_name,
        'agency_name', a.agency_name,
        'churn_rate', ROUND(
          CASE WHEN total_members > 0
            THEN (cancelled_count::numeric / total_members) * 100
            ELSE 0
          END, 2),
        'total_members', total_members,
        'cancelled_count', cancelled_count,
        'active_members', active_count
      ) AS row_data,
      CASE WHEN total_members > 0
        THEN (cancelled_count::numeric / total_members) * 100
        ELSE 0
      END AS churn_rate
    FROM advisors a
    LEFT JOIN LATERAL (
      SELECT
        COUNT(m.id) AS total_members,
        COUNT(m.id) FILTER (WHERE m.status = 'active') AS active_count,
        COUNT(m.id) FILTER (WHERE m.status IN ('cancelled', 'inactive', 'terminated')) AS cancelled_count
      FROM members m
      WHERE m.advisor_id = a.id
    ) mc ON true
    WHERE a.organization_id = p_org_id
      AND a.status = 'active'
      AND mc.total_members >= 5  -- Minimum threshold to avoid noise
    ORDER BY churn_rate ASC
    LIMIT p_limit
  ) sub;

  RETURN jsonb_build_object('advisors', v_result);
END;
$$;


--
-- Name: FUNCTION rpc_lowest_churn_advisors_widget(p_org_id uuid, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rpc_lowest_churn_advisors_widget(p_org_id uuid, p_limit integer) IS 'Advisors with lowest churn rate for dashboard widget';


--
-- Name: rpc_top_advisors_widget(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_top_advisors_widget(p_org_id uuid, p_metric text DEFAULT 'enrollments'::text, p_limit integer DEFAULT 5) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
  v_period date := date_trunc('month', CURRENT_DATE)::date;
BEGIN
  IF p_metric = 'revenue' THEN
    SELECT COALESCE(jsonb_agg(row_data ORDER BY value DESC), '[]'::jsonb)
    INTO v_result
    FROM (
      SELECT jsonb_build_object(
        'advisor_id', a.id,
        'name', a.first_name || ' ' || a.last_name,
        'agency_name', a.agency_name,
        'value', COALESCE(s.gross_commissions, 0),
        'metric', 'revenue'
      ) AS row_data,
      COALESCE(s.gross_commissions, 0) AS value
      FROM advisors a
      LEFT JOIN advisor_commission_summary s
        ON s.advisor_id = a.id AND s.period_month = v_period
      WHERE a.organization_id = p_org_id AND a.status = 'active'
      ORDER BY value DESC
      LIMIT p_limit
    ) sub;
  ELSE
    -- Default: enrollments
    SELECT COALESCE(jsonb_agg(row_data ORDER BY value DESC), '[]'::jsonb)
    INTO v_result
    FROM (
      SELECT jsonb_build_object(
        'advisor_id', a.id,
        'name', a.first_name || ' ' || a.last_name,
        'agency_name', a.agency_name,
        'value', COUNT(e.id),
        'metric', 'enrollments'
      ) AS row_data,
      COUNT(e.id) AS value
      FROM advisors a
      LEFT JOIN enrollments e ON e.advisor_id = a.id
        AND e.enrollment_date >= v_period
        AND e.enrollment_date < (v_period + interval '1 month')::date
      WHERE a.organization_id = p_org_id AND a.status = 'active'
      GROUP BY a.id, a.first_name, a.last_name, a.agency_name
      ORDER BY value DESC
      LIMIT p_limit
    ) sub;
  END IF;

  RETURN jsonb_build_object('advisors', v_result, 'period', v_period, 'metric', p_metric);
END;
$$;


--
-- Name: FUNCTION rpc_top_advisors_widget(p_org_id uuid, p_metric text, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rpc_top_advisors_widget(p_org_id uuid, p_metric text, p_limit integer) IS 'Top N advisors by enrollments or revenue for dashboard widget';


