--
-- Name: search_in_network_providers(uuid, text, text, text, numeric, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_in_network_providers(p_network_id uuid, p_zip_code text, p_service_category text DEFAULT NULL::text, p_tier text DEFAULT NULL::text, p_radius_miles numeric DEFAULT 50, p_limit integer DEFAULT 20) RETURNS TABLE(provider_id uuid, provider_name text, provider_type text, address text, city text, state text, zip text, phone text, latitude numeric, longitude numeric, network_tier text, tier_discount_pct numeric, specialty_tags text[], accepting_new_patients boolean, distance_miles numeric, source_table text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_lat numeric;
  v_lng numeric;
BEGIN
  -- Resolve ZIP center from existing locations
  SELECT hl.latitude, hl.longitude INTO v_lat, v_lng
  FROM healthcare_locations hl
  WHERE hl.zip = p_zip_code AND hl.latitude IS NOT NULL AND hl.is_active = true
  LIMIT 1;

  IF v_lat IS NULL THEN
    SELECT pl.latitude, pl.longitude INTO v_lat, v_lng
    FROM provider_locations pl
    WHERE pl.zip = p_zip_code AND pl.latitude IS NOT NULL AND pl.is_active = true
    LIMIT 1;
  END IF;

  RETURN QUERY
  (
    -- Healthcare locations branch
    SELECT
      np.id                     AS provider_id,
      hl.name                   AS provider_name,
      hl.location_type          AS provider_type,
      hl.address_line1          AS address,
      hl.city,
      hl.state,
      hl.zip,
      hl.phone,
      hl.latitude,
      hl.longitude,
      np.network_tier,
      np.tier_discount_pct,
      np.specialty_tags,
      COALESCE(np.accepting_new_patients, hl.accepting_new_patients) AS accepting_new_patients,
      CASE
        WHEN v_lat IS NOT NULL AND hl.latitude IS NOT NULL THEN
          ROUND(
            (3959.0 * acos(
              LEAST(1.0,
                cos(radians(v_lat)) * cos(radians(hl.latitude)) *
                cos(radians(hl.longitude) - radians(v_lng)) +
                sin(radians(v_lat)) * sin(radians(hl.latitude))
              )
            ))::numeric, 1
          )
        ELSE NULL
      END                       AS distance_miles,
      'healthcare_locations'::text AS source_table
    FROM network_providers np
    INNER JOIN healthcare_locations hl ON hl.id = np.healthcare_location_id
    WHERE np.network_id = p_network_id
      AND np.is_active = true
      AND hl.is_active = true
      AND (np.end_date IS NULL OR np.end_date > CURRENT_DATE)
      AND (p_tier IS NULL OR np.network_tier = p_tier)
      AND (
        p_service_category IS NULL
        OR p_service_category = ANY(np.specialty_tags)
        OR EXISTS (
          SELECT 1 FROM healthcare_location_services hls
          JOIN healthcare_services hs ON hs.id = hls.service_id
          WHERE hls.location_id = hl.id AND hs.service_category = p_service_category
        )
      )
      AND (
        v_lat IS NULL OR hl.latitude IS NULL
        OR (3959.0 * acos(
            LEAST(1.0,
              cos(radians(v_lat)) * cos(radians(hl.latitude)) *
              cos(radians(hl.longitude) - radians(v_lng)) +
              sin(radians(v_lat)) * sin(radians(hl.latitude))
            )
          ) <= p_radius_miles)
      )

    UNION ALL

    -- Provider locations branch
    SELECT
      np.id                     AS provider_id,
      pl.name                   AS provider_name,
      pl.provider_type,
      pl.address_line1          AS address,
      pl.city,
      pl.state,
      pl.zip,
      pl.phone,
      pl.latitude,
      pl.longitude,
      np.network_tier,
      np.tier_discount_pct,
      np.specialty_tags,
      COALESCE(np.accepting_new_patients, pl.accepting_patients) AS accepting_new_patients,
      CASE
        WHEN v_lat IS NOT NULL AND pl.latitude IS NOT NULL THEN
          ROUND(
            (3959.0 * acos(
              LEAST(1.0,
                cos(radians(v_lat)) * cos(radians(pl.latitude)) *
                cos(radians(pl.longitude) - radians(v_lng)) +
                sin(radians(v_lat)) * sin(radians(pl.latitude))
              )
            ))::numeric, 1
          )
        ELSE NULL
      END                       AS distance_miles,
      'provider_locations'::text AS source_table
    FROM network_providers np
    INNER JOIN provider_locations pl ON pl.id = np.provider_location_id
    WHERE np.network_id = p_network_id
      AND np.healthcare_location_id IS NULL  -- avoid double-counting
      AND np.is_active = true
      AND pl.is_active = true
      AND (np.end_date IS NULL OR np.end_date > CURRENT_DATE)
      AND (p_tier IS NULL OR np.network_tier = p_tier)
      AND (p_service_category IS NULL OR p_service_category = ANY(np.specialty_tags))
      AND (
        v_lat IS NULL OR pl.latitude IS NULL
        OR (3959.0 * acos(
            LEAST(1.0,
              cos(radians(v_lat)) * cos(radians(pl.latitude)) *
              cos(radians(pl.longitude) - radians(v_lng)) +
              sin(radians(v_lat)) * sin(radians(pl.latitude))
            )
          ) <= p_radius_miles)
      )
  )
  ORDER BY
    CASE network_tier
      WHEN 'in_network_preferred' THEN 1
      WHEN 'in_network' THEN 2
      WHEN 'out_of_network' THEN 3
    END,
    distance_miles ASC NULLS LAST
  LIMIT p_limit;
END;
$$;


--
-- Name: FUNCTION search_in_network_providers(p_network_id uuid, p_zip_code text, p_service_category text, p_tier text, p_radius_miles numeric, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.search_in_network_providers(p_network_id uuid, p_zip_code text, p_service_category text, p_tier text, p_radius_miles numeric, p_limit integer) IS 'Find in-network providers near a ZIP, sorted by tier then distance';


--
-- Name: search_members_with_dependents(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_members_with_dependents(p_org_id uuid, p_search text) RETURNS SETOF uuid
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  -- Members whose own name matches
  SELECT id FROM members
  WHERE organization_id = p_org_id
    AND (
      first_name ILIKE '%' || p_search || '%'
      OR last_name ILIKE '%' || p_search || '%'
      OR email ILIKE '%' || p_search || '%'
      OR (first_name || ' ' || last_name) ILIKE '%' || p_search || '%'
    )
  UNION
  -- Members who have a dependent whose name matches
  SELECT d.member_id FROM dependents d
  WHERE d.organization_id = p_org_id
    AND (
      d.first_name ILIKE '%' || p_search || '%'
      OR d.last_name ILIKE '%' || p_search || '%'
      OR (d.first_name || ' ' || d.last_name) ILIKE '%' || p_search || '%'
    )
$$;


--
-- Name: search_procedure_prices(text, text, text, numeric, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_procedure_prices(p_zip_code text, p_procedure_name text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_radius_miles numeric DEFAULT 50, p_limit integer DEFAULT 20) RETURNS TABLE(procedure_id uuid, procedure_code text, procedure_name text, category text, avg_national_price numeric, provider_location_id uuid, provider_name text, provider_type text, address text, city text, state text, zip text, phone text, latitude numeric, longitude numeric, cash_price numeric, discounted_price numeric, price_range_low numeric, price_range_high numeric, distance_miles numeric, rating numeric, review_count integer, last_verified_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_lat numeric;
  v_lng numeric;
BEGIN
  -- Resolve ZIP to approximate lat/lng from provider_locations
  SELECT pl.latitude, pl.longitude INTO v_lat, v_lng
  FROM provider_locations pl
  WHERE pl.zip = p_zip_code AND pl.latitude IS NOT NULL
  LIMIT 1;

  -- Fall back to healthcare_locations
  IF v_lat IS NULL THEN
    SELECT hl.latitude, hl.longitude INTO v_lat, v_lng
    FROM healthcare_locations hl
    WHERE hl.zip = p_zip_code AND hl.latitude IS NOT NULL
    LIMIT 1;
  END IF;

  RETURN QUERY
  SELECT
    mp.id                   AS procedure_id,
    mp.procedure_code,
    mp.procedure_name,
    mp.category,
    mp.avg_national_price,
    pl.id                   AS provider_location_id,
    pl.name                 AS provider_name,
    pl.provider_type,
    pl.address_line1        AS address,
    pl.city,
    pl.state,
    pl.zip,
    pl.phone,
    pl.latitude,
    pl.longitude,
    pp.cash_price,
    pp.discounted_price,
    pp.price_range_low,
    pp.price_range_high,
    CASE
      WHEN v_lat IS NOT NULL AND pl.latitude IS NOT NULL THEN
        ROUND(
          (3959.0 * acos(
            LEAST(1.0,
              cos(radians(v_lat)) * cos(radians(pl.latitude)) *
              cos(radians(pl.longitude) - radians(v_lng)) +
              sin(radians(v_lat)) * sin(radians(pl.latitude))
            )
          ))::numeric, 1
        )
      ELSE NULL
    END                     AS distance_miles,
    pl.rating,
    pl.review_count,
    pp.last_verified_at
  FROM procedure_prices pp
  INNER JOIN medical_procedures mp ON mp.id = pp.procedure_id
  INNER JOIN provider_locations pl ON pl.id = pp.provider_location_id
  WHERE pp.is_active = true
    AND mp.is_active = true
    AND pl.is_active = true
    AND (
      p_procedure_name IS NULL
      OR mp.procedure_name ILIKE '%' || p_procedure_name || '%'
      OR mp.procedure_code ILIKE '%' || p_procedure_name || '%'
      OR p_procedure_name = ANY(mp.search_keywords)
    )
    AND (p_category IS NULL OR mp.category = p_category)
    AND (
      v_lat IS NULL OR pl.latitude IS NULL
      OR (
        3959.0 * acos(
          LEAST(1.0,
            cos(radians(v_lat)) * cos(radians(pl.latitude)) *
            cos(radians(pl.longitude) - radians(v_lng)) +
            sin(radians(v_lat)) * sin(radians(pl.latitude))
          )
        ) <= p_radius_miles
      )
    )
  ORDER BY
    CASE WHEN v_lat IS NOT NULL AND pl.latitude IS NOT NULL THEN
      3959.0 * acos(
        LEAST(1.0,
          cos(radians(v_lat)) * cos(radians(pl.latitude)) *
          cos(radians(pl.longitude) - radians(v_lng)) +
          sin(radians(v_lat)) * sin(radians(pl.latitude))
        )
      )
    ELSE 99999 END,
    pp.cash_price ASC
  LIMIT p_limit;
END;
$$;


--
-- Name: seed_default_deal_stages(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seed_default_deal_stages(p_org_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM profiles WHERE user_id = auth.uid() AND organization_id = p_org_id
  ) THEN
    RAISE EXCEPTION 'Unauthorized: caller does not belong to this organization';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM crm_deal_stages WHERE organization_id = p_org_id) THEN
    INSERT INTO crm_deal_stages (organization_id, key, name, color, probability, is_won, is_lost, display_order)
    VALUES
      (p_org_id, 'qualification', 'Qualification', '#8b5cf6', 10, false, false, 1),
      (p_org_id, 'needs_analysis', 'Needs Analysis', '#6366f1', 25, false, false, 2),
      (p_org_id, 'proposal', 'Proposal', '#3b82f6', 50, false, false, 3),
      (p_org_id, 'negotiation', 'Negotiation', '#0ea5e9', 75, false, false, 4),
      (p_org_id, 'closed_won', 'Closed Won', '#22c55e', 100, true, false, 5),
      (p_org_id, 'closed_lost', 'Closed Lost', '#ef4444', 0, false, true, 6);
  END IF;
END;
$$;


