--
-- Name: send_email_notification_on_comment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_email_notification_on_comment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ticket record;
  v_author record;
  v_email text;
  v_name text;
  v_template record;
  v_subject text;
  v_body_text text;
  v_body_html text;
BEGIN
  -- Only send email for non-internal comments
  IF NEW.is_internal = true THEN
    RETURN NEW;
  END IF;
  
  -- Get ticket details
  SELECT t.*, p.email AS requester_email, p.full_name AS requester_name
  INTO v_ticket
  FROM tickets t
  LEFT JOIN profiles p ON t.requester_id = p.id
  WHERE t.id = NEW.ticket_id;
  
  IF v_ticket IS NULL THEN
    RETURN NEW;
  END IF;
  
  -- Determine recipient email (requester or anonymous submitter)
  v_email := COALESCE(v_ticket.requester_email, v_ticket.submitter_email);
  
  IF v_email IS NULL OR v_email = '' THEN
    RETURN NEW;
  END IF;
  
  v_name := COALESCE(v_ticket.requester_name, v_ticket.submitter_name, 'Valued Customer');
  
  -- Get author details
  SELECT full_name, email INTO v_author
  FROM profiles
  WHERE id = NEW.author_id;
  
  -- Get email template
  SELECT * INTO v_template
  FROM email_templates
  WHERE template_type = 'staff_reply' AND is_active = true
  LIMIT 1;
  
  IF v_template IS NOT NULL THEN
    -- Replace variables in template
    v_subject := v_template.subject;
    v_subject := replace(v_subject, '{{ticket_number}}', substring(v_ticket.id::text, 1, 8));
    
    v_body_text := v_template.body_text;
    v_body_text := replace(v_body_text, '{{requester_name}}', v_name);
    v_body_text := replace(v_body_text, '{{staff_name}}', COALESCE(v_author.full_name, 'Support Team'));
    v_body_text := replace(v_body_text, '{{comment_body}}', NEW.body);
    v_body_text := replace(v_body_text, '{{ticket_number}}', substring(v_ticket.id::text, 1, 8));
    v_body_text := replace(v_body_text, '{{ticket_subject}}', v_ticket.subject);
    v_body_text := replace(v_body_text, '{{ticket_status}}', v_ticket.status);
    
    v_body_html := v_template.body_html;
    v_body_html := replace(v_body_html, '{{requester_name}}', v_name);
    v_body_html := replace(v_body_html, '{{staff_name}}', COALESCE(v_author.full_name, 'Support Team'));
    v_body_html := replace(v_body_html, '{{comment_body}}', replace(NEW.body, E'\n', '<br>'));
    v_body_html := replace(v_body_html, '{{ticket_number}}', substring(v_ticket.id::text, 1, 8));
    v_body_html := replace(v_body_html, '{{ticket_subject}}', v_ticket.subject);
    v_body_html := replace(v_body_html, '{{ticket_status}}', v_ticket.status);
  ELSE
    -- Fallback if no template
    v_subject := 'Update on Your Support Ticket - #' || substring(v_ticket.id::text, 1, 8);
    v_body_text := 'Hello ' || v_name || ',

' || COALESCE(v_author.full_name, 'Our support team') || ' has replied to your support ticket:

' || NEW.body || '

Ticket Details:
- Ticket ID: #' || substring(v_ticket.id::text, 1, 8) || '
- Subject: ' || v_ticket.subject || '
- Status: ' || v_ticket.status;
  END IF;
  
  -- Create email notification
  INSERT INTO ticket_email_notifications (
    ticket_id,
    recipient_email,
    recipient_name,
    notification_type,
    subject,
    body_text,
    body_html,
    status,
    metadata
  ) VALUES (
    v_ticket.id,
    v_email,
    v_name,
    'staff_reply',
    v_subject,
    v_body_text,
    v_body_html,
    'pending',
    jsonb_build_object(
      'comment_id', NEW.id,
      'author_id', NEW.author_id,
      'author_name', COALESCE(v_author.full_name, 'Support Team'),
      'triggered_by', 'staff_reply'
    )
  );
  
  -- Update ticket's last_email_sent_at
  UPDATE tickets
  SET last_email_sent_at = now()
  WHERE id = v_ticket.id;
  
  -- Log activity
  PERFORM create_activity_log_entry(
    v_ticket.id,
    'email_sent',
    NEW.author_id,
    jsonb_build_object(
      'comment_id', NEW.id,
      'recipient', v_email,
      'subject', v_subject
    )
  );
  
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION send_email_notification_on_comment(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.send_email_notification_on_comment() IS 'Sends email notification to ticket requester when staff replies (non-internal only)';


--
-- Name: set_record_title(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_record_title() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  -- Regenerate title from data on INSERT, or on UPDATE when data changed
  IF TG_OP = 'INSERT' OR (TG_OP = 'UPDATE' AND NEW.data IS DISTINCT FROM OLD.data) THEN
    NEW.title := generate_record_title(NEW.data);
  END IF;

  -- Also extract email and phone if present
  IF NEW.email IS NULL AND NEW.data->>'email' IS NOT NULL THEN
    NEW.email := NEW.data->>'email';
  END IF;

  IF NEW.phone IS NULL THEN
    NEW.phone := coalesce(NEW.data->>'phone', NEW.data->>'mobile');
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: set_super_admin_active_org(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_super_admin_active_org(p_org_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_profile_id uuid;
  v_is_super boolean;
BEGIN
  SELECT id, is_super_admin 
  INTO v_profile_id, v_is_super
  FROM public.profiles 
  WHERE user_id = auth.uid() 
  LIMIT 1;
  
  IF v_is_super IS NOT TRUE THEN
    RAISE EXCEPTION 'Only super admins can switch organizations';
  END IF;
  
  INSERT INTO public.super_admin_sessions (profile_id, active_organization_id)
  VALUES (v_profile_id, p_org_id)
  ON CONFLICT (profile_id) 
  DO UPDATE SET active_organization_id = p_org_id, updated_at = now();
  
  RETURN true;
END;
$$;


--
-- Name: FUNCTION set_super_admin_active_org(p_org_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_super_admin_active_org(p_org_id uuid) IS 'Sets the active organization for a super admin session';


