--
-- Name: shift_sequence_steps(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.shift_sequence_steps(p_sequence_id uuid, p_from_order integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE email_sequence_steps
  SET step_order = step_order + 1
  WHERE sequence_id = p_sequence_id
    AND step_order >= p_from_order;
END;
$$;


--
-- Name: staff_logs_search_vector_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_logs_search_vector_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  NEW.search_vector := 
    setweight(to_tsvector('english', COALESCE(NEW.title, '')), 'A') ||
    setweight(to_tsvector('english', COALESCE(NEW.description, '')), 'B') ||
    setweight(to_tsvector('english', COALESCE(NEW.project_name, '')), 'C') ||
    setweight(to_tsvector('english', COALESCE(NEW.software_component, '')), 'C') ||
    setweight(to_tsvector('english', COALESCE(array_to_string(NEW.tags, ' '), '')), 'B');
  RETURN NEW;
END;
$$;


--
-- Name: sync_advisor_to_crm_records(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_advisor_to_crm_records() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_module_id uuid;
  v_owner_id uuid;
  v_org_id uuid;
  v_data jsonb;
BEGIN
  -- Determine the org_id (advisors table uses organization_id)
  IF TG_OP = 'DELETE' THEN
    v_org_id := OLD.organization_id;
  ELSE
    v_org_id := NEW.organization_id;
  END IF;

  -- Find the "advisors" CRM module for this org
  SELECT id INTO v_module_id
    FROM crm_modules
    WHERE organization_id = v_org_id AND key = 'advisors';

  IF v_module_id IS NULL THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    ELSE
      RETURN NEW;
    END IF;
  END IF;

  -- Get owner (profile_id of the advisor)
  IF TG_OP != 'DELETE' THEN
    v_owner_id := NEW.profile_id;
  END IF;

  IF TG_OP = 'INSERT' THEN
    v_data := jsonb_build_object(
      'advisor_code', NEW.advisor_code,
      'first_name', NEW.first_name,
      'last_name', NEW.last_name,
      'agency_name', NEW.agency_name,
      'license_number', NEW.license_number,
      'npn', NEW.npn,
      'commission_tier', NEW.commission_tier,
      'enrollment_code', NEW.enrollment_code,
      'contract_date', NEW.contract_date,
      'primary_channel', NEW.primary_channel,
      'agent_role', NEW.agent_role
    );

    INSERT INTO crm_records (
      organization_id, module_id, owner_id,
      title, status, email, phone,
      data, system,
      created_at, updated_at
    ) VALUES (
      v_org_id,
      v_module_id,
      v_owner_id,
      NEW.first_name || ' ' || NEW.last_name,
      NEW.status,
      NEW.email,
      NEW.phone,
      v_data,
      jsonb_build_object(
        'source_table', 'advisors',
        'source_id', NEW.id::text,
        'advisor_code', NEW.advisor_code,
        'synced', true
      ),
      NEW.created_at,
      now()
    );

  ELSIF TG_OP = 'UPDATE' THEN
    v_data := jsonb_build_object(
      'advisor_code', NEW.advisor_code,
      'first_name', NEW.first_name,
      'last_name', NEW.last_name,
      'agency_name', NEW.agency_name,
      'license_number', NEW.license_number,
      'npn', NEW.npn,
      'commission_tier', NEW.commission_tier,
      'enrollment_code', NEW.enrollment_code,
      'contract_date', NEW.contract_date,
      'primary_channel', NEW.primary_channel,
      'agent_role', NEW.agent_role
    );

    UPDATE crm_records SET
      title = NEW.first_name || ' ' || NEW.last_name,
      status = NEW.status,
      email = NEW.email,
      phone = NEW.phone,
      data = v_data,
      owner_id = v_owner_id,
      updated_at = now()
    WHERE module_id = v_module_id
      AND system->>'source_table' = 'advisors'
      AND system->>'source_id' = NEW.id::text;

  ELSIF TG_OP = 'DELETE' THEN
    DELETE FROM crm_records
    WHERE module_id = v_module_id
      AND system->>'source_table' = 'advisors'
      AND system->>'source_id' = OLD.id::text;

    RETURN OLD;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: sync_billing_schedule_on_enrollment_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_billing_schedule_on_enrollment_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  IF NEW.base_monthly_cost IS DISTINCT FROM OLD.base_monthly_cost THEN
    UPDATE billing_schedules
    SET amount = NEW.base_monthly_cost,
        updated_at = now()
    WHERE enrollment_id = NEW.id
      AND status = 'active';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: sync_email_from_auth(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_email_from_auth() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  NEW.email := (SELECT email FROM auth.users WHERE id = NEW.id);
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


--
-- Name: sync_enrollment_to_crm_records(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_enrollment_to_crm_records() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_module_id uuid;
  v_market_type text;
  v_carrier_id uuid;
  v_plan_name text;
  v_data_patch jsonb;
BEGIN
  IF TG_OP = 'UPDATE'
    AND OLD.status = NEW.status
    AND OLD.selected_plan_id IS NOT DISTINCT FROM NEW.selected_plan_id
  THEN
    RETURN NEW;
  END IF;

  IF NEW.status NOT IN ('submitted', 'approved', 'active') THEN
    RETURN NEW;
  END IF;

  IF NEW.primary_member_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT id INTO v_module_id
    FROM crm_modules WHERE organization_id = NEW.organization_id AND key = 'members';

  IF v_module_id IS NULL THEN RETURN NEW; END IF;

  IF NEW.selected_plan_id IS NOT NULL THEN
    SELECT name INTO v_plan_name FROM plans WHERE id = NEW.selected_plan_id;
  END IF;

  v_market_type := CASE
    WHEN NEW.plan_type ILIKE '%health%share%' OR NEW.plan_type ILIKE '%sharing%' THEN 'healthshare'
    WHEN NEW.plan_type ILIKE '%insurance%' OR NEW.plan_type ILIKE '%traditional%' THEN 'traditional_insurance'
    WHEN v_plan_name ILIKE '%MPB%' OR v_plan_name ILIKE '%MPowering%'
      OR v_plan_name ILIKE '%Sedera%' OR v_plan_name ILIKE '%Zion%'
      OR v_plan_name ILIKE '%sharing%' THEN 'healthshare'
    ELSE NULL
  END;

  IF NEW.snapshot IS NOT NULL AND NEW.snapshot->>'carrier' IS NOT NULL THEN
    SELECT id INTO v_carrier_id
      FROM insurance_carriers
      WHERE organization_id = NEW.organization_id
        AND LOWER(TRIM(carrier_name)) = LOWER(TRIM(NEW.snapshot->>'carrier'))
        AND is_active = true
      LIMIT 1;
  END IF;

  -- Build in chunks to stay under 100-arg limit
  v_data_patch := jsonb_build_object(
    'enrollment_id', NEW.id,
    'enrollment_number', NEW.enrollment_number,
    'enrollment_status', NEW.status,
    'selected_plan_id', NEW.selected_plan_id,
    'plan_name', v_plan_name,
    'plan_type', NEW.plan_type,
    'effective_date', NEW.effective_date,
    'requested_effective_date', NEW.requested_effective_date,
    'base_monthly_cost', NEW.base_monthly_cost,
    'tobacco_surcharge', NEW.tobacco_surcharge,
    'total_monthly_cost', NEW.total_monthly_cost,
    'enrollment_date', NEW.enrollment_date,
    'enrollment_source', COALESCE(NEW.source, NEW.enrollment_source),
    'first_billing_date', NEW.first_billing_date,
    'next_billing_date', NEW.next_billing_date,
    'next_billing_amount', NEW.next_billing_amount,
    'permanent_bill_day', NEW.permanent_bill_day,
    'pay_type', NEW.pay_type,
    'is_paid', NEW.is_paid,
    'last_payment_date', NEW.last_payment_date
  );

  v_data_patch := v_data_patch || jsonb_build_object(
    'product_paid_through_date', NEW.product_paid_through_date,
    'administration_fee', NEW.administration_fee,
    'association_fee', NEW.association_fee,
    'iua_fee', NEW.iua_fee,
    'product_fee', NEW.product_fee,
    'monthly_contribution_fee', NEW.monthly_contribution_fee,
    'hold_date', NEW.hold_date,
    'hold_reason', NEW.hold_reason,
    'hold_return_date', NEW.hold_return_date,
    'hold_amount', NEW.hold_amount,
    'contract_number', NEW.contract_number,
    'contract_length', NEW.contract_length,
    'underwriter', NEW.underwriter,
    'refund_requested', NEW.refund_requested,
    'refund_provided', NEW.refund_provided,
    'tpv_code', NEW.tpv_code,
    'product_label', NEW.product_label,
    'product_benefit', NEW.product_benefit,
    'period_label', NEW.period_label,
    'product_status', NEW.product_status
  );

  v_data_patch := v_data_patch || jsonb_build_object(
    'product_stage', NEW.product_stage,
    'product_source', NEW.product_source,
    'product_source_detail', NEW.product_source_detail,
    'product_code', NEW.product_code,
    'sale_date', NEW.sale_date,
    'renewal_date', NEW.renewal_date,
    'category', NEW.category,
    'category3', NEW.category3,
    'category4', NEW.category4,
    'enroller_id', NEW.enroller_id,
    'enroller_name', NEW.enroller_name,
    'product_agent_id', NEW.product_agent_id,
    'product_agent_label', NEW.product_agent_label,
    'agent_code', NEW.agent_code,
    'assigned_agents', NEW.assigned_agents
  );

  UPDATE crm_records SET
    market_type = COALESCE(v_market_type, market_type),
    tobacco_user = COALESCE(NEW.primary_is_smoker, tobacco_user),
    carrier_id = COALESCE(v_carrier_id, carrier_id),
    data = data || v_data_patch,
    normalization_status = CASE
      WHEN COALESCE(v_market_type, market_type) IS NOT NULL
        AND COALESCE(v_market_type, market_type) != 'unknown'
      THEN 'normalized'
      ELSE normalization_status
    END,
    updated_at = now()
  WHERE module_id = v_module_id
    AND system->>'source_table' = 'members'
    AND system->>'source_id' = NEW.primary_member_id::text;

  RETURN NEW;
EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING 'sync_enrollment_to_crm_records failed for enrollment %: %', NEW.id, SQLERRM;
    RETURN NEW;
END;
$$;


--
-- Name: FUNCTION sync_enrollment_to_crm_records(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sync_enrollment_to_crm_records() IS 'Pushes enrollment plan/carrier/tobacco data to the linked CRM record when enrollment status changes to submitted, approved, or active.';


--
-- Name: sync_integration_conn_org_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_integration_conn_org_id() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.org_id IS NOT NULL AND NEW.organization_id IS NULL THEN
    NEW.organization_id := NEW.org_id;
  ELSIF NEW.organization_id IS NOT NULL AND NEW.org_id IS NULL THEN
    NEW.org_id := NEW.organization_id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: sync_member_active_plan_type(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_member_active_plan_type() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_plan_type text;
BEGIN
  -- On membership insert/update, sync plan_type to member
  IF NEW.status = 'active' THEN
    SELECT p.plan_type INTO v_plan_type
    FROM plans p WHERE p.id = NEW.plan_id;

    UPDATE members
    SET active_plan_type = v_plan_type,
        plan_id = NEW.plan_id,
        plan_type = COALESCE(plan_type, v_plan_type)
    WHERE id = NEW.member_id;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: sync_member_to_crm(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_member_to_crm() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_contacts_module_id uuid;
  v_existing_record_id uuid;
  v_record_title       text;
BEGIN
  SELECT id INTO v_contacts_module_id
  FROM crm_modules
  WHERE organization_id = NEW.organization_id
    AND key = 'contacts'
    AND is_enabled = true
  LIMIT 1;

  IF v_contacts_module_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_record_title := TRIM(COALESCE(NEW.first_name, '') || ' ' || COALESCE(NEW.last_name, ''));
  IF v_record_title = '' THEN
    v_record_title := COALESCE(NEW.email, 'Member ' || NEW.id::text);
  END IF;

  -- 1. Exact linked_member_id match (cheapest and most specific).
  SELECT id INTO v_existing_record_id
  FROM crm_records
  WHERE module_id = v_contacts_module_id
    AND organization_id    = NEW.organization_id
    AND (data->>'linked_member_id') = NEW.id::text
  LIMIT 1;

  -- 2. Email match (case-insensitive) when no link yet.
  IF v_existing_record_id IS NULL
     AND NEW.email IS NOT NULL
     AND NEW.email <> '' THEN
    SELECT id INTO v_existing_record_id
    FROM crm_records
    WHERE module_id = v_contacts_module_id
      AND organization_id    = NEW.organization_id
      AND email IS NOT NULL
      AND LOWER(email) = LOWER(NEW.email)
    ORDER BY updated_at DESC NULLS LAST
    LIMIT 1;
  END IF;

  -- 3. Phone + name match. Phone alone is too loose (household lines,
  --    office numbers), so we require the name to line up too.
  IF v_existing_record_id IS NULL
     AND NEW.phone IS NOT NULL
     AND NEW.phone <> ''
     AND NEW.first_name IS NOT NULL
     AND NEW.last_name  IS NOT NULL THEN
    SELECT id INTO v_existing_record_id
    FROM crm_records
    WHERE module_id = v_contacts_module_id
      AND organization_id    = NEW.organization_id
      AND phone     = NEW.phone
      AND LOWER(COALESCE(data->>'first_name','')) = LOWER(NEW.first_name)
      AND LOWER(COALESCE(data->>'last_name', '')) = LOWER(NEW.last_name)
    ORDER BY updated_at DESC NULLS LAST
    LIMIT 1;
  END IF;

  IF v_existing_record_id IS NOT NULL THEN
    -- Update + stamp linked_member_id so subsequent syncs short-circuit on
    -- the fast path.
    UPDATE crm_records
    SET
      title = COALESCE(NULLIF(title, ''), v_record_title),
      email = COALESCE(NULLIF(email, ''), NEW.email),
      phone = COALESCE(NULLIF(phone, ''), NEW.phone),
      -- Don't stomp an Active status with a Pending one — but do promote
      -- the other way around.
      status = CASE
        WHEN NEW.status = 'Active' THEN 'Active'
        WHEN status = 'Active'     THEN status
        ELSE COALESCE(NEW.status, status)
      END,
      data = jsonb_set(
        jsonb_set(
          jsonb_set(
            jsonb_set(
              COALESCE(data, '{}'::jsonb),
              '{first_name}', to_jsonb(COALESCE(NEW.first_name, data->>'first_name'))
            ),
            '{last_name}',  to_jsonb(COALESCE(NEW.last_name,  data->>'last_name'))
          ),
          '{email}',        to_jsonb(COALESCE(NEW.email,      data->>'email'))
        ),
        '{linked_member_id}', to_jsonb(NEW.id::text)
      ),
      updated_at = now()
    WHERE id = v_existing_record_id;

    RETURN NEW;
  END IF;

  -- Nothing matched — insert a fresh Contact.
  INSERT INTO crm_records (
    organization_id, module_id, title, email, phone, status, data,
    created_at, updated_at
  ) VALUES (
    NEW.organization_id,
    v_contacts_module_id,
    v_record_title,
    NEW.email,
    NEW.phone,
    COALESCE(NEW.status, 'Active'),
    jsonb_build_object(
      'first_name',       NEW.first_name,
      'last_name',        NEW.last_name,
      'email',            NEW.email,
      'phone',            NEW.phone,
      'contact_status',   COALESCE(NEW.status, 'Active'),
      'linked_member_id', NEW.id::text,
      'source',           'enrollment_sync'
    ),
    now(), now()
  );

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'sync_member_to_crm failed for member %: %', NEW.id, SQLERRM;
  RETURN NEW;
END;
$$;


--
-- Name: sync_member_to_crm_records(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_member_to_crm_records() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_module_id uuid;
  v_owner_id uuid;
  v_advisor_code text;
  v_advisor_name text;
  v_org_id uuid;
  v_data jsonb;
  v_market_type text;
  v_canonical_advisor_id uuid;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_org_id := OLD.organization_id;
  ELSE
    v_org_id := NEW.organization_id;
  END IF;

  SELECT id INTO v_module_id
    FROM crm_modules WHERE organization_id = v_org_id AND key = 'members';

  IF v_module_id IS NULL THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;

  IF TG_OP = 'DELETE' THEN
    DELETE FROM crm_records
      WHERE module_id = v_module_id
        AND system->>'source_table' = 'members'
        AND system->>'source_id' = OLD.id::text;
    RETURN OLD;
  END IF;

  v_canonical_advisor_id := NEW.advisor_id;
  IF NEW.advisor_id IS NOT NULL THEN
    SELECT a.advisor_code, a.first_name || ' ' || a.last_name, p.id
    INTO v_advisor_code, v_advisor_name, v_owner_id
    FROM advisors a LEFT JOIN profiles p ON p.id = a.profile_id
    WHERE a.id = NEW.advisor_id;
  END IF;

  v_market_type := CASE
    WHEN NEW.plan_type ILIKE '%health%share%' OR NEW.plan_type ILIKE '%sharing%' THEN 'healthshare'
    WHEN NEW.plan_type ILIKE '%insurance%' OR NEW.plan_type ILIKE '%traditional%' THEN 'traditional_insurance'
    WHEN NEW.plan_name ILIKE '%MPB%' OR NEW.plan_name ILIKE '%MPowering%'
      OR NEW.plan_name ILIKE '%Sedera%' OR NEW.plan_name ILIKE '%Zion%'
      OR NEW.plan_name ILIKE '%sharing%' THEN 'healthshare'
    ELSE 'unknown'
  END;

  -- Build data in chunks to stay under 100-arg limit
  v_data := jsonb_build_object(
    'member_number', NEW.member_number,
    'first_name', NEW.first_name,
    'last_name', NEW.last_name,
    'date_of_birth', NEW.date_of_birth,
    'gender', NEW.gender,
    'marital_status', NEW.marital_status,
    'address_line1', NEW.address_line1,
    'address_line2', NEW.address_line2,
    'city', NEW.city,
    'state', NEW.state,
    'zip_code', NEW.postal_code,
    'advisor_id', NEW.advisor_id,
    'advisor_code', v_advisor_code,
    'advisor_name', v_advisor_name,
    'plan_name', NEW.plan_name,
    'plan_type', NEW.plan_type,
    'effective_date', NEW.effective_date,
    'monthly_share', NEW.monthly_share,
    'coverage_type', NEW.coverage_type,
    'program_type', NEW.program_type
  );

  v_data := v_data || jsonb_build_object(
    'enrollment_source', COALESCE(NEW.custom_fields->>'enrollment_source', ''),
    'county', NEW.county,
    'phone2', NEW.phone2,
    'phone3', NEW.phone3,
    'fax', NEW.fax,
    'email2', NEW.email2,
    'email3', NEW.email3,
    'do_not_call', NEW.do_not_call,
    'company_name', NEW.company_name,
    'position', NEW.position,
    'department', NEW.department,
    'division', NEW.division,
    'ethnicity', NEW.ethnicity,
    'height', NEW.height,
    'weight', NEW.weight,
    'disability', NEW.disability,
    'source', NEW.source,
    'referral', NEW.referral,
    'member_type', NEW.member_type,
    'stage', NEW.stage,
    'internal_id', NEW.internal_id,
    'external_username', NEW.external_username
  );

  IF TG_OP = 'INSERT' THEN
    INSERT INTO crm_records (
      organization_id, module_id, owner_id,
      title, status, email, phone,
      data, system,
      market_type, canonical_advisor_id, normalized_advisor_name,
      tobacco_user, record_type, import_source, normalization_status,
      created_at, updated_at
    ) VALUES (
      NEW.organization_id, v_module_id, v_owner_id,
      NEW.first_name || ' ' || NEW.last_name,
      NEW.status, NEW.email, NEW.phone,
      v_data,
      jsonb_build_object(
        'source_table', 'members',
        'source_id', NEW.id::text,
        'member_number', NEW.member_number,
        'synced', true
      ),
      v_market_type, v_canonical_advisor_id, v_advisor_name,
      COALESCE(NEW.is_smoker, false),
      'individual', 'enrollment',
      CASE WHEN v_market_type != 'unknown' THEN 'normalized' ELSE 'needs_review' END,
      NEW.created_at, now()
    )
    ON CONFLICT (org_id, module_id, lower(email)) WHERE (email IS NOT NULL AND email <> '') DO NOTHING;
  ELSIF TG_OP = 'UPDATE' THEN
    UPDATE crm_records SET
      title = NEW.first_name || ' ' || NEW.last_name,
      status = NEW.status, email = NEW.email, phone = NEW.phone,
      owner_id = COALESCE(v_owner_id, owner_id),
      data = v_data,
      system = jsonb_build_object(
        'source_table', 'members', 'source_id', NEW.id::text,
        'member_number', NEW.member_number, 'synced', true
      ),
      market_type = COALESCE(v_market_type, market_type),
      canonical_advisor_id = COALESCE(v_canonical_advisor_id, canonical_advisor_id),
      normalized_advisor_name = COALESCE(v_advisor_name, normalized_advisor_name),
      tobacco_user = COALESCE(NEW.is_smoker, tobacco_user),
      record_type = COALESCE(record_type, 'individual'),
      import_source = COALESCE(import_source, 'enrollment'),
      updated_at = now()
    WHERE module_id = v_module_id
      AND system->>'source_table' = 'members'
      AND system->>'source_id' = OLD.id::text;

    IF NOT FOUND THEN
      INSERT INTO crm_records (
        organization_id, module_id, owner_id,
        title, status, email, phone,
        data, system,
        market_type, canonical_advisor_id, normalized_advisor_name,
        tobacco_user, record_type, import_source, normalization_status,
        created_at, updated_at
      ) VALUES (
        NEW.organization_id, v_module_id, v_owner_id,
        NEW.first_name || ' ' || NEW.last_name,
        NEW.status, NEW.email, NEW.phone,
        v_data,
        jsonb_build_object(
          'source_table', 'members', 'source_id', NEW.id::text,
          'member_number', NEW.member_number, 'synced', true
        ),
        v_market_type, v_canonical_advisor_id, v_advisor_name,
        COALESCE(NEW.is_smoker, false),
        'individual', 'enrollment',
        CASE WHEN v_market_type != 'unknown' THEN 'normalized' ELSE 'needs_review' END,
        COALESCE(NEW.created_at, now()), now()
      )
    ON CONFLICT (org_id, module_id, lower(email)) WHERE (email IS NOT NULL AND email <> '') DO NOTHING;
    END IF;
  END IF;

  RETURN NEW;
EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING 'sync_member_to_crm_records failed for member %: %', NEW.id, SQLERRM;
    RETURN NEW;
END;
$$;


--
-- Name: sync_message_to_comment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_message_to_comment() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  -- Only sync if ticket exists and not already a comment
  IF NEW.ticket_id IS NOT NULL AND NOT NEW.is_internal THEN
    INSERT INTO ticket_comments (
      ticket_id,
      author_id,
      body,
      is_internal
    ) VALUES (
      NEW.ticket_id,
      NEW.sender_id,
      NEW.message_body,
      false
    )
    ON CONFLICT DO NOTHING;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: sync_org_tenant_key(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_org_tenant_key() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.organization_id is null then
    new.organization_id := new.org_id;
  end if;
  if new.org_id is null then
    new.org_id := new.organization_id;
  end if;
  return new;
end;
$$;


--
-- Name: track_link_visit(text, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.track_link_visit(p_link_slug text, p_session_id text, p_visitor_id text DEFAULT NULL::text, p_ip_address text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text, p_referrer_url text DEFAULT NULL::text, p_utm_source text DEFAULT NULL::text, p_utm_medium text DEFAULT NULL::text, p_utm_campaign text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_link enrollment_links%ROWTYPE;
  v_visit_id uuid;
BEGIN
  -- Get the link
  SELECT * INTO v_link
  FROM enrollment_links
  WHERE slug = p_link_slug AND is_active = true
  LIMIT 1;

  IF v_link IS NULL THEN
    RETURN NULL;
  END IF;

  -- Check if link is expired or maxed out
  IF v_link.expires_at IS NOT NULL AND v_link.expires_at < now() THEN
    RETURN NULL;
  END IF;

  IF v_link.max_uses IS NOT NULL AND v_link.total_visits >= v_link.max_uses THEN
    RETURN NULL;
  END IF;

  -- Insert visit
  INSERT INTO enrollment_link_visits (
    organization_id, link_id, advisor_id, session_id, visitor_id,
    ip_address, user_agent, referrer_url,
    utm_source, utm_medium, utm_campaign
  ) VALUES (
    v_link.organization_id, v_link.id, v_link.advisor_id, p_session_id, p_visitor_id,
    p_ip_address, p_user_agent, p_referrer_url,
    COALESCE(p_utm_source, v_link.utm_source),
    COALESCE(p_utm_medium, v_link.utm_medium),
    COALESCE(p_utm_campaign, v_link.utm_campaign)
  )
  RETURNING id INTO v_visit_id;

  RETURN v_visit_id;
END;
$$;


--
-- Name: track_ticket_status_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.track_ticket_status_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF OLD.status IS DISTINCT FROM NEW.status THEN
    INSERT INTO ticket_status_history (
      ticket_id,
      changed_by,
      old_status,
      new_status
    ) VALUES (
      NEW.id,
      auth.uid(),
      OLD.status,
      NEW.status
    );
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: trg_achievement_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_achievement_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM emit_system_event(
    NEW.organization_id,
    'achievement_earned',
    'advisor_achievements',
    NEW.id,
    jsonb_build_object(
      'advisor_id', NEW.advisor_id,
      'achievement_type', NEW.achievement_type,
      'title', NEW.title
    )
  );
  RETURN NEW;
END;
$$;


--
-- Name: trg_auto_create_agency(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_auto_create_agency() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF NEW.agent_role = 'Agency' AND (OLD IS NULL OR OLD.agent_role IS DISTINCT FROM 'Agency') THEN
    -- Create agency row if one doesn't already exist for this advisor
    INSERT INTO agencies (organization_id, owner_advisor_id, name, company_name, logo_url,
                          primary_color, secondary_color, header_bg_color, header_text_color, website_url)
    VALUES (
      NEW.organization_id, NEW.id,
      COALESCE(NEW.company_name, NEW.first_name || ' ' || NEW.last_name || ' Agency'),
      NEW.company_name, NEW.logo_url,
      NEW.primary_color, NEW.secondary_color, NEW.header_bg_color, NEW.header_text_color, NEW.website_url
    )
    ON CONFLICT DO NOTHING;

    -- Auto-add as owner member
    INSERT INTO agency_users (agency_id, advisor_id, role)
    SELECT ag.id, NEW.id, 'owner'
    FROM agencies ag
    WHERE ag.owner_advisor_id = NEW.id
    ON CONFLICT (agency_id, advisor_id) DO NOTHING;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: trg_commission_ledger_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_commission_ledger_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM emit_system_event(
    NEW.organization_id,
    'commission_created',
    'commission_ledger',
    NEW.id,
    jsonb_build_object(
      'advisor_id', NEW.advisor_id,
      'amount', NEW.amount,
      'product_type', NEW.product_type,
      'status', NEW.status
    )
  );
  RETURN NEW;
END;
$$;


--
-- Name: trg_commission_to_ledger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_commission_to_ledger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  -- Only create ledger entry when commission is approved (or on insert if already approved)
  IF NEW.status = 'approved' THEN
    -- Upsert: create if not exists, update amount if exists
    INSERT INTO commission_ledger (
      organization_id, advisor_id, commission_id,
      amount, product_type, status
    ) VALUES (
      NEW.organization_id, NEW.advisor_id, NEW.id,
      NEW.commission_amount, NEW.product_type, 'available'
    )
    ON CONFLICT (commission_id)
    DO UPDATE SET
      amount = EXCLUDED.amount,
      product_type = EXCLUDED.product_type,
      status = CASE
        WHEN commission_ledger.status = 'available' THEN 'available'
        ELSE commission_ledger.status  -- Don't revert scheduled/paid
      END,
      updated_at = now();
  END IF;

  -- If commission is reversed, reverse the ledger entry
  IF NEW.status = 'reversed' THEN
    UPDATE commission_ledger
    SET status = 'reversed',
        reversed_at = now(),
        reversed_reason = 'Commission reversed',
        updated_at = now()
    WHERE commission_id = NEW.id
      AND status IN ('available', 'scheduled');
  END IF;

  -- If commission is held, hold the ledger entry
  IF NEW.status = 'held' THEN
    UPDATE commission_ledger
    SET status = 'held', updated_at = now()
    WHERE commission_id = NEW.id
      AND status = 'available';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: trg_enrollment_commission_auto_fire(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_enrollment_commission_auto_fire() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_advisor_id      uuid;
  v_commission_amt  numeric;
  v_product_type    text;
BEGIN
  -- Only fire on status change TO 'active'
  IF NEW.status != 'active' THEN RETURN NEW; END IF;
  IF OLD IS NOT NULL AND OLD.status = 'active' THEN RETURN NEW; END IF;

  -- Need an advisor
  v_advisor_id := NEW.advisor_id;
  IF v_advisor_id IS NULL THEN RETURN NEW; END IF;

  -- Check if commission already exists for this enrollment
  IF EXISTS (
    SELECT 1 FROM commissions
    WHERE enrollment_id = NEW.id
      AND commission_type = 'signup'
  ) THEN
    RETURN NEW;
  END IF;

  -- Get product type from the enrollment's product
  SELECT p.product_type INTO v_product_type
  FROM products p
  WHERE p.id = COALESCE(NEW.selected_plan_id, NEW.product_id)
  LIMIT 1;

  -- Calculate commission using existing function
  v_commission_amt := calculate_enrollment_commission(NEW.id, 'signup');

  -- Insert direct commission if amount > 0
  IF v_commission_amt > 0 THEN
    INSERT INTO commissions (
      organization_id, advisor_id, enrollment_id, member_id,
      commission_type, product_type,
      base_amount, commission_rate, commission_amount,
      commission_period, status
    ) VALUES (
      NEW.organization_id, v_advisor_id, NEW.id, NEW.primary_member_id,
      'signup', v_product_type,
      COALESCE(NEW.total_monthly_cost, 0), 0, v_commission_amt,
      date_trunc('month', COALESCE(NEW.effective_date, now()))::date, 'pending'
    );
  END IF;

  -- Generate override commissions for upline (up to 5 levels)
  DECLARE
    v_current_id uuid := v_advisor_id;
    v_parent_id  uuid;
    v_level      int := 1;
    v_override_amt  numeric;
  BEGIN
    LOOP
      EXIT WHEN v_level > 5;

      SELECT parent_advisor_id INTO v_parent_id
      FROM advisors WHERE id = v_current_id;

      EXIT WHEN v_parent_id IS NULL;

      -- Check parent is commission eligible
      IF EXISTS (
        SELECT 1 FROM advisors
        WHERE id = v_parent_id AND commission_eligible = true
      ) THEN
        -- Get override rate for parent
        SELECT cr.override_commission_percent INTO v_override_amt
        FROM commission_rates cr
        JOIN advisors pa ON pa.id = v_parent_id
        WHERE cr.organization_id = NEW.organization_id
          AND cr.is_active = true
          AND cr.effective_date <= current_date
          AND (cr.end_date IS NULL OR cr.end_date > current_date)
          AND (cr.agent_level_id IS NULL OR cr.agent_level_id = pa.agent_level_id)
          AND (cr.product_id IS NULL OR cr.product_id = NEW.selected_plan_id)
        ORDER BY
          CASE WHEN cr.product_id IS NOT NULL THEN 0 ELSE 1 END,
          CASE WHEN cr.agent_level_id IS NOT NULL THEN 0 ELSE 1 END
        LIMIT 1;

        IF v_override_amt IS NOT NULL AND v_override_amt > 0 THEN
          INSERT INTO commissions (
            organization_id, advisor_id, enrollment_id, member_id,
            source_advisor_id, override_level,
            commission_type, product_type,
            base_amount, commission_rate, commission_rate_type, commission_amount,
            commission_period, status
          ) VALUES (
            NEW.organization_id, v_parent_id, NEW.id, NEW.primary_member_id,
            v_advisor_id, v_level,
            'override', v_product_type,
            COALESCE(NEW.total_monthly_cost, 0), v_override_amt, 'percentage',
            COALESCE(NEW.total_monthly_cost, 0) * (v_override_amt / 100),
            date_trunc('month', COALESCE(NEW.effective_date, now()))::date, 'pending'
          );
        END IF;
      END IF;

      v_current_id := v_parent_id;
      v_level := v_level + 1;
    END LOOP;
  END;

  RETURN NEW;
END;
$$;


--
-- Name: trg_financial_change_capture(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_financial_change_capture() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_org_id uuid;
  v_old_json jsonb;
  v_new_json jsonb;
  v_changed jsonb := '{}'::jsonb;
  v_key text;
BEGIN
  -- Extract org_id from the row
  v_org_id := COALESCE(
    NEW.organization_id,
    (SELECT NEW.organization_id)
  );

  v_old_json := to_jsonb(OLD);
  v_new_json := to_jsonb(NEW);

  -- Build diff: only changed fields
  FOR v_key IN SELECT jsonb_object_keys(v_new_json)
  LOOP
    IF v_old_json->v_key IS DISTINCT FROM v_new_json->v_key THEN
      v_changed := v_changed || jsonb_build_object(
        v_key, jsonb_build_object('old', v_old_json->v_key, 'new', v_new_json->v_key)
      );
    END IF;
  END LOOP;

  -- Skip if nothing actually changed
  IF v_changed = '{}'::jsonb THEN
    RETURN NEW;
  END IF;

  INSERT INTO financial_audit_log (
    organization_id, action, entity_type, entity_id,
    old_values, new_values, details
  ) VALUES (
    v_org_id,
    'field_changed',
    TG_TABLE_NAME,
    COALESCE(NEW.id, OLD.id),
    v_old_json,
    v_new_json,
    v_changed
  );

  RETURN NEW;
END;
$$;


--
-- Name: trg_payout_batch_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_payout_batch_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_event_type text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_event_type := 'payout_batch_created';
  ELSIF NEW.status = 'approved' OR NEW.status = 'processing' THEN
    v_event_type := 'payout_batch_approved';
  ELSIF NEW.status = 'paid' THEN
    v_event_type := 'payout_completed';
  ELSIF NEW.status = 'failed' THEN
    v_event_type := 'payout_failed';
  ELSE
    RETURN NEW;
  END IF;

  PERFORM emit_system_event(
    NEW.organization_id,
    v_event_type,
    'commission_payment_batches',
    NEW.id,
    jsonb_build_object(
      'batch_number', NEW.batch_number,
      'status', NEW.status,
      'total_amount', NEW.total_amount,
      'total_advisors', NEW.total_advisors
    )
  );
  RETURN NEW;
END;
$$;


