--
-- Name: trigger_job_definition_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_job_definition_audit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_event_type text;
  v_changes jsonb := '{}';
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_event_type := 'schedule_created';
  ELSIF TG_OP = 'UPDATE' THEN
    IF OLD.is_active != NEW.is_active THEN
      v_event_type := CASE WHEN NEW.is_active THEN 'schedule_activated' ELSE 'schedule_paused' END;
    ELSE
      v_event_type := 'schedule_updated';
      IF OLD.schedule_cron IS DISTINCT FROM NEW.schedule_cron THEN
        v_changes := v_changes || jsonb_build_object('schedule_cron', jsonb_build_object('old', OLD.schedule_cron, 'new', NEW.schedule_cron));
      END IF;
      IF OLD.name != NEW.name THEN
        v_changes := v_changes || jsonb_build_object('name', jsonb_build_object('old', OLD.name, 'new', NEW.name));
      END IF;
    END IF;
  ELSIF TG_OP = 'DELETE' THEN
    v_event_type := 'schedule_deleted';
  END IF;

  INSERT INTO public.ops_audit_log (
    organization_id,
    event_type,
    entity_type,
    entity_id,
    vendor_code,
    changes,
    metadata
  ) VALUES (
    COALESCE(NEW.organization_id, OLD.organization_id),
    v_event_type,
    'job_definition',
    COALESCE(NEW.id, OLD.id),
    COALESCE(NEW.vendor_code, OLD.vendor_code),
    NULLIF(v_changes, '{}'),
    jsonb_build_object(
      'name', COALESCE(NEW.name, OLD.name),
      'job_type', COALESCE(NEW.job_type, OLD.job_type),
      'is_active', COALESCE(NEW.is_active, OLD.is_active)
    )
  );

  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: trigger_job_run_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_job_run_audit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_event_type text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_event_type := 'job_run_started';
  ELSIF TG_OP = 'UPDATE' THEN
    IF OLD.status != NEW.status THEN
      CASE NEW.status
        WHEN 'completed' THEN v_event_type := 'job_run_completed';
        WHEN 'failed' THEN v_event_type := 'job_run_failed';
        WHEN 'cancelled' THEN v_event_type := 'job_run_cancelled';
        ELSE v_event_type := NULL;
      END CASE;
    END IF;
  END IF;

  IF v_event_type IS NOT NULL THEN
    INSERT INTO public.ops_audit_log (
      organization_id,
      event_type,
      entity_type,
      entity_id,
      vendor_code,
      actor_id,
      metadata
    ) VALUES (
      COALESCE(NEW.organization_id, OLD.organization_id),
      v_event_type,
      'job_run',
      COALESCE(NEW.id, OLD.id),
      NEW.vendor_code,
      NEW.triggered_by,
      jsonb_build_object(
        'job_type', NEW.job_type,
        'job_name', NEW.job_name,
        'status', NEW.status,
        'trigger_type', NEW.trigger_type,
        'duration_ms', NEW.duration_ms,
        'records_processed', NEW.records_processed
      )
    );
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: trigger_refresh_pricing_mv(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_refresh_pricing_mv() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Debounce: only refresh if it hasn't been refreshed in the last 5 seconds
  -- In production, use pg_cron or application-level refresh instead
  PERFORM pg_advisory_xact_lock(hashtext('pricing_mv_refresh'));
  REFRESH MATERIALIZED VIEW CONCURRENTLY pricing_lookup_mv;
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  -- Non-blocking: if concurrent refresh is already running, skip
  RETURN NULL;
END;
$$;


