--
-- Name: undismiss_duplicate_pair(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.undismiss_duplicate_pair(p_a_id uuid, p_b_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor_profile_id uuid;
  v_actor_org_id     uuid;
  v_actor_role       text;
  v_left_id          uuid;
  v_right_id         uuid;
  v_deleted          int;
BEGIN
  IF p_a_id IS NULL OR p_b_id IS NULL OR p_a_id = p_b_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Two different record ids are required');
  END IF;

  SELECT id, organization_id, crm_role
    INTO v_actor_profile_id, v_actor_org_id, v_actor_role
    FROM public.profiles
   WHERE user_id = auth.uid()
   LIMIT 1;

  IF v_actor_profile_id IS NULL OR v_actor_role NOT IN ('crm_admin', 'crm_manager') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Only CRM admins and managers can undismiss duplicate pairs');
  END IF;

  v_left_id  := LEAST(p_a_id, p_b_id);
  v_right_id := GREATEST(p_a_id, p_b_id);

  DELETE FROM public.crm_duplicate_dismissals
   WHERE organization_id  = v_actor_org_id
     AND left_record_id  = v_left_id
     AND right_record_id = v_right_id;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  IF v_deleted > 0 THEN
    INSERT INTO public.crm_audit_log (organization_id, actor_id, entity, entity_id, action, diff)
    VALUES (
      v_actor_org_id,
      v_actor_profile_id,
      'record',
      v_left_id,
      'duplicate_undismissed',
      jsonb_build_object('left_id', v_left_id, 'right_id', v_right_id)
    );
  END IF;

  RETURN jsonb_build_object('success', true, 'left_id', v_left_id, 'right_id', v_right_id, 'removed', v_deleted);
END;
$$;


--
-- Name: update_agent_call_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_agent_call_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.status = 'active' AND OLD.status != 'active' THEN
    -- Call started
    UPDATE agent_call_status
    SET
      status = 'busy',
      active_call_id = NEW.id,
      current_call_count = current_call_count + 1,
      updated_at = now()
    WHERE agent_id = NEW.assigned_agent_id;
  ELSIF NEW.status = 'ended' AND OLD.status = 'active' THEN
    -- Call ended
    UPDATE agent_call_status
    SET
      current_call_count = GREATEST(current_call_count - 1, 0),
      active_call_id = CASE
        WHEN current_call_count <= 1 THEN NULL
        ELSE active_call_id
      END,
      status = CASE
        WHEN current_call_count <= 1 THEN 'available'
        ELSE status
      END,
      updated_at = now()
    WHERE agent_id = NEW.assigned_agent_id;
  END IF;
  RETURN NEW;
END;
$$;


