$$;


--
-- Name: update_delegation_permissions(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_delegation_permissions(p_delegation_id uuid, p_permissions jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_delegation record;
BEGIN
  SELECT * INTO v_delegation FROM org_delegations WHERE id = p_delegation_id;

  IF v_delegation IS NULL THEN
    RAISE EXCEPTION 'DELEGATION_NOT_FOUND';
  END IF;

  -- Verify caller is in parent org
  IF (SELECT get_user_organization_id()) != v_delegation.parent_org_id THEN
    RAISE EXCEPTION 'ACCESS_DENIED: must be in parent org';
  END IF;

  -- CRITICAL: Never allow view_raw_records via this path
  IF (p_permissions->>'view_raw_records')::boolean = true THEN
    RAISE EXCEPTION 'FORBIDDEN: raw record access cannot be granted via delegation';
  END IF;

  UPDATE org_delegations
  SET permissions = p_permissions,
      updated_at = now()
  WHERE id = p_delegation_id;

  RETURN jsonb_build_object(
    'delegation_id', p_delegation_id,
    'permissions', p_permissions,
    'updated', true
  );
END;
$$;


--
-- Name: update_email_thread_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_email_thread_stats() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE email_threads
  SET
    message_count = (SELECT COUNT(*) FROM email_messages WHERE thread_id = NEW.thread_id),
    unread_count = (SELECT COUNT(*) FROM email_messages WHERE thread_id = NEW.thread_id AND NOT is_read),
    has_attachments = EXISTS(
      SELECT 1 FROM email_messages
      WHERE thread_id = NEW.thread_id
        AND jsonb_array_length(attachments) > 0
    ),
    last_message_at = (SELECT MAX(sent_at) FROM email_messages WHERE thread_id = NEW.thread_id),
    updated_at = now()
  WHERE id = NEW.thread_id;

  RETURN NEW;
END;
$$;


--
-- Name: update_enrollment_status_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_enrollment_status_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF OLD.status IS DISTINCT FROM NEW.status THEN
    NEW.last_status_change_at := now();
    
    -- Auto-populate workflow timestamps based on status
    CASE NEW.status
      WHEN 'submitted' THEN
        IF NEW.submitted_at IS NULL THEN
          NEW.submitted_at := now();
        END IF;
      WHEN 'approved' THEN
        IF NEW.approved_at IS NULL THEN
          NEW.approved_at := now();
        END IF;
      WHEN 'rejected' THEN
        IF NEW.rejected_at IS NULL THEN
          NEW.rejected_at := now();
        END IF;
      WHEN 'cancelled' THEN
        IF NEW.cancelled_at IS NULL THEN
          NEW.cancelled_at := now();
        END IF;
      ELSE
        -- No action for other statuses
    END CASE;
  END IF;
  
  RETURN NEW;
END;
$$;


