--
-- Name: update_link_conversion_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_link_conversion_stats() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Update the link stats
  UPDATE enrollment_links
  SET
    total_conversions = total_conversions + 1,
    conversion_rate = CASE
      WHEN total_visits > 0 THEN ((total_conversions + 1)::numeric / total_visits * 100)
      ELSE 0
    END
  WHERE id = NEW.link_id;

  -- Mark the visit as converted
  IF NEW.visit_id IS NOT NULL THEN
    UPDATE enrollment_link_visits
    SET
      converted = true,
      conversion_id = NEW.id,
      converted_at = NEW.converted_at
    WHERE id = NEW.visit_id;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: update_link_visit_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_link_visit_stats() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE enrollment_links
  SET
    total_visits = total_visits + 1,
    unique_visits = (
      SELECT COUNT(DISTINCT COALESCE(visitor_id, session_id))
      FROM enrollment_link_visits
      WHERE link_id = NEW.link_id
    )
  WHERE id = NEW.link_id;
  RETURN NEW;
END;
$$;


--
-- Name: update_onedrive_sync_status(uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_onedrive_sync_status(p_file_id uuid, p_status text, p_onedrive_id text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.files
  SET 
    onedrive_sync_status = p_status,
    onedrive_last_sync_at = CASE 
      WHEN p_status = 'synced' THEN now()
      ELSE onedrive_last_sync_at
    END,
    onedrive_id = COALESCE(p_onedrive_id, onedrive_id),
    onedrive_metadata = CASE 
      WHEN p_metadata != '{}'::jsonb THEN p_metadata
      ELSE onedrive_metadata
    END,
    updated_at = now()
  WHERE id = p_file_id
    AND owner_id = auth.uid();
END;
$$;


