--
-- Name: validate_advisor_capacity(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_advisor_capacity(p_advisor_id uuid, p_product_type text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_capacities text[];
BEGIN
  -- If no product_type specified, allow (backward compatibility)
  IF p_product_type IS NULL OR p_product_type = '' THEN
    RETURN true;
  END IF;

  -- Validate product_type value
  IF p_product_type NOT IN ('health_insurance', 'health_share') THEN
    RAISE EXCEPTION 'Invalid product_type: %. Must be health_insurance or health_share', p_product_type;
  END IF;

  -- Get advisor capacities
  SELECT capacities INTO v_capacities
  FROM advisors
  WHERE id = p_advisor_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Advisor % not found', p_advisor_id;
  END IF;

  -- Empty capacities = no restriction (backward compatibility for existing advisors)
  IF v_capacities IS NULL OR array_length(v_capacities, 1) IS NULL THEN
    RETURN true;
  END IF;

  -- Check if advisor has the required capacity
  RETURN p_product_type = ANY(v_capacities);
END;
$$;


--
-- Name: FUNCTION validate_advisor_capacity(p_advisor_id uuid, p_product_type text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.validate_advisor_capacity(p_advisor_id uuid, p_product_type text) IS 'Validates that an advisor has the capacity (role) to sell a given product type';


--
-- Name: validate_free_text(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_free_text(txt text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  -- Return true if text is null or empty
  IF txt IS NULL OR trim(txt) = '' THEN
    RETURN true;
  END IF;

  -- Check for Social Security Numbers
  IF txt ~* '(ssn|social\s*security|[0-9]{3}-[0-9]{2}-[0-9]{4})' THEN
    RETURN false;
  END IF;

  -- Check for Medical Record Numbers
  IF txt ~* '(mrn|medical\s*record|patient\s*id)' THEN
    RETURN false;
  END IF;

  -- Check for medical terms
  IF txt ~* '(diagnosis|prescription|medication|treatment|procedure|surgery)' THEN
    RETURN false;
  END IF;

  -- Check for Date of Birth patterns
  IF txt ~* 'dob\s*:?\s*[0-9]{1,2}[/-][0-9]{1,2}[/-][0-9]{2,4}' THEN
    RETURN false;
  END IF;

  -- Check for HIPAA/PHI keywords
  IF txt ~* '(hipaa|phi|protected\s*health|health\s*information)' THEN
    RETURN false;
  END IF;

  -- Text is safe
  RETURN true;
END;
$$;


--
-- Name: FUNCTION validate_free_text(txt text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.validate_free_text(txt text) IS 'Validate text does not contain PHI (Protected Health Information) for HIPAA compliance';


--
-- Name: verify_audit_chain(uuid, bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_audit_chain(p_organization_id uuid, p_from_sequence bigint DEFAULT 1, p_to_sequence bigint DEFAULT NULL::bigint) RETURNS TABLE(sequence_number bigint, is_valid boolean, expected_hash text, actual_hash text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_log RECORD;
  v_prev_hash text := NULL;
  v_computed_hash text;
BEGIN
  FOR v_log IN
    SELECT *
    FROM unified_audit_logs
    WHERE organization_id = p_organization_id
      AND unified_audit_logs.sequence_number >= p_from_sequence
      AND (p_to_sequence IS NULL OR unified_audit_logs.sequence_number <= p_to_sequence)
    ORDER BY unified_audit_logs.sequence_number ASC
  LOOP
    -- Compute expected hash
    v_computed_hash := compute_audit_entry_hash(
      v_log.sequence_number,
      v_prev_hash,
      v_log.organization_id,
      v_log.app_source,
      v_log.actor_id,
      v_log.action,
      v_log.target_entity_type,
      v_log.target_entity_id,
      v_log.details,
      v_log.created_at
    );

    -- Return verification result
    sequence_number := v_log.sequence_number;
    is_valid := (v_log.entry_hash = v_computed_hash) AND
                (v_log.previous_hash IS NOT DISTINCT FROM v_prev_hash);
    expected_hash := v_computed_hash;
    actual_hash := v_log.entry_hash;
    RETURN NEXT;

    -- Update previous hash for next iteration
    v_prev_hash := v_log.entry_hash;
  END LOOP;
END;
$$;


