    current_coverage text,
    CONSTRAINT leads_status_check CHECK ((status = ANY (ARRAY['new'::text, 'contacted'::text, 'working'::text, 'qualified'::text, 'unqualified'::text, 'converted'::text, 'lost'::text])))
);


--
-- Name: advisor_contact_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.advisor_contact_summary AS
 SELECT a.organization_id,
    a.id AS advisor_id,
    a.full_name,
    a.email,
    a.state,
    a.is_active AS advisor_active,
    count(DISTINCT l.id) AS total_leads,
    count(DISTINCT m.id) AS total_members,
    (count(DISTINCT l.id) + count(DISTINCT m.id)) AS total_contacts,
    max(GREATEST(COALESCE(l.created_at, '1900-01-01 00:00:00+00'::timestamp with time zone), COALESCE(m.created_at, '1900-01-01 00:00:00+00'::timestamp with time zone))) AS last_contact_at
   FROM ((public.advisors a
     LEFT JOIN public.leads l ON ((l.advisor_id = a.id)))
     LEFT JOIN public.members m ON ((m.advisor_id = a.id)))
  GROUP BY a.organization_id, a.id, a.full_name, a.email, a.state, a.is_active;


--
-- Name: VIEW advisor_contact_summary; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.advisor_contact_summary IS 'Per-advisor aggregate of leads + members. Backs the advisor admin page and POST /api/crm/advisors/summary.';


