--
-- Name: profiles; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.profiles (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    email text NOT NULL,
    full_name text NOT NULL,
    avatar_url text,
    role text DEFAULT 'staff'::text NOT NULL,
    is_active boolean DEFAULT true,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    display_name text,
    phone text,
    time_zone text DEFAULT 'America/New_York'::text,
    crm_role text,
    ui_theme text DEFAULT 'light'::text,
    is_super_admin boolean DEFAULT false,
    advisor_role text,
    advisor_id uuid,
    capacity_preferences text[] DEFAULT '{}'::text[],
    ui_preferences jsonb DEFAULT '{}'::jsonb NOT NULL,
    member_id uuid,
    CONSTRAINT profiles_advisor_role_check CHECK ((advisor_role = ANY (ARRAY['advisor'::text, 'manager'::text, 'owner_admin'::text]))),
    CONSTRAINT profiles_crm_role_check CHECK (((crm_role IS NULL) OR (crm_role = ANY (ARRAY['crm_admin'::text, 'crm_manager'::text, 'crm_agent'::text, 'crm_viewer'::text])))),
    CONSTRAINT profiles_role_check CHECK ((role = ANY (ARRAY['owner'::text, 'super_admin'::text, 'admin'::text, 'advisor'::text, 'staff'::text]))),
    CONSTRAINT profiles_ui_theme_check CHECK (((ui_theme IS NULL) OR (ui_theme = ANY (ARRAY['light'::text, 'dark'::text, 'system'::text]))))
);


--
-- Name: COLUMN profiles.ui_theme; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.profiles.ui_theme IS 'User theme preference: light (default), dark, or system';


--
-- Name: COLUMN profiles.is_super_admin; Type: COMMENT; Schema: public; Owner: -
