--
-- Name: billing_automation_config; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.billing_automation_config (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    billing_enabled boolean DEFAULT false NOT NULL,
    commission_enabled boolean DEFAULT false NOT NULL,
    run_day_of_month integer DEFAULT 20 NOT NULL,
    run_hour_utc integer DEFAULT 2 NOT NULL,
    batch_size integer DEFAULT 50 NOT NULL,
    max_retries integer DEFAULT 4 NOT NULL,
    circuit_breaker_threshold integer DEFAULT 5 NOT NULL,
    circuit_breaker_cooldown integer DEFAULT 300 NOT NULL,
    rate_limit_per_minute integer DEFAULT 30 NOT NULL,
    notify_on_failure boolean DEFAULT true NOT NULL,
    notify_email text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT billing_automation_config_batch_size_check CHECK (((batch_size >= 1) AND (batch_size <= 500))),
    CONSTRAINT billing_automation_config_circuit_breaker_cooldown_check CHECK (((circuit_breaker_cooldown >= 60) AND (circuit_breaker_cooldown <= 3600))),
    CONSTRAINT billing_automation_config_circuit_breaker_threshold_check CHECK (((circuit_breaker_threshold >= 1) AND (circuit_breaker_threshold <= 50))),
    CONSTRAINT billing_automation_config_max_retries_check CHECK (((max_retries >= 0) AND (max_retries <= 10))),
    CONSTRAINT billing_automation_config_rate_limit_per_minute_check CHECK (((rate_limit_per_minute >= 1) AND (rate_limit_per_minute <= 120))),
    CONSTRAINT billing_automation_config_run_day_of_month_check CHECK (((run_day_of_month >= 1) AND (run_day_of_month <= 31))),
    CONSTRAINT billing_automation_config_run_hour_utc_check CHECK (((run_hour_utc >= 0) AND (run_hour_utc <= 23)))
);


