-- Name: change_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.change_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    source_type text NOT NULL,
    source_name text,
    source_id text,
    change_type text NOT NULL,
    entity_type text NOT NULL,
    entity_id uuid NOT NULL,
    entity_title text,
    severity text DEFAULT 'info'::text NOT NULL,
    requires_review boolean DEFAULT false,
    title text NOT NULL,
    description text,
    diff jsonb,
    payload jsonb DEFAULT '{}'::jsonb,
    actor_id uuid,
    actor_name text,
    actor_type text DEFAULT 'user'::text,
    reconciliation_status text DEFAULT 'none'::text,
    reviewed_by uuid,
    reviewed_at timestamp with time zone,
    review_notes text,
    content_hash text,
    previous_hash text,
    sync_status text DEFAULT 'synced'::text,
    synced_at timestamp with time zone,
    detected_at timestamp with time zone DEFAULT now(),
    created_at timestamp with time zone DEFAULT now(),
    organization_id uuid,
    CONSTRAINT change_events_actor_type_check CHECK ((actor_type = ANY (ARRAY['user'::text, 'system'::text, 'integration'::text, 'vendor'::text]))),
    CONSTRAINT change_events_reconciliation_status_check CHECK ((reconciliation_status = ANY (ARRAY['none'::text, 'pending'::text, 'approved'::text, 'rejected'::text, 'auto_resolved'::text]))),
    CONSTRAINT change_events_severity_check CHECK ((severity = ANY (ARRAY['critical'::text, 'high'::text, 'medium'::text, 'low'::text, 'info'::text]))),
    CONSTRAINT change_events_source_type_check CHECK ((source_type = ANY (ARRAY['user'::text, 'system'::text, 'integration'::text, 'vendor'::text, 'import'::text]))),
    CONSTRAINT change_events_sync_status_check CHECK ((sync_status = ANY (ARRAY['synced'::text, 'pending'::text, 'conflict'::text, 'stale'::text])))
);

ALTER TABLE ONLY public.change_events REPLICA IDENTITY FULL;


--
-- Name: TABLE change_events; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.change_events IS 'Centralized change intelligence tracking for all system changes';


--
-- Name: change_feed_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.change_feed_view AS
 SELECT ce.id,
    ce.organization_id AS org_id,
    ce.source_type,
    ce.source_name,
    ce.source_id,
    ce.change_type,
    ce.entity_type,
    ce.entity_id,
    ce.entity_title,
    ce.severity,
    ce.requires_review,
    ce.title,
    ce.description,
    ce.diff,
    ce.payload,
    ce.actor_id,
    ce.actor_name,
    ce.actor_type,
    ce.reconciliation_status,
    ce.reviewed_by,
    ce.reviewed_at,
    ce.review_notes,
    ce.content_hash,
    ce.previous_hash,
    ce.sync_status,
    ce.synced_at,
    ce.detected_at,
    ce.created_at,
    p.full_name AS actor_full_name,
    NULL::text AS actor_avatar_url,
    rp.full_name AS reviewer_full_name
   FROM ((public.change_events ce
     LEFT JOIN public.profiles p ON ((ce.actor_id = p.id)))
     LEFT JOIN public.profiles rp ON ((ce.reviewed_by = rp.id)));


--
-- Name: VIEW change_feed_view; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.change_feed_view IS 'Change events with joined actor and reviewer profile information';


