--
-- Name: channel_activity_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.channel_activity_summary WITH (security_invoker='on') AS
 SELECT sc.id AS channel_id,
    sc.channel_type,
    sc.name,
    count(DISTINCT cm.id) AS total_messages,
    count(DISTINCT cm.ticket_id) AS tickets_created,
    count(DISTINCT
        CASE
            WHEN (cm.created_at >= (now() - '24:00:00'::interval)) THEN cm.id
            ELSE NULL::uuid
        END) AS messages_24h,
    max(cm.created_at) AS last_activity
   FROM (public.support_channels sc
     LEFT JOIN public.channel_messages cm ON ((cm.channel_id = sc.id)))
  WHERE (sc.is_active = true)
  GROUP BY sc.id, sc.channel_type, sc.name;


