--
-- Name: chat_response_time_analytics; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.chat_response_time_analytics WITH (security_invoker='on') AS
 SELECT cs.id AS session_id,
    cs.assigned_agent_id,
    cs.started_at,
    min(cm.created_at) FILTER (WHERE (cm.sender_type = 'agent'::public.sender_type)) AS first_agent_response,
    (EXTRACT(epoch FROM (min(cm.created_at) FILTER (WHERE (cm.sender_type = 'agent'::public.sender_type)) - cs.started_at)) / (60)::numeric) AS first_response_minutes,
    count(cm.id) FILTER (WHERE (cm.sender_type = 'customer'::public.sender_type)) AS customer_messages,
    count(cm.id) FILTER (WHERE (cm.sender_type = 'agent'::public.sender_type)) AS agent_messages
   FROM (public.chat_sessions cs
     LEFT JOIN public.channel_messages cm ON (((cm.metadata ->> 'session_id'::text) = (cs.id)::text)))
  GROUP BY cs.id, cs.assigned_agent_id, cs.started_at;


