    normalized_agent_name text,
    normalization_status text,
    normalization_notes text,
    import_source text,
    source_record_id text,
    import_batch_id text,
    estimated_age integer,
    age_range text,
    age_is_estimated boolean DEFAULT false,
    age_notes text,
    record_type text,
    tobacco_user boolean,
    original_start_date date,
    current_year_start_date date,
    cancellation_date date,
    group_name text,
    search tsvector GENERATED ALWAYS AS (to_tsvector('english'::regconfig, ((((((((((((((((((((((((((((((((((((((((((((((((COALESCE(title, ''::text) || ' '::text) || COALESCE((data ->> 'first_name'::text), ''::text)) || ' '::text) || COALESCE((data ->> 'last_name'::text), ''::text)) || ' '::text) || COALESCE(email, ''::text)) || ' '::text) || COALESCE(phone, ''::text)) || ' '::text) || COALESCE(status, ''::text)) || ' '::text) || COALESCE((data ->> 'spouse'::text), ''::text)) || ' '::text) || COALESCE((data ->> 'spouse_phone_number'::text), ''::text)) || ' '::text) || COALESCE((data ->> 'spouse_email'::text), ''::text)) || ' '::text) || COALESCE((data ->> 'child_1'::text), ''::text)) || ' '::text) || COALESCE((data ->> 'child_2'::text), ''::text)) || ' '::text) || COALESCE((data ->> 'child_3'::text), ''::text)) || ' '::text) || COALESCE((data ->> 'child_4'::text), ''::text)) || ' '::text) || COALESCE((data ->> 'child_5'::text), ''::text)) || ' '::text) || COALESCE((data ->> 'child_1_name'::text), ''::text)) || ' '::text) || COALESCE((data ->> 'child_2_name'::text), ''::text)) || ' '::text) || COALESCE((data ->> 'child_3_name'::text), ''::text)) || ' '::text) || COALESCE((data ->> 'contact_name'::text), ''::text)) || ' '::text) || COALESCE((data ->> 'mailing_city'::text), ''::text)) || ' '::text) || COALESCE((data ->> 'mailing_state'::text), ''::text)) || ' '::text) || COALESCE((data ->> 'carrier'::text), ''::text)) || ' '::text) || COALESCE((data ->> 'product'::text), ''::text)) || ' '::text) || COALESCE((data ->> 'producer_name'::text), ''::text)) || ' '::text) || COALESCE(group_name, ''::text)) || ' '::text) || COALESCE(
CASE
    WHEN (tobacco_user = true) THEN 'tobacco smoker'::text
    ELSE ''::text
END, ''::text)))) STORED,
    advisor_id uuid,
    stage_updated_at timestamp with time zone,
    organization_id uuid,
    CONSTRAINT chk_crm_records_age_range CHECK (((age_range IS NULL) OR (age_range = ANY (ARRAY['0-17'::text, '18-25'::text, '26-34'::text, '35-44'::text, '45-54'::text, '55-64'::text, '65+'::text])))),
    CONSTRAINT chk_crm_records_estimated_age CHECK (((estimated_age IS NULL) OR ((estimated_age >= 0) AND (estimated_age <= 150)))),
    CONSTRAINT chk_crm_records_market_type CHECK (((market_type IS NULL) OR (market_type = ANY (ARRAY['healthshare'::text, 'traditional_insurance'::text, 'unknown'::text])))),
    CONSTRAINT chk_crm_records_normalization_status CHECK (((normalization_status IS NULL) OR (normalization_status = ANY (ARRAY['normalized'::text, 'needs_review'::text, 'unresolved'::text])))),
    CONSTRAINT chk_crm_records_record_type CHECK (((record_type IS NULL) OR (record_type = ANY (ARRAY['individual'::text, 'group'::text, 'unknown'::text]))))
);

