--
-- Name: crm_contact_coverage_reporting_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.crm_contact_coverage_reporting_v AS
 SELECT c.id AS contact_id,
    c.organization_id,
    c.title AS contact_title,
    c.status AS contact_status,
    c.original_start_date AS contact_original_start_date,
    c.current_year_start_date AS contact_current_year_start_date,
    (c.data ->> 'start_date'::text) AS contact_start_date_json,
    (c.data ->> 'health_insurance_start_date'::text) AS contact_health_insurance_start_date_json,
    (c.data ->> 'contact_status'::text) AS contact_status_json,
    l.id AS lead_id,
    l.status AS lead_status,
    (l.data ->> 'lead_status'::text) AS lead_status_json,
    (l.data ->> 'is_converted'::text) AS lead_is_converted,
    (l.data ->> 'health_insurance_start_date'::text) AS lead_health_insurance_start_date_json,
    (l.data ->> 'start_date'::text) AS lead_start_date_json,
    public._parse_import_date(COALESCE((c.original_start_date)::text, (c.current_year_start_date)::text, (c.data ->> 'start_date'::text), (c.data ->> 'health_insurance_start_date'::text), (c.data ->> 'sharing_effective_date'::text), (l.data ->> 'health_insurance_start_date'::text), (l.data ->> 'start_date'::text), (l.data ->> 'sharing_effective_date'::text))) AS reporting_effective_start_date,
        CASE
            WHEN ((l.id IS NOT NULL) AND ((l.data ->> 'is_converted'::text) = 'true'::text) AND (l.status IS DISTINCT FROM 'Converted'::text)) THEN 'converted_lead_status_drift'::text
            WHEN ((l.id IS NOT NULL) AND (public._parse_import_date(COALESCE((l.data ->> 'health_insurance_start_date'::text), (l.data ->> 'start_date'::text))) IS NOT NULL) AND (c.original_start_date IS NULL) AND ((c.data ->> 'health_insurance_start_date'::text) IS NULL) AND ((c.data ->> 'start_date'::text) IS NULL)) THEN 'start_date_stranded_on_lead'::text
            WHEN ((c.status = ANY (ARRAY['In Process'::text, 'In process'::text, 'Pending'::text])) AND (public._parse_import_date(COALESCE((c.original_start_date)::text, (c.data ->> 'start_date'::text), (c.data ->> 'health_insurance_start_date'::text))) IS NULL) AND (l.id IS NOT NULL) AND (public._parse_import_date(COALESCE((l.data ->> 'health_insurance_start_date'::text), (l.data ->> 'start_date'::text))) IS NOT NULL)) THEN 'contact_missing_date_on_linked_lead'::text
            ELSE NULL::text
        END AS reconciliation_issue
   FROM (((public.crm_records c
     JOIN public.crm_modules cm ON (((cm.id = c.module_id) AND (cm.key = 'contacts'::text))))
     LEFT JOIN public.crm_record_links rl ON (((rl.link_type = 'lead_to_contact'::text) AND (rl.target_record_id = c.id))))
     LEFT JOIN public.crm_records l ON ((l.id = rl.source_record_id)))
  WHERE (c.organization_id IS NOT NULL);


--
-- Name: VIEW crm_contact_coverage_reporting_v; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.crm_contact_coverage_reporting_v IS 'Reporting lineage: coalesced effective start date + flags for lead/contact status/date splits.';


