--
-- Name: crm_duplicate_audit; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.crm_duplicate_audit AS
 WITH email_clusters AS (
         SELECT r.organization_id AS org_id,
            'email'::text AS rule,
            lower(btrim(r.email)) AS match_key,
            array_agg(r.id ORDER BY r.created_at, r.id) AS ids,
            array_agg(r.title ORDER BY r.created_at, r.id) AS titles,
            array_agg(r.module_id ORDER BY r.created_at, r.id) AS module_ids,
            (count(*))::integer AS member_count,
            NULL::numeric AS min_name_similarity
           FROM public.crm_records r
          WHERE ((r.email IS NOT NULL) AND (btrim(r.email) <> ''::text))
          GROUP BY r.organization_id, (lower(btrim(r.email)))
         HAVING (count(*) > 1)
        ), phone_clusters_raw AS (
         SELECT r.organization_id AS org_id,
            regexp_replace(COALESCE(r.phone, ''::text), '\D'::text, ''::text, 'g'::text) AS digits,
            array_agg(r.id ORDER BY r.created_at, r.id) AS ids,
            array_agg(r.title ORDER BY r.created_at, r.id) AS titles,
            array_agg(r.module_id ORDER BY r.created_at, r.id) AS module_ids,
            (count(*))::integer AS member_count
           FROM public.crm_records r
          WHERE (length(regexp_replace(COALESCE(r.phone, ''::text), '\D'::text, ''::text, 'g'::text)) >= 10)
          GROUP BY r.organization_id, (regexp_replace(COALESCE(r.phone, ''::text), '\D'::text, ''::text, 'g'::text))
         HAVING (count(*) > 1)
        ), phone_clusters AS (
         SELECT pc.org_id,
            'phone+name'::text AS rule,
            pc.digits AS match_key,
            pc.ids,
            pc.titles,
            pc.module_ids,
            pc.member_count,
            ( SELECT min(public.similarity(COALESCE(t1.t, ''::text), COALESCE(t2.t, ''::text))) AS min
                   FROM unnest(pc.titles) WITH ORDINALITY t1(t, i),
                    unnest(pc.titles) WITH ORDINALITY t2(t, i)
                  WHERE (t1.i < t2.i)) AS min_name_similarity
           FROM phone_clusters_raw pc
          WHERE (NOT (EXISTS ( SELECT 1
                   FROM email_clusters ec
                  WHERE ((ec.org_id = pc.org_id) AND (ec.ids @> pc.ids)))))
        )
 SELECT c.org_id,
    o.name AS org_name,
    c.rule,
    c.match_key,
    c.ids[1] AS keeper_id_oldest,
    c.ids[2:] AS duplicate_ids,
    c.titles,
    c.module_ids,
    c.member_count,
    c.min_name_similarity
   FROM (( SELECT email_clusters.org_id,
            email_clusters.rule,
            email_clusters.match_key,
            email_clusters.ids,
            email_clusters.titles,
            email_clusters.module_ids,
            email_clusters.member_count,
            email_clusters.min_name_similarity
           FROM email_clusters
        UNION ALL
         SELECT phone_clusters.org_id,
            phone_clusters.rule,
            phone_clusters.match_key,
            phone_clusters.ids,
            phone_clusters.titles,
            phone_clusters.module_ids,
            phone_clusters.member_count,
            phone_clusters.min_name_similarity
           FROM phone_clusters) c
     LEFT JOIN public.organizations o ON ((o.id = c.org_id)))
  ORDER BY c.member_count DESC, c.org_id, c.rule, c.match_key;


--
-- Name: VIEW crm_duplicate_audit; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.crm_duplicate_audit IS 'Read-only audit of duplicate clusters in crm_records under conservative rules (email, phone+name). All orgs. min_name_similarity is NULL for email clusters; for phone+name clusters, filter min_name_similarity >= 0.5 to match the prior PIFH sweep policy. See migration 202605020017.';


--
-- Name: crm_duplicate_audit_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.crm_duplicate_audit_summary WITH (security_invoker='true') AS
 SELECT org_id,
    org_name,
    rule,
    (count(*))::integer AS cluster_count,
    (sum((member_count - 1)))::integer AS mergeable_records,
    (sum(member_count))::integer AS total_records_in_clusters,
    (count(*) FILTER (WHERE ((rule = 'email'::text) OR ((rule = 'phone+name'::text) AND (COALESCE(min_name_similarity, (0)::real) >= (0.5)::double precision)))))::integer AS cluster_count_passing_threshold,
    (sum((member_count - 1)) FILTER (WHERE ((rule = 'email'::text) OR ((rule = 'phone+name'::text) AND (COALESCE(min_name_similarity, (0)::real) >= (0.5)::double precision)))))::integer AS mergeable_records_passing_threshold
   FROM public.crm_duplicate_audit
  GROUP BY org_id, org_name, rule
  ORDER BY ((sum((member_count - 1)) FILTER (WHERE ((rule = 'email'::text) OR ((rule = 'phone+name'::text) AND (COALESCE(min_name_similarity, (0)::real) >= (0.5)::double precision)))))::integer) DESC NULLS LAST, org_id, rule;


--
-- Name: VIEW crm_duplicate_audit_summary; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.crm_duplicate_audit_summary IS 'Per-org / per-rule rollup of crm_duplicate_audit. mergeable_records_passing_threshold is the count of dup rows that would be merged if the prior PIFH policy (phone+name trigram >= 0.5) is applied org-wide. Run this first to see scope before authorizing a merge migration.';


