--
-- Name: enterprise_verification_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.enterprise_verification_summary WITH (security_invoker='on') AS
 SELECT ( SELECT count(*) AS count
           FROM public._enterprise_verification
          WHERE (_enterprise_verification.status = 'PASS'::text)) AS passed,
    ( SELECT count(*) AS count
           FROM public._enterprise_verification
          WHERE (_enterprise_verification.status = 'WARN'::text)) AS warnings,
    ( SELECT count(*) AS count
           FROM public._enterprise_verification
          WHERE (_enterprise_verification.status = 'FAIL'::text)) AS failed,
    ( SELECT count(*) AS count
           FROM public._enterprise_verification) AS total,
        CASE
            WHEN (( SELECT count(*) AS count
               FROM public._enterprise_verification
              WHERE (_enterprise_verification.status = 'FAIL'::text)) = 0) THEN 'ENTERPRISE READY'::text
            ELSE 'NEEDS ATTENTION'::text
        END AS overall_status;


