--
-- Name: mv_advisor_monthly_performance; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.mv_advisor_monthly_performance AS
 SELECT a.id AS advisor_id,
    a.organization_id,
    a.parent_advisor_id,
    a.commission_tier,
    a.agent_level_id,
    COALESCE(c.product_type, 'all'::text) AS product_type,
    date_trunc('month'::text, ((c.commission_period)::date)::timestamp with time zone) AS month,
    count(DISTINCT c.enrollment_id) AS total_enrollments,
    count(c.id) AS commission_count,
    sum(
        CASE
            WHEN (c.commission_type = 'signup'::text) THEN c.commission_amount
            ELSE (0)::numeric
        END) AS signup_commissions,
    sum(
        CASE
            WHEN (c.commission_type = 'monthly'::text) THEN c.commission_amount
            ELSE (0)::numeric
        END) AS monthly_commissions,
    sum(
        CASE
            WHEN (c.commission_type = 'override'::text) THEN c.commission_amount
            ELSE (0)::numeric
        END) AS override_commissions,
    sum(
        CASE
            WHEN (c.commission_type = 'bonus'::text) THEN c.commission_amount
            ELSE (0)::numeric
        END) AS bonus_commissions,
    sum(c.commission_amount) AS total_commissions,
    sum(c.base_amount) AS total_base_amount,
    sum(
        CASE
            WHEN (c.status = 'paid'::text) THEN c.commission_amount
            ELSE (0)::numeric
        END) AS paid_commissions,
    sum(
        CASE
            WHEN (c.status = 'pending'::text) THEN c.commission_amount
            ELSE (0)::numeric
        END) AS pending_commissions,
    sum(
        CASE
            WHEN (c.status = 'approved'::text) THEN c.commission_amount
            ELSE (0)::numeric
        END) AS approved_commissions
   FROM (public.advisors a
     JOIN public.commissions c ON ((c.advisor_id = a.id)))
  GROUP BY a.id, a.organization_id, a.parent_advisor_id, a.commission_tier, a.agent_level_id, COALESCE(c.product_type, 'all'::text), (date_trunc('month'::text, ((c.commission_period)::date)::timestamp with time zone))
  WITH NO DATA;


--
-- Name: executive_kpi_mv; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.executive_kpi_mv AS
 SELECT organization_id AS org_id,
    month,
    sum(total_commissions) AS total_commission,
    sum(paid_commissions) AS paid_commission,
    sum(pending_commissions) AS pending_commission,
    sum(total_enrollments) AS total_policies,
    count(DISTINCT advisor_id) AS total_advisors,
    sum(
        CASE
            WHEN (product_type = 'health_share'::text) THEN total_commissions
            ELSE (0)::numeric
        END) AS health_share_commission,
    sum(
        CASE
            WHEN (product_type = 'health_insurance'::text) THEN total_commissions
            ELSE (0)::numeric
        END) AS insurance_commission,
    sum(
        CASE
            WHEN (product_type = 'health_share'::text) THEN total_enrollments
            ELSE (0)::bigint
        END) AS health_share_policies,
    sum(
        CASE
            WHEN (product_type = 'health_insurance'::text) THEN total_enrollments
            ELSE (0)::bigint
        END) AS insurance_policies,
    COALESCE(avg(total_commissions) FILTER (WHERE (total_commissions > (0)::numeric)), (0)::numeric) AS avg_commission_per_advisor
   FROM public.mv_advisor_monthly_performance m
  WHERE (product_type = ANY (ARRAY['health_share'::text, 'health_insurance'::text]))
  GROUP BY organization_id, month
  WITH NO DATA;


--
-- Name: executive_top_advisor_mv; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.executive_top_advisor_mv AS
 SELECT DISTINCT ON (r.organization_id, r.period_month) r.organization_id AS org_id,
    r.period_month AS month,
    r.advisor_id AS top_advisor_id,
    a.first_name AS top_advisor_first_name,
    a.last_name AS top_advisor_last_name,
    r.production_score AS top_advisor_score,
    r.total_commissions AS top_advisor_commissions,
    r.tier AS top_advisor_tier
   FROM (public.advisor_rankings r
     JOIN public.advisors a ON ((a.id = r.advisor_id)))
  WHERE (r.capacity_scope IS NULL)
  ORDER BY r.organization_id, r.period_month, r.rank_position
  WITH NO DATA;


