    CONSTRAINT member_lifecycle_events_reason_check CHECK (((reason IS NULL) OR (reason = ANY (ARRAY['cost'::text, 'coverage_change'::text, 'moved_state'::text, 'joined_medicaid'::text, 'joined_employer_plan'::text, 'dissatisfied'::text, 'non_payment'::text, 'aging_out'::text, 'life_event'::text, 'better_option'::text, 'voluntary'::text, 'involuntary'::text, 'other'::text]))))
