--
-- Name: mv_org_monthly_dashboard; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.mv_org_monthly_dashboard AS
 SELECT organization_id,
    COALESCE(product_type, 'all'::text) AS product_type,
    date_trunc('month'::text, ((commission_period)::date)::timestamp with time zone) AS month,
    count(DISTINCT advisor_id) AS active_advisors,
    count(DISTINCT enrollment_id) AS total_enrollments,
    count(DISTINCT member_id) AS total_members,
    count(id) AS commission_count,
    sum(commission_amount) AS total_commissions,
    sum(base_amount) AS total_base_amount,
    sum(
        CASE
            WHEN (status = 'paid'::text) THEN commission_amount
            ELSE (0)::numeric
        END) AS paid_amount,
    sum(
        CASE
            WHEN (status = 'pending'::text) THEN commission_amount
            ELSE (0)::numeric
        END) AS pending_amount,
    sum(
        CASE
            WHEN (status = 'approved'::text) THEN commission_amount
            ELSE (0)::numeric
        END) AS approved_amount,
    avg(commission_amount) AS avg_commission
   FROM public.commissions c
  GROUP BY organization_id, COALESCE(product_type, 'all'::text), (date_trunc('month'::text, ((commission_period)::date)::timestamp with time zone))
  WITH NO DATA;


