 SELECT o.id,
    o.name,
    o.slug,
    o.subdomain,
    o.domain,
    o.plan,
    o.status,
    o.branding,
    m.role,
    m.is_default,
    m.last_active_at
   FROM (public.organization_members m
     JOIN public.organizations o ON ((o.id = m.organization_id)))
  WHERE ((m.user_id = auth.uid()) AND (m.is_active = true) AND (o.status = 'active'::text));


