--
-- Name: pricing_lookup_mv; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.pricing_lookup_mv AS
 SELECT p.id AS plan_id,
    COALESCE(p.plan_code, p.code) AS plan_code,
    p.name AS plan_name,
    p.brand_name,
    p.category,
    p.metal_tier,
    ra.id AS rating_area_id,
    ra.rating_area_code,
    ra.state,
    ab.id AS age_band_id,
    ab.band_label,
    ab.min_age,
    ab.max_age,
    pr.tobacco,
    pr.monthly_rate,
    pr.effective_year,
    bt.id AS benefit_tier_id,
    bt.tier_code,
    bt.display_name AS tier_name,
    pbm.premium_modifier,
    pbm.fixed_adjustment,
    round(((pr.monthly_rate * COALESCE(pbm.premium_modifier, 1.0)) + COALESCE(pbm.fixed_adjustment, (0)::numeric)), 2) AS tiered_monthly_rate,
    round((((pr.monthly_rate * COALESCE(pbm.premium_modifier, 1.0)) + COALESCE(pbm.fixed_adjustment, (0)::numeric)) * (12)::numeric), 2) AS tiered_annual_rate
   FROM (((((public.plan_rates pr
     JOIN public.plans p ON ((p.id = pr.plan_id)))
     JOIN public.rating_areas ra ON ((ra.id = pr.rating_area_id)))
     JOIN public.age_bands ab ON ((ab.id = pr.age_band_id)))
     LEFT JOIN public.plan_benefit_matrix pbm ON (((pbm.plan_id = p.id) AND (pbm.active = true))))
     LEFT JOIN public.benefit_tiers bt ON ((bt.id = pbm.benefit_tier_id)))
  WHERE (p.is_active = true)
  WITH NO DATA;


--
-- Name: MATERIALIZED VIEW pricing_lookup_mv; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON MATERIALIZED VIEW public.pricing_lookup_mv IS 'Pre-computed pricing projection for fast API lookups — refresh after rate changes';


