--
-- Name: ticket_metrics; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.ticket_metrics WITH (security_invoker='on') AS
 SELECT id,
    ticket_id,
    first_response_target_minutes,
    first_response_at,
    first_response_by,
    first_response_duration_minutes,
    first_response_met,
    first_response_breach_minutes,
    resolution_target_minutes,
    resolved_at,
    resolved_by,
    resolution_duration_minutes,
    resolution_met,
    resolution_breach_minutes,
    sla_status,
    overall_breach AS sla_breached,
    ticket_priority,
    ticket_category,
    assigned_agent_id,
    ticket_created_at,
    last_calculated_at,
    created_at,
    updated_at
   FROM public.sla_metrics;


