    CONSTRAINT warehouse_exports_export_type_check CHECK ((export_type = ANY (ARRAY['commissions'::text, 'rankings'::text, 'agencies'::text, 'kpis'::text, 'full'::text]))),
    CONSTRAINT warehouse_exports_format_check CHECK ((format = ANY (ARRAY['csv'::text, 'json'::text, 'parquet'::text]))),
    CONSTRAINT warehouse_exports_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'processing'::text, 'completed'::text, 'failed'::text])))
);


