    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now()
);


--
-- Name: workflow_execution_stats; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.workflow_execution_stats WITH (security_invoker='on') AS
 SELECT w.id AS workflow_id,
    w.name AS workflow_name,
    count(we.id) AS total_executions,
    count(
        CASE
            WHEN (we.status = 'completed'::text) THEN 1
            ELSE NULL::integer
        END) AS successful_executions,
    count(
        CASE
            WHEN (we.status = 'failed'::text) THEN 1
            ELSE NULL::integer
        END) AS failed_executions,
    max(we.started_at) AS last_execution
   FROM (public.workflows w
     LEFT JOIN public.workflow_executions we ON ((w.id = we.workflow_id)))
  GROUP BY w.id, w.name;


