   FROM public.tasks t
  WHERE ((t.id = task_watchers.task_id) AND ((t.assignee_id = ( SELECT auth.uid() AS uid)) OR (t.created_by_id = ( SELECT auth.uid() AS uid)) OR (EXISTS ( SELECT 1
           FROM public.task_watchers tw2
          WHERE ((tw2.task_id = t.id) AND (tw2.user_id = ( SELECT auth.uid() AS uid))))) OR ((t.project_id IS NOT NULL) AND (EXISTS ( SELECT 1
           FROM (public.projects p
             LEFT JOIN public.project_members pm ON ((pm.project_id = p.id)))
          WHERE ((p.id = t.project_id) AND ((p.owner_id = ( SELECT auth.uid() AS uid)) OR (pm.user_id = ( SELECT auth.uid() AS uid))))))))))));


