   FROM public.crm_roles r
  WHERE ((r.id = crm_user_roles.role_id) AND (r.organization_id IS NOT NULL) AND public.has_crm_role(r.organization_id, ARRAY['crm_admin'::text]))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM public.crm_roles r
  WHERE ((r.id = crm_user_roles.role_id) AND (r.organization_id IS NOT NULL) AND public.has_crm_role(r.organization_id, ARRAY['crm_admin'::text])))));


